(function () {
  "use strict";
  window.__bookText = {"faith_life":{"id":"faith_life","title":"حياة الإيمان","author":"قداسة البابا شنوده الثالث","url":"https://drive.google.com/file/d/1yHqM7AYCgFo6-ejDm43YJJMas1GXptxh/view","file":"حياة الإيمان.pdf","pageOffset":2,"review":{"status":"needs-review","note":"نُقل الكتاب (من «قصة هذا الكتاب» إلى آخر الفصل العاشر، ص٤ إلى ص١٠٩ بترقيم الملف) بقراءة صفحات الكتاب الممسوحة بالنظر؛ حُذف غلاف الكتاب والفهرس وإعلان «الكتاب المقبل». ملاحظات للمراجعة: (١) في الملف صفحتان مطبوعتان (٥٨ و٥٩) وردتا بترتيب معكوس فنُقلتا بترتيب القراءة، (٢) بعد عنوان الفصل الثامن يبدأ النص التالي في منتصف جملة فلعل صفحة ناقصة من ملف المصدر، (٣) بعد ص٨٢ المطبوعة يزيد رقم الصفحة المطبوعة عن ترقيم الملف بمقدار ٣ بدل ٢ لذلك قد تظهر أرقام الصفحات في الواجهة أقل بواحد في الجزء الأخير، (٤) عناوين الفصول المزخرفة قرئت بأفضل ما تيسر."},"chapters":[{"title":"قصة هذا الكتاب والمقدمة","from":4,"to":6},{"title":"الفصل الأول: ما أعظم الإيمان","from":7,"to":10},{"title":"الفصل الثاني: ما هو الإيمان (الإيقان بأمور لا ترى)","from":11,"to":32},{"title":"الفصل الثالث: درجات وأنواع من الإيمان","from":33,"to":44},{"title":"الفصل الرابع: علاقة الإيمان بالسلام وعدم الخوف","from":45,"to":54},{"title":"الفصل الخامس: علاقة الإيمان بنقاوة القلب","from":55,"to":60},{"title":"الفصل السادس: بساطة الإيمان","from":61,"to":66},{"title":"الفصل السابع: طاعة الإيمان أو حياة التسليم","from":67,"to":80},{"title":"الفصل الثامن: ما يقوي الإيمان","from":81,"to":89},{"title":"الفصل التاسع: ما يضعف الإيمان","from":90,"to":101},{"title":"الفصل العاشر: اختبار الإيمان","from":102,"to":109}],"transcribed":[4,109],"pages":{"4":[{"h":"قصة هذا الكتاب"},"إنه ثمرة أكثر من ١٥ محاضرة ألقيت كلها فى الكاتدرائية المرقسية بدير الأنبا رويس بالقاهرة (ماعدا الثلاث محاضرات الأولى) . وقد حان الآن نشرها بناء على دعوة من مجلس كنائس الشرق الأوسط الذى قرر عقد اجتماع عن الإيمان فى منتصف سبتمبر ١٩٨٤ .","أما هذه المحاضرات ـ مصدر هذا الكتاب ـ فهى حسب تواريخها كالآتى :","١ ـ محاضرة ألقيت فى مؤتمر عن الإيمان عقد فى كنيسة المنصورة يوم ١٩٦٦/٦/١ .","٢ ، ٣ ـ محاضرتان عن الإيمان ألقيتا فى القاعة المرقسية بدير الأنبا رويس يومى الجمعة ١٩٦٦/٧/٨ ، ١٩٦٦/٧/١٥ .","٤ ـ ٧ ـ أربع محاضرات ألقيت فى الكاتدرائية الكبرى سنة ١٩٧١ تأملاً فى « كما قسم لكل واحد نصيباً من الإيمان » (رو ١٢ : ٣) .","٨ ـ محاضرة عن الإيمان ألقيت فى الكاتدرائية الكبرى فى أواخر مايو سنة ١٩٧٣ بمناسبة عودة رفات القديس أثناسيوس إلى القاهرة .","٩ ـ محاضرة عن عوائق الإيمان ألقيت يوم الجمعة ١٩٧٥/٥/٢٣ .","١٠ ـ محاضرة يوم الجمعة ١٩٨٠/٢/٢٢ ، موضوعها (ناظرين إلى ما لا يرى) .","١١ ـ محاضرة يوم الجمعة ١٩٨٠/٧/٢٥ ، موضوعها (بساطة الإيمان) .","١٢ ـ محاضرة يوم الجمعة ١٩٨٠/٩/٢٦ ، موضوعها (لا يعلم إلى أين يذهب) .","١٣ ـ محاضرة يوم الجمعة ١٩٨٠/١٠/٣ ، موضوعها (الإيقان بأمور لا ترى) .","١٤ ـ محاضرة يوم الجمعة ١٩٨١/٨/١٤ ، موضوعها (طاعة الإيمان) .","١٥ ـ محاضرات متفرقة نشرت فى مجلة الكرازة .","وقد سجلت هنا هذه التواريخ لمن يريد أن يحصل على التسجيلات الصوتية الخاصة بحياة الإيمان ، راجياً للقارىء العزيز حياة مملوءة بالإيمان .","البابا شنوده الثالث"],"5":[{"h":"مقدمة"},{"h":"ليس الإيمان هو مجرد اعتناق مجموعة من العقائد ، تتلوها فى « قانون الإيمان » ... إنما الإيمان هو حياة تحياها أو هو عقيدة تقود إلى حياة ..."},"لأنه ما فائدة الإيمان بالله ، بدون أن تكون لك علاقة بهذا الإله : تطيعه وتحبه ، وتكون لك عشرة معه تؤهلك إلى عشرة دائمة فى ملكوته ؟!","وما فائدة الإيمان بالأبدية والحياة بعد الموت ، إن لم تعد نفسك لها بالتوبة ، وبالسهر الروحى الدائم ، وبمحبة الله .","وما فائدة الإيمان بالفضيلة ، إن كنت لا تحياها .","لذلك فإن هناك فرقاً كبيراً جداً بين الإيمان النظرى الذى لا يخلص النفس ، والإيمان العملى الذى تظهر ثماره فى حياتك . وهكذا تحيا حياة الإيمان ...","إننا من أجل حياة الإيمان ، وضعنا كتابنا هذا ...","نشرح لك ما هو الإيمان ، وما هى درجاته وأنواعه ، وما أهمية الإيمان فى حياتنا ، وما عظمته ... ؟","ولقد أردنا أن نقف قليلاً عند قول القديس بولس الرسول : « جربوا أنفسكم : هل أنتم فى الإيمان ؟ إمتحنوا أنفسكم » (٢كو ١٣ : ٥) .","فليس كل إنسان يقول إنه مؤمن ، هو مؤمن بالحقيقة . بل المقياس لذلك هو قول الرب « من ثمارهم تعرفونهم » (متى ٧ : ١٦) .","لأن هناك من له إسم المؤمن ، وليس له قلب المؤمن ، ولا حياة المؤمن . فما هى حياة المؤمن هذه ؟","حياة الإيمان ترتبط بالسلام والاطمئنان وعدم الخوف . فإن وقع فى الخوف ، يقول له الرب « يا قليل الإيمان ، لماذا شككت » (متى ١٤ : ٣١) ."],"6":["وحياة المؤمن ترتبط بنقاوة السيرة ، لأن المؤمن يشعر دواماً أن الله أمامه يرى ويسمع ويسجل كل ما يعمله . لذلك يشعر بالإستحياء ، ويخاف أن يخطىء أمام الله .","وحياة المؤمن هى حياة التسليم للمشيئة الإلهية ، فى إيمان كامل أن الله هو صانع الخيرات ، وكل ما يسمح به هو خير . لذلك بالإيمان يعيش أولاد الله فى هدوء وفى فرح وفى رضى بكل ما يريده الرب لهم .","وحياة الإيمان ، لا ترى شيئاً مستحيلاً على الرب . بل كما يقول :",{"h":"« كل شىء مستطاع للمؤمن » (مر ٩ : ٢٣) ."},"لذلك فإن المؤمن لا يهتز فى أية ضيقة تحل به ، بل يؤمن تماماً أن الله عنده حلول كثيرة ، وأنه لا بد سيتدخل ويصنع مشيئته ...","المؤمن لا يجادل الله ولا يناقشه فيما يفعله ، بل يقبل كل شىء بثقة كاملة فى حكمة الله وفى محبته .","المؤمن ينظر دائماً إلى ما لا يرى ، أكثر مما ينظر إلى المرئيات « لأن الأشياء التى تُرى وقتية ، أما التى لا ترى فأبدية » (٢كو ٤ : ١٨) .","إن أبطال الإيمان ليسوا هم فقط الذين دافعوا عن العقيدة ، وإنما هم الذين عاشوا فى الإيمان الحى المثمر العامل بالمحبة ...","وهذا الكتاب الذى بين يديك يعطيك فكرة مبسطة عن حياة الإيمان كيف تكون ؟ وكيف تختبر عملياً هل أنت فى الإيمان .","البابا شنوده الثالث"],"7":[{"h":"الفصل الأول"},{"h":"ما أعظم الإيمان"}],"8":["لعل أهمية الإيمان تبدو واضحة فى قول الرسول عن الرب :",{"h":"« بدون إيمان ، لا يمكن إرضاؤه » (عب ١١ : ٦) ."},"وتبدو أهمية الإيمان أيضاً ، فى أن الرسول قد وصفه بأنه إحدى الفضائل الثلاث الكبار « الإيمان والرجاء والمحبة » (١كو ١٣ : ١٣) ، وذكر أنه الوسيلة التى يحيا بها الإنسان البار فقال :",{"h":"« أما البار ، فبالإيمان يحيا » (عب ١٠ : ٣٨) ."},"والإيمان هو بدء الطريق الموصل إلى الله . لأنه كيف يمكن أن تثبت فى الله ، والله فيك ، وكيف يمكنك أن تسير مع الله وتحفظ وصاياه ، إن لم تؤمن أولاً بوجوده وبصفاته الإلهية ، وتؤمن بكتابه وبكل ما ورد فيه ... ؟",{"h":"الإيمان إذن هو بدء الطريق إلى الله . وأول الشروط اللازمة للخلاص"},"حسب قول الرب نفسه « من آمن واعتمد خلص » (مر ١٦ : ١٦) ، « لكى لا يهلك كل من يؤمن به ، بل تكون له الحياة الأبدية » (يو ٣ : ١٦) ، « الذى يؤمن به لا يدان ، والذى لا يؤمن به قد دين ... » (يو ٣ : ١٨) . وكما وبخ اليهود قائلاً : « إن لم تؤمنوا أنى أنا هو ، تموتون فى خطاياكم » (يو ٨ : ٢٤) .","إن دم المسيح موجود ، قادر أن يخلص كل أحد . ولكنه لا يخلص بدون إيمان . ولهذا قال القديسان بولس وسيلا لحافظ السجن فى فيلبى « آمن بالرب يسوع ، فتخلص أنت وأهل بيتك » (أع ١٦ : ٣١) .",{"h":"من أجل هذا الإيمان كتبت الأناجيل ، وكرز بها الرسل ."},"وهكذا يقول القديس يوحنا الإنجيلى فيما كتبه بوحى من الروح القدس « ... أما هذه فقد كتبت لتؤمنوا أن يسوع المسيح إبن الله ، ولكى تكون لكم إذا آمنتم حياة بإسمه » (يو ٢٠ : ٣١) .","الإيمان هو بدء الحياة مع الله ، وهو رفيق الطريق طول هذه الحياة ، لذلك من أهمية الإيمان علاقته بالبر ."],"9":["وهكذا يتحدث الرسول عن البر الذى حُسب بالإيمان (عب ١١ : ٧) ، وعن الإيمان الذى حُسب براً (يع ٢ : ٢٣) .","ويتحدث الكتاب عن التبرير بالإيمان (رو ٥ : ١) .",{"h":"والإيمان هو العنصر الأساسى اللازم لصنع المعجزات ، ولتقبلها :"},"لهذا ما أعظم قول الرب لأعمى أريحا بارتيماوس : « إيمانك قد شفاك » (لو ١٨ : ٤٢ ، مر ١٠ : ٥٢) . وما أجمل قوله لذلك الأبرص الذى طهر « إيمانك خلصك » (لو ١٧ : ١٩) . وهكذا قال أيضاً لنازفة الدم « ثقى يا إبنة : إيمانك قد شفاك » (متى ٩ : ٢٢) . كذلك فإنه لما سمع الأعميين اللذين صرخا « إرحمنا يا ابن داود » ، قال لهما : « بحسب إيمانكما ليكن لكما » فانفتحت أعينهما (متى ٩ : ٢٩) .","ومن الناحية الأخرى ، نرى أن السيد الرب لما جاء إلى وطنه « لم يصنع هناك قوات كثيرة لعدم إيمانهم » (متى ١٣ : ٥٨) .",{"h":"إن قوة الله قادرة أن تصنع معك الأعاجيب . ولكنها تنتظر إيمانك ."},"وحسب إيمانك يعطيك . ولهذا فإن المعجزات تحدث مع البعض ، ولا تحدث مع البعض الآخر ، مع أن قوة الله هى هى .","ولكن ماذا عن الشخص ضعيف الإيمان ؟ هذا عليه أن يصلى مع أبى الولد الذى عليه روح الأخرس قائلاً : « أؤمن يا سيد . فأعن عدم إيمانى » (مر ٩ : ٢٤) . وهنا نقول إنه فى غالبية الأحوال يصنع الله المعجزة بحسب الإيمان ، ولكن ...",{"h":"فى أحيان أخرى يصنع المعجزة لكى نؤمن ."},"وهكذا فى الحالين ، يرتبط الإيمان بالمعجزة : فإما أن يكون سابقاً لها ، وإما أن يكون نتيجة لها ...",{"h":"إن الإيمان ـ أياً كان نوعه ـ هو قوة ."},"يكفى أن يؤمن الإنسان بفكرة ، فتراه يعمل بقوة المسيح لكى ينفذها . الإيمان يعطيه عزيمة وإرادة وجرأة ما كانت عنده من قبل ."],"10":["حقاً حيثما يوجد الإيمان ، توجد معه القوة . فالصلاة المملوءة إيماناً ، هى الصلاة القوية . الذى يؤمن بالصلاة وفاعليتها ، تراه يصلى بحرارة وإيمان وقوة . والعظة التى يقولها إنسان وهو مؤمن بكل كلمة فيها ، تكون عظة قوية ، ينتقل بها إيمانه إلى قلوب الناس .",{"h":"ومن أهمية الإيمان أيضاً إرتباطه بعديد من الفضائل ، تنبع منه :"},"فمن نتائج الإيمان القوة ، والطمأنينة ، والشجاعة ، والسلام القلبى ، وعدم الخوف ، وعدم القلق .","ومن ثماره أيضاً : حياة النقاوة والبر ، وحياة التسليم الكامل لله ، وحياة التجرد والزهد ، وحياة الصلاة ... وفضائل عديدة أخرى","ونحن نعدك أيها القارىء العزيز ، أننا لا ننتهى من هذا الكتاب ، حتى نحدثك عن هذا كله بمشيئة الله .",{"h":"أما الآن فنريد أن نسأل : ما هو هذا الإيمان ؟"},"ما هو هذا الإيمان ، الذى من نتائجه الخلاص والتبرير ؟","وما هو هذا الإيمان ، الذى من نتائجه كل هذه الفضائل ؟","وما هو هذا الإيمان ، الذى يقدر على صنع الآيات والعجائب ، والذى قال عنه الرب : « كل شىء مستطاع للمؤمن » (مر ٩ : ٢٣) ."],"11":[{"h":"الفصل الثانى"},{"h":"ما هو الإيمان"},"الإيقان بأمور لا ترى","« جربوا أنفسكم هل أنتم فى الإيمان ... إمتحنوا أنفسكم » (٢كو ١٣ : ٥) ."],"12":[{"h":"ما هو الإيمان ؟"},"كلمة إيمان قد يدعيها كل إنسان يعبد الله ... وربما لا يكون مؤمناً بالحقيقة ...",{"h":"قد يكون له إسم المؤمن ، ولكن ليس له قلب المؤمن ."},"ليس الإيمان هو أن يولد الإنسان من أسرة متدينة تؤمن بوجود الله ، فيصير مؤمناً تلقائياً بوجود الله . إنما الإيمان له معنى أو معان أعمق من هذا بكثير ... نعم له معنى قد يشمل الحياة الروحية كلها ، وله معنى قد يصنع الأعاجيب .","فى إحدى المرات لم يستطع تلاميذ الرب أن يخرجوا شيطاناً من إنسان مصروع ، فسألوا الرب عن سر ذلك فقال لهم « لعدم إيمانكم » (متى ١٧ : ٢٠) ... ووبخ الجمع قائلاً : « أيها الجيل غير المؤمن ، الملتوى » (متى ١٧ : ١٧) .","ليكن ذلك الجيل غير مؤمن . ولكن رسل المسيح نفسه ، أُطلق عليهم حينذاك عبارة « عدم إيمانكم » ؟ ... يا للهول . وهنا يستطرد المسيح قائلاً لتلاميذه : « الحق أقول لكم لو كان لكم إيمان مثل حبة خردل ، لكنتم تقولون لهذا الجبل : إنتقل من هنا إلى هناك . فينتقل » (متى ١٧ : ٢٠) .",{"h":"حقاً ، ما هو هذا الإيمان ، الذى حبة خردل منه ، تستطيع أن تنقل الجبل ؟ ! ..."},"لذلك حسناً قال الرسول : « إختبروا أنفسكم : هل أنتم فى الإيمان ؟ إمتحنوا أنفسكم » (٢كو ١٣ : ٥) .","على أن الكتاب يروى لنا شيئاً عجيباً ... أخطر من هذا بكثير ... فما هو ؟ إنه حال إنسان يبدو مؤمناً بالرب ، ويصلى ، ويصنع المعجزات ، وهو غير مؤمن بالحقيقة ! بل غير مقبول أمام الله ! هوذا الرب نفسه يقول :","« ليس كل من يقول لى يارب يارب ، يدخل ملكوت السموات ... » (متى ٧ : ٢١) ."],"13":["ويتابع الرب كلامه قائلاً : « كثيرون سيقولون لى فى ذلك اليوم : يارب يارب ، أليس باسمك تنبأنا ، وباسمك أخرجنا شياطين ، وباسمك صنعنا قوات كثيرة ؟ فحينئذ أصرح لهم إنى لم أعرفكم قط . إذهبوا عنى يا فاعلى الإثم » (متى ٧ : ٢٢ ، ٢٣) .","ماذا نسمى هؤلاء الذين يقولون يارب يارب ... باسمك صنعنا كذا وكذا ... ؟ أهم مؤمنون بالحقيقة ؟ !",{"h":"ربما يكون هذا إيماناً ظاهرياً ، أو إيماناً شكلياً ، أو إيماناً بالإسم ، أو مجرد إيمان عقلى ، ولكنه ليس إيماناً حقيقياً مقبولاً أمام الله !"},"فما هو إذن الإيمان الحقيقى المقبول أمام الله ؟ نسأل الرب فيجيب :","« ليس كل من يقول لى يارب يارب ... بل الذى يفعل إرادة أبى الذى فى السموات (متى ٧ : ٢١) . ويذكرنا هذا أيضاً بقصة العذارى الجاهلات اللاتى استعملن أيضاً عبارة يارب يارب . ووقفن وراء الباب المغلق يقلن : ياربنا ياربنا إفتح لنا . فسمعن منه تلك الإجابة الصريحة المرعبة « الحق أقول لكن إنى ما أعرفكن » (متى ٢٥ : ١٢) .",{"h":"إن عبارة يارب لا تفيد مطلقاً ، إن كنت تنتظر العريس بمصباح لا زيت فيه ، أو إن جئت بعد أن أغلق الباب ..."},"ما هو الإيمان إذن ؟ وما علاقته بالزيت الذى يرمز إلى الروح القدس ، وإلى المسحة المقدسة ؟ وما علاقته بمشيئة الآب الذى فى السموات ؟","إنه هذا الإيمان الحى ، المقبول من الله ، كما سنشرح بالتفصيل فيما بعد ...",{"h":"إذن الإيمان ليس مجرد عقيدة ، إنما هو أيضاً حياة ."},"يمكن أن تختبره بثماره فى حياتك ... فهكذا قال الرب « من ثمارهم تعرفونهم ... كل شجرة جيدة تصنع أثماراً جيدة ... لا تقدر شجرة جيدة أن تصنع أثماراً ردية . ولا شجرة ردية أن تصنع أثماراً جيدة . فإذن من ثمارهم تعرفونهم » (متى ٧ : ١٦ ـ ٢٠) .",{"h":"بهذا تختبر نفسك : هل إيمانك له ثمر ؟ لأنه من ثمارهم تعرفونهم ."}],"14":["وهكذا يعلمنا القديس يوحنا الحبيب : « بهذا نعرف أننا قد عرفناه ... » ، كيف ؟ « إن حفظنا وصاياه » ، « من قال قد عرفته ، وهو لا يحفظ وصاياه ، فهو كاذب وليس الحق فيه ... » (١يو ٢ : ٣ ، ٤) ... إذن الإيمان يختبر بحياة الطاعة لوصايا الله . والذى لا تكون له هذه الطاعة لا يعتبر مؤمناً بالحقيقة . بل لا نقول عنه إنه قد عرف الله ...",{"h":"إن هناك وسائل كثيرة لاختبار الإيمان ، سنحدثك عنها فى باب خاص ."},"والقديس بولس الرسول يقدم لنا قائمة رائعة لرجال الإيمان فى رسالته إلى العبرانيين (عب ١١) . وكلهم من ذلك النوع الذى ظهر الإيمان فى حياته الخاصة ...","مثل أبينا أخنوخ الذى لم يقل الكتاب عنه إنه دافع عن عقيدة معينة ، كالقديس أثناسيوس الرسول الذى دافع عن العقيدة ضد الأريوسية ، أو كالقديس كيرلس الكبير الذى دافع عن العقيدة ضد النسطورية ، ومثل باقى أبطال الإيمان فى العقيدة ...","إنما كان أخنوخ من أبطال الإيمان ، لأنه « أرضى الله » (عب ١١ : ٥) . أو كما قال سفر التكوين « وسار أخنوخ مع الله » (تك ٥ : ٢٢ ، ٢٤) .","وأنت قد لا تكون لاهوتياً عميقاً فى المعرفة مثل القديس أثناسيوس أو القديس كيرلس . ولكنك بلا شك فى إمكانك أن تحيا فى منهج أبينا أخنوخ الذى سار مع الله . وأن تحيا مثل باقى رجال الإيمان الذين ذكرهم القديس بولس الرسول الذين « أقروا بأنهم غرباء ونزلاء على الأرض ... وكانوا يبتغون وطناً أفضل أى سماوياً » (عب ١١ : ١٣ ، ١٦) .","لقد كان أبونا إبراهيم من رجال الإيمان ، لأنه « لما دعى أطاع » (عب ١١ : ٨) ، فخرج وراء الله « وهو لا يعلم إلى أين يذهب » . وحُسب من رجال الإيمان ، لأنه صدق مواعيد الله حق وهو يقدم إبنه وحيده ، واثقاً أن الله قادر على الإقامة من الأموات (عب ١١ : ١٧ ـ ١٩) .","ووضعت زوجته ساره فى قائمة أبطال الإيمان ، لأنها صدقت قول الرب « إذ حسبت الذى وعد صادقاً » (عب ١١ : ١١) .",{"h":"إذن ليس أبطال الإيمان هم فقط أبطال الدفاع عن العقيدة ، إنما أيضاً"}],"15":[{"h":"أولئك الذين صدقوا الرب ، وأرضوه ، وساروا معه ، وصنعوا براً (عب ١١ : ٣٣) ."},"وأيضاً أولئك الذين « عذبوا ولم يقبلوا النجاة ، لكى ينالوا قيامة أفضل » ، وأولئك الذين « طافوا فى جلود غنم وجلود ماعز ، معتازين مكروبين مذلين ، « تائهين فى برارى وجبال ومغائر وشقوق الأرض ، « وهم لم يكن العالم مستحقاً لهم » (عب ١١ : ٣٥ ـ ٣٨) .","هؤلاء كلهم كانوا مشهوداً لهم بالإيمان (عب ١١ : ٣٩) .","فى كل هذا يعطينا الكتاب معنى واسعاً لكلمة الإيمان .","ومعلمنا القديس بولس الرسول يقول لنا فى معنى الإيمان هذا :",{"h":"« الإيمان هو الثقة بما يرجى ، والإيقان بأمور لا ترى » (عب ١١ : ١) ."},"وعبارة أمور لا ترى هى عبارة واسعة جداً ، سندخل فى تفاصيلها بعد حين إن شاء الله . ولكننا نقول كمثال : أنت ترجو أشياء كثيرة بعد الموت . ترجو حياة أخرى دائمة ، وعشرة مع الملائكة والقديسين . وترجو رؤية الرب فى الفردوس . وترجو القيامة من الموت بجسد روحانى غير قابل للفساد (١كو ١٥) . وترجو النعيم الأبدى بعد القيامة العامة . وأنت تثق بوجود كل هذه الأمور ، ثقة يقينية كاملة لا شك فيها ، دون أن ترى من كل ذلك شيئاً ... إنه الإيمان .",{"h":"الإيمان فوق مستوى الحواس :"},{"h":"وهنا نرى أن الإيمان يرتفع فوق مستوى الحواس :"},"إنه لا يتعارض مع الحواس ، إنما هو مستوى أعلى من مستوى الحواس . وهو قدرة أعلى من قدرة الحواس التى لها نطاق معين لا تتعداه . فالحواس المادية تدرك الماديات . غير أن هناك أشياء غير مادية ، تخرج عن نطاق قدرة الحواس المادية . وحتى قدرة الحواس بالنسبة للأشياء المادية ، هى محدودة أيضاً . وكثيراً ما تستعين الحواس بعديد من الأجهزة لمعرفة أشياء مادية أدق من أن تدركها حواسنا الضعيفة . فكم بالحرى إذن الأمور غير المادية ، التى قال عنها الرسول إنها « أمور لا ترى » ؟ !"],"16":["إن ما يرى بالعين المادية يدخل فى نطاق (العيان) وليس الإيمان (٢كو ٥ : ٧) . فالروح مثلاً لا ترى ولا تدرك بالحواس المادية . سواء كانت روح بشر أو ملائكة . وعدم إدراك الحواس لها لا يعنى عدم وجودها . إنما يعنى أن قدرة الحواس محدودة . لها نطاق معين تعمل فيه لا يصل إلى مستوى الروح .",{"h":"والله روح (يو ٤ : ٢٤) . لذلك فإنه لا يدرك بالحواس المادية ."},"لذلك فإننى عجبت من رائد الفضاء الذى قال إنه صعد إلى السماء ولم ير الله ! وقد ظن فى تهكمه أنه يمكن أن يرى الله بهذه العين الجسدية القاصرة التى لا ترى كثيراً من الماديات ! كما أن الله فى كل مكان ، فى الأرض وفى السماء وما بينهما ، ولا يحده مكان . فإن كان لم ير الله على الأرض ، فلن يراه أيضاً فى السماء ، ولا فى أى موضع آخر ، لأن الله لا يُرى إلا بالإيمان ... تراه بالروح (١كو ٢ : ١٠) .","عدم رؤيتك لله بعينك ، لا يعنى أن الله غير موجود . إنما تفسير ذلك هو أن عينك قاصرة . ومهما قويت ، فإن لها نطاقاً محدوداً تعمل فيه ، هو نطاق الماديات . ولذلك قلنا إن الإيمان أعلى من مستوى الحواس .",{"h":"فى العهد القديم ، كان مستوى الناس ضعيفاً ، فكان تأثير الحواس فى الدرجة الأولى والأهم ، لذلك كان الله يظهر لهم فى السحاب والضباب والنار ."},"لقد كلمهم من على الجبل وسط البروق والرعود ، والجبل يدخن ، وقد صعد دخانه كدخان الأتون . وارتجف كل الجبل جداً . وكان سحاب ثقيل على الجبل ، وصوت بوق شديد ، فارتعد كل الشعب الذى فى المحلة (خر ١٩ : ١٦ ـ ١٨) . وكان المنظر هكذا مخيفاً حتى قال موسى أنا خائف ومرتعد (عب ١٢ : ٢١) .","بهذا الأسلوب كانوا يفهمون قوة الله وأهمية الوصية المعطاة لهم . أما فى حياة الإيمان ، فإن القلب يفهم قوة الله فى غير حاجة مطلقاً إلى هذا الإعتماد الكبير على الحواس . إن الإيمان مستوى أعلى من الحواس ، لا يعتمد عليها ، ولا يحتاج إليها ."],"17":[{"h":"والإيمان مستوى أعلى من العقل :"},"إن العقل قد يوصلك إلى بداية الطريق . أما الإيمان فيكمل معك الطريق إلى أقصاه . الإيمان لا يتعارض مع العقل . ولكنه يتجاوزه إلى مراحل أبعد بما لا يقاس ، لا يستطيع العقل بمفرده أن يصل إليها .","وما لا يدركه العقل ، نسميه « غير المدرك » . ونحن نصف الله بأنه « غير مدرك » . لأنه أيضاً غير محدود . بينما العقل البشرى محدود ، ولا يدرك سوى الأمور المحدودة ، التى تدخل فى نطاقه . العقل يستطيع أن يوصلك إلى مجرد معرفة الله ، وإلى بعض صفاته . ولكن بالإيمان « الروح يفحص كل شىء ، حتى أعماق الله » (١كو ٢ : ١٠) . وبالنسبة إلى المؤمن ، يكشف الله له ذاته . أو يكشف له ما تحتمل الطبيعة البشرية أن تدركه ...",{"h":"العقل قد لا يدرك أشياء كثيرة ، ولكنه يقبلها ."},"العقل ليس من طبيعته أن يرفض كل ما لا يدركه . بل حتى فى المحيط المادى فى العالم الذى نعيش فيه ، توجد مثلاً مخترعات كثيرة لا يدركها إلا المتخصصون . ومع ذلك فالعقل العادى يقبلها ، ويتعامل معها ، دون أن يدرك كيف تعمل ، وكيف تحدث . والموت يقبله العقل ، ويتحدث عنه ، ومع ذلك فهو لا يدركه ، ولا يعرف كيف يحدث .","فإن كان العقل يقبل أموراً كثيرة فى عالمنا ، وهو لا يدركها . فطبيعى لا يوجد ما يمنعه من قبول أمور أخرى أعلى من مستوى هذا العالم .",{"h":"العقل لا يدرك (المعجزة) كيف تتم . ولكنه يقبلها ويطلبها ، ويفرح بها ."},"لقد سميت المعجزة معجزة ، لأن العقل يعجز عن إدراكها وعن تفسيرها . ولكنه يقبلها بالإيمان ... الإيمان بوجود قوة غير محدودة ، أعلى من مستواه ، يمكنها أن تعمل ما يعجز العقل عن إدراكه . وهذه القوة هى قوة الله القادر على كل شىء .",{"h":"إننا نحترم العقل . ولكننا فى نفس الوقت ندرك حدود النطاق الذى يعمل فيه . ولا نوافق العقل المغرور الذى يريد أن يعى كل شىء ، رافضاً كل ما هو فوق مستوى إدراكه ."}],"18":["ينبغى للعقل أن يتضع ، ويعرف مستواه ، « ولا يرتئى فوق ما ينبغى » (رو ١٢ : ٣) . وفى الأمور التى هى فوق إدراكه ، يجب أن يسلم قياده للإيمان .","أما إن أراد العقل أن يحطم كل ما لا يدركه ، فإنه سيحطم نفسه أخيراً ، ويفقد الإيمان . ويحصر نفسه فى دائرة ضيقة جداً ، هى دائرة إدراكه المحدود .","والذين يسلكون هكذا ، إعتاد البعض أن يسميهم (العقلانيون) ، لأنهم يعتمدون على العقل وحده ، دون الإيمان ودون الروح !",{"h":"إن العاقل يمكنه أن يصل إلى الله . أما العقلانى فلا يصل ."},"والمؤمنون عاقلون ، ويحترمون العقل ، ويستخدمونه أيضاً فى الأمور الدينية واللاهوتية . ويوجد بين المؤمنين فلاسفة وحكماء وأشخاص على مستوى عال من الفكر والذكاء . ولكنهم على الرغم من كل هذا ، لا يمزجون العقل بالغرور ، ولا يثقون بقدرة العقل على إدراك كل شىء . وإنما فى بساطة واتضاع ، يعترفون أن عقولهم محدودة ، وقاصرة عن إدراك كل ما يحيط بالله غير المدرك ... وبالإيمان تقبل قلوبهم وعقولهم ما هو فوق مستوى العقل ...",{"h":"العقل البسيط المتواضع ، هو الذى يقبل الإيمان ، والمعجزة ."},"نقصد بعبارة (المتواضع) إنه لا يعتز بإدراكه الخاص . ولا يحطم كل ما هو فوق إدراكه . ونقصد بعبارة (البسيط) ، العقل الذى لا يعقد الأمور ، ولا يصر على إدخال كل شىء فى حدود معامله ومقاييسه الخاصة .","ولعلنا سنعود إلى هذه النقطة ، حينما نتحدث عن (بساطة الإيمان) .",{"h":"الإيمان ليس هو مجرد تلاوة قانون الإيمان ، إنما هو حياة نحياها ."},"إن كنت تحيا فى الإيمان ، والإيمان له ثماره فى حياتك العملية ، فإنك تستطيع أن تختبر إيمانك بالفضائل التى تبدو واضحة فى حياة المؤمن ، وهى عديدة ... وبها تنفذ قول الرسول « إمتحنوا أنفسكم : هل أنتم فى الإيمان ؟ إختبروا أنفسكم » (٢كو ١٣ : ٥) ."],"19":[{"h":"الإيقان بأمور لا ترى"},"قال الرسول فى معنى الإيمان إنه « الثقة بما يرجى ، والإيقان بأمور لا ترى » (عب ١١ : ١) . ونود أن نعرف تفسير هذه العبارة .",{"h":"الإيقــان :"},"أى التأكد الشديد ، والثقة ، والعقيدة التى لا تعرف شكاً . ليس الأمر مجرد فكر أو رأى ، أو معلومات نتيجة قراءة أو سماع . إنما يقين أكيد بوجود هذه الأمور التى لا ترى .",{"h":"وهنا يبدو الفرق بين رجال الإيمان ، ورجال البحوث العلمية ."},"أصحاب البحوث العلمية ، لا تدخل فى نطاق عملهم كل تلك الأمور التى لا ترى . وهم لا يكونون فى حالة يقين من شىء إلا إذا فحصوه تماماً بكل أجهزتهم ومقاييسهم العلمية . وعلى نفس هذا المنهج كل أصحاب المذاهب المادية .","أما المؤمنون فهم ليسوا كذلك . إنهم يتبعون قول الرب « طوبى لمن آمن دون أن يرى » (يو ٢٠ : ٢٩) .","المؤمن يقبل مثلاً فكرة الخلق من العدم . أما الباحث العلمى ، فترفض أبحاثه هذا الأمر ، كما ترفض أيضاً أن يشبع من خمس خبزات خمسة آلاف رجل (غير النساء والأطفال) ، وتفيض عنهم إثنتا عشرة قفة مملوءة . أما المؤمن فيقبل كل هذا ...",{"h":"المؤمن يقبل أولاً فكرة الله القادر على كل شىء . ثم فى دائرة يقينه من جهة هذه القدرة غير المحدودة ، يقبل كل شىء ..."},"وهكذا يريح نفسه من شكوك غير المؤمن ومن بحوثه وفحوصه الكثيرة . وهو ليس فقط يقبل ما لا يرى ، ويكون موقناً بوجود غير المرئيات ، بل إنه أكثر من هذا يعايش ما لا يرى ، ويركز فيه كل تفكيره وكل عواطفه ، حسبما قال الرسول « غير ناظرين إلى الأمور التى ترى ، بل إلى التى لا ترى ، لأن التى ترى وقتية . أما التى لا ترى فأبدية » (٢كو ٤ : ١٨) ."],"20":["ولعلك تسأل : كيف ننظر ما لا يرى ؟ فأقول بالإيمان .","ما هى إذن هذه الأمور التى لا ترى ؟ لعل فى مقدمتها الله نفسه ، وصفاته ، وعمله ، وكل ما يتعلق به .",{"h":"١ ـ الله ، وصفاته ، وعمله :"},"إن الله لا يُرى ، وقد قال القديس يوحنا الإنجيلى : « الله لم يره أحد قط ... » (يو ١ : ١٨) . حقاً من يستطيع أن يرى اللاهوت ؟ ! لا أحد . ومع ذلك فأنت تؤمن به من كل قلبك ، وبكل ثقة . ولا يعتمد هذا الإيمان مطلقاً على الحواس . أو قل إنك تراه بتلك الحواس الروحية المدربة (عب ٥ : ١٤) . تلك الحواس غير المادية التى تدربت أن ترى ما لا يرى . ولنا أمثلة على ذلك من الكتاب :",{"h":"يقول داود النبى « تقدمت فرأيت الرب أمامى فى كل حين ، لأنه عن يمينى فلا أتزعزع » (مز ١٥) ."},"فكيف رأى الرب أمامه وعن يمينه كل حين ؟ لا شك أنه رآه بعين الإيمان . وفى بعض الترجمات يقول « جعلت الرب أمامى كل حين » . أى أنه ناظر إليه باستمرار ، ناظر إلى ما لا يرى ، مركزاً فيه فكره وشعوره .",{"h":"وبنفس المعنى يقول إيليا النبى « حى هو رب الجنود الذى أنا واقف أمامه » (١مل ١٨ : ١٥) ."},"فكيف شعر أنه واقف أمام الرب ؟ وكيف كان يرى الرب أمامه فى كل حين ؟ ... ليس بالحواس الجسدية طبعاً ، لأن الحواس الجسدية ليست هى التى تحرك قلب المؤمن . بل إن الرب أمامه بالإيمان . وهو بالإيمان يرى ما لا يرى .",{"h":"إن كنت فى الإيمان ، فلا بد ستثق إن الله أمامك فى كل حين ، وتتصرف وفق هذا الإيمان : إنه يراك ويسمعك ..."},"وإن عشت فى الإيمان ، فستثق أن الله فى وسط شعبه ، حسب وعده الصادق « ... هناك أكون فى وسطهم » (متى ١٨ : ٢٠) ، « ها أنا معكم كل الأيام وإلى انقضاء الدهر » (متى ٢٨ : ٢٠) . إنك لست تراه بعينك الجسدية ، ولكنك تؤمن تماماً أنه فى وسطنا . لست محتاجاً أن ترى بعينيك لكى تصدق . فأنت تؤمن دون أن ترى . أو ترى ما لا يرى ."],"21":[{"h":"ما هى حياتنا الروحية يا إخوتى ؟ إنها ليست سوى انتقال من نطاق المحسوسات والمرئيات إلى نطاق ما لا يرى ."},"ونحن نعيش فى ما لا يرى ، بملء الثقة أنه موجود أمامنا . وهذا هو الفرق بين المؤمن وغير المؤمن .","غير المؤمن يريد أن يرى كل شىء بعينيه ، وإلا فإنه لا يصدق .","أما المؤمن فإنه لا يجعل من عينيه حكماً على كل ما يؤمن به ... ولا كل حواسه ، ولا المعلومات الظاهرة . بل إن قلبه يوقن بوجود أمور لا يراها بعينيه ... إن اعتماد الإنسان على عينيه لكى يصدق ، أمر وبخ الرب عليه تلميذه توما قائلاً له « لا تكن غير مؤمن بل مؤمناً » « ألأنك رأيتنى يا توما آمنت ؟ ! طوبى للذين آمنوا ولم يروا » (يو ٢١ : ٢٧ ، ٢٩) .","قلنا إنه من ضمن الإيقان بأمور لا ترى ، الإيمان بالله ... ولكننا لا نعنى بهذا مجرد الإيمان بوجود الله ، وإنما الإيمان أيضاً بصفاته وبعمله .","فتؤمن مثلاً بصلاح الله وخيريته . وبأنه لا يصنع إلا خيراً . وتؤمن أنه ضابط الكل ، يرقب كل شىء وكل أحد . وتؤمن أن الله قادر على كل شىء ، وأن « غير المستطاع عند الناس ، مستطاع عند الله » (لو ١٨ : ٢٧) . وتؤمن بمحبة الله لك ولغيرك ...","كل هذه الصفات ، لا تراها . ولكن تؤمن بوجودها ، وتؤمن برعاية الله للكون ، وحفظه له جملة ، ولكل فرد فيه على حدة ... وتؤمن أن الله يعمل ، سواء رأيت عمله أو نتائج عمله ، أو لم تر شيئاً ...",{"h":"٢ ـ ومن الأشياء التى لا ترى أيضاً مواعيد الله ."},"وقد حسب من رجال الإيمان أولئك الذين « لم ينالوا المواعيد ، بل من بعيد نظروها وصدقوها وحيوها ، وأقروا بأنهم نزلاء وغرباء على الأرض » (عب ١١ : ٣) . وهؤلاء نظروا المواعيد بالإيمان ، إذ صدقوا ما قيل لهم من قبل الرب ...","ومن هذه المواعيد « ما أعده الله للذين يحبونه » وكلها من الأمور التى لا تُرى ، إذ قال عنها الرسول « ما لم تره عين ، ولم تسمع به أذن ، ولم يخطر على قلب بشر » (١كو ٢ : ٩) ."],"22":[{"h":"ومن الأمور التى لا ترى ، إنذارات الله ."},"لقد آمن نوح بكلام الرب أنه سيحدث طوفان ، مع أن كلمة (طوفان) هذه ، كانت جديدة على سمعه وعلى معرفته . ولم يحدث طوفان من قبل فى أيامه ، ولا فى أيام سابقيه . ولكنه آمن بحدوث هذا الشىء لم يره أحد من قبل . وظل سنوات يعمل فى بناء الفلك ، محتملاً استهزاء الناس به وبفلكه وتهكمهم ... وكانت سنوات من الإيمان .","ولذلك اعتبر أبونا نوح من رجال الإيمان لأنه صدق إنذار الله بالطوفان . وبالإيمان رأى هذا الطوفان قائماً قبل أن يكون . ولذلك دخل الفلك هو وبنوه ونساؤهم . وكما قال معلمنا القديس بولس الرسول « بالإيمان نوح ، لما أوحى إليه عن أمور لم تر بعد ، خاف فبنى فلكاً لخلاص بيته ... » (عب ١١ : ٧) . بينما معاصروه لم يصدقوا إنذار الله ، ولم يؤمنوا بصدق كلام الله فهلكوا ...","ونفس الوضع نقوله عن أبينا لوط وأهل سدوم . هو صدق إنذار الله قبل أن يحدث . مع أنها كانت المرة الأولى التى تنزل فيها نار من السماء ، كما كانت المرة الأولى التى يحدث فيها طوفان فى أيام نوح .","أما أهل سدوم الذين لم يؤمنوا بإنذار الله فقد هلكوا ، كما هلك الذين لم يؤمنوا بإنذار الله أيام نوح .","وهوذا إنذارات الله الخاصة بالأبدية وبالدينونة قائمة أمامنا ، ومع ذلك فالناس مازالوا فى شرورهم وأخطائهم ، كأن الله لم يقل شيئاً ... لا مخافة الله فى قلوبهم ، ولا خشية الأبدية ، ولا حرصاً ، ولا توبة ...","تحدثنا عن الله وعن صفاته وعمله ، وعن مواعيده وإنذاراته ، ضمن الأمور التى لا ترى . ونضيف على ذلك :",{"h":"٣ ـ سكنى الروح وعمله فينا ، من الأمور التى لا ترى :"},"صموئيل النبى صب من قنينة الدهن على الصبى داود ، فحلّ عليه روح الرب (١صم ١٦ : ١٣) . ولم ير أحد روح الرب وهو يحل عليه . ولكن هكذا كان . إنه من الأمور التى لا ترى"],"23":["وكان الرسل يضعون أيديهم على الناس ، فيحل عليهم الروح القدس (أع ٨ : ١٧) . وما كان أحد يرى الروح القدس وهو يحل على الناس . ثم أصبح الروح القدس ينال بالمسحة المقدسة (١يو ٢ : ٢٠ ، ٢٧) . وعرفت هذه المسحة باسم (الميرون) . ولم يكن أحد يرى الروح ، إنما ثماره تظهر فى الحياة .","أنت تعرف تماماً أن هناك قوة خفية تعمل فيك وتعمل معك ، دون أن تراها ، هى التى قال عنها الرب « ولكنكم ستنالون قوة متى حل الروح القدس عليكم » (أع ١ : ٨) . هذه القوة ، قوة الروح هى التى تعمل فيك كل خير ، وتساعدك فى كل خدمة ، وتحميك من كل خطية ...",{"h":"هنا ونقول إن حياتنا كلها تصبح شركة مع الروح القدس (٢كو ١٣ : ١٤) ."},"ما هذه الشركة ؟ وكيف تحدث ؟ وكيف نصبح شركاء للطبيعة الإلهية فى العمل ؟ إن هذا من الأمور التى لا ترى . لا نراها ولكن نؤمن بها . نؤمن بروح الله العامل فى الكنيسة ، الساكن فيها .","هوذا الرسول يقول « أما تعلمون أنكم هيكل الله ، وروح الله يسكن فيكم » (١كو ٣ : ١٦) ، « أم لستم تعلمون أن جسدكم هو هيكل للروح القدس الذى فيكم ، الذى لكم من الله » (١كو ٦ : ١٩) .","وسكنى الروح فينا أمر لا نراه . قد نرى ثماره فقط . أما نفس السكنى فلا نراها . والروح لا تراه .","ومن عمل الروح فينا قول الرب لنا عن الوقوف أمام الولاة والملوك « لأنكم تعطون فى تلك الساعة ما تتكلمون به . لأن لستم أنتم المتكلمين ، بل روح أبيكم يتكلم فيكم » (متى ١٠ : ١٩ ، ٢٠) .","كيف يتكلم روح الله فينا ؟ إن هذا من الأمور التى لا ترى .",{"h":"٤ ـ وعمل النعمة فينا ، من الأمور التى لا ترى :"},"تأتينا زيارات من النعمة ، تشعلنا بمحبة الله . لا نراها ولكن نحسها . ولا شك أن عمل النعمة فينا هو من الأمور التى لا ترى ."],"24":["يقول القديس يوحنا الإنجيلى « أما النعمة والحق فبيسوع المسيح صارا » (يو ١ : ١٧) . فما هى هذه النعمة العاملة فينا ؟ ما هى هذه النعمة التى عاش بها القديس بولس الرسول فقال « ... ولكن بنعمة الله ، أنا ما أنا . ونعمته المعطاة لى لم تكن باطلة » (١كو ١٥ : ١٠) . ويقول عنا جميعاً « فإن الخطية لن تسودكم ، لأنكم لستم تحت الناموس ، بل تحت النعمة » (رو ٦ : ١٤) . ويقول لتلميذه تيموثاوس الأسقف « فتقو أنت يا إبنى بالنعمة التى فى المسيح يسوع » (٢تى ٢ : ١) .","نحن لا نرى هذه النعمة بعيوننا الجسدية ، فهى من الأمور التى لا ترى . ولكننا نلمسها فى حياتنا . وعمل نعمة الله فينا هو فوق الحواس . ونحن نتقبل هذه النعمة من الله . ونأخذها بركة من الكنيسة التى تردد لنا قول القديس بولس الرسول « نعمة ربنا يسوع المسيح ، ومحبة الله ، وشركة الروح القدس تكون مع جميعكم ، آمين » (٢كو ١٣ : ١٤) .","إن هذا يجعلنا ننتقل إلى نقطة أخرى هى البركة :",{"h":"٥ ـ البركة أيضاً هى من الأمور التى لا ترى :"},"سواء البركة التى من الله نفسه مباشرة ، أو بركة الله التى تأتى عن طريق الوالدين ، أو من الكنيسة من الأب الكاهن . كلها أمور لا ترى .","لقد قال الله لأبينا ابرآم أبى الآباء « أباركك ، وأعظم إسمك . وتكون بركة . وأبارك مباركيك ... وتتبارك فيك جميع قبائل الأرض » (تك ١٢ : ٢ ، ٣) . لقد رأى ابرآم ثمار هذه البركة فى حياته . ولكن البركة نفسها : ما هى ؟ إنها من الأمور التى لا ترى .","واسحق بارك يعقوب إبنه ، فصار مباركاً . وبكى عيسو لأنه لم يحصل على هذه البركة (تك ٢٧) . ويعقوب بارك افرايم ومنسى قائلاً « الملاك الذى خلصنى من كل شر يبارك الغلامين » (تك ٤٨ : ١٦) . وصار الغلامان مباركين . ولكن افرايم صار أكثر بركة من أخيه ، لأن أبانا يعقوب وضع عليه يده اليمنى (تك ٤٨ : ١٧ ـ ٢٠) .","ما هى هذه البركة ؟ وكيف سرت من يد إسحق ومن يد يعقوب ؟ وكيف"],"25":["سرت من أيدى الآباء الرسل ؟ وكيف تسرى من أيدى خلفائهم ومن رجال الله جميعاً ، كما يروى لنا الكتاب ... ؟","إنها كلها أمور لا ترى . ونحن نؤمن بالبركة مع أنها لا ترى ، ونسعى إلى طلبها ونوالها . ونأخذها من أيدى الآباء والأمهات ومن الآباء الكهنة ومن كل رجال الله المباركين . ونعرف تماماً أن ابرآم كان بركة للعالم حسب قول الرب . وأن يوسف الصديق كان بركة فى بيت فوطيفار وبركة فى كل أرض مصر ، وأن إيليا النبى كان بركة فى بيت أرملة صرفة صيدا ...","نقول هذا كله ، ونحن لا نستطيع وضع معنى محدد للبركة ، فهى أوسع بكثير من الألفاظ المحدودة . وهى أمر لا يرى . نرى ثماره فقط . ولكن البركة نفسها . من يستطيع أن يراها ويشخصها ؟ !","كيف سرت البركة من يد السيد المسيح إلى الخمس خبزات والسمكتين ، فصار هذا الطعام البسيط كافياً لعدة آلاف من الناس ، وفاض عنهم إثنتا عشرة قفة مملوءة ؟ كيف حدث هذا الأمر ؟ وما نوعيته ومفعوله بالضبط ... كلها أمور لا ترى ...",{"h":"٦ ـ ومن ضمن الإيمان أيضاً بما لا يرى ، الإيمان بوجود الملائكة وعملهم :"},"نحن نؤمن بوجود الملائكة ، والملائكة أرواح لا ترى . وربما لا نكون قد رأينا ملاكاً فى حياتنا كلها . ومع ذلك نؤمن أنهم حولنا وأن « ملاك الرب حال حول خائفيه وينجيهم » (مز ٣٤ : ٧) . ونوقن بأن الملائكة تملأ الكنيسة . ونثق أنهم معنا فى كل مواضعنا « أليسوا جميعهم أرواحاً خادمة ، مرسلة للخدمة لأجل العتيدين أن يرثوا الخلاص » (عب ١ : ١٤) .",{"h":"كثيرون يفرحون حينما يرون العذراء فى رؤيا ، أو يرون قديسين ."},"ولكن أعظم من هذا أن تؤمن بأن كل هؤلاء حولك ، دون أن تراهم . ليس من الضرورى أن يرسل لك الله حمامة بيضاء أثناء حضورك إجتماعات المساء فى الكنيسة ... إنما أنت تؤمن ـ دون أن ترى ـ أن الكنيسة مملوءة بأرواح الملائكة . وترفرف عليها أرواح القديسين الذين يرسلهم الله لخدمة البشر ..."],"26":["إن جيحزى تلميذ أليشع ، خاف لما رأى الأعداء عيطين بالمكان ...",{"h":"ولكن أليشع ، الرجل المفتوح العينين ، فكان يرى الملائكة يدافعون عن المدينة ضد هؤلاء الأعداء ."},"لذلك طمأن غلامه قائلاً له « لا تخف ، لأن الذين معنا أكثر من الذين علينا ... » (٢مل ٦ : ١٦) . وصلى من أجله لكى يفتح الرب عينيه فيرى ، إذ كان جيحزى ليس له الإيقان بأمور لا ترى .",{"h":"٧ ـ ومن الإيقان بما لا يرى أيضاً : الإيمان بالروح ، والعالم الآخر :"},"نحن لا نرى الروح . ولكننا نوقن بوجودها . وحينما يموت إنسان ، نقول إن روحه فارقت جسده . ونحن لم نر هذه الروح تفارق الجسد .","كذلك الإيمان أيضاً يشمل مصير هذه الروح ، فى الفردوس أو الجحيم . ويشمل أيضاً عودة هذه الروح إلى الجسد بالقيامة . ومصير هذا الإنسان القائم من الأموات فى الأبدية بعد الدينونة العامة ...","وكل هذه الأمور : الروح ـ القيامة ـ الأبدية ـ الدينونة (الحساب) ـ الفردوس ـ النعيم ـ الجحيم ... كلها أمور لا ترى . لذلك فالإيقان بوجودها جميعاً يدخل فى نطاق الإيمان . حقاً إن العالم الآخر بكل ما فيه ، لا يتحدث عنه أحد إلا بالإيمان . والذى يؤمن بالحياة بعد الموت ، إنما يوقن بأمور لا ترى .",{"h":"٨ ـ لقد آمن الناس بمجىء المسيا ، دون أن يروه :"},"حتى المرأة السامرية ، قالت للرب « أنا أعلم أن المسيا ـ الذى يقال له المسيح ـ يأتى . فمتى جاء ذاك يخبرنا بكل شىء » (يو ٤ : ٢٥) .","وهكذا كان الجميع موقنين بمجىء المسيا ، حسب وعد الرب . وكانوا ينتظرونه بكل شوق . ويعرفون ما قاله اشعياء النبى « ها العذراء تحبل وتلد ابناً ، وتدعو إسمه عمانوئيل » (اش ٧ : ١٤) . وما كانوا قد رأوا من قبل عذراء تلد ، ومع ذلك آمنوا بهذا الأمر فيما بعد ...","ويشبه الإيمان الذى كان به أهل العهد القديم ينتظرون مجىء المسيا ، هكذا"],"27":["نحن فى العهد الجديد ننتظر مجىء الرب ثانية ، على السحاب ، حسب وعد الرب (متى ٢٤ ، ٢٥) ، وحسب بشرى الملاكين للتلاميذ (أع ١ : ١١) .","لم نر الرب من قبل على سحاب السماء مع ربوات قديسيه ، فى مجد أبيه ، ومعه ملائكته القديسون . ولكننا نؤمن بمجيئه فى هذا المنظر الذى لم نره من قبل . لأن الإيمان هو الإيقان بأمور لا ترى .",{"h":"٩ ـ الفداء أيضاً هو من الأمور التى لا ترى :"},"فى الفداء ، من محبة المسيح لنا ، حمل جميع خطايانا ومات عنها « كلنا كغنم ضللنا . ملنا كل واحد إلى طريقه . والرب وضع عليه إثم جميعنا » (اش ٥٣ : ٦) . وهكذا قال عنه القديس يوحنا المعمدان « هذا هو حمل الله الذى يرفع خطية العالم » (يو ١ : ٢٩) . وقال القديس يوحنا الرسول « وهو كفارة لخطايانا ، ليس لخطايانا فقط ، بل لخطايا كل العالم أيضاً » (١يو ٢ : ٢) . وقال القديس بولس الرسول « مسامحاً لكم بجميع الخطايا ، إذ محا الصك الذى علينا » (كو ٢ : ١٣ ، ١٤) . وقال أيضاً « عاملاً الصلح بدم صليبه » (كو ١ : ٢٠) .","ونحن نرى الصليب فقط ، وقد يراه البعض عاراً ! ! أما ما فى الصليب من حب ، ومن فداء وكفارة ، ومن مغفرة ومحو للصك المكتوب ، وحمل خطايا العالم ، وأيضاً ما فى الصليب من عمل المصالحة ... فكل هذه أمور لا ترى . نراها نحن بالإيمان ...","بطرس الرسول ـ قبل الإيمان بكل هذا ـ ما كان يرى فى الصليب سوى الضياع والعار ... ! لذلك قال « حاشاك يارب » (متى ١٦ : ٢٢) . فانتهره الرب ، إذ لم يكن يرى الأمور التى لا ترى ...","إن الصليب كان يمثل عمق إحسانات الرب إلينا . ولكن الكتبة والفريسيين لم يروا هذا ، لأن عيونهم ما كانت تبصر . لأنهم « لو عرفوا لما صلبوا رب المجد » (١كو ٢ : ٨) .","إن هذا يقودنا إلى نقطة أخرى وهى :"],"28":[{"h":"١٠ ـ إحسانات الله الخفية ، هى من الأمور التى لا ترى :"},"إننا نشكر الله فقط على إحساناته التى نراها أو التى نعرفها . ولكن هناك إحسانات أخرى لا ترى ينبغى أن نشكره عليها أيضاً . ولذلك عندما ندخل بالإيمان فى حياة التسليم ، ندخل تلقائياً فى حياة الشكر الدائم . كما قال الرسول « شاكرين فى كل حين ، على كل شىء » (أف ٥ : ٢٠) .",{"h":"وفى هذا الشكر الدائم ، نشكر على التجارب أيضاً ..."},"لأننا نشعر أنه توجد فيها إحسانات خفية من الله ، نحن لا نبصرها . وإن أبصرناها ، لا بد أن نغنى مع القديس يعقوب الرسول قائلين « إحسبوه كل فرح يا إخوتى ، حينما تقعون فى تجارب متنوعة » (يع ١ : ٢) .","وبهذا نرى الإيمان يعطى معنى روحياً للألم ، الألم الذى يسمح الله به من أجل بركات معينة كامنة فيه ، هى من الأمور التى لا ترى ، ولكننا نتقبلها بالإيمان ، واثقين من محبة الله الصانع الخيرات ، وواثقين من قول الكتاب « كل الأشياء تعمل معاً للخير ، للذين يحبون الله » (رو ٨ : ٢٨) .",{"h":"١١ ـ وجود الله فى حياتنا ، وقوته العاملة فينا ، من الأمور التى لا ترى :"},"ما أجمل قول الرب لأبينا يعقوب « وها أنا معك . وأحفظك حيثما تذهب . وأردك إلى هذه الأرض » (تك ٢٨ : ١٥) ... كان الرب معه يحفظه حيثما يذهب ... ولم يكن يرى الرب وهو معه . ولكن من المريح للنفس أن يشعر الإنسان بهذا ، ويوقن به ، فيحيا فى اطمئنان دائم وفى فرح ...","ولم يكن هذا الأمر ميزة لأبينا يعقوب فقط ، بل أن الرب يقول « ها أنا معكم كل الأيام وإلى انقضاء الدهر » (متى ٢٨ : ٢٠) .",{"h":"إن شعورنا بوجود الله معنا ، يشعرنا بقوة إلهية ترافقنا وتحفظنا ."},"هذه القوة هى العاملة فيك ومعك منذ أن تدخل فى شركة الروح القدس ، فيشترك الروح القدس معك فى العمل . وهكذا فى الكنيسة الأولى كنا نرى أن ملكوت الله قد أتى بقوة (مر ٩ : ١) ، « وبقوة عظيمة كان الرسل يؤدون الشهادة"],"29":["بقيامة الرب يسوع ، ونعمة عظيمة كانت على جميعهم » (أع ٤ : ٢٣) . قيل عن القديس اسطفانوس أول الشمامسة إنه كان « مملوءاً إيماناً وقوة » (أع ٦ : ٨) ، وإنه وقف ضد عدة مجامع « ولم يقدروا أن يقاوموا الحكمة والروح الذى كان يتكلم به » (أع ٦ : ١٠) . هذه هى القوة فى الإيمان . أما الذى يؤمن ، ولكنه يخاف من إعلان إيمانه ، فهو إنسان ضعيف الإيمان ، لا يؤمن بقوة الله العامل معه .","المرأة نازفة الدم ، كانت تشعر أنها لو لمست ولو هدب ثوب المسيح ، ستخرج قوة من المسيح تشفيها . وقد كان (متى ٢٠ : ٢١ ، لو ٨ : ٤٦) .",{"h":"وأنت إن آمنت بقوة الرب ، والتصقت به ، ستنالها ."},"ليكن لك هذا الإيمان وهذا الشعور ، فى كل تفاصيل حياتك : فى خدمتك وفى صلاتك ، وفى عملك . كما قال القديس أنطونيوس عن أبا مقار الكبير « إن قوة عظيمة تخرج من هاتين اليدين » .",{"h":"حتى فى حالة سقوطك : آمن أن هناك قوة ستخلصك ."},"إن كنت أنت أضعف من الشياطين ، آمن أن الله الذى يحبك هو أقوى منهم ، وهو قادر أن يخلصك من الخطية ، وفى قوة إيمان تضرع إلى الله أن يمنحك القوة التى تنتصر بها فى حياتك الروحية ، واطلب إليه أنه هو « يقودك فى موكب نصرته » (٢كو ٢ : ١٤) .","حتى إن طالت بك المدة ، آمن أن قوة الرب ستصلك ولو فى المزيع الأخير ، لكى تنقذك . قوة الرب هذه غير مرئية ، ولكنها موجودة ، ومستعدة أن تعمل مع كل الذين يطلبونها مؤمنين .","عليك أن تبصر أن هذه القوة تصحبك ، ليس فى حياة التوبة فقط ، إنما فى كل نواحى حياتك الروحية ... حتى إن تكلمت ، يشعر الناس بقوة الكلمة ومفعولها ...",{"h":"إن المؤمن هو إنسان قوى ، يؤمن بقوة الله العاملة فيه ."},"هوذا القديس بولس الرسول يقول « أتعب أيضاً مجاهداً ، بحسب عمله الذى يعمل فىّ بقوة » (كو ١ : ٢٩) . ويقول أيضاً عن الله « القادر أن يفعل فوق كل شىء ، أكثر جداً مما نطلب أو نفتكر ، بحسب القوة التى تعمل فينا » (أف ٣ : ٢٠) ."],"30":["وبفضل هذا الإيمان بقوة الله العاملة ، التى قد لا نراها ولكن نؤمن بها ، عاش القديس بولس فى ملء الثقة ، وأمكنه أن يقول :",{"h":"« أستطيع كل شىء فى المسيح الذى يقوينى » (فى ٤ : ١٣)"},"عبارة كلها قوة ، وكلها إيمان ، وكلها ثقة بعمل الله . ونحن نسأل : هل هذه العبارة هى من شأن قديس عظيم فقط مثل بولس الرسول ؟ فيجيبنا الرب نفسه « كل شىء مستطاع للمؤمن » (مر ٩ : ٢٣) .","لعل هذه القوة هى اختبار لحياتنا الروحية : هل نحن فى الإيمان ؟","إنها قوة نسعد بها فى حياتنا ، ونحيا مطمئنين .","فى حياتنا أيضاً داخل الكنيسة ، نسعد بأمور كثيرة لا ترى ...",{"h":"١٢ ـ من الأمور التى لا ترى ، ما يحدث فى المعمودية :"},"يقول بولس الرسول « لأن جميعكم الذين اعتمدتم للمسيح ، قد لبستم المسيح » (غل ٣ : ٢٧) . حقاً ما أعجب هذا السر ! من رآه ؟ ! إنه من الأمور التى لا ترى . وقال حنانيا الدمشقى لشاول الطرسوسى « أيها الأخ شاول ... لماذا تتوانى ؟ قم اعتمد واغسل خطاياك » (أع ٢٢ : ١٦) . من رأى هذه الخطايا وهى تغسل ؟ إنها أمور لا ترى ، نقبلها بالإيمان ، كما قال الرسول « بمقتضى رحمته خلصنا ، بغسل الميلاد الثانى » (تى ٣ : ٥) . هذا الخلاص الذى ننلناه فى غسل الميلاد الثانى ، أمر لم نره ، ولكننا نؤمن به حسب قول الرب « من آمن واعتمد ، خلص » (مر ١٦ : ١٦) .","ثم ما معنى هذا الميلاد الثانى ؟ وما معنى الولادة من فوق ، والولادة من الله . والولادة من الماء والروح ؟ كل هذه التى تحدث عنها الرب بنفسه (يو ٣ : ٣ ـ ٦) . كلها أمور لا ترى فعملية الولادة من الله سرّ لا يرى . نحن نرى الإنسان يغطس فى جرن المعمودية . ولكننا لا نرى كيف يولد من الروح . وطوبى لمن آمن دون أن يرى . لذلك حسن أن الكنيسة أطلقت على هذا الأمر إسم (سر) .","أتريد أن تدخل العقل هنا ؟ العقل قاصر عن أن يدخل ."],"31":["يقول الرسول « مدفونين معه بالمعمودية ، التى فيها أقتم أيضاً معه ... مسامحاً لكم بجميع خطاياكم » (كو ٢ : ١٢) . ويقول نفس المعنى فى الرسالة إلى رومية ، ويضيف بأن إنساننا العتيق قد صلب معه ، وأننا نسلك فى جدة الحياة (رو ٦ : ٣ ـ ٦) . فمن رأى هذا الموت وهذا الدفن ، والقيامة ، والمسامحة بالخطايا ، والحياة الجديدة ، وصلب الإنسان العتيق ... إنها كلها أمور لا ترى . ولكن نؤمن بها ...",{"h":"١٣ ـ سر الأفخارستيا أيضاً ، هو من الأمور التى لا ترى :"},"فيه ترى بالإيمان أن الخبز والخمر اللذين أمامك قد صارا جسد الرب ودمه (بعد صلاة التقديس) . هنا لا تجعل حواسك تحكم ، لأن الحواس الجسدية لا تبصر سوى الأمور التى ترى . أما الحواس الروحية فتستمع إلى قول المسيح « هذا هو جسدى ... هذا هو دمى » (متى ٢٦ : ٢٦ ، ٢٨) ، « من يأكل جسدى ويشرب دمى ، فله حياة أبدية ... لأن جسدى مأكل حق ، ودمى مشرب حق . من يأكل جسدى ويشرب دمى ، يثبت فىّ وأنا فيه » (يو ٦ : ٥٣ ـ ٥٦) .",{"h":"أنا لا أجادل الرب فيما يقوله ، إنما أتقبله فى إيمان ."},"فهذا هو الإيمان « الإيقان بأمور لا ترى » . أما التى تُرى فهى الخبز والخمر . وهكذا يقول القديس بولس الرسول « كأس البركة التى نباركها ، أليست هى شركة دم المسيح . الخبز الذى نكسره ، أليس هو شركة جسد المسيح » (١كو ١٠ : ١٦) . ويقول أيضاً « إذن أى من أكل هذا الخبز ، أو شرب كأس الرب ، بدون استحقاق ، يكون مجرماً فى جسد الرب ودمه ... يأكل ويشرب دينونة لنفسه ، غير مميز جسد الرب » (١كو ١١ : ٢٧ ، ٢٩) .","وكيف نميز أن هذا جسد الرب ، حتى لا ننال دينونة ؟",{"h":"هنا نرتفع فوق مستوى الحواس ، وفوق مستوى العقل ، بالإيمان ."},"عقولنا هى التى تتعبنا حينما نتقبل أسرار الكنيسة . وحواسنا تتعبنا أيضاً . ونحتاج إلى بساطة الإيمان . نصدق ما قاله المسيح . ونصدق ما قاله رسوله القديس بولس الرسول ولا نجادل ."],"32":[{"h":"١٤ ـ وبالإيمان بما لا يرى نتقبل ما فى المسيحية من أسرار :"},"نتقبل (وضع اليد) الذى ناله برنابا وشاول من الرسل ، لكى يفرزا للخدمة (أع ١٣ : ٢ ، ٣) . ووضع اليد الذى ناله تيموثاوس من بولس الرسول (٢تى ١ : ٦) . ونوقن أن فى ذلك سراً .","ونتقبل السلطان الذى أعطاه الرب بقوله « إقبلوا الروح القدس . من غفرتم خطاياه تغفر له . ومن أمسكتم خطاياه أمسكت » (يو ٢٠ : ١٣) ، « كل ما تربطونه على الأرض يكون مربوطاً فى السماء وكل ما تحلونه على الأرض يكون محلولاً فى السماء » (متى ١٨ : ١٨) .","هذا السلطان غير مرئى ، ولكنه سر نراه بالإيمان . إنه ليس لكل أحد ، ولا يأخذه أحد من نفسه بل المدعو من الله كما هرون (عب ٥ : ٤) .","وهكذا فى باقى الأسرار التى لا نراها ، ولكن نؤمن بها ...",{"h":"إن رؤية ما لا يرى ، هى الرؤية الروحية الحقيقية :"},"لعلها هى التى عناها رب المجد بقوله لتلاميذه القديسين « أما أنتم فطوبى لعيونكم لأنها تبصر » (متى ١٣ : ١٦) . تبصر ماذا ؟ تبصر المسيح وعجائبه . وأيضاً تبصر ما لا يرى ، مثلما أبصر القديس يوحنا رؤياه العجيبة . ومثلما أبصر القديس بولس السماء الثالثة وكثرة من الإستعلانات (٢كو ١٢ : ٢ ، ٧) ، أمور « لا ينطق بها ، ولا يسوغ لإنسان أن يتكلم عنها » (٢كو ١٢ : ٢) .","أما أولئك الذين لم تكن لهم هذه الحاسية الروحية ، فقد وبخهم الرب بقوله « أغمضوا عيونهم لئلا يبصروا » (متى ١٣ : ١٥) . وكرر رسوله عنهم نفس التعبير (أع ٢٨ : ٢٧) . وعبارة أغمضوها قد تعنى أنهم لم يدربوا نفوسهم على رؤية الروحيات . أو أنهم رفضوا أن يروا الروحيات من فرط انشغالهم بالماديات .","كان جيحزى لا يبصر ما يبصره معلمه أليشع (٢مل ٦ : ١٧) . وأيضاً مثلها كان مرافقو شاول الطرسوسى فى وقت الرؤيا الإلهية ، وقد قال عنهم الكتاب « وقفوا صامتين ، يسمعون الصوت ، ولا ينظرون أحداً » (أع ٩ : ٧) ."],"33":[{"h":"الفصل الثالث"},{"h":"درجات وأنواع من الإيمان"},"« كما قسم الله لكل واحد نصيباً من الإيمان » (رو ١٢ : ٣) ."],"34":[{"h":"درجات من الإيمان :"},"يختلف الناس فى نوعية إيمانهم ودرجته حسبما « قسّم الله لكل واحد نصيباً من الإيمان » (رو ١٢ : ٣) .","وقد يبالغ البعض ، وإذ يجد إنسان ناقصاً فى إيمانه ، يقول عنه إنه غير مؤمن على الإطلاق . وهذا الحكم ضد تعليم الكتاب المقدس كما سنرى . والبعض قد يخلط بين كلمة (المؤمنين) وكلمة (المختارين) ، كما لو كانتا تدلان على معنى واحد .","فلنتأمل إذن أنواع الإيمان ودرجاته :","١ ـ هناك نوع « حديث الإيمان » وهذا قد أمر الرسول بعدم سيامته فى درجة الأسقفية « لئلا يتصلف » (١تى ٣ : ٦) .","٢ ـ وهناك نوع « قليل الإيمان » أو « ضعيف الإيمان » .","وسنضرب أمثلة من الإنجيل لهذا النوع :","أ ـ الذين يشكون فى عناية الرب بهم فى المأكل أو الملبس . هؤلاء ضرب الرب لهم مثلاً بزنابق الحقل التى ولا سليمان فى كل مجده كان يلبس كواحدة منها . ثم وبخهم قائلاً « فإن كان عشب الحقل الذى يوجد اليوم ويطرح غداً فى التنور ، يلبسه الله هكذا ، أفليس بالحرى يلبسكم أنتم يا قليلى الإيمان ؟ ! » (متى ٦ : ٢٨ ـ ٣٠ ، لو ١٢ : ٢٨) .","ب ـ كذلك وبخ التلاميذ لما فكروا أنهم لم يأخذوا معهم خبزاً ، فانتهرهم قائلاً « يا قليلى الإيمان » (متى ١٦ : ٨) .","ج ـ ووبخ الرب القديس بطرس لما خاف بعدما مشى معه على الماء فبدأ يغرق . حينئذ أمسكه الرب قائلاً له « يا قليل الإيمان ، لماذا شككت ؟ » (متى ١٤ : ٣١) .","د ـ وبالمثل وبخ التلاميذ لما خافوا حينما غطت الأمواج السفينة أثناء نومه فيها . حينئذ قال لهم « ما بالكم خائفين يا قليلى الإيمان » (متى ٨ : ٢٦) ."],"35":[{"h":"إذن الخوف ، والشك فى معونة الله دليلان على قلة الإيمان ."},"هـ ـ وقد ضرب الرسول مثلاً فى ضعف الإيمان بالأخ الذى يعثر من أكل ما ذبح للأوثان . وأمر بأن ضعيف الإيمان لا يجوز إدانته ولا الإزدراء به ، وقال « هو لمولاه : يثبت أو يسقط . ولكنه سيثبت لأن الله قادر أن يثبته » (رو ١٤ : ١ ـ ٤) .","هنا ويعجبنى والد الطفل المصروع ، لما سأله الرب « أتؤمن ؟ » لكى يشفيه . حينئذ أجاب « أؤمن يارب . أعن عدم إيمانى » (مر ٩ : ٢٤) .","إن الإيمان الضعيف يحتاج إلى من يصلى لأجله ، لكى يعينه الرب . ولا يجب مطلقاً أن نزدرى به . فالله قادر أن يثبته .",{"h":"٣ ـ هناك نوع ثالث : هو الإيمان المحدود :"},"ونقصد به الذى يؤمن بالرب فى حدود معينة ، ولا يصل إيمانه إلى ما هو أبعد منه ... مثال ذلك مريم ومرثا ، اللتان كانتا تؤمنان أن الرب يقدر أن يشفى أخاهما من المرض فلا يموت . أما إن مات ، فقد كانت إقامته من الأموات أمراً لم يكن إيمانها قد وصل إليه .","لذلك كل منها قالت للرب « لو كنت ههنا ، لم يمت أخى » (يو ١١ : ٢١ ، ٣٢) . ولما قال الرب لمرثا « سيقوم أخوك » أجابته « أنا أعلم أنه سيقوم فى القيامة فى اليوم الأخير » (يو ١١ : ٢٤) . ولما ذهب الرب إلى القبر وقال « إرفعوا الحجر » ، قالت مرثا « يا سيد قد أنتن ، لأن له أربعة أيام » (يو ١١ : ٣٩) .",{"h":"إن الله لم يرفض هذا الإيمان المحدود ، إنما أعطاه فرصة لينمو ."},"لذلك قال لمرثا « من آمن بى ، ولو مات فسيحيا » . ووبخها عند القبر قائلاً « ألم أقل لك إن آمنت ترين مجد الله » (يو ١١ : ٢٥ ، ٤٠) . وأعطاها فرصة أن ترى مجد الله فى إقامة أخيها لعازر ، لتؤمن ، وليؤمن أيضاً اليهود الذين شهدوا المعجزة .",{"h":"وهنا كان الإيمان لاحقاً للمعجزة ، وليس سابقاً لها ."},"وربما كان ذلك لأن تلك المعجزة كانت الأولى من نوعها ، أى إقامة ميت بعد"],"36":["أربعة أيام من موته ، بعد أن أنتن .","٤ ـ نوع رابع ، من الإيمان الضعيف ، هو البطء القلب فى الإيمان . وربما يكون عن بطء فى الفهم ، أو عن عدم إدراك ، فلا يأتى إيمانه سريعاً . وكان هذا هو نوعية إيمان تلميذى عمواس من جهة قيامة الرب . ولذلك وبخهما قائلاً « أيها الغبيان والبطيئا القلوب فى الإيمان بجميع ما تكلم به الأنبياء . أما كان ينبغى أن المسيح يتألم ... » (لو ٢٤ : ٢٥ ، ٢٦) . ثم بدأ يشرح لهما الأمور المختصة به فى جميع الكتب ... لكى يؤمنا ، أو لكى يعالج هذا البطء فى إيمانها ، الناتج عن عدم فهم أو عدم معرفة .","وفى هذا المثال أيضاً نقول : إن علاج الأخطاء الخاصة بالإيمان ، هو الوضع السليم . وهذا أفضل من الإزدراء أو التحقير الذى لا يأتى بنتيجة ولا يوصل إلى الإيمان السليم .",{"h":"٥ ـ وهناك حالة خطيرة هى الإيمان الميت :"},"فقد قال القديس يعقوب الرسول « الإيمان بدون أعمال ميت » (يع ٢ : ٢٠ ، ١٧) . وقال إن مثل هذا الإيمان لا يقدر أن يخلص صاحبه (يع ٢ : ١٤) . ورأى أن الإيمان الحى ينبغى أن تكون له أعمال تدل عليه ، فقال « أنا أريك بأعمالى إيمانى » (يع ٢ : ١٨) .",{"h":"٦ ـ هناك أيضاً إيمان غير ثابت :"},"مثال ذلك أن السيد المسيح (قبيل القبض عليه) قال لتلميذه بطرس « هوذا الشيطان طلبكم لكى يغربلكم كالحنطة . ولكنى طلبت من أجلك ، لكى لا يفنى إيمانك » (لو ٢٢ : ٢١ ، ٢٢) .","فى ذلك الوقت إهتز إيمان بطرس ، لكنه عاد بعدئذ إلى قوته الأولى .","٧ ـ وهناك حالات وصفها الكتاب بأنها خروج عن الإيمان السليم . ومنها :","أ ـ قال القديس بولس الرسول « إن كان أحد لا يعتنى بخاصته ، ولاسيما أهل بيته ، فقد أنكر الإيمان ، وهو شر من غير المؤمن » (١تى ٥ : ٨) ."],"37":["ب ـ وقال عن الأرامل الحدثات اللائى يرجعن فى نذرهن للبتولية « أرفضهن ، لأنهن متى بطرن على المسيح ، يردن أن يتزوجن . ولهن دينونة ، لأنهن رفضن الإيمان الأول » (١تى ٥ : ١٢) .","ج ـ وقال كذلك « محبة المال أصل لكل الشرور . الذى إذا ابتغاه قوم ، ضلوا عن الإيمان ، وطعنوا أنفسهم بأوجاع كثيرة » (١تى ٦ : ١٠) .","د ـ وقال « إحفظ الوديعة ، معرضاً عن الكلام الباطل الدنس ... الذى إذ تظاهر به قوم ، زاغوا من جهة الإيمان » (١تى ٦ : ٢١) .",{"h":"هل بعد هذه الأمثلة نستطيع أن ننكر علاقة الإيمان بالأعمال ؟ !"},"لأنه هنا بعمل خاطىء يقال إن إنساناً أنكر الإيمان ، أو رفض الإيمان ، أو ضل أو زاغ عن الإيمان ... لعلنا بأمثال هذه المقاييس نمتحن أنفسنا ، عملاً بقول الرسول « إختبروا أنفسكم : هل أنتم فى الإيمان » (٢كو ١٣ : ٥) .",{"h":"٨ ـ أخطر حالة هى « الإرتداد عن الإيمان » :"},"يقول الرسول « فى الأزمنة الأخيرة يرتد قوم عن الإيمان تابعين أرواحاً مضلة » (١تى ٤ : ١) . وعبارة الإرتداد عن الإيمان ، تعنى أنهم كانوا فى الإيمان ثم ارتدوا","ويتحدث الرسول عن الإرتداد العظيم الذى يسبق مجىء المسيح فيقول إنه « لا يأتى إن لم يأتِ الإرتداد أولاً » (٢تس ٢ : ٣) .","هذا من الجهة العامة ، أما عن الناحية الفردية فيقول « أما البار فبالإيمان يحيا . وإن ارتد لا تسرّ به نفسى » (عب ١٠ : ٣٨) . وهنا يتكلم عن ارتداد إنسان مؤمن بار كان بالإيمان يحيا .",{"h":"مادام المؤمن يمكن أن يرتد ، إذن المؤمنون هم غير المختارين . فالمختارون يبقون على إيمانهم كل حياتهم ، حتى ملاقاة الرب ..."},"كل ما ذكرناه فى الأنواع السابقة ، هو عن السلبيات فى الإيمان . نتابع كلامنا إذن عن الإيجابيات الإيمانية ."],"38":[{"h":"٩ ـ النمو فى الإيمان :"},"يقول القديس بولس لأهل تسالونيكى « نشكر الله كل حين من جهتكم أيها الأخوة ... لأن إيمانكم ينمو كثيراً » (٢تس ١ : ٣) . وقال عن أهل كورنثوس إنهم يزدادون فى الإيمان (٢كو ٨ : ٧) .","إذن الإيمان فضيلة كسائر الفضائل ، يمكن أن ينمو فيها الإنسان ...",{"h":"١٠ ـ حفظ الإيمان والثبات فيه :"},"يقول الرسول عن نفسه فى أواخر حياته ، ووقت انحلاله قد حضر « ... أكملت السعى ، حفظت الإيمان . وأخيراً وضع لى إكليل البر » (٢تى ٤ : ٧ ، ٨) .","ويقول لأهل كولوسى « ... ليحضركم قديسين وبلا لوم ولا شكوى أمامه ، إن ثبتم على الإيمان ... » (كو ١ : ٢٣) .","وأقوى من الثبات فى الإيمان ، تعبير آخر هو :",{"h":"١١ ـ الرسوخ فى الإيمان :"},"يقول القديس بطرس الرسول عن محاربات إبليس « ... فقاوموه راسخين فى الإيمان » (١بط ٥ : ٩) .","وهناك درجة أخرى من الإيمان هى :",{"h":"١٢ ـ الغنى فى الإيمان :"},"يقول القديس يعقوب الرسول « أما اختار الله فقراء العالم أغنياء فى الإيمان ، وورثة الملكوت الذى وعد به الذين يحبونه » (يع ٢ : ٥) .","وهناك درجة أزيد من الغنى فى الإيمان وهى :",{"h":"١٣ ـ الإمتلاء من الإيمان :"},"قيل عن القديس اسطفانوس أول الشمامسة « فاختاروا اسطفانوس رجلاً مملوءاً من الإيمان والروح القدس » ، « وأما اسطفانوس فإذ كان مملوءاً إيماناً وقوة ، كان يصنع عجائب وآيات عظيمة ... » (أع ٦ : ٥ ، ٨) .","كل هذه الصفات تقال عن حالة لازمة للإيمان هى :"],"39":[{"h":"١٤ ـ الإيمان العامل بالمحبة :"},"يقول القديس بولس الرسول « فى المسيح يسوع ، لا الختان ينفع شيئاً ولا الغرلة ، بل الإيمان العامل بالمحبة » (غل ٥ : ٦) .","ولعله ذكر عبارة الإيمان العامل ، لأن الإيمان بدون أعمال ميت (يع ٢ : ٢٠) . أما عبارة المحبة ، فلأنه بها يتعلق الناموس كله والأنبياء (متى ٢٢ : ٤٠) .","وهناك نوع عظيم من الإيمان هو :",{"h":"١٥ ـ الإيمان الذى يصنع العجائب :"},"تحدث السيد الرب عن « آيات تتبع المؤمنين » (مر ١٦ : ١٧) . وقال القديس يعقوب الرسول « صلاة الإيمان تشفى المريض » (يع ٥ : ١٥) .","ولكن لعل قمة هذا الأمر تبدو فى قول الرب « كل شىء مستطاع للمؤمن » (مر ٩ : ٢٢) .","ولعل هناك نوعاً آخر ، ليس لصانع الأعجوبة ، إنما للذى يتقبلها وهو :",{"h":"١٦ ـ إيمان الثقة والتصديق :"},"وهو الذى كان يتطلبه الرب ممن تحدث معه المعجزة . وأحياناً يسأله « أتؤمن ؟ » . وكما قال للأعميين اللذين طلبا منه الشفاء « أتؤمنان أنى أقدر أن أفعل هذا ؟ » (متى ٩ : ٢٨) .","وقد طوّب الرب هذا النوع من الإيمان ، مثلما قال للمرأة الكنعانية « عظيم هو إيمانك » (متى ١٥ : ٢٨) . ومثلما قال عن قائد المائة « لم أجد ولا فى اسرائيل إيماناً بمقدار هذا » (متى ٨ : ١٠) .",{"h":"١٧ ـ كل الإيمان :"},"يقول القديس بولس الرسول « إن كان لى كل الإيمان حتى أنقل الجبال ... » فاعتبر أن هذا الإيمان الذى ينقل الجبال ، هو كل الإيمان ، أى قمته ، ولا شىء بعده ."],"40":[{"h":"أنواع من الإيمان :"},"هناك فرق كبير بين نوعين من الإيمان : إيمان نظرى ، وإيمان عملى .",{"h":"١ ـ الإيمان النظرى (العقلى) :"},"هو إيمان فكرى ، فلسفى . مجرد الإقتناع العقلى بوجود الله ، وبوجود الأمور التى لا ترى دون أن يكون لذلك أى تأثير على الحياة . وهناك نص يثبت أن الشياطين لهم هذا النوع من الإيمان . إذ يقول القديس يعقوب الرسول عن الإيمان الميت ، الخالى من الأعمال :",{"h":"« أنت تؤمن أن الله واحد . حسناً تفعل . والشياطين يؤمنون ويقشعرون » (يع ٢ : ١٩) ."},"وسفر أيوب يعطينا دليلاً عملياً على هذه النقطة . لأن حديث الشيطان مع الله تبارك إسمه يثبت هذا الإيمان النظرى ، إذ يقول الشيطان للرب « هل مجاناً يتقى أيوب الله ؟ أليس أنك سيجت حوله ... باركت أعمال يديه . ولكن إبسط الآن يدك ومس كل ماله ، فإنه فى وجهك يجدف عليك » (أى ١ : ٩ ـ ١١) . ولما أخذ إذناً من الله للتصرف ، ذهب ليعمل ضد أيوب . وفى المرة الثانية قال أيضاً للرب « ... ولكن الآن إبسط يدك ومس عظمه ولحمه ، فإنه فى وجهك يجدف عليك » (أى ٢ : ٥) .","وهذا الكلام كله يثبت أن الشيطان يؤمن عقلياً بأن هذا هو الله ، وأنه هو الذى بارك أعمال أيوب ، وهو القادر أن يمس ماله ، وأن يمس لحمه وعظمه . وأن أى عبارة تصدر من أيوب ضد الله تعتبر تجديفاً على الله ...","ومع كل هذا ، كان الشيطان يحارب ملكوت الله وأولاده ، ولا يزال .",{"h":"إيمان الشيطان العقلى الذى تحدث عنه معلمنا يعقوب ، هو أيضاً إيمان ميت ، حسب قول الرسول نفسه « إيمان بدون أعمال ميت » (يع ٢ : ٢٠) . فإن كان الإيمان الخالى من الأعمال الصالحة إيماناً ميتاً ، فكم بالأكثر المشحون بالأعمال الردية ومقاومة كل صلاح أياً كان ..."},{"h":"إن الإيمان العقلى سهل . ما أسهل إثبات وجود الله بالأدلة العقلية وبالبراهين"}],"41":["العديدة . المهم هو الإيمان العملى .","هذا يقودنا إلى النوع الهام من الإيمان ، وهو :",{"h":"٢ ـ الإيمان العملى :"},"هو الإيمان الذى تظهر علاماته فى الحياة العملية ، حياة إنسان يؤمن أن الله كائن أمامه ، يراه ويحسه ، ويتصرف بما يليق بهذا الإيمان . وهو يحب هذا الإله الذى يؤمن بوجوده وبعنايته ورعايته وحفظه ، ويكلم هذا الإله المحبوب فى صلواته وتضرعاته ، ويخشى أن يفعل شيئاً يجرح قلبه المحب ... وفى اطمئنانه لعمله لا يخاف ولا يضطرب ، بل يحيا فى سلام دائم ، مسلماً حياته كلها لتدبيره الحكيم ...",{"h":"وهكذا يقوده الإيمان إلى عديد من الفضائل لا تحصى ."},"وهذا النوع من الإيمان سيكون موضوع كتابنا هذا بمشيئة الرب ، حيث سنشرح كيف يقود الإيمان حياتنا كلها لتصبح حياة الإيمان .","وهذا المفهوم ينقلنا إلى صفة أخرى من صفات الإيمان السليم وهى :",{"h":"٣ ـ إيمان دائم :"},"ونعنى به أنه لا يكون إله مناسبات . فلا يظهر إيماننا فقط حينما نكون فى الكنيسة أو فى اجتماع روحى ، أو حينما نصلى ، أو نقرأ الكتاب ، أو نتقدم للتناول . وإنما يظهر هذا الإيمان فى كل وقت ، وكل مكان ، فى خارج الكنيسة كما فى داخلها . الله أمامنا باستمرار ، وفى فكرنا باستمرار ، بإيمان لا يتغير . إنه ليس فقط إله الكنائس وإله الكتاب ، إنما هو إله القلب والفكر جميعاً ، وإله الحياة كلها .",{"h":"٤ ـ إيمان دون أن يرى :"},"إيمان لا يعتمد على الحواس ، وينطبق عليه قول الرب « طوبى للذين آمنوا دون أن يروا » (يو ٢٠ : ٢٩) . ليس مثل العلماء الذين لا يؤمنون بشىء ، إلا إذا أحضروه فى معاملهم ، وتيقنوا منه بأبصارهم وأجهزتهم . وليس مثل الصدوقيين الذين أنكروا وجود الملائكة والقيامة والأرواح (أع ٢٣ : ٨) ، لأنهم لا يرون شيئاً من ذلك كله ..."],"42":[{"h":"٥ ـ إيمان الثقة والإختبار :"},"إنه ليس الإيمان بالله الذى نقرأ عنه فى كتب اللاهوت ، أو فى المعاهد الدينية ، أو فى الكنائس وفى فصول التعليم الدينى على أنواعها . وإنما إيمان بالله الذى اختبرناه فى حياتنا ، وعاشرناه ، وأدخلناه فى كل تفاصيل حياتنا ، واختبرنا عملياً قول داود النبى « ذوقوا وانظروا ما أطيب الرب » (مز ٣٤ : ٨) ... ووجدنا أن الله عجيب عجيب ، إلى أبعد الحدود ، فوق ما يتصور العقل ... حياتنا كلها مجرد عشرة معه ، ذقنا فيها حلاوته وحبه ورعايته . ورأينا أيضاً قوته وجلاله . وجربنا كيف يدخل فى مشاكلنا ويحلها ، بطرق ما كانت تخطر على عقولنا .","ونتيجة للإختبار ، صارت لنا ثقة ، غير مبنية على الكتب ، وإنما على ما لمسناه بأيدينا ... لذلك إيماننا إيمان حقيقى راسخ فى قلوبنا .",{"h":"٦ ـ إيمان قوى :"},"وهو الإيمان الذى يستطيع كل شىء (مر ٩ : ٢٣) . ويمكنه أن ينتصر على كل عقبة . ولا يرى أمامه شيئاً مستحيلاً . بل كما قيل عن زربابل « من أنت أيها الجبل العظيم ؟ ! أمام زربابل تصير سهلاً » (زك ٤ : ٧) .","إنه الإيمان الذى يستطيع أن يضع قدمه فى الماء ، لكى يعبر البحر الأحمر فى أيام موسى النبى (خر ١٤ : ٢٢) ، وأن يعبر نهر الأردن فى أيام يشوع (يش ٣) . ويستطيع أن يمشى فى داخل الغمر العظيم ، والمياه تحيط به مثل سور ، عن يمين وعن شمال ، دون أن يخاف ...","إنه الإيمان الذى يستطيع أن يضرب الصخرة فيتفجر منها الماء (خر ١٧ : ٦) . وهو الإيمان الذى يسير فى الصحراء بلا زاد وبلا مرشد ، يجمع طعامه من المن النازل من السماء يوماً بيوم (خر ١٦ : ٢١) . وترشده السحابة نهاراً ، وعمود النار ليلاً (عد ٩ : ١٥ ـ ٢٣) .","إنه الإيمان القوى الذى استطاع أن ينقل الجبل المقطم على يد سمعان الدباغ ، أيام البابا ابرآم بن زرعه ."],"43":["وهو الإيمان القوى الذى استطاع به إيليا النبى أن يقول « لا يكون طلّ ولا مطر فى هذه السنين إلا عند قولى » (١مل ١٧ : ١) . وهكذا « لم تمطر على الأرض ثلاث سنين وستة أشهر . ثم صلى فأعطت السماء مطراً » (يع ٥ : ١٧ ، ١٨) . وهكذا استطاع أن يغلق السماء ويفتحها .","ما أكثر الأمثلة عن هذا الإيمان القوى . ولكن هناك أمثلة أخرى عن هذا الإيمان القوى ، تبدو فى مظهر آخر هو :",{"h":"٧ ـ إيمان لا يتزعزع :"},"إنه إيمان ثابت ، لا يتأثر مطلقاً بالعوامل الخارجية : فهو يؤمن بمحبة الله سواء كان على جبل التجلى أو على جبل الجلجثة .","يؤمن بمحبة الله الذى يعطيه من سارة نسلاً فى ظروف تدعو إلى اليأس ، تماماً كما يؤمن بمحبة الله وهو يقول له : خذ إبنك وحيدك الذى تحبه إسحق ، وأصعده هناك محرقة على الجبل الذى أريك إياه (تك ٢٢ : ٢) .",{"h":"إن إبراهيم وهو يرفع بيده السكين على إبنه اسحق ، ما كان يشك مطلقاً فى محبة الله ، ولا فى صدق مواعيده ..."},"لم يتزعزع إيمانه مطلقاً فى هذا الإله ، ولا فى أنه سيكون له من اسحق نسلاً مثل نجوم السماء ورمل البحر فى الكثرة ...","إن الإيمان الثابت لا يتغير بالظروف الخارجية المحيطة به ، لأن ثقته ثابتة فى الله ، وسلامه القلبى لا يستمده من الظروف الخارجية ، إنما من الله نفسه ومحبته وصدق مواعيده .",{"h":"٨ ـ الإيمان كموهبة :"},"هناك إيمان عادى ، وإيمان يعتبر موهبة من الروح القدس . ولا شك أن هذا له درجة عالية تفوق الإيمان العادى بكثير ...","يقول القديس بولس الرسول فى حديثه عن المواهب « فأنواع مواهب موجودة ، ولكن الروح واحد ... ولكنه لكل واحد يعطى إظهار الروح للمنفعة . فإنه لواحد"],"44":["يعطى بالروح كلام حكمة ... ولآخر إيمان بالروح الواحد . ولآخر مواهب شفاء بالروح الواحد ... » (١كو ١٢ : ٤ ـ ٩) .","وهكذا أيضاً وضع الإيمان ضمن ثمار الروح (غل ٥ : ٢٢) .","ويبدو هنا أننا لا نستطيع أن نفصل الإيمان عن عمل الروح القدس : إما من ثمار الروح ، وإما من مواهب الروح . ولكل منها درجته ...",{"h":"٩ ـ الإيمان السليم :"},"ما أكثر ما يؤمن الناس بأفكار ، أو مذاهب ، سياسية أو اجتماعية ، ويعطيهم إيمانهم بها قوة على التنفيذ ، وعلى نقلها إلى عقول الناس ...","ولكننا نود فى هذه الصفحات أن نتحدث عن الإيمان السليم ، الذى يكون له طابع روحى وصلة وطيدة بالله « الإيمان العديم الرياء » (١تى ٢ : ٥) ، « الإيمان المسلّم مرة للقديسين » (يه ٣) ... هذا الإيمان الطاهر النقى فكراً وسلوكاً . وهذا يجعلنا نقول :",{"h":"إن الإيمان ، ليس هو مجرد عقيدة ، إنما هو حياة ... أو هو حياة مؤسسة على عقيدة . أو هو عقيدة إختبارية عاشها الناس ، وليست مجرد أفكار فى الكتب ."},"وما نريد أن نتحدث عنه فى هذا الكتاب هو هذه الحياة ، حياة الإيمان ..."],"45":[{"h":"الفصل الرابع"},{"h":"علاقة الإيمان بالسلام وعدم الخوف"}],"46":["من صفات المؤمن ، أن يكون قلبه مملوءاً بالسلام والهدوء . لا يضطرب مطلقاً ، ولا يقلق ، ولا يخاف ، لأنه يؤمن بحماية الله له ... وهو يحتفظ بسلامه الداخلى ، مهما كانت الظروف الخارجية تبدو مزعجة .","يخاف الشخص الذى يشعر أنه واقف وحده . أما الذى يؤمن أن الله معه فلا يخاف ...","١ ـ هوذا داود النبى يقول « إن يحاربنى جيش ، فلن يخاف قلبى . وإن قام علىّ قتال ، ففى هذا أنا مطمئن » (مز ٢٧ : ٣) . وإن سألته عن السبب فى هذا ، يجيب فى نفس المزمور « الرب نورى وخلاصى ، ممن أخاف ؟ ! الرب حصن حياتى ، ممن أرتعب » (مز ٢٧ : ١) . لقد اختبر الرب ومعونته وحمايته ، فقال عندما اقترب إلىّ الأشرار ليأكلوا لحمى ، مضايقى وأعدائى عثروا وسقطوا » (مز ٢٧ : ٢) .",{"h":"إنه لا يستمد سلامه من تحسن الظروف الخارجية من حوله ، إنما يستمد سلامه من عمل الله فيها ومعه ."},"لذلك فهو يقول فى مزمور الراعى « إن سرت فى وادى ظل الموت ، لا أخاف شراً » لماذا ؟ « لأنك أنت معى » (مز ٢٣ : ٤) .","إن كان لك هذا الإيمان ، أن الله معك ، فلن تخاف ، مهما حاربك جيش ، أو قام عليك قتال ، حتى إن سرت فى وادى ظل الموت .",{"h":"٢ ـ ولعل هذا السلام وعدم الخوف ، نراهما فى مقابلة إيليا النبى لآخاب :"},"كان آخاب الملك يفتش عن إيليا النبى فى كل مكان لكى يقتله . ومع ذلك فإن إيليا ذهب ليتراءى لآخاب . ولما حذره عوبديا من الخطر ، أجاب إيليا « حى هو رب الجنود الذى أنا واقف أمامه ، إنى اليوم أتراءى له » (١مل ١٧ : ١٤ ، ١٥) . وقد كان . قابل إيليا آخاب الملك ، ولم يخف منه . بل وبخه على عبادته للأصنام (١مل ١٧ : ١٨) . إيليا لم يكن يخاف ، لإيمانه أنه واقف أمام رب الجنود ."],"47":[{"h":"٣ ـ وبالمثل كان داود فى لقائه مع جليات الجبار :"},"داود ـ الصبى الصغير ـ كان بالإيمان مملوءاً بالسلام لا يخاف جليات ، بل يتكلم بثقة ... ويقول لشاول الملك « لا يسقط قلب أحد بسببه » (١صم ١٧ : ٣٢) . أما الملك وكل جيشه فكانوا خائفين ، ومرتاعين جداً . لأنهم لم يكونوا ناظرين إلى الله الذى لا يرى ... بل كانوا مركزين أبصارهم فى هذا الذى يرونه أمامهم « الرجل الصاعد » الذى « طوله ست أذرع وشبر ، وقناة رمحه كنول النساجين ، ووزن درعه خمسة آلاف شاقل نحاس » (١صم ١٧ : ٤ ـ ٧) .","داود رجل الإيمان ، لما دخل إلى ميدان المعركة أدخل الله معه ، وأدخل روح الإيمان والإطمئنان إلى قلوب رجال الحرب بقوله « من هو هذا الأغلف حتى يعير صفوف الله الحى ... لا يسقط قلب أحد بسببه » (١صم ١٧ : ٢٦ ، ٣٢) . وقال لذلك الجبار « أنت تأتى إلىّ بسيف ورمح . وأنا آتى إليك باسم رب الجنود » (١صم ١٧ : ٤٥) . أعنى : أنت تأتى إلىّ بالأمور التى ترى ، وأنا آتى إليك بالذى لا يرى .",{"h":"وسنلاحظ أن إسم الله لم يفارق لسان داود . وكان يمنحه سلاماً"},"وبهذا الإيمان ، وهذا السلام القلبى ، وبهذه الثقة تقدم داود إلى ذلك الجبار المرعب ، وقال له فى يقين الإيمان « اليوم يحبسك الرب فى يدى ... فتعلم كل الأرض أنه يوجد إله ... لأن الحرب للرب » (١صم ١٧ : ٤٦ ، ٤٧) .","حقاً إن الرجل المؤمن لا يعرف الخوف ، مهما كانت الظروف مخيفة من حوله ... سلامه القلبى لا يفارقه مطلقاً ... بل يمنحه الإيمان أيضاً شجاعة وبسالة .",{"h":"٤ ـ فى وسط الضيقة ، أياً كانت ، نرى الإيمان يعطى سلاماً ."},"ضيقة تحل بإثنين : أحدهما مؤمن والآخر غير مؤمن . فيضطرب غير المؤمن ويخاف ويقلق ، ويتصور أسوأ النتائج ، وتزعجه الأفكار ... أما المؤمن فيلاقيها بكل اطمئنان ، وبسلام قلبى عجيب . وقد يسأله البعض عن شعوره إزاء الضيقة فيقول « هذه المشكلة ، سيتدخل الله فيها ويحلها ، وستؤول إلى الخير » . وقد تسأله كيف سيتدخل الله ؟ وكيف سيحلها ؟ فيجيبك : أنا لا أعرف . ولا يهمنى هذا . إنما أعرف أننا لا نهتم بمشاكلنا ، فالله هو المهتم بالكل ..."],"48":[{"h":"حقاً إنى لا أعرف كيف ستحل المشكلة . ولكنى أعرف الله الذى سيحلها ."},"وهكذا يقوده الإيمان إلى الإطمئنان . وهكذا أولاد الله يعيشون دائماً فى سلام ، بل وفى فرح ، شاعرين أن الله معهم ، هو الذى يتولى كل أمورهم ، ويعمل من أجلهم ما لا يستطيعون عمله لأجل أنفسهم ...",{"h":"٥ ـ إن يونان ـ حتى وهو فى بطن الحوت ـ لم يفقد إيمانه وسلامه ."},"بل إنه صلى إلى الرب وهو فى بطن الحوت ، صلاة كلها إيمان ، وقال فى ثقة « ولكننى أعود أنظر هيكل قدسك » (يون ٢ : ٤) . ونذر للرب نذراً وقال : « أما أنا فبصوت الحمد أذبح لك . وأوفى بما نذرته . للرب الخلاص » (يون ٢ : ٩) .","حتى وهو فى بطن الحوت ، كان يرى خلاص الرب . وكان يرى أنه سيخرج منه ، ويرى الهيكل المقدس ، ويذبح للرب ويوفى نذوره .","إنه الإيمان مصدر كل سلام وراحة . لا خوف فيه ولا قلق .",{"h":"٦ ـ فإذا قلّ الإيمان ، حينئذ يخاف الإنسان ."},"بطرس فى إيمانه استطاع أن يمشى مع الرب فوق الماء ، ناسياً كل قوانين الجاذبية . فلما تذكرها وخاف حينئذ سقط ، فوبخه الرب قائلاً « يا قليل الإيمان لماذا شككت » (متى ١٤ : ٣١) .","وهكذا ربط الرب بين الخوف والشك وقلة الإيمان . وحقاً إنه ترابط عجيب :",{"h":"الشك يضعف الإيمان . وضعف الإيمان يؤدى إلى الخوف . والخوف يسبب السقوط ."},"وبنفس الوضع نتحدث عن التلاميذ لما هاجت عليهم الأمواج فى السفينة . رؤيتهم الأمواج تغطى السفينة ، بينما الرب نائم فيها ، جعلتهم يشكون فى اهتمام الرب بهم . والشك أضعف إيمانهم ، فخافوا . لذلك وبخهم الرب قائلاً « ما بالكم خائفين يا قليلى الإيمان » (متى ٨ : ٢٦) .",{"h":"فى كل مرة تخاف ، وبخ نفسك على قلة إيمانك ."},"قل لنفسك أين هو إيمانى بأن الله موجود ، وبأنه ضابط الكل يرى كل شىء ؟"],"49":["وأين إيمانى بمحبة الله ، وبتدخله فى مشاكلى ، وبقدرته على كل شىء ، وأين إيمانى بأن الله صانع الخيرات ، وبأنه لا بد سيصنع معى خيراً ؟ !","هذه الأفكار كلها تقوى إيمانك ، وتمنحك سلاماً ، وثقة بعمل الله .",{"h":"الإيمان مريح للنفس . لأن الذى يؤمن بوجود الله ، لا يشعر بالوحدة . بل يثق أن هناك قوة إلى جواره"},"إنه يؤمن بوجود هذه القوة القادرة على كل شىء ، التى تسانده ، والتى كلها حب وعدل . وهى تعمل لخير الجميع ، وتتراءف على كل من هو فى ضيقة ... وإذ يطمئن إلى هذه القوة الإلهية الحافظة ، يمتلىء قلبه سلاماً ، ولا يقلق ولا يخاف ... أما غير المؤمن ، فإذ لا يثق بقوة خفية تسنده ، نراه يتعب ، ويقف وحيداً فى ضيقاته فاقداً للسلام ...",{"h":"٧ ـ القديس بطرس كان فى السجن ، وقد نام نوماً ثقيلاً ."},"مع أن هيرودس الملك ، لكى يرضى اليهود ، كان قد قتل القديس يعقوب بن زبدى أحد الإثنى عشر ، وأمر بالقبض على القديس بطرس وألقاه فى السجن « مسلماً إياه إلى أربعة أرابع من العسكر ليحرسوه » . وكان مزمعاً قتله بعد الفصح (أع ١٢ : ١ ـ ٤) .","وعلى الرغم من السجن ، ومن الحراسة المشددة ، ومن توقع القتل ... نام بطرس فى السجن ، واثقاً من وجود حراسة إلهية تحرسه ، أكثر من حراسة العسكر عليه . وكان نوماً ثقيلاً ، لدرجة أن الملاك الذى أتى لينقذه ، ضربه فى جنبه ليوقظه (أع ١٢ : ٧) ...","أى سلام قلبى هذا ، الذى يجعل إنساناً فى مثل هذه الظروف ينام ، وهو فى السجن ، وفى نفس الليلة التى كان فيها هيرودس الملك مزمعاً أن يقدمه للقتل ... !",{"h":"إنه الإيمان بحفظ الله ، إن أراد له حياة على الأرض ... أو الإيمان بالأبدية السعيدة ، إن شاء الله له أن يستشهد ."},"وفى كلتى الحالتين ، الأمر يدعو إلى الفرح . لذلك كان السلام يملأ قلبه . وكان ينام فى هدوء . وما كانت الأمور الخارجية تزعجه ...","ولعله كان هناك سبب آخر لهذا السلام ، وهو أنه « كان بطرس محروساً فى"],"50":["السجن . وأما الكنيسة فكانت تصير منها صلاة بلجاجة إلى الله من أجله » (أع ١٢ : ٥) .",{"h":"الإنسان المؤمن هو الذى يستطيع أن ينام فى حضن الله ويستريح ."},"إنه يسلم حياته وكل مشاكله للرب . ويقول للرب : ما دمت أنت قد استلمت هذه الموضوعات ، فأنا سوف لا أشغل نفسى بها . إنها قد انتهت بالنسبة إلىّ ، وانتقلت إلى يديك أنت ، وأنا واثق أنك ستصنع كل خير . أما أنا فمطمئن إلى عملك ، وسأنام وأستريح . لذلك حسناً قيل فى المزمور إنه « يعطى أحباءه نوماً » (مز ١٢٧ : ٢) .",{"h":"٨ ـ دانيال النبى والثلاثة فتية ، مثال للإيمان المملوء بالسلام ."},"دانيال كان ينتظر أن يلقى فى جب الأسود ، ومع ذلك لم يفقد سلامه ، ولم يفقد أيضاً شجاعته . واحتفظ بإيمانه ، وصلى إلى الله إلهه بكل مجاهرة ، وبلا خوف .","فى جب الأسود ، كان قلب دانيال أقوى من قلوب جميع الأسود التى معه ... وكأنه يقول : وماذا إن ألقونى فى جب الأسود ؟ أليس الرب هناك أيضاً . أوليس هناك ملاكه يسد أفواه الأسود ...","وكذلك الثلاثة فتية ما خافوا من أتون النار .","لا شك أن الإيمان يخلق فى القلب كل شجاعة وجرأة ، وينزع منه كل خوف .",{"h":"٩ ـ وهكذا كان القديسون فى طريقهم إلى الإستشهاد ."},"كانوا يغنون أغانى الفرح ، ويسبحون الله ، وهم فى طريقهم إلى الموت . وما كان الموت يزعجهم ، ولا العذاب . كان إيمانهم بالحياة الأخرى ، وبالأبدية السعيدة ، وبعشرة الرب فى الفردوس ، كل ذلك كان يملأهم سلاماً بل وفرحاً ، بل أيضاً اشتياقاً إلى الموت ، مغنين مع بولس الرسول « لى اشتهاء أن أنطلق وأكون مع المسيح . فذاك أفضل جداً » (فى ٢ : ٢٣) .","إن الموت لا يخيف المؤمن ، بل يفرحه ...",{"h":"١٠ ـ فى كل ضيقة وصعوبة وعقبة ، المؤمن لا يخاف ، ولا يفقد سلامه ."},"المؤمن ينتصر على العقبات ، دون أن يخاف منها . يشعر أن الله سيحل"],"51":["الصعوبات التى تصادفه ، ولا يتركه وحده فيها .","أما غير المؤمن فربما الصعوبات تصيبه بالتردد والخوف . وبعدم إيمانه يجبن . بل عدم الإيمان قد يصور له صعاباً ومخاوف غير موجودة ، كأن « الأسد فى الطريق . الشبل فى الشوارع » (أم ٢٦ : ١٣) .","أما المؤمن فلا يخاف مطلقاً مهما صادفته المصاعب والمتاعب . إنه يلاقيها كلها فى هدوء وفى اطمئنان واثقاً بعمل الله معه .",{"h":"١١ ـ بهذا الإيمان والإطمئنان ، وقف القديس أثناسيوس يحارب الأريوسية ."},"بكل ما كان للأريوسية من صلة بالإمبراطور ، وتأثير عليه وعلى حاشيته . بل بكل ما كان لها أيضاً من تضليل للشعب ، وضغط على الأساقفة وإقناع لبعضهم ، وإثارة جو عام من الشك . حتى قيل لهذا البابا المؤمن :",{"h":"[ العالم كله ضدك يا أثناسيوس ] فأجاب [ وأنا أيضاً ضد العالم ]"},"وهكذا لم ترهبه قرارات النفى من الأباطرة ، ولا قرارات الحرم من بعض الأساقفة ، ولا الشكوك المنتشرة فى كل مكان ، ولا الإتهامات الباطلة التى يلصقونها به . وإنما ظل يطوف من بلد إلى بلد ، بكل ثقة ، يعلم ويقنع ، ويزيل الشكوك ، ويثبت الناس فى الإيمان ، ويكتب الردود والمقالات ، ويدحض براهين الأريوسيين ... إلى أن انتصر أخيراً ، وانتصر الإيمان على يديه . وقال القديس جيروم :",{"h":"[ مر وقت ، كاد فيه العالم كله أن يصبح أريوسياً ، لولا أثناسيوس ]"},"هذا هو الإيمان الذى لا يعرف خوفاً ولا اضطراباً ، ولا تهزه الأحداث ، بل يحتفظ بسلامه وسط النيران المتقدة إلى أن يطفئها الله ...","إن إيمان القديس أثناسيوس بالعقيدة التى كان يدافع عنها ، منحه قوة جبارة ، وقف بها ضد جميع المقاومات . وكل قوة أثناسيوس ، إنما تكمن فى إيمانه ، الإيمان الذى يستطيع أن يصنع الأعاجيب .",{"h":"١٢ ـ بالإيمان بشر أناس بالمسيح فى بلاد تأكل لحوم البشر ولم يخافوا ."},"ودخلوا فى مجاهل أفريقيا ، وفى الغابات ، وفى مناطق خطرة حتى من جهة"],"52":["طبيعتها ومناخها وطبائع أهلها . ولم يخافوا . إيمانهم بالله الحافظ لهم ، أعطاهم قوة وشجاعة . وكذلك إيمانهم بخيرية وأهمية العمل الذى يقومون به ، أهمية أن يوصلوا كلمة الله للنفوس التى هناك حتى لا تهلك فى عدم إيمان . كل هذا أعطاهم قوة ، ونزع الخوف من قلوبهم ، فتمموا عملهم ، ولم تثنهم عنه الغربة ، ولا قسوة المناخ ، ولا وحشية الناس ، ولا خطورة الطبيعة ...",{"h":"١٣ ـ بالإيمان أخذ أبونا نوح معه الوحوش فى الفلك ولم يخف ."},"مادام الله قد قال له خذها معك اثنين اثنين ، إذن فسيأخذها . والله الذى أصدر الأمر سيحفظه منها . وستكون معه كما كانت مع آدم فى الفردوس ، يعيش معها بلا خوف ، وبكل سلام فى القلب ... وقد كان .","أبونا نوح كان مؤمناً بكلمة الله له ، لذلك لم يخف .",{"h":"١٤ ـ بل إن كل من آمن بفكرة ، يعطيه الإيمان بها قوة لتنفيذها ."},"وهكذا كان المصلحون فى كل زمان ومكان . آمنوا بفكرة ، فجاهدوا بكل قوة لتنفيذها . وبسبب إيمانهم احتملوا الكثير من الضيق ، حتى أكملوا عملهم .","غاندى مثلاً آمن بحق الإنسان فى الحرية ، وآمن بسياسة عدم العنف . وأعطاه هذا الإيمان قوة عجيبة إستطاع بها أن يحرر الهند ، وأن يعطى الحقوق للمنبوذين متساوين مع إخوتهم . واستطاع أن يحتمل الكثير لكى لا يسلك أتباعه بعنف ، ولا يلاقون العنف بالعنف . إيمانه بالفكرة أعطاه القوة على تنفيذها ، فكم بالأكثر بما لا يقاس : الإيمان بالله .",{"h":"١٥ ـ بل حق الإيمان بالعلم يصنع الأعاجيب . مثال ذلك رواد الفضاء ."},"وأقصد كمثال إيمانهم بما قيل لهم عن منطقة إنعدام الوزن . وكيف أن الإنسان فيها يمكن أن يمشى فى الجو دون أن يسقط . من من الناس يجرؤ أن يمشى فى الجو دون أن يخاف . أما الذى جعلهم ينفذون ذلك فهو إيمانهم الأكيد ببحوث العلماء الذين قالوا بهذا . والإيمان يعطى قوة وشجاعة . فكم بالأكثر الإيمان بالله .",{"h":"إن الفرق بين أشجع الناس وأخوف الناس ، هو الإيمان ."},"إن الشخص الجرىء هو الذى لديه إيمان ، بأنه لن يحدث له ضرر ما ، أو هو"],"53":["المؤمن بلزوم عمله وضرورته مهما حدث له ، أو هو المؤمن بصفة الشجاعة وعدم الخوف . أما الجبان فهو على عكس هذا كله .",{"h":"١٦ ـ أيضاً الإيمان بالأبدية ، يعطى الإنسان راحة وسلاماً ."},"إذ يوقن أنه لا بد سينال حقه ، إن لم يكن على الأرض ، ففى السماء . ولا يكن مظلوماً هنا وهناك . كذلك سينال سعادته كاملة : مالم يتحقق منها هنا ، سيتحقق بكل تأكيد فى النعيم الأبدى . وهكذا يعيش مرتاحاً ، ولو كان مثل لعازر المسكين .",{"h":"١٧ ـ الإيمان بقوة الصليب وعلامة الصليب ، يمنع الخوف ."},"الذى يؤمن بالصليب وقوة الصليب وعلامة الصليب ، كثيراً ما يشعر باطمئنان إذ يحتمى وراء هذا الصليب .","فإن تعرض لخوف أو خطر ، ورشم ذاته بعلامة الصليب ، يمتلىء قلبه سلاماً ، ويحس أن قوة تحميه ، وتمنع عنه الخوف ، ويحس أن قلبه دخلته قوة لم تكن فيه من قبل . وصارت له علامة الصليب سلاحاً .",{"h":"وهناك إنسان آخر له إيمان كبير بفاعلية المزامير ."},"يتلوها فى أى وقت ، أو فى وقت الحاجة ، فيشعر أن المزمور فيه قوة خاصة ، تطمئن قلبه وتمنحه سلاماً . فإن كان خائفاً مثلاً ، وتلا مزمور ٩١ (الساكن فى ستر العلى) ، أو ٢٣ (الرب يرعانى) ، أو ٢٧ (الرب نورى وخلاصى) ... للوقت يشعر بسلام داخله ، وبأن قوة المزمور قد حلت عليه .","نحن نعرف أن المزامير قد قيلت بالروح (متى ٢٢ : ٤٣ ، ٤٤) . وأنها كجزء من الكتاب ، قالها داود مسوقاً بالروح القدس (٢بط ١ : ٢١) . لذلك لها قوة بلا شك .",{"h":"آخرون لهم إيمان فى أرواح القديسين وعملها لأجلهم ."},"لذلك يشعرون بسلام ، حينما يطلبون صلاة ومعونة قديس يحبونه ويثقون بدالته عند الله .","أذكر بهذه المناسبة راهباً أثيوبياً متوحداً ، كان يعيش فى مغارة فى وادى"],"54":["النطرون . فى إحدى المرات ضلّ طريقه بالليل ، إذ كان يشكو وقتذاك من ضعف فى بصره . وأقبل عليه الليل والظلام . فرسم دائرة واسعة على أرض الصحراء ، وحوّطها بعلامة الصليب من كل ناحية ، ونام داخلها . وفى الصباح رأى آثار الدبيب والحيوانات خارج الدائرة ، ولم تستطع أن تدخلها لتؤذيه .","أتذكر منذ زمن طويل ، أننى كنت مسافراً فى سفينة ، وقد هاجت الأمواج جداً عليها ، وخاف الركاب . ونظرت فرأيت من بين الركاب معنا إنساناً طيباً جداً كنت أثق كثيراً بقداسته . فاطمأن قلبى . وقلت فى داخلى « من المحال أن يسمح الله بغرق السفينة ، وفى داخلها هذا الإنسان الطيب الذى يحب الله » . ونجت السفينه فعلاً ، ولم يحدث لها أى ضرر .","لقد كان مجرد وجود هذا الإنسان الطيب سبباً فى السلام وتقوية الإيمان . وربما كان هذا شعور ركاب آخرين ...","إن القصص الإختبارية فى هذا المجال ، لا تدخل تحت حصر . وكلها تقوى الإيمان . ولكنى لست أرى الآن مجالها ...","نكتفى بهذا الجزء وندخل فى علامة أخرى من علامات الإيمان ..."],"55":[{"h":"الفصل الخامس"},{"h":"علاقة الإيمان بنقاوة القلب"}],"56":[{"h":"لا شك أنك تخجل أن تخطىء أمام إنسان بار تحترمه ."},"وقد تكون فى حضرته فى منتهى الحرص ، تستحى من أن ترتكب شيئاً مشيناً أمامه . لا تحب أن يأخذ عنك فكرة سيئة ، أو أن تسقط من نظره ... بل قد تحترس أيضاً من الخطأ أمام أحد خدمك أو مرءوسيك ، لئلا يحتقرك فى داخله ، أو يقل احترامه لك ...",{"h":"لذلك ففالبية الخطايا تعمل فى الخفاء ، إما بسبب الخوف أو بسبب الإستحياء ."},"وهكذا قيل عن الخطاة إنهم « أحبوا الظلمة أكثر من النور ، لأن أعمالهم شريرة » (يو ٣ : ١٩) . وقال الرب عن أعدائه المتآمرين عليه « هذه ساعتكم وسلطان الظلام » (لو ٢٢ : ٥٣) .",{"h":"فإن كنت تخجل أو تخاف من إنسان يراك ، فكم بالأولى الله ؟ !"},"فإن آمنت تماماً بأن الله موجود فى كل مكان أنت فيه ، يراك ويسمعك ويرقبك ، فلا شك سوف تخجل أو تخاف من أن ترتكب أى خطأ ... أمام الله . ولهذا فإن القديس يوسف الصديق عندما عرضت عليه الخطية ، رفض الخطية قائلاً :",{"h":"« كيف أفعل هذا الشر العظيم ، وأخطىء إلى الله » (تك ٣٩ : ٩) ."},"إعتبر أنه خطأ إلى الله . كسر لوصاياه . وعدم احترام له ، إذ يفعل الشر قدامه بلا حياء ... فهل عندك هذا الشعور ؟ هل تضع الله أمامك فى كل خطية تحارب بارتكابها . وهل تذكر ما قاله الرب لكل ملاك من ملائكة الكنائس السبع (فى سفر الرؤيا) . إذ قال لكل منهم :",{"h":"« أنا عارف أعمالك » (رؤ ٢ : ٢ ، ٩ ، ١٣ ، ١٩ ، رؤ ٣ : ١ ، ٨ ، ١٥) ."},"لو عرفت هذا ستخجل وتخاف ، وتمتنع عن الخطية ، لأن خوف الله سيكون أمام عينيك باستمرار فى كل مرة تحاول فيها أن تخطىء",{"h":"بل إنك تشعر بالاستحياء من أرواح الملائكة والقديسين ."},"إن كنت تؤمن من كل قلبك أن ملائكة الله حالة حولنا (مز ٣٤ : ٧) . وأننا « صرنا منظراً للعالم ، للملائكة والناس » (١كو ٤ : ٩) ... حينئذ لابد ستخجل"],"57":["من الملاك الذى حولك ، والذى لقداسته لا يحتمل رؤية بعض الخطايا فيتركك ... وكذلك لابد ستخجل من أرواح القديسين ومن أرواح أقربائك ومعارفك ... وبهذا الخجل تبعد عن الخطية ، وتقترب إلى حياة النقاوة .",{"h":"وإن كنت تؤمن أن الله قدوس ، ستخشى أن تظهر نجاساتك أمام هذه القداسة غير المحدودة ."},"وفى كل مرة تقول فى صلاتك « قدوس قدوس قدوس » ستشعر فى داخلك بخزى عظيم على الماضى ، ولا تجرؤ على ارتكاب الخطية فى المستقبل . إن اشعياء النبى عندما سمع السارافيم يسبحون الرب بهذه التسبحة « قدوس ... » صرخ قائلاً « ويل لى قد هلكت . لأنى إنسان نجس الشفتين ... » (اش ٦ : ٣ ، ٤) .",{"h":"إن كنت تؤمن أن الله فاحص القلوب وقارىء الأفكار ..."},"وأنه يعلم كل ما يخطر على فكرك وفى قلبك من مشاعر وخطط وتدابير ، حينئذ كنت تخاف من معرفته لدواخلك وتخجل من قدسيته ، وتبتعد عن هذه الأفكار والمشاعر ، فتصل إلى حياة النقاوة .",{"h":"ولعلك تقول :"},"أنا أؤمن بكل هذا : أؤمن أن الله موجود ، وأنه يرى كل شىء ويسمع ، وأنه يفحص القلوب ويقرأ الأفكار ... ومع ذلك أنا لا أزال فى أخطائى ... أجيبك على هذا بأنه :",{"h":"ربما تؤمن بكل هذا نظرياً . ولكنك لا تحيا حياة تليق بإيمانك ... !"},"إن الذى يحيا فى هذا الإيمان بأن الله يراه ، والملائكة تراه ، وأرواح المنتقلين تراه ... عملياً لو وضع هذا الفكر فى قلبه ، لكان يخجل ، وتصغر نفسه فى عينيه ، ولا يجرؤ أن يكمل خطاياه . ولكن على رأى أحد الآباء ـ كما ورد فى بستان الرهبان ـ كل خطية يسبقها إما الشهوة ، أو التهاون ، أو النسيان .",{"h":"لعل الإنسان يكون أثناء الخطية ناسياً الله وملكوته ."},"ولعله يكون ناسياً أنه صورة الله ومثاله ، إن كان يؤمن حقاً بهذا . ولعله يكون ناسياً أيضاً كل وصايا الله ، وكل إنذاراته ، مع أنه نظرياً يؤمن بكل هذا ، ولكن لا يحياه . هو كما قلنا : له إسم المؤمن ، وليس له حياة المؤمن ..."],"58":[{"h":"لذلك : إن كنت تؤمن بالأبدية ، فضع الأبدية أمامك لكى لا تخطىء ."},"إن الذى يؤمن حقاً بأن الموت يأتى كلص (١تس ٥ : ٢) ، والذى يؤمن بأن الله عادل . وقد قال إنه سيأتى ليجازى كل واحد حسب أعماله (رؤ ٢٢ : ١٢) ، والذى يؤمن بالحياة بعد الموت ، والدينونة ، والثواب والعقاب ، والوقوف أمام الله فى ذلك اليوم الرهيب الذى فيه تفتح الأسفار ، وتكشف النيات والأفكار ، وتعلن كل أعمال بنى البشر أمام الكل ... الذى يؤمن بهذا حقاً ، إيماناً عملياً ، من الصعب عليه أن يخطىء ، بل يجد رادعاً داخله يثنيه ، خوفاً وخجلاً ... وتراه دائماً يستعد للملاقاة الرب فى ذلك اليوم ...","ولماذا أتكلم عن الدينونة ، إنى أقول من ناحية أخرى :",{"h":"إن كنت تؤمن بمحبة الله ، فإنك تخجل أن تجرح محبته ."},"كثيراً ما تقول « الله محبة » (١يو ٤ : ٨ ، ١٦) . ولكنك أثناء الخطية ، لا تكون فى حالة إيمان عملى بمحبته . بل ربما لا تكون هذه المحبة فى فكرك إطلاقاً .","إن كنت تؤمن حقاً بأن المحبة هى الرباط المقدس الذى يربطك بالله ، فكيف يمكن أن تخطىء ؟ ! « المولود من الله لا يخطىء » (١يو ٣ : ٩) .",{"h":"بل أنت لا تخطىء ، إن كنت تؤمن بالفضيلة كمنهج حياة ."},"كثيرون يتحدثون عن الفضيلة ، ويدعون الآخرين إليها ، ويمجدونها كثيراً . ولكنهم لا يحبونها . لا يؤمنون عملياً فى أعماقهم بأن تكون الفضيلة هى منهج حياة لهم . وإن آمنوا بذلك عملياً ، لعاشوا فى حياة النقاوة ، مبكتين أنفسهم بشدة على كل ضعف ...",{"h":"أيضاً الذى يؤمن بفناء هذا العالم ، يزهده ولا يخطىء ."},"مثلما كان يقول داود النبى « غريب أنا على الأرض ، فلا تخف عنى وصاياك » (مز ١١٩ : ١٩) ، « غريب أنا عندك ، نزيل مثل جميع آبائى » (مز ٣٩ : ١٢) . وهكذا عاش رجال الإيمان فى كل جيل « أقروا إنهم غرباء ونزلاء على الأرض ... يبتغون وطناً أفضل ... سماوياً » (عب ١١ : ١٣ ، ١٦) ... زهدوا كل شىء فى هذه الدنيا ، وأطاعوا قول الرسول « لا تحبوا العالم ولا الأشياء التى فى العالم ... لأن العالم يمضى وشهوته معه » (١يو ٢ : ١٥ ، ١٧) ."],"59":[{"h":"وبهذا الإيمان عاشوا فى العالم ، دون أن يعيش العالم فيهم ."},"وكان هؤلاء « الذين يستعملون العالم ، كأنهم لا يستعملونه » (١كو ٧ : ٣١) . وبهذا الإيمان ـ على نطاق أكبر ـ عاش الرهبان والمتوحدون وسكان الجبال فى زهد ونسك « وهم لم يكن العالم مستحقاً لهم ، تائهين فى برارى وجبال وشقوق الأرض » (عب ١١ : ٣٨) . وشُهد لهم بالإيمان ...","هكذا يفعل الإيمان ، فى تنقية القلب . وكما قال الرسول :",{"h":"« هذه هى الغلبة التى تغلب العالم ، إيماننا » (١يو ٥ : ٤) ."},"إيماننا بأن نعيش على الأرض « غير ناظرين إلى الأشياء التى تُرى ، بل إلى التى لا تُرى . لأن التى ترى وقتية ، أما التى لا ترى فأبدية » (٢كو ٤ : ١٨) . نعم إن الإيمان بفناء العالم ، هو الذى يجعلنا نغلب العالم ، ونتنقى من العالم وما فيه .",{"h":"إن الإيمان بالأبدية ، يعطى الإنسان يقظة فى ضميره ."},"وهكذا يكون له باستمرار ضمير حىّ : يحكم على كل عمل ، ليس فقط من جهة نجاحه أو فشله ، أو من جهة نتائجه فى حياتنا الحالية ... إنما يحكم على الأمور بمنظار الأبدية ... لأن كل تصرف يتصرفه ، له دخله فى مصيره الأبدى ، وربما فى مصائر الناس ... فكل خير يعمله محفوظ له فى السماء . وكل خطأ يقترفه فى حق الناس أو فى حق نفسه ، سيعطى عنه حساباً فى يوم الدين .",{"h":"وأيضاً الإيمان بوجود الله أمامنا ، يمنح القلب اتضاعاً ."},"يمنحه اتضاعاً فى القلب ، واتضاعاً فى التصرف ، ويمنحه خشية وخشوعاً لأنه واقف أمام الله . مثلما قيل عن القديس بطرس ، إذ كان يصيد (بعد القيامة) إنه لما عرف أن الرب قد أتى « ائتزر بثوبه ، لأنه كان عرياناً » (يو ٢١ : ٧) .","فى حضرة الرب يقف كل إنسان فى خشوع . وبقدر إحساسه بوجود الله ، على هذا القدر يكون خشوعه . وهكذا يختلف الناس فى شعورهم أثناء الصلاة ، فمنهم من يركع ومن يسجد ، أمام عظمة الله غير المحدودة ... أما الذى يكون جالساً أثناء الصلاة ، فماذا أقول عنه ؟ !","والإحساس الدائم بوجود الله ـ حتى فى غير وقت الصلاة ـ يجعل الإنسان فى"],"60":["اتضاع دائم ، لأن العظمة هى لله وحده . وتعاظم الإنسان عمل ضد الإيمان ...",{"h":"لذلك فنحن نرى الملائكة القديسين فى هذا الخشوع الدائم ."},"يقول الكتاب عن طغمة السارافيم « لكل واحد ستة أجنحة : باثنين يغطى وجهه ، وباثنين يغطى رجليه ، وباثنين يطير » (اش ٦ : ٢) . فإن كان الملاك الساراف ، يغطى وجهه ورجليه فى حضرة الله ، من بهاء عظمة الله ، فماذا نقول نحن ؟ وكيف ينبغى أن نكون خاشعين وفى اتضاع قدامه ...","إلى هذه الدرجة نرى الإيمان ينقى القلب ، ويمنحه خشية وحياء واتضاعاً ...",{"h":"فالذى يؤمن بأهمية الله بالنسبة إليه ، يخشى من اقتراف الخطية ، لأنها انفصال عن الله . وما أخطر أن ينفصل إنسان عن الله ."},"أما الذى لا يؤمن بخطورة الخطية ، وبخطورة نتائجها الروحية ، فإنه يتساهل معها ويسقط ، ويفقد نقاوته . أنظر مدى شعور داود بخطورة الخطية حينما قال للرب « لك وحدك أخطأت ، والشر قدامك صنعت » (مز ٥١) . وانظروا إلى يوسف الصديق ، إذ يؤمن أنه حينما يخطىء إلى أحد ، إنما « يخطىء إلى الله » (تك ٣٩ : ٩) .","كل هذه المشاعر الإيمانية إما أنها تجعل الإنسان يمتنع عن الخطية مثل يوسف ، أو ينسحق بعدها مثل داود . وكلا الأمرين من علامات نقاوة القلب ."],"61":[{"h":"الفصل السادس"},{"h":"بساطة الإيمان"}],"62":[{"h":"بساطة الإيمان ، كثير من المفكرين يشتهونها ولا يجدونها ."},"مرّ أحد الفلاسفة على فلاح بسيط ، يصلى فى حرارة شديدة وهو ساجد فى خشوع ، يكلم الله بلجاجة ودالة ، كأنه واقف أمامه ... فقال : أنا مستعد أن أتنازل عن كل فلسفتى ، مقابل أن أحصل على شىء من إيمان هذا الرجل البسيط ، الذى يكلّم من لا يراه ، بكل هذه الثقة ...","لقد شعر الفيلسوف بأن هذا الرجل البسيط ، يمتلك شيئاً ثميناً لم يستطع هو بكل فلسفته أن يحصل عليه ... وهو الإيمان .",{"h":"بساطة الإيمان « تصدق كل شىء » يختص بالله ، وتقبله بلا فحص وبلا جدال ... أعنى ذلك الجدال الذى يشتهر به العقلانيون ..."},"وهذه البساطة تذكرنا بإيمان الأطفال ، الذين يؤمنون بكل الحقائق اللاهوتية والروحية ، فى ثقة كاملة لا تشك ولا تكذّب ، ولا تقدم أى اعتراض من العقل . ولعل هذا من الأسباب التى دعت السيد المسيح أن يقول لتلاميذه « إن لم ترجعوا وتصيروا مثل الأطفال ، فلن تدخلوا ملكوت السموات » (متى ١٨ : ٣) ... قد يكون إيمان الإنسان الكبير أكثر عمقاً . ولكن إيمان الطفل أكثر براءة وبساطة وصدقاً . إيمان حقيقى لا شك فيه . ليت إيمانك يكون قوياً ، كإيمان طفل .",{"h":"أنا لست أوافق الذين يقولون إن الأطفال غير مؤمنين ..."},"هوذا بولس الرسول يقول لتلميذه تيموثاوس « إنك منذ الطفولية تعرف الكتب المقدسة القادرة أن تحكمك للخلاص ، بالإيمان الذى فى المسيح يسوع » (٢تى ٣ : ١٥) . وما أعظم امتداح الرب للطفل الذى أقامه وسط تلاميذه (متى ١٨ : ٢ ، ٣) .",{"h":"الذى يسلك فى بساطة الإيمان ، يعيش بعيداً عن تعقيدات العقل ."},"ويعيش بعيداً عما يقدمه العقل من شكوك وأفكار ، وربما من أضاليل . حقاً إن العقل وزنة من الله . ولكنها كثيراً ما تضل إن بعدت عن الإيمان .",{"h":"الإيمان هو نوع من التجلى ، يقدمه الله للعقل لكى يستنير ."}],"63":["وإن وقف العقل وحده ، فإنه يتعب صاحبه بأفكاره ... لو كان الصبى داود يعتمد على عقله وفكره ، لخاف من جليات مثلما خاف شاول الملك وكل الجيش ... ولكنه اعتمد على الإيمان البسيط ، الذى قال به لجليات « اليوم يحبسك الرب فى يدى » (١صم ١٧ : ٤٦) . ولكن كيف يحبسه الرب فى يده ؟ هذا شىء لم يفكر فيه داود ، إنما تركه إلى الله نفسه ، لأن الحرب للرب كما قال (١صم ١٧ : ٤٦) ... هذا هو الإيمان . وبه انتصر داود ، أكثر من الذين كانوا يستخدمون العقل ميزاناً للأمور ...",{"h":"فى الإيمان البسيط ، المسألة ليست مسألة تفكير ، إنما مسألة ثقة ."},"وحتى إن قال العقل إن الحرب لا بد أن تبحث ما مدى توازن القوى فى القتال ، وكيف تتفوق إحداها ؟ فالإجابة بسيطة : وهى أن الله إذا دخل المعركة ، فإنه سيغير الفكرة البشرية عن ميزان القوى ، فيصبح الطفل داود ومعه قوة الله ، أقوى بكثير من جليات الجبار بدون هذه القوة . وهنا نرى أن الإيمان ـ مع بساطته ـ لا يتعارض مع العقل وموازينه ...",{"h":"الذى يحيا بالإيمان البسيط ، يعيش بلا همّ ."},"لأن الهمّ غالباً ما يأتى نتيجة التفكير الكثير ، الذى يفكر فى المشاكل بطريقة عقلانية . ولكن فى بساطة الإيمان يعمل الإنسان ما يستطيعه ، ويترك العنصر الأهم لله نفسه ، ولا يحمل هماً . وإيقانه بأن الله يعمل ، يعطيه سلاماً فى القلب ، ولا يسمح للهم بالسيطرة على مشاعره .","الذى له الإيمان البسيط لا يحمل هماً ، لأنه قد ترك تدبير أموره إلى الله . وإذ وثق بحسن تدبير الله لحياته ، صار لا يهتم بالغد ، لأن إله الغد هو المهتم به . وكل ما يحدث له فى حياته يتلقاه بعبارة « كله للخير » ، « كل الأشياء تعمل معاً للخير ، للذين يحبون الله » (رو ٨ : ٢٨) .","أما الذى يضع تفكيره مكان التدبير الإلهى ، فإنه يتعب كثيراً ، ويحمل همومه بدلاً من أن يحملها الله عنه .",{"h":"كذلك مما ينزع الهمّ ، ثقة الإيمان البسيط باستجابة صلاته ."},"ولعلكم جميعكم تعرفون قصة تلك البلدة التى أتعبها الجفاف لعدم سقوط المطر ،"],"64":["فقرر أهلها إقامة يوم للصلاة من أجل أن يسقط الله المطر على الأرض . ودعى الكل لكى يصلوا . ولكن طفلة ذهبت وهى تحمل معها مظلة (شمسية) . فلما سألوها عن ذلك ، قالت : ألسنا سنصلى من أجل المطر ؟ ماذا نفعل إذن ، حينما يستجيب الله صلاتنا ويسقط المطر ، وليست معنا شمسيات ؟ ! لقد كان لها الإيمان باستجابة الصلاة . ومن أجل إيمانها أنزل الله المطر ...",{"h":"هذا الإيمان البسيط ، له قوته بالنسبة إلى المعجزات والرؤى"},"لقد تحدث المعجزة بالنسبة إلى شخص ، ولا تحدث بالنسبة إلى شخص آخر . لأن الأول فى بساطة الإيمان يصدقها ويقبلها . أما الآخر فإن الصعوبات التى يقدمها عقله ، تجعله يشك فى داخله من جهة إمكانية حدوثها .","ونفس الوضع يحدث بالنسبة للرؤى . البعض يرى المناظر الإلهية والإستعلانات ببساطة إيمانه . والبعض لا يراها بتعقيدات عقله . والأمر واضح جداً كما حدث فى ظهور السيدة العذراء بكنيستها فى الزيتون بالقاهرة .",{"h":"العقل يحاول أن يحلل كل شىء علمياً ، وإلا فإنه لا يصدّق . بينما الإيمان يحتاج إلى تصديق ، فى بساطة ، بعيدة عن تعقيدات العقل ..."},"لذلك فالمعجزات والرؤى تحدث بالأكثر مع البسطاء . أما (العقلاء كثيراً ! !) الذين ينكرونها ويستهزئون بصدقها ، فإنها لا تحدث لهم إلا نادراً ، لكى تجذبهم إلى الإيمان ، أو لتكون شاهداً عليهم (يو ١٥ : ٢٢) .","إن اليهود لم يصدقوا حتى معجزة منح البصر للمولود أعمى ، وقالوا له إن الذى شفاه رجل خاطىء ! ! (يو ٩ : ٢٤) . كان العقل يضع أمامهم مشكلة الشفاء فى يوم السبت ، لكى يضيّع بها إيمانهم (يو ٩ : ١٦) .","لذلك حسناً قال السيد المسيح عن هؤلاء وأمثالهم ، وممجداً للبسطاء : « أحمدك أيها الآب ... لأنك أخفيت هذه عن الحكماء والفهماء ، وأعلنتها للأطفال » (متى ١١ : ٢٥) . حقاً هؤلاء الأطفال يقصد بهم البسطاء فى إيمانهم ... أما هؤلاء الحكماء والفهماء فى هذه الآية ، فهم المعتزون بإدراكهم وفهمهم ، والمعتمدون على عقلهم وحده ، بعيداً عن الإيمان ... حتى أن بعض الروحيين أمسك رأسه بين يديه"],"65":["وقال : « إن هذه هى الثمرة التى أكل منها آدم وحواء » ... يقصد الثمرة البعيدة عن الله ...",{"h":"فى إحدى الليالى ، قبل رهبنتى ، كنت راجعاً من زيارة أحد الآباء فى الجبل ."},"وكان الظلام قد انتشر ، فقيل لى « لا ترجع وحدك إلى الدير لئلا تضل الطريق » . وكنت أعرف الطريق جيداً ، وأؤمن بإرشاد الله فيه ، ومع ذلك قلت « إن ضللت طريق ، سأبيت فى الصحراء حتى الصباح . وكنت مؤمناً من أعماق بستر الله فى هذا ، وبخاصة لأن كثيراً من الأعراب يبيتون فى الصحراء بلا خوف ، ولكن قيل لى « إنك بسيط أزيد مما يجب ، ولا تعرف الجبل . لأن الجبل مملوء بالحشرات والدبيب ، وهناك خطر الوحوش أيضاً ، وأخطار أخرى من جهة الجو ... وظل (العقل) ينصب فى أذنى ، ليزيل ما فى قلبى من بساطة الإيمان ... ورجعت ليلتها إلى الدير مع أحد الآباء . ولم يعطنى (العقل) وقتذاك فرصة أختبر فيها عمل الله مع الساثرين ليلاً فى الصحراء ، ولا حتى اختبار إيمان الإعرابى الذى يبيت كل ليلة هناك ، وتبيت معه عناية الله وستره ...","أشكر الله أنى عوضت ذلك فيما بعد حينما سكنت فى الجبل وحدى .",{"h":"إن العقل يمكنه أن يصور خطورة فى كل مكان . وفى نفس الوقت لا يعطى مجالاً للتفكير فى عمل الله ... وعلى العكس يطرح غير المؤمن فى عقدة الخوف ."},"ليس معنى هذا أن يلقى الإنسان بنفسه فى التهلكة ، بلا حكمة . وإنما إذا احترس بقدر طاقته ، ثم وجد نفسه فيما يسمونه خطراً ، فحينئذ بكل بساطة يثق فى حفظ الله وستره . ويغنى مع داود النبى « يسقط عن يسارك ألوف ، وعن يمينك ربوات . وأما أنت فلا يقتربون إليك » (مز ٩١) .",{"h":"الإيمان البسيط يثق بأن يد الله تتدخل للإنقاذ ولحل كل مشكلة ."},"هو يثق تماماً أن الله كمحب للبشر ، وكصانع للخيرات ، لا بد سيتدخل فى المشكلة ـ حسب وعوده لأولاده ـ وتمتد يده لحلها","أما كيف يحدث هذا ؟ فهذا ما لا يسأل عنه الإيمان البسيط .",{"h":"إنه يتقبل عمل النعمة فى بساطة ، دون أن يفحص كيف تعمل ."}],"66":["وكم من مرة حاولنا أن نحل مشاكلنا بطرق بشرية . ثم فشلت هذه الطرق جميعها ، ولم تأت بنتيجة . وكانت بصمات الله واضحة ، فوق كل فكر .",{"h":"الإيمان البسيط يثق بعمل الله ، عقيدياً ، وعن طريق الخبرة ."},"الإيمان يدخل الإنسان فى دائرة الإختبارات . والإختبارات تعمق الإيمان وتبنيه على أسس واقعية وليس على مجرد أسس نظرية . والإيمان والإختبار يقويان بعضهما بعضاً ... حتى يصل الإنسان إلى يقين بديهى وهو بساطة الإيمان .",{"h":"الإيمان البسيط يثق أن كل شىء مستطاع ، وليس هناك مستحيل ."},"إنه يوقن تماماً أن الله قادر على كل شىء ، ولا يعسر عليه أمر (أى ٤٢ : ٢) . مهما كان صعب الفهم أو صعب الحدوث . إنه يؤمن بقول الرب « غير المستطاع عند الناس ، مستطاع عند الله » (لو ١٨ : ٢٧) .","وأنا لا تدهشنى عبارة « كل شىء مستطاع عند الله » إنما تذهلنى عبارة « كل شىء مستطاع للمؤمن » (مر ٩ : ٢٣) .",{"h":"وهكذا فإن الإيمان البسيط الموقن بهذا ، يرتفع فوق كل الشكوك ."},"إنه إيمان قوى ، أقوى من كل شك . لأن الشكوك هى من عمل العقل ، والعقل معتز بمقاييسه . أما المؤمن فقد اجتاز مرحلة العقل ، وعاش فى مجال أعلى منها وأعمق . فأعلى من الشكوك توجد بساطة الإيمان .",{"h":"مشكلة الدين ، أن البعض يحاول أحياناً أن يحوله إلى فلسفة ، وأن يخرجه من القلب ، ومن الروح ليحصره فى نطاق العقل ."},"وهذا هو الأمر الذى حاربه القديس بولس الرسول بكل قوته ، فقال إن كرازته كانت « لا بحكمة كلام ، لئلا يتعطل صليب المسيح ... » (١كو ١ : ١٧ ـ ٢٠) .","يقيناً أن المؤمن البسيط ، الذى يكتنز إيمانه فى أعماقه ، فوق مستوى الفحص ، هو أقوى إيماناً من بعض علماء اللاهوت ، الذين يستمدون إيمانهم من الكتب التى يظنون أن لهم فيها حياة ... وقد يكون إيماناً يمكن أن تزعزعه أفكار عقلية مضادة ...",{"h":"درّب نفسك على حياة الإيمان البسيط . وانتفع بما مرّ فى حياتك أو حياة غيرك من خبرات . ولا تجعل كثرة التفكير تبعدك عن الإيمان !"}],"67":[{"h":"الفصل السابع"},{"h":"طاعة الإيمان أو حياة التسليم"}],"68":["إن الذى يؤمن بمحبة الله له ، وسهره على راحته ، وبحكمة الله وحسن تدبيره لحياته ، وبأن الله صانع الخيرات ، يعمل لأجله كل خير ... هذا يمكنه أن يسلّم حياته لله ، يدبرها كيفما يشاء .","وبهذا الإقتناع يحيا باستمرار فى طاعة الإيمان .",{"h":"إنه يسلم حياته لله وهو مطمئن وسعيد ..."},"أما الذى لا يحيا فى حياة التسليم ، فإنه على العكس يعيش قلقاً على حياته ، ويظل يفكر : ماذا أكون ؟ وكيف أكون ؟ ومتى أكون ؟ وهل ينبغى أن أغير ما أنا فيه ؟ وبأية وسيلة ؟ أم أظل كما أنا ... ؟ ويتعبه التفكير ، وغالباً ما يفقد سلامه ، ويظل فى سعى مستمر ، ومناقشة الأمور مع نفسه ، إلى غير نهاية ... ولا يفكر مطلقاً أن يستريح ، ويترك الأمر لله مثل رجل الإيمان ...",{"h":"الإنسان المؤمن عندما يسلم حياته لله ، لا يشترط عليه شروطاً ، ولا يطلب منه ضمانات ، ولا يراقب الله فى عمله معه ..."},"إنه واثق بالله كل الثقة ، فى محبته ، وفى حكمته ، وفى قدرته . مؤمناً أن الله يعرف ما هو الخير له أكثر مما يعرف هو . لذلك يسلم حياته فى يدى الله ، وينساها هناك . وهكذا نراه لا يحمل هماً .","مادام هو مؤمناً بعمل الله من أجله ، لا يمكن أن يقلق ويهتم ، ولا يمكن أن يتعب نفسه بالتفكير . فالمؤمن يحيا فى راحة ، أكثر من الذى يفكر لنفسه ويتعبه تفكيره ...",{"h":"كثيرون لا يقبلون التسليم لله ، إلا إذا فشلت طرقهم البشرية !"},"منهجهم الأساسى هو الإعتماد على الذراع البشرى كل الإعتماد : إما اعتداداً بذهنهم وقدراتهم وحيلهم ، أو لتعودهم هذا الأسلوب ، أو لخطأ عقيدى عندهم ، أو اقتناعاً بأن الله لا يلجأ إليه إلا فى حالة العجز والفشل الكاملين ! حينئذ يأتون إلى الله ، لأنهم جربوا كل حيلة وكل وسيلة وما وصلوا إلى غايتهم ، ولأن فكرهم تعب وأنهك بلا فائدة . فلم يبق سوى الله !"],"69":[{"h":"ليس هذا هو الإيمان ، إنما هذا هو الإضطرار إلى الله ."},"الإيمان هو أن تلجأ إليه فى الصغائر ، كما تلجأ إليه فى الكبائر .","قال السيد المسيح « بدونى لا تقدرون أن تعملوا شيئاً » (يو ١٥ : ٥) . ذلك لأن كل طاقة لنا هى من عنده ... حتى الفكر الصائب ، وحتى مجرد الإرادة الطيبة ، وحتى القدرة على العمل . وذكاؤنا هذا الذى نعتمد عليه ، هو أيضاً من عنده . وما أصدق قول الرسول « لأن الله هو العامل فيكم أن تريدوا وأن تعملوا لأجل المسرة » (فى ٢ : ١٣) .",{"h":"إن عملنا فى الواقع ، هو أن نشترك مع الله ، فى عمله لأجلنا ."},"وهذه هى شركتنا مع الطبيعة الإلهية ، شركتنا مع الروح القدس : نشترك مع الله فى العمل . كما قال القديس بولس الرسول عن نفسه وعن زميله أبولس « نحن عاملان مع الله » (١كو ٣ : ٩) .","وكل عمل لا يشترك الله معنا فيه ، لا يكون عملاً مقدساً ، ولا عملاً مباركاً . وتسليمنا الإرادة لله ، هو نوع من الشركة معه ، نكون فيه كآلات طيعة بين يديه تعمل مشيئته . هو يسيّرها كيفما يشاء . وهى تعمل بفكره وإرادته ، أو بتسليم إرادتها لإرادته ، كشركة الحواس مع المخ ...",{"h":"إن أخطر ما يهدد الحياة الروحية ، هو استقلال الإنسان عن الله ."},"وهذه هى الخطية الكبرى التى وقع فيها شاول الملك فرفضه الله (١صم ١٦) . كان يعمل بفكره وبتدبيره ، بعيداً عن مشورة الله وعن شركته . ولا يرى أنه محتاج إلى أن يشترك الله معه فى العمل . وكأنه يقول : مادمت أستطيع أن أعمل هذا العمل ، فسأعمله ، بكل قوة ، وبكل سرعة ، وحتى بدون صلاة ... لأن إرادتى وحدها هى التى سوف تعمله ... ! وبدون اعتماد على الله . وإن فشلت ، ألجأ إليه ! مادام الله قد وهبنى عقلاً وإرادة ، فلماذا لا أستخدمهما ؟ ! ... وكثيرون مثل شاول ...",{"h":"الله قد وهب البشرية العقل والإرادة . ولكن ليس لتستقل عنه !"},"وليس لكى تعتد بذاتها . فالكتاب يقول « وعلى فهمك لا تعتمد » (أم ٣ : ٥) . ولنتذكر أن خطيئة الإنسان الأول ، كانت محاولته الحصول على المعرفة بعيداً عن الله (تك ٣) ..."],"70":["ومتى بدأ الإنسان يقول « أنا أعرف ، وأنا أقدر ، ولا أجد الحاجة فى هذا الأمر إلى الله ! ؟ » يكون حينئذ قد بعد عن الإيمان بالله ، ودخل فى الإيمان بالأنا (الذات) الـ Ego ...",{"h":"أما المؤمن فلا يكتفى بالإعتماد على الله ، بل يسلمه كل شىء ..."},"ويقول له : حياتى هى صنع يديك ، وهى الآن بين يديك ، إفعل بها ما تشاء . حيثما تسيرنى أسير ، وكيفما تصيرنى أصير . أنا ليست لى إرادة خاصة ، فإرادتى الوحيدة هى أن أصنع إرادتك ، وأن أتحد بإرادتك ، فأريد ما تريده أنت ، أنت يا صانع الخيرات ...","لست أقول عن شىء إننى أعرف . فكل معرفة الإنسان هى جهالة عند الله (١كو ١ : ٢٠) . المعرفة الحقيقية هى من عندك يارب وحدك . أنت هو الحكمة (١كو ١ : ٢٤) . أنت « المذخر فيه كل كنوز الحكمة والعلم » (كو ٢ : ٣) .",{"h":"ولأنى أعترف أنى لا أعرف ، لذلك سلمت حياتى فى يديك ."},"أنت تعرف الخير أكثر مما أعرفه . وأنت تعرف الخير لى أكثر مما أعرفه لنفسى . وأنا واثق بحكمتك وبحسن تدبيرك لحياتى . حتى إن شئت لى التجربة أو الضيقة ، فأنا أقبلها باعتبار أنها خير خالص هو من يديك . ولولا ذلك ما كنت أنت المحب ترضاها لى . حقاً فى حالات كثيرة ، لا نعرف أين هو الخير !",{"h":"إن حياة التسليم لا تعرف الشكوى ولا التذمر ، بل تقبل كل شىء برضى وفرح ..."},"مادمت يا أخى تثق بحكمة الله فى تدبيرك ، فلماذا إذن أنت تشكو أو تتذمر أو تضجر . إذا دخل التذمر إلى حياتك ، فافحص نفسك جيداً ، لئلا يكون إيمانك قد ضعف وأنت لا تدرى .",{"h":"الذى يحيا حياة الإيمان والتسليم ، يحيا دائماً فى فرح وفى شكر ."},"إنه لا يشكو بل يشكر ، الإبتسامة لا تفارق شفتيه ، والبشاشة لا تفارق وجهه ، والفرح لا يفارق قلبه . إنه يؤمن بحكمة الله ومحبته . ويؤمن أن مشيئة الله دائماً صالحة ومفيدة . وهو يخضع لمشيئة الله فى فرح ...","لا يخضع لمشيئة الله فى تغصب واضطرار . وكأن قلبه يقول لله : « ماذا أفعل"],"71":["يارب ؟ أنت هو القوى وأنا الضعيف . وكل ما تعمله أنا أقبله . وأنا منتظر نهاية هذا الأمر ... ! ! » . لا شك أن هذا كلام إنسان متعب فى داخله ، يتكلم بكلام تذمر فى أسلوب تسليم . وليس التسليم هكذا ...",{"h":"إذن ما معنى « لتكن مشيئتك » فى حياة الإيمان وحياة التسليم ؟"},"الإنسان المؤمن يقول فى رضى قلبى كامل : أنا يارب خاضع لمشيئتك ، لأنى أحب مشيئتك من أعماقى ، وأثق بك وبها . مشيئتك هذه أصلحت أفكارى ، وأصلحت أحكامى على بعض الأمور ، وعدلت مسارى وطريقى ... ما أجمل طرقك يارب « ما أبعد أحكامك عن الفحص ، وطرقك عن الإستقصاء » (رو ١١ : ٣٣) . مشيئتك هذه هى أجمل أغنية فى فمى ، وأحلى الأخبار فى أذنى . فلتكن مشيئتك إذن ، لأنه لا توجد مشيئة أخرى أياً كانت أصلح منها . إلى جوارها أشعر بجهالة أية مشيئة تتعارض معها ، سواء كانت لى أو لغيرى ...",{"h":"ليست حياة التسليم ، هى الخضوع لسياسة الأمر الواقع ، دون اقتناع !"},"وليست هى الخضوع لسياسة الضغط الإلهى (!) الذى يفرض سلطانه عليك فرضاً ! وأنت مضطر أن تخضع له سواء أردت أو لم ترد ! !","لا يا أخوتى ، ليس هذا هو معنى عبارة « لتكن مشيئتك » . فحياة التسليم تعلمنا أن نشعر بأن مشيئة الله هى الخير الكامل ، وهى أصلح ما يصلح لنا ، وهى سبب فرحتنا وبهجتنا ، ولهذا كان داود النبى يتغنى بأحكام الله . ويقول للرب : أحكامك هى درسى . أحكامك هى لذتى . أنا أتأمل أحكامك وأدرسها (مز ١١٩) .",{"h":"التسليم لله ينبغى أن يكون تسليماً حقيقياً ، وليس حسب الظاهر ."},{"h":"البعض يظن أنه يسلّم حياته لله ، بينما يفرض على الله خططه !"},"كلما يتصرف الله فى حياته ، يحاول أن يستوقف الله ، ويقول له : إنتظر يارب لأرى ما أنت فاعل بى . لا يصلح هذا الأمر . إعمل كذا وكذا لأستريح . وهكذا يود أن يشتغل عند الله وزير تخطيط . هو يخطط ، والله ينفذ ! !","كلا ، ليس التسليم هكذا ، إنما هو أن تترك الله يعمل حسبما يشاء ، وترضى بما يعمل . ولا تقاوم خطط الله بتصرفاتك . لا تقاوم مشيئته بما تعمله حسب هواك ..."],"72":[{"h":"الإنسان المؤمن يترك التدبير لله . ولا يقبل أن يدبر نفسه بنفسه ."},"ماذا كانت خطية أبينا آدم سوى أنه بدأ يدبر نفسه : كيف يصل إلى المعرفة ؟ كيف يصير مثل الله ؟ كيف يكوّن نفسه وبينها ... وهكذا سقط .",{"h":"وخطية الشيطان ، هى أنه بدأ يدبر نفسه ، ويبنيها ويكبرها حسب هواه !"},"« أصعد إلى السموات . أرفع كرسىّ فوق كواكب الله ... أصعد فوق مرتفعات السحاب . أصير مثل العلى » (اش ١٤ : ١٣ ، ١٤) . إنها خطط تشبه أحلام اليقظة ، رسمها الشيطان لنفسه « فانحدر إلى الهاوية ، إلى أسافل الجب » .",{"h":"وبالمثل الذين بنوا برج بابل ، جلسوا يخططون لبناء أنفسهم ، ففشلوا ."},"قالوا « هلم نبنِ لأنفسنا مدينة وبرجاً رأسه فى السماء . ونصنع لأنفسنا إسماً لئلا نتبدد على وجه الأرض » (تك ١١ : ٤) . فكان تخطيطهم ضدهم . وما خشوه ، هو الذى صاروا إليه « فبددهم الله على وجه كل الأرض » (تك ١١ : ٩) .","أما الإنسان الروحى فلا يفعل هكذا ، بل فى حياة التسليم يقول :",{"h":"« إن لم يبن الرب البيت ، فباطلاً يتعب البناءون » (مز ١٢٧ : ١) ."},{"h":"الله هو الذى يبنينا وليس نحن . إذن نسلمه أنفسنا لينبنيها ."},"وهكذا نعيش فى راحة ، مطمئنين إلى عمل الله فينا ، وإلى نجاح عمله . نقف ونتأمل ، فنرى عجائب من تدبيره . واثقين أنه يعمل الخير ، مهما كان الذى يحدث أمامنا غريباً ، أو صعباً ، أو ضد ما كنا نرجوه .",{"h":"ليس المهم أن نفهم ما يعمله الله . إنما المهم أننا بالإيمان والتسليم نتقبله ."},"والكتاب المقدس حافل بأمثلة التسليم فى حياة رجال الإيمان :","١ ـ أبونا ابراهيم مثلاً ، كانت بداية قصته مع الله ، هى قول الله له « أترك أهلك وعشيرتك وبيت أبيك ، إلى الأرض التى أريك » (تك ١٢ : ١) .",{"h":"وأبونا ابراهيم لم يسأل لماذا ؟ ولا إلى أين ؟ بل أطاع ..."},"هذه هى حياة التسليم ، التى لا تجادل ولا تناقش ، بل تقبل وتطيع ، بلا تردد . تدع فهمها جانباً ، وتركز على أمر الله ."],"73":[{"h":"٢ ـ وهكذا كان نوح فى الفلك ، وكان يونان فى بطن الحوت ، وكان موسى فى البحر الأحمر ... فى حياة تسليم كامل ."},"إنها طاعة الإيمان . مادام الله يريد هذا ، فنحن لا نناقشه . وما هو عقلنا المحدود الضعيف ، حتى يناقش الله غير المحدود ، كلى الحكمة ... ؟ ! إن موسى فى بدء إرساليته جادل الله فى كيف يدخل إلى فرعون (خر ٣) ، ولكنه لما نما فى الإيمان والتسليم لم يجادل فى دخوله البحر الأحمر ...",{"h":"٣ ـ القديسة العذراء مريم عاشت كمثال لحياة الطاعة والتسليم ."},"مع كل محبتها للبتولية ، قيل لها أن تخطب لرجل وتعيش معه فى بيت واحد ، فأطاعت . وأرسل لها الله ملاكاً يقول لها إنها ستحبل وتلد ، فقالت له « هوذا أنا أمة الرب . ليكن لى كقولك » (لو ١ : ٣٨) ... ومع ولادتها لله الكلمة ، ورؤيتها كل ما أحاط بهذا الميلاد من معجزات ، قيل لها أن تهرب به إلى مصر وتتغرب هناك ، فقبلت كل ذلك فى طاعة الإيمان . وفى تسليم أيضاً رجعت من مصر ، وقبلت أن تسكن فى الناصرة (متى ٢ : ٢٣) ، التى قيل إنها لا يخرج منها شىء صالح (يو ١ : ٤٦) .","وكان شعارها فى حياة التسليم هذه ، عبارتها الخالدة « ليكن لى كقولك » .",{"h":"٤ ـ ولعل الإيمان والتسليم يظهران فى حياة الرسل فى طاعتهم التلقائية لقول الرب « إتبعنى » أو « هلم ورائى » ."},"هكذا قال الرب لمتى (لاوى) . وهو فى مكان الجباية (مر ٢ : ١٤) فلم يناقش وإنما « ترك كل شىء وقام وتبعه » (لو ٥ : ٢٨) . ولم يفكر مطلقاً فى كل مسئولياته وعمله .","وبالمثل لما دعا الرب بطرس وأندراوس وباقى الرسل ، يلخص القديس بطرس كل قصص هذه الدعوة بقوله للرب « تركنا كل شىء وتبعناك » (لو ١٨ : ٢٨) .","إنها طاعة الإيمان التى تتبع الرب حيثما ذهب ، بلا سؤال ، بلا استفسار ، بلا تفكير فى المستقبل . وكما سنشرح أن كلاً منهم أطاع ، وهو لا يعلم إلى أين يذهب (عب ١١ : ٨) .",{"h":"ونحن كثيراً ما ندعى ، فنحاول أولاً أن نطمئن على مستقبلنا ."},"لذلك نسأل الكثير من الأسئلة . ونحصل على ما نستطيعه من الضمانات ."],"74":["وبكل هذا نخرج من الإيمان إلى العيان ... إلى المستقبل الذى نراه بعيوننا ونطمئن إليه ، وليس إلى المجهول الذى نراه بالإيمان ، ونقبله بحياة التسليم والطاعة ...",{"h":"٥ ـ من أمثلة حياة الإيمان والتسليم والطاعة ، أرميا النبى ."},"سار وراء الله بالإيمان ، فى طرق لم يفكر مطلقاً أن يسير فيها ... وأخيراً لخص خبرته فى حياة التسليم فى عبارة عميقة قال فيها « عرفت يارب أنه ليس للإنسان طريقه . ليس لإنسان يمشى أن يهدى خطواته » (أر ١٠ : ٢٣) . ولماذا لا يهدى خطواته ؟ لأن الله هو الذى يقود هذه الخطوات ويهديها ...",{"h":"هذه هى حياة التسليم ، أن تسير وراء الله ، وليس وراء فكرك ."},"تسير ليس وراء هواك ورغباتك ، وليس وراء مشيئة الناس أو مشورة الناس ، إنما وراء الله نفسه الذى يقود حياتك . يضعها فى أى وضع ، وفى أى موضع ، حسب أعماق حكمته . فاسأل نفسك هل الله هو الذى يقود حياتك ؟ أم تقودها رغبة معينة ، هى التى تحدد تصرفاتك ومسير خطواتك ؟",{"h":"٦ ـ من الأمثلة العجيبة فى حياة التسليم : يوسف الصديق ."},"أظهر له الله بالرؤى أنه سيصير سيداً لإخوته ، وسيسجدون له جميعهم (تك ٣٧ : ١٠) . فماذا كان تحقيق الوعد ؟ أخذه إخوته وألقوه فى بئر ليقتلوه . ثم باعوه كعبد . وسحبه المديانيون من البئر ليبيعوه للإسماعيليين (تك ٣٧ : ٢٨) . ثم بيع لفوطيفار ليخدم فى بيته ...",{"h":"وفى كل هذا لم يحتج يوسف متذمراً على الرب وعلى أحلامه ..."},"بل سكت . وسلّم فى هدوء لما سمح به الرب ، وسلك بكل أمانة وإخلاص . وقبل الحياة كخادم ... ولكنه رضى بالبلوى ، والبلوى لم ترض به ! فإذا بتهمة باطلة رديئة تلفق ضده ، ويلقى به فى بيت السجن كفاعل إثم ... !",{"h":"ولم يحدث أن يوسف سأل الرب لماذا ؟ ... أو أين هى وعودك ؟"},"سكت فى مثل رائع لحياة التسليم وطاعة الإيمان . ولم يتذمر مطلقاً . وفى المرة الوحيدة التى خرج فيها قليلاً جداً عن حياة التسليم ، وقال لرئيس السقاة بعد أن فسّر له حلمه « حينما يصير لك خير ، تصنع إلىّ إحساناً ، وتذكرنى لفرعون ، وتخرجنى من هذا البيت » (تك ٤٠ : ١٤) ... لما فعل هذا ، أجاب الوحى الإلهى على هذا"],"75":["الطلب بقوله « ولكن لم يذكر رئيس السقاة يوسف ، بل نسيه » (تك ٤٠ : ٢٣) ...","ولكن الله لم ينس يوسف ، الذى بقى فى السجن فى حياة التسليم ، حتى أخرجه الله منه بمجد عظيم ...",{"h":"٧ ـ ومن أمثلة حياة التسليم وطاعة الإيمان : داود النبى ."},"كان « يرعى الغنيمات القليلات فى البرية » . وأرسل له الله صموئيل النبى ومسحه ملكاً . ولكنه لم يسلمه من الملك شيئاً ... وبقى يرعى الغنيمات القليلات ، دون أن يتذمر . ثم اختير خادماً للملك شاول المرفوض من الله الذى بغته روح ردىء من قبل الرب (١صم ١٦ : ١٤) ... ولم يحتج داود .",{"h":"لم يقل أنا الملك المختار من الله . فكيف أخدم هذا المرفوض ؟ !"},"بل فى حياة التسليم تقبل الوضع . وكان يهدىء شاول الملك حينما تبغته الشياطين ... وظل شاول يطارد داود من برية إلى برية ، ويحاول قتله ، حسداً منه وغيرة ... ولم يحدث مطلقاً أن داود ناقش الله ، أو قال له أين مواعيدك ؟ أين المسحة المقدسة من النبى العظيم ؟ ولم يقل له ماذا فعلت من شر حتى أستحق كل هذا ؟ ! ... بل انتظر ، فى هدوء وفى تسليم ، خلاص الرب . وقد كان ...",{"h":"٨ ـ ومن أمثلة حياة التسليم : تلاميذ الرب ."},"دعاهم الرب للخدمة كما قال لبطرس وأندراوس « هلما ورائى فأجعلكما صيادى الناس » (متى ٤ : ١٩) . ومرت ثلاث سنوات وهم يتبعونه ، دون أن يخدموا . ولم يصيدوا أحداً . ثم ضلب الرب . وخافوا ، وأغلقوا على أنفسهم فى العلية لئلا يصيدهم اليهود ... ومع كل ذلك لم يشكوا . وبقوا فى حياة الإيمان والتسليم .","وأخيراً بعد حلول الروح القدس ، تمم الرب وعده . وفى يوم واحد تمكن بطرس بعظة واحدة من أن يصيد ثلاثة آلاف نفس ... ولو أنه كان كل يوم يصيد نفسين ، ما وصل إلى هذا الرقم كله ، ولكن حياة التسليم تقول للرسول : « إنتظر الرب . تقوّ ، وليتشدد قلبك . وانتظر الرب » (مز ٢٧ : ١٤) .","نعم يارب سأنتظر وعدك فى صيد الناس . ولكن هل إلى ثلاث سنوات وأكثر ؟ إنه لكذلك . ولكن « ليس لكم أن تعرفوا الأزمنة والأوقات التى جعلها الله فى سلطانه وحده » (أع ١ : ٨) .",{"h":"إن حياة التسليم لا تناقش الرب فى مدى الإنتظار الطويل لمواعيده ."}],"76":["إنها لا تقول له : لماذا يارب تجعل بطرس ينتظر أكثر من ثلاث سنوات ليصير صياداً للناس ؟ ولماذا تترك ابراهيم ينتظر خمسة وعشرين عاماً حتى تحقق له وعدك فى ميلاد اسحق ؟ ولماذا تترك داود فى مذلته من شاول عشرات السنوات ، حتى تحقق له اختيارك له ملكاً ... ؟",{"h":"إن حياة التسليم لا تشك ، وترى فى الإنتظار حكمة إلهية ."},"فقد كان داود صبياً حين اختياره . وكان الإنتظار نافعاً له حتى يكبر وينضج ، وحتى يزداد الناس حباً له يوماً بعد يوم . كذلك كان الإنتظار نافعاً لبطرس حتى تكتمل تلمذته للرب ، وحتى يحين موعد حلول الروح القدس لينال به قوة هو وسائر الرسل . كذلك كان الإنتظار نافعاً لولادة اسحق ، ليصير إبناً للموعد ...",{"h":"٩ ـ من أجمل الأمثلة فى حياة التسليم : تقديم اسحق محرقة ."},"لقد صبر ابرآم خمساً وعشرين سنة ، حتى ولد له اسحق ، إبنه المحبوب الذى أخذ المواعيد من أجله . وفرح به فرحاً لا يوصف . وكبر اسحق . وإذا بالرب يقول لأبينا ابراهيم « خذ إبنك ، وحيدك ، الذى تحبه ، إسحق ... وأصعده محرقة على أحد الجبال الذى أريك » (تك ٢٢ : ٢) ... أى قلب يمكنه أن يحتمل هذا ؟ ! وأى عقل يسمع هذا ولا يشك ... ؟ !",{"h":"ولكن أبانا ابراهيم فى حياة التسليم ، لم يناقش ، ولم يتردد فى التنفيذ . بل بكّر صباحاً ، وأخذ إسحق ليذبحه ... ولم يحسب نفسه أحنّ من الله ... ولم يشك فى محبة الله ولا فى حكمته ..."},"إن الطاعة لا تكون فى الأمور السهلة فقط ، وإنما تظهر فى قمة سموها فى الأمور التى تبدو صعبة جداً فى التنفيذ .",{"h":"حياة التسليم تظهر فى الدخول من الباب الضيق والطريق الكرب ."},"مادمت أنت يارب موافقاً على هذا الباب الضيق ، فإنه يكون أصلح الأبواب للدخول . ولا نناقشك ... بل نفرح بذلك ، ونرى أنك تختبر به محبة أولادك ، ونقاوة قلوبهم ، وتعد به لهم أكاليل فى ملكوتك ...","وبهذا الإيمان ، إستقبل الشهداء والمعترفون كل أنواع الآلام فى فرح . وكل أولادك يارب كانوا « يحسبونه كل فرح حينما يقعون فى تجارب متنوعة » (يع ١ : ٢) ."],"77":[{"h":"لا يعلم إلى أين يذهب"},"« بالإيمان ، إبراهيم لما دعى أطاع ... فخرج وهو لا يعلم إلى أين يذهب » (عب ١١ : ٨)","١ ـ هكذا سار أبونا ابراهيم وراء الله ، إلى المجهول ... لم يكن يعلم إلى أين الطريق ، إنما كان واثقاً أن الله يصحبه فى الطريق ، ويرشد خطاه ...",{"h":"٢ ـ وهكذا حدث مع آبائنا الرسل الأطهار ، لما دعاهم الرب فتبعوه ."},"وهم لا يعلمون إلى أين ... إذ لم يكن للمسيح مقر معروف ، بل لم يكن له أين يسند رأسه (لو ٩ : ٥٨) . كان يطوف المدن والقرى يعلّم ويشفى ، مع أنه لم تكن له وظيفة رسمية فى المجتمع اليهودى ... ولم يكن له دخل مالى معروف . وحتى لما دعا تلاميذه ، قال لهم « لا تحملوا ذهباً ولا فضة ولا نحاساً فى مناطقكم ... ولا تحملوا معكم شيئاً للطريق » (متى ١٠ : ٩ ، مر ٦ : ٨) .","ولو سألت أحد تلاميذه وقتذاك : ما هو عملك ؟ وما هو مستقبلك مع المسيح ؟ لوقف وأوقفك معه ، أمام علامة استفهام كبيرة لا يعرف لها جواباً ، سوى حياة التسليم ... يكفيه أنه سائر مع المسيح ، مع أنه معه وفى وجوده لا يعمل شيئاً ... المسيح يعمل كل شىء ، وتلاميذه مجرد متفرجين .",{"h":"٣ ـ خذوا مثالاً لذلك القديس مار مرقس الرسول حينما دخل الإسكندرية :"},"دخلها وهو لا يعلم إلى أين يذهب ، إذ لم تكن هناك كنيسة يستقر فيها ، ولم يكن له هناك شعب ، ولا مسكن ... بل على العكس كانت الوثنية فى كل مكان ، وكانت اليهودية تقاوم الإيمان ... ولكن بالإيمان جاء مارمرقس إلى مصر ، وأرشد الله خطاه إلى إنيانوس ، وما كان فى فكره هذا الأمر ...","وما حدث لمار مرقس ، حدث تقريباً لباقى الرسل . تتنوع الأمكنة والأسماء ، ولكن قلب الموضوع واحد . وكأن كل رسول كان يقول :"],"78":[{"h":"لو كانت الخدمة عملاً بشرياً ، لكان يهمنى أن أعرف خطة مسيرى . أما الخدمة عمل إلهى ، فلا يهمنى إلى أين أذهب . أنا مع الله . حيث قادنى أسير ."},"٤ ـ يوحنا المعمدان كان يرى أن واجبه هو أن يشهد للحق . فشهد للحق ، وقال لهيرودس الملك « لا يحل لك » ولم يهتم بعد ذلك إلى أين يذهب : إلى السجن ، إلى الموت ... ليكن ما يكون . رسالة الله تتم فى طاعة إيمانية كاملة . أما الحياة ، وأما المصير ، فهما مسلمان لله ... إلى التمام .","وهكذا كان بولس الرسول يشهد للرب ... وبعد ذلك لا يهمه إلى أين يذهب : « أشدة أم ضيق أم اضطهاد أم جوع أم عرى أم خطر أم سيف » ، يقول فى ثقة بحياة التسليم « لكننا فى هذه جميعها ، يعظم انتصارنا بالذى أحبنا » (رو ٨ : ٣٥ ، ٣٧) .","بهذا الأسلوب ، سار أولاد الله جميعهم فى طريق الحياة فى حياة التسليم .",{"h":"كل ما يهمهم هو أن الله يقودهم . ولكن لا يعنيهم إلى أين ... ولكنهم واثقون بالإيمان ، أنه سيقودهم إلى المراعى الخضراء ، وإلى ينابيع الماء الحى . خبرتهم مع الله تجعلهم مسرورين بقيادته ، واثقين بمحبته ."},{"h":"٥ ـ إسحق بن ابراهيم حمل الحطب وراء أبيه ، ولم يعلم إلى أين يذهب ."},"كل ما تعلمه فى حياته ، هو التسليم والطاعة ، وبها سار حتى إلى المذبح . وربطه إبراهيم أبوه ووضعه على المذبح فوق الحطب (تك ٢٢) ، ورفع عليه السكين . كل هذا وإسحق فى تسليم كامل . لم يشك فى محبة أبيه ، ولم يشك فى محبة الله ... وانتصر على طول الخط .","بتسليمه هذا ، كسب طاعة الإيمان ، وكسب حياته ، وكسب وعود الله ...",{"h":"٦ ـ لعازر الدمشقى لما سافر ليختار زوجة لإسحق ، ما كان يعلم إلى أين يذهب ."},"ولكنه سلّم خطاه لله ليرشده . ودبر الله له كل شىء بطريقة عجيبة وقف أمامها مذهولاً . وتم كل شىء حسبما طلب منه سيده ابراهيم . ولهذا قال « الرب"],"79":["أنجح طريق » (تك ٢٤ : ٥٦) .","ولعل لعازر الدمشقى كان يقول « لم أكن أعلم إلى أين أنا أذهب . لكنى كنت أعلم تماماً أن الله ذاهب معى » .","ونفس الوضع تقريباً حدث ليعقوب فى رحلته إلى خاله لابان . وما أجمل قول الرب له « ها أنا معك . أحفظك حيثما تذهب » (تك ٢٨ : ١٥) .",{"h":"٧ ـ الشعب فى البرية ، أتراه كان يعلم إلى أين يذهب ؟ !"},"ما كان يعلم شيئاً . كان الله يقوده يوماً بيوم . وكان يرتحل بإرشاد إلهى ، ويقف بإرشاد إلهى . وكان هذا الإرشاد يتمثل فى السحابة تظلله نهاراً ، وعمود النار يهديه ليلاً ... والشعب فى تسليم كامل لقيادة الله ، لا يسأله إلى أين ... ؟","وما كانت أمام موسى النبى خطة لمسيره ، ولا خريطة لمسيره . وكأنه يقول :",{"h":"يكفينا يارب أن تكون سحابتك فوق رؤوسنا ، وعمود النار أمامنا . نحن لا نحدد مسارنا ، إنما تحدده مشيئتك الصالحة . أما نحن فيسعدنا أننا تحت قيادتك . حيثما سارت سحابتك نسير . وحيثما حلت نستظل تحتها ... يفرحنا أننا نرى فوق تابوت العهد الضباب الذى يمثل وجودك ."},"فلتتحرك خيمة الإجتماع فى البرية نحو المجهول . إنه مجهول بالنسبة إلينا . ولكنه فى علمك ومعرفتك منذ الأزل . وهذا يكفينا ، لكى نسلّم خطانا لهذا المجهول ، ونحن فى ملء الثقة بأننا فى طريق كنعان ...",{"h":"٨ ـ القديس الأنبا أنطونيوس أب جميع الرهبان ، حينما دخل إلى الجبل ، أتراه كان يعلم إلى أين يذهب ؟ ! وكذلك القديس الأنبا بولا أول السوّاح ..."},"وأيضاً كل السواح والمتوحدين حينما توغلوا فى البرية الجوانية ، ما كان أمامهم هدف مكانى معين يقصدونه . كل ما كان أمامهم هو الهدف الروحى وهو أن ينفردوا بالله فى حياة السكون والهدوء ، مسلمين حياتهم بالكلية له « تائهين فى البرارى والجبال وشقوق الأرض » ...","تسأل كل واحد من التائهين فى البرارى : أتعلم أين أنت ؟ فيجيبك :",{"h":"على خريطة المكان ، لست أعلم أين أنا ... ولكن على خريطة الحب ، أعلم أننى فى حضن الآب ."}],"80":[{"h":"٩ ـ ولعل البعض يسأل : أما ينبغى أن يحسب كل إنسان حساب النفقة ، حسب وصية الرب نفسه (لو ١٤ : ٢٨) ؟"},"إن حياة الإيمان ، هى أبعد ما تكون عن علم الحساب الذى يقصدونه . إذن ما الذى يقصده الرب بأن يجلس الإنسان أولاً ويحسب النفقة ؟",{"h":"حساب النفقة هو : هل عندك من الإيمان ما يكفى ؟"},"هل عندك من الإيمان ما تسلّم به الأمر كله لله لكى يدبره ؟ إنك تفعل ما تستطيعه . ولكن هذا هو أقل المطلوب . أما العنصر الأساسى فهو إيمانك بما يفعله الله ، وتسليمك له كل الأمر ...","وهذا كان منهجنا ، حينما كنا نريد أن نبنى كنيسة أو أى مشروع للخدمة والرعاية . لم يكن السؤال الأساسى هو « من أين التكاليف ؟ » ، إنما كان السؤال الأساسى هو : هل الله موافق على هذا البناء أم لا ؟ فإن كان موافقاً فهو الذى سيقوم بكل تكاليفه . وما علينا إلا أن نبدأ ، ويد الله تكمل العمل معنا « وإن لم يبن الرب البيت ، فباطلاً يتعب البناءون » (مز ١٢٧ : ١) .",{"h":"الإيمان هو أن تغمض عينيك ، وتبصر الله ."},"طالما أنت تفتح عينيك ، فأنت تسير بالحواس الجسدية . أما إن أغمضت هذه العين الجسدانية ، حينئذ سوف تسلك بالقلب والروح .","إن تأكدت بحواسك الروحية أن الله سيذهب معك فى طريق ، سر فيه ولو كان فى وادى ظل الموت . يقيناً ، هناك سوف لا تخاف شراً لأن الرب معك (مز ٢٣) .",{"h":"١٠ ـ هذه هى حياة التسليم ، التى فيها يختار الرب لنا ما نشاء ، دون أن نختار نحن لأنفسنا . آخذين درساً من قصة لوط وإبراهيم ."},"لوط اختار لنفسه السكنى فى سادوم ، الأرض المعشبة (تك ١٤ : ١٠ ، ١١) . وكان يعلم إلى أين يذهب . أما إبراهيم فلم يختر لنفسه شيئاً . إنما قال له الرب « إرفع عينيك وانظر ... جميع الأرض التى أنت ترى ، لك أعطيها » (تك ١٠ : ١٤ ، ١٥) ... وماذا كانت النتيجة ؟ لوط سبى وهو فى سادوم وأنقذه إبراهيم (تك ١٤) . ثم احترق كل ماله فى سادوم وخسر الكل ...","وهكذا كانت حياة التسليم التى لإبراهيم ذات نتيجة أفضل ..."],"81":[{"h":"الفصل الثامن"},{"h":"(عنوان الفصل مطبوع بخط مزخرف مقلوب في ملف المصدر الممسوح ولا يمكن قراءته بدقة. ويبدو أن ما يلي هذه الصفحة في الملف يبدأ في منتصف جملة؛ فلعل صفحة أو أكثر ناقصة من ملف المصدر.)"}],"82":["١١ : ١٩) . هذا هو « الله الذى آمن به ، الذى يحيى الموتى ، ويدعو الأشياء غير الموجودة كأنها موجودة » (رو ٤ : ١٧) .","بالإيمان بقدرة الله على كل شىء ، دخل موسى فى البحر الأحمر وعبره . ودخل يشوع فى نهر الأردن وعبره ، كل منها مع شعبه ...",{"h":"د ـ كذلك ينبغى أن تثق بحكمة الله ، وبأن كل تدابيره صالحة ، حتى لو كنت لم تفهم بعد أعماق هذه الحكمة ..."},"إن آمنت بحكمة الله ، تعيش فى سلام ، وتقبل كل شىء برضى . أما إن كانت (حكمتك) البشرية لا تثق بحكمة الله ، ستعيش فى تذمر وشكوى وتعب نفسى ... لذلك فى كل ما يحدث لك ، قل له : أنا واثق يارب بحكمتك وحسن تدبيرك . وإن كان فهمى الآن عاجزاً ، لابد أننى سأعرف بعد حين ما قصدته بى ، كما عرف يوسف الصديق .","إن ثقتك بأن الله صانع الخيرات ، وأنه أب محب ، وحكيم فى تدابيره ، ويريد لك الخير ، وقادر على ذلك ... كل هذا يعمّق إيمانك ، ويمنحك سلاماً فى قلبك ...","هناك وسيلة أخرى لتقوية الإيمان ، وهى :",{"h":"٢ ـ الثقة فى صدق مواعيد الله :"},"لقد وعد الله أبانا ابرآم بأنه سوف يعطيه نسلاً ، وأعطاه ولو بعد زمن . ووعده بأن نسله سيكون كنجوم السماء فى الكثرة ، وقد كان ... مع أن زوجته كانت عاقراً ، وكان هو قد تقدم فى الأيام وشاخ .","ووعد الله شعبه بأنه سيرده من السبى . وردّه كما وعد .","ووعد إيليا وقت المجاعة ، بأنه سيعوله . وعاله بأعجوبة (١مل ١٧ : ٣ ـ ٦) .","ووعد الله أمنا حواء بأن نسلها سيسحق رأس الحية (تك ٣ : ١٥) . وقد حقق هذا الوعد على الصليب فى ملء الزمان .","ووعد الله بأنه سيسكب روحه على كل بشر (يوئيل ٢ : ٢٨) . وفعل ذلك فى يوم الخمسين ، ومازلنا هياكل لروحه القدوس (١كو ٣ : ١٦) ...","وعود الله كلها صادقة . ويعوزنا أن نتتبع وعود الله منذ القديم ."],"83":[{"h":"ولكن هناك وعوداً دائمة لله ، يريحنا أن نحيا فيها بالإيمان ."},"وذلك كقوله « ها أنا معكم كل الأيام وإلى انقضاء الدهر » (متى ٢٨ : ٢٠) ، « حيثما اجتمع اثنان أو ثلاثة بإسمى ، فهناك أكون فى وسطهم » (متى ١٨ : ٢٠) ، « أعطيكم فماً وحكمة لا يقدر جميع معانديكم أن يقاوموها » (لو ٢١ : ١٥) ، « لا تهتموا كيف أو بما تتكلمون ، لأنكم تعطون فى تلك الساعة ما تتكلمون به . لأنكم لستم المتكلمين ، بل روح أبيكم الذى يتكلم فيكم » (متى ١٠ : ١٩ ، ٢٠) . وكذلك قوله عن الكنيسة إن أبواب الجحيم لن تقوى عليها (متى ١٦ : ١٨) .","ليتنا نعيش فى هذه الوعود بكل قلوبنا ، لكى تقوى إيماننا .",{"h":"وليتك أيها القارىء المحبوب تجمع كل وعود الله وتقرأها باستمرار . وتقول لنفسك : لابد أن يكون الله صادقاً فى وعوده . وبالتالى لابد أن أعيش سعيداً بهذه الوعود الإلهية ..."},"إن دوام التذكار لوعود الله ، يطمئن النفس ، ويقوى الإيمان ...","وأيضاً مما يقوى الإيمان :",{"h":"٣ ـ النظر إلى الله ، وليس إلى الظروف المحيطة :"},"قبيل عبور البحر الأحمر ، كل الظروف المحيطة كانت تدعو إلى اليأس . أما موسى النبى فإنه دعا الناس أن ينظروا إلى الله ، وقال لهم « قفوا وانظروا خلاص الرب ... الرب يقاتل عنكم وأنتم تصمتون » (خر ١٤ : ١٣ ، ١٤) .","كذلك فى حرب داود وجليات . لو نظر إلى الجبار القوى المتحدى ، ليئس . لكنه بالإيمان نظر إلى الله الذى سيحبسه فى يده (١صم ١٧) .","نفس الوضع فى معجزة الخمس خبزات والسمكتين . لما نظر التلاميذ إلى الطعام الموجود ، والآلاف المنتظرة ، قالوا « ما هذا لمثل هؤلاء ؟ ! » . ولكن المسيح نظر إلى فوق وبارك . ولو نظر التلاميذ هكذا بالإيمان إلى فوق ، لاطمأنوا ورأوا قوة الله .","مرثا نظرت إلى قبر أخيها الميت منذ أربعة أيام ، فقالت قد أنتن . أما الرب فقال لها : ألم أقل لك إن آمنت ترين مجد الله (يو ١١ : ٣٩ ، ٤٠) .",{"h":"إذن علينا أن ننظر دائماً إلى فوق ، فيدخل الإيمان إلى قلوبنا ."}],"84":["ننظر إلى الله المحب القادر على كل شىء ، ولا نركز أفكارنا فى الظروف المحيطة .","لا تنظر إلى قوة أعدائك ، إنما أنظر إلى الله الذى ينقذك منهم .","لا تنظر إلى الخطية التى « طرحت كثيرين جرحى ، وكل قتلاها أقوياء » (أم ٧ : ٢٦) ، إنما أنظر إلى الرب يسوع الذى « يخلص شعبه من خطاياهم » (متى ١ : ٢١) .","كذلك من الأمور التى تقوى الإيمان :",{"h":"٤ ـ قصص الإيمان ، ومعاشرة رجال الإيمان :"},"وهكذا عندما أراد الله أن يعطى دروساً فى الإيمان ، قال « تأملوا زنابق الحقل ... ولا سليمان فى كل مجده كان يلبس كواحدة منها » (متى ٦ : ٢٨ ، ٢٩) . فإن كان عشب الحقل ... « يلبسه الله هكذا » « أفليس بالحرى يلبسكم أنتم يا قليل الإيمان » .","وقال أيضاً « أنظروا إلى طيور السماء » . وفى إحدى المرات ، فعلت كما أمر الرب ، ونظرت إلى عصفورة فى حقل الدير ... أمامها الكثير من الحبوب . ولكنها التقطت اثنتين أو ثلاثاً ، وتركت الباقى كله وطارت « لم تجمع إلى مخازن » كما قال الرب . كانت واثقة أنها فى كل مكان تحل فيه ، سيرزقها الله قوتها ، فلماذا تخزن إذن ؟ أو لماذا تترك الجو العالى الفسيح ، وتقبع إلى جوار الحبوب لتخزن كما تفعل زميلتها النملة (القليلة الإيمان ! ) التى لا ترتفع إلى فوق ...",{"h":"وقد أعطانا الرب مثالاً شبيهاً فى قصة (المن) وجمعه ."},"كانوا يجمعونه ، على قدر حاجتهم ، يوماً بيوم ، دون أن يخزنوا ... والذين خالفوا هذه القاعدة وخزنوا منّاً « تولد فيه الدود وأنتن » (خر ١٦ : ٢٠) .","كلما يقرأ الإنسان قصصاً عن الإيمان ، والثقة بالله ، والأعاجيب التى تحدث مع قديسيه ، يمتلىء قلبه إيماناً ، ويحب هذه الحياة المملوءة إيماناً ... كذلك كلما يعاشر رجال الإيمان ، يتعلم منهم ، وتثيره حياتهم وعمل الله معهم ، لكى يتمثل بإيمانهم » (عب ١١ : ٧) . لذلك قال أحد الآباء « شهية هى أخبار القديسين » ..."],"85":[{"h":"من أجل هذا سجل لنا الكتاب سيراً من الإيمان ، لنتأثر بها ونتعلم ."},"ولكى تقوى إيماننا ، إذ نرى أمامنا أمثلة عملية لحياة الإيمان التى نشتهيها . ونرى أمامنا الطريق الذى سلكه رجال الإيمان . وكيف عاملهم الله ، وكيف تعاملوا هم معه ... وماذا أيضاً ؟",{"h":"إن كانت القراءة توثّر ، فإن المعاشرة تأثيرها أعمق بلا شك ."},"لذلك عاشروا الذين يتصفون بالإيمان ، وامتصوا الإيمان منهم . فإن الإيمان يناله الإنسان بالتسليم ، أكثر مما يناله بالتعليم . أنظروا كيف يعيشون ، وكيف يظهر الإيمان فى حياتهم ، وكيف يتعاملون مع الله ، وكيف يتصرفون إزاء الأحداث ...","وإن أردتم أن تقووا إيمانكم ، لابد من صفة تتصفون بها وهى :",{"h":"٥ ـ إتضاع القلب والفكر :"},"الإنسان المتضع يقبل كل ما يأتى من الله برضى . أما الفكر المعتد بذاته فإنه يناقش ويجادل ، ويرفض ما لا يعجبه ، فلا يصل إلى الإيمان الذى يصل إليه المتضع .",{"h":"الإنسان المتضع يعترف أن عقله محدود ، وكل قدراته محدودة ، ولا يمكنه أن يستوعب الله غير المحدود ، ولا يدرك أعماق حكمته وصفاته . لذلك يقبل فى إيمان ولا يشك . وإن ضغط عليه الفكر ، ينسكب أمام الله ويقول « أحكامك يارب فوق فهمى ، وأعمالك فوق معرفتى . من أنا قدامك ؟ وكل معرفتى هى جهالة أمامك ."},{"h":"أنا آخذ منك عن طريق التسليم ، وليس عن طريق الفحص ..."},"أعطنى يارب إيمان الأطفال ، وليس إيمان الفلاسفة والحكماء (لو ١٠ : ٢١) . حادثة مثل إلقاء الثلاثة فتية فى أتون النار ، دون أن يحترقوا (دا ٣ : ٢٥) . هذه ، هل نخضعها لفهمنا المحدود ، أم نتقبلها بالإيمان فى اتضاع الفكر الذى ينحنى أمام المعجزة ؟ ! والمعجزة هى عمل الله القادر على كل شىء ...","الإيمان يحتاج إلى اتضاع الفكر وبساطة القلب ، وأيضاً إلى :"],"86":[{"h":"٦ ـ الخبرة مع الله :"},"إلق نفسك فى دائرة الله . عش معه واختبره . جرب الإتكال عليه . حينئذ سترى عجائب من عمله معك . أما إن كنت طوال حياتك تحصر نفسك فى دائرة إمكانيات الفكر ، والذكاء البشرى ، وخبرات المجتمع ، ومشورات الناس ، بعيداً عن الله ، تأكل كل يوم من شجرة معرفة الخير والشر ، فكيف تصل إذن إلى الإيمان ؟ !","إذن إختبر عملياً وجود الله فى حياتك . عاشره لتعرف من هو . وكما قال داود النبى « ذوقوا وانظروا ما أطيب الرب » (مز ٣٤ : ٨) .","ولعل سائلاً يسأل : وكيف ندخل فى الخبرة مع الله ؟ أقول :",{"h":"٧ ـ إبصر الله فى كل أمر :"},{"h":"الناس لا يقوى إيمانهم ، لأنهم يعيشون فى عالم ، فصلوه عن الله ."},"كل ما يحدث فى هذا العالم ، يرجعونه إلى أسباب عديدة ولا يذكرون إسم الله كأنما الكون يدور ... بدون الله .","أ ـ مثال : العالم يستطيع أن يحطم الذرة ، ويستخدم القوة النووية ، ويصنع سفن الفضاء ، ويصل إلى القمر ، ويدور حول الكون ، ويتعامل مع الإلكترونات ... ويصرخ الناس ويقولون : ما أعظم العقل البشرى ! أو ما أعظم الشعب الذى اخترع كل هذه المخترعات ... ! ولا يذكرون إسم الله إطلاقاً ...","أما المؤمن فيقول : مبارك أنت يارب الذى خلقت هذا العقل البشرى ، ووهبته كل هذه الإمكانيات ، وكشفت له ما وضعته فى الطبيعة من قوى ... إن كان عبيدك الترابيون يعرفون كل هذا ، فكم وكم تكون أنت يا غير المحدود ، القادر على كل شىء ؟ ! وهكذا يقوى إيمان المؤمن بإرجاعه كل قوة وكل عجيبة إلى الله ...","ب ـ مثال آخر : يمرض إنسان بمرض خطير . ويستطيع طبيب أن ينقذه من الموت فيشنى . وينذهل المريض وأقرباؤه من مهارة الطبيب ، ويشكرونه فى الجرائد ويمدحونه . ويعتبرونه سبب الشفاء . أما الله فلا يتردد إسمه مطلقاً على أفواههم . ولكن المؤمن يقول : نشكر الله الذى شنى المريض ، وكانت يده مع يد الطبيب ."],"87":["ج ـ مثال ثالث : إنسان يتعرض لحادث تصادم يكاد يودى بحياته ، لولا أن سائق العربة يوقفها بمهارة على بعد سنتيمترات من الرجل . ويصرخ الناس : يا لمهارة السائق ! بينما المؤمن يقول : لقد منح الله هذا الإنسان عمراً جديداً ...",{"h":"ليتك فى كل حادث ، تبحث عن أصبع الله فيه ، ليقوى إيمانك ."},"إبحث عن حكمة الله وعمل الله فى كل ما يمر بك من الأحداث اليومية ، حينئذ ستجد الله كائناً أمامك كل يوم ، تلمسه وتتعامل معه ، وتشعر بوجوده فى كل ما يمر بك من صغيرة وكبيرة . وبهذا يزداد إيمانك يوماً بعد يوم .","د ـ مثال رابع : المؤمن إذا مرّ على حديقة ورأى زهرة من الزهور ، لا يكتفى بالتمتع بشكلها ورائحتها كما يفعل العلمانيون ... إنما يقف أمامها مندهشاً ويقول : ما هذا الجمال الذى خلقته يارب ؟ ! وما هذه الألوان العجيبة التى يعجز أمهر الفنانين عن أن يصنعوا مثلها ... لا شك أن الزهور الصناعية جميلة ومتقنة ، ولكنها ليست فى هذا التناسق ، كما أنها لا حياة فيها ، ولا نضارة ، ولا رائحة لها . إنها جمال ميت ... !",{"h":"حقاً ، إن التأمل فى الطبيعة بهذا الأسلوب ، يقوى الإيمان ..."},"أهل العالم يتأملون الطبيعة منفردة ، قائمة بذاتها ، وقد فصلوها عن الله . أما الذى يريد أن يقوى إيمانه ، فإنه يرى الله فى الطبيعة ... أليست هى صنعة يديه ؟ ... وهكذا كان داود النبى يقول « السموات تحدث بمجد الله ، والفلك يخبر بعمل يديه (مز ١٩ : ١) . أتراك تعجب بليلة قمرية جميلة ، دون أن تمجد الله خالق القمر ؟ !","تذكر الله هكذا ، ليكون الله بالنسبة إليك حقيقة عملية ، وليس مجرد حقيقة عقلية تثبتها البراهين ... بهذا تحيا مع الله كل يوم .",{"h":"إن أردت أن يقوى إيمانك ، لا تفضل مخلوقات الله على الله ."},"لا تبهرك الطبيعة ، وتنسى الله خالقها . لا يبهرك العقل البشرى وتصرفه فى المادة . وإنما قل : عجيب أنت يارب ! كيف خلقت المادة هكذا ، بهذه الخاصية وبهذا المفعول ، بحيث يمكن للعقل أن يستخدمها فى كل هذه الأغراض ... ! أتراننا نعجب بطبيب يستخلص دواء من مادة معينة ، بينما ننسى الله الذى وضع هذه"],"88":["الخاصية فى تلك المادة ، حتى يمكنها أن تخدم غرض الطبيب ... !","أمر آخر يمكنه أن يقوى إيمانك وهو :",{"h":"٨ ـ إتخذ الرب صديقاً لك :"},"لو فعلت هذا ، لأمكن أن يقوى إيمانك ، لأنك ستكون علاقة مع الله وتتحدث معه بدالة بلا خوف ، فتتوطد صلتك به .","كثيرون ينظرون إلى الرب كمجرد إله أو سيد . ولكن هل نظرت إليه أيضاً كصديق ومحب ، تثق به وبمحبته وبإخلاصه لك . إنه يقرع على بابك ، ويطلب إليك أن تفتح له كصديق ، فيدخل ويتعشى معك وأنت معه (رؤ ٣ : ٢٠) . إن قبلت صداقة الله ومحبته ، ستدخل فى الإيمان الحقيقى ... تشتاق إلى رؤياه كصديق ، وتحكى له أسرارك ، وتتمتع بعشرته ومحبته ... وتحرص كصديق له ألا تخدش شعوره أو تغضبه . وهو نفسه سيكشف لك أسراره ، كما كشف لإبراهيم (تك ١٨ : ١٧) .","إن الله يريدك هكذا ، لأنه قال « لا أعود أسميكم عبيداً ... بل أحباء » (يو ١٥ : ١٥) ... إتخذه إذن كصديق أو كأب ، تؤمن بأبوته ومحبته ، كما تؤمن بسلطانه وقدرته . تحدثه عن أسرارك ، ويحدثك عن أسراره .",{"h":"من قصص الصداقة والصراحة مع الله ، مسح إيليا لأليشع نبياً ."},"قال الرب يوماً لإيليا النبى العظيم إذهب « إمسح ياهو بن نمشى ملكاً على اسرائيل ... وامسح أليشع بن شافاط ، نبياً عوضاً عنك » (١مل ١٩ : ١٦) .","لم يقل إيليا : حسناً يارب أن أمسح ياهو ملكاً . ولكن كيف أمسح نبياً عوضاً عنى ؟ وهل استغنيت عن خدماتى ؟ هل يحدث هذا بعد تعبى الكثير من أجلك ، وبعد وقوفى ضد آخاب الملك وزوجته إيزابل ، وبعد تخليصى البلاد من كل أنبياء البعل وأنبياء السوارى ؟ ... هل تغيرت محبتك لى ؟ !","لم يقل شيئاً من هذا ، ولم يشك فى محبة الله ، بل فعل كما أمره ، واثقاً من محبة الله ومن حكمته . بل اعتبرها دالة وصداقة بينه وبين الله ، بها يشركه الله معه فى تنفيذ الخطة الإلهية ، حتى لو كان منها مسح نبى عوضاً عنه . فهذا لا يدل على أن الصداقة بينه وبين الله قد انتهت أو نقصت .","بدليل أن الله رفعه إليه إلى السماء فى مجد (٢مل ٢ : ١١) . وبدليل أنه"],"89":["ظهر معه بعد زمن على جبل التجلى يتحدث إليه (مر ٩ : ٤) . إنها المحبة التى يصارحه بها الله ، حتى فى الأمور التى تمسه . وكان مسح نبى عوضاً عنه ، متدمه لترقيته إلى حالة أفضل ، هى أعظم من نبى ...",{"h":"٩ ـ صلاة لأجل الإيمان :"},"أطلب من أجل إيمانك فى صلاتك ، لكى ينمو ويزداد .","قل له : إعطنى يارب أن أؤمن بك الإيمان كله . إعطنى أن أحبك وأثق بك فى كل شىء ، وأؤمن أنك تفعل بى خيراً مهما كانت الدنيا مظلمة أمامى . إشعرنى بأن عقلى أصغر بكثير من أن يفهم حكمتك وأحكامك . أنا أعرف أنك صانع الخيرات ، وأنك محب ، وأنك ترى كل شىء ، وقادر على كل شىء . ومع ذلك كثيراً ما أضعف ... فأعن ضعف إيمانى ..."],"90":[{"h":"الفصل التاسع"},{"h":"ما يضعف الإيمان"}],"91":["الشيطان يعمل باستمرار ، وبكل جهده ، على إضعاف إيمان المؤمنين .","ويحاول هو وأعوانه أن يضلوا ولو أمكن المختارين أيضاً » (متى ٢٤ : ٢٤) . ولا يكتفى هؤلاء بمجرد إضعاف الإيمان ، بل يحاولون أن يوصلوا فريستهم حتى إلى الإرتداد . وهكذا فى آخر الأيام يرتد كثيرون عن الإيمان « تابعين أرواحاً مضلة وتعاليم شياطين » (١تى ٤ : ١) . وما أخطر قول الكتاب فى المجىء الثانى للمسيح « ولكن متى جاء ابن الإنسان ، ألعله يجد الإيمان على الأرض ؟ ! » (لو ١٨ : ٨) .","فما هى وسائل الشيطان فى إضعاف الإيمان ؟ إنها كثيرة : بعضها عنيف جداً . وبعضها هادىء قد لا يحسه أحد :",{"h":"١ ـ الذات :"},{"h":"كثيراً ما تقف الذات ضد الله ، وترفضه لأنه ضد رغباتها الخاطئة :"},"تشعر الذات أن الله يحد حريتها ، التى تشتهى أشياء لا يوافق الله عليها . فلكى تتمتع بهذه (الحرية) أو بهذا التسيب ، تنفصل عن الله ، كما انفصل الإبن الضال عن بيت أبيه (لو ١٥ : ١١ ـ ١٤) ، لكى ينفق ماله حسب هواه ... أو ترفض الله . ولعل الوجوديين الملحدين من أمثلة الرافضين لله . وهؤلاء صار شعارهم هو :",{"h":"من الخير أن الله لا يوجد ، لكى أوجد أنا ..."},"وهؤلاء قد أخطأوا فَهم المعنى الحقيقى للوجود ، والمعنى الحقيقى للحرية . فليست الحرية هى أن يفعل الإنسان ما يشاء ، فقد تكون مشيئته خاطئة . إنما الحرية الحقيقية هى أن يتحرر الإنسان من كل شىء يشينه ... يتحرر من العادات الرديئة التى تستعبده ، ومن الشهوات الدنسة التى تنجسه . ويتحرر من سيطرة المادة عليه ، هذه التى تمنع روحه من إنطلاقها ومن العشرة مع الله التى هى الوجود الحقيقى ...","ومن معوقات الذات للإيمان ، رغبة الإنسان فى الشعور بذاته ، فى القوة والعظمة والكبرياء ... وهنا يرى الله منافساً له ...",{"h":"وهكذا وجد هيرودس أن مولود بيت لحم سينافسه الملك ، فرفض الإيمان"}],"92":["به ، وحاول أن يتخلص منه بقتله ... وكان من أمثال هيرودس أيضاً : الكتبة والفريسيون ، الذين رأوا أن المسيح قد أخذ مكانتهم وشعبيتهم كمعلم . فقال بعضهم لبعض « أنظروا ، إنكم لا تنفعون شيئاً . هوذا العالم قد ذهب وراءه » (يو ١٢ : ١٩) . ومن أجل الذات أيضاً رفض كل هؤلاء الإيمان بقيامة المسيح ، لئلا تكون دليلاً يجلب عليهم دم ذلك البار (أع ٥ : ٢٨) ... إن الذات من أكبر معرقلات الإيمان ، لذلك قال الرب :",{"h":"« من أراد أن يتبعنى ، فلينكر ذاته ... » (متى ١٦ : ٢٤) ."},"وقال أيضاً « من وجد حياته يضيعها . ومن أضاع حياته من أجلى يجدها » (متى ١٠ : ٣٩) . وهكذا نجد أن القديس بولس الرسول ، من أجل الإيمان يقول « لست أحتسب لشىء ، ولا نفسى ثمينة عندى » (أع ٢٠ : ٢٤) ، « بل أنى أحسب كل شىء أيضاً خسارة ، من أجل فضل معرفة المسيح يسوع ربى ، الذى من أجله خسرت كل الأشياء وأنا أحسبها نفاية ، لكى أربح المسيح وأوجد فيه » (فى ٣ : ٨ ، ٩) . فهل أنت كذلك ؟ أم ...",{"h":"هل إيمانك يتعطل بسبب ذاتك ؟ بسبب رغباتك وغرائزك وأفكارك وشهواتك ؟ !"},"هل هناك تعارض بين الله وذاتك ؟ إن كان كذلك ، إنكر ذاتك . قاومها . إنتصر عليها . لأن مالك روحه خير من مالك مدينة (أم ١٦ : ٣٢) .","إن الكتبة والفريسيين والكهنة والشيوخ ، كانوا يحرصون على ذاتهم حرصاً خاطئاً . كانت فى ذات كل منهم عيوب ، وكان المسيح يكشفها ، حتى دون أن يتكلم عنها . بمجرد المقارنة تنكشف . لذلك كانوا يكرهونه ، ولم يؤمنوا به ، لأنه نور يهتك ظلمتهم ... ووقفت ذاتهم ـ التى تود أن تتغطى ـ عقبة فى طريق إيمانهم .",{"h":"لا ننس أن الشيطان نفسه ، كانت ذاته سبباً فى ضياع إيمانه ."},"وذلك حين فكر كيف تكبر هذه الذات ... كيف يصعد إلى السموات ، ويرتفع فوق كواكب الله ، ويصير مثل العلى (اش ١٤ : ١٤) . فوقفت (عظمة) ذاته ضد الإيمان بالله . أما الملائكة الأطهار فاحتفظوا بمكانتهم ، لأنهم فى إيمانهم بالله حسبوا أنفسهم « خدامه العاملين مرضاته » (مز ١٠٣ : ٢١) ."],"93":[{"h":"كثيرون أنفسهم جميلة فى أعينهم . ذاتهم هى صنمهم ."},"يمنعهم عن حياة الإيمان : محبة الذات ، والإعتداد بالذات ، والرغبة فى تكبير الذات ، وتفخيم الذات ، وتحقيق شهوات الذات ، والهروب من كل من يكشف هذه الذات أو يظهر مساوئها ... وهكذا يريدون أن تحيا ذاتهم فى جو من التدليل والمجاملة والمديح . يتضايقون من كل كلمة صريحة ومن كل تأنيب وكل تأديب . فكيف يمكنهم أن يحيوا فى الإيمان ؟ !","إن كنت كذلك أصلح ذاتك لكى تتضع أمام الله ، فتحيا فى الإيمان ...","كذلك من الأمور التى تضعف الإيمان :",{"h":"٢ ـ سيطرة الحواس :"},"وفى هذا وقع القديس توما الرسول ، حينما رفض الإيمان بقيامة الرب ، وقال « إن لم أبصر فى يديه أثر المسامير ، وأضع أصبعى فى أثر المسامير ، وأضع يدى فى جنبه ، لا أؤمن » (يو ٢٠ : ٢٥) وقد تنازل الله لضعف توما ، وسمح له أن يتأكد بحواسه قائلاً له « ولا تكن غير مؤمن بل مؤمناً » ، ووبخه قائلاً « لأنك رأيتنى ياتوما آمنت ؟ ! طوبى للذين آمنوا دون أن يروا » (يو ٢٠ : ٢٧ ، ٢٩) . هذا الذى يبصره الإنسان ، نسميه عياناً لا إيماناً . ولكنه قد يؤدى إلى الإيمان ...",{"h":"أهذا إيمان ضعيف ؟ هناك ما هو أسوأ : أى الذى يرى ولا يؤمن ."},"مثال ذلك : الكهنة الذين رأوا القبر الفارغ ولم يؤمنوا بالقيامة . والكتبة والفريسيون الذين رأوا معجزات المسيح كشفاء المولود أعمى وإقامة الموتى ولم يؤمنوا . هؤلاء رافضون للإيمان لأسباب فى قلوبهم . وينطبق عليهم قول أبينا ابراهيم لغنى لعازر « ولا إن قام واحد من الموتى يصدقون » (لو ١٦ : ٣١) .",{"h":"٣ ـ إخضاع الإيمان للعقل :"},"وقد قلنا قبلاً إن العقل له حدود لا يتعداها ، وإن الإيمان مستوى أعلى منه . ولكن هناك أشخاصاً يريدون أن تعى عقولهم اللا محدود ، وما هو فوق إدراكهم ، وإلا فإنهم يرفضون كل هذا ! ... يريدون أن تخضع اللاهوتيات كلها للفحص العلمى ... وهذا غير ممكن منطقياً . وليس من العقل ، أن يخضع غير المحدود"],"94":["للعقل ، الذى هو محدود !","ولعل من أمثلة هذا فى أيامنا ما يعرف فى بعض المعاهد باسم علم اللاهوت الجديد New Theology حيث يريدون إخضاع الوحى والمعجزة للبحث العلمى البحت ، أو لمجرد التفسير الرمزى . وبهذا ينكرون كثيراً من المعجزات ومن قصص الكتاب ، ويدخلونها فى علم الأساطير Mythology ! ! حقاً إن العقل يضل ، إذا حاول أن يرتئى فوق ما ينبغى له أن يرتئى (رو ١٢ : ٣) . وبهذا ينحرف عن الإيمان ، ويحاول أن يقود غيره فى نفس الإنحراف .",{"h":"٤ ـ معاشرة الشكاكين :"},"كما أن معاشرة رجال الإيمان تقوى الإيمان ، كذلك معاشرة الشكاكين تغرس الشك فى العقول والقلوب ، إن كانت بمداومة ، أو من النوع العميق التأثير ، أو كان المستوى الخاضع للشكوك أقل فى المعرفة أو المستوى العقلى ، أو كان غير عميق فى الإيمان .",{"h":"ولهذا فإن الكتاب يمنع من مخالطة المنحرفين فى إيمانهم وفى أفكارهم ."},"يقول القديس يوحنا الرسول « إن كان أحد يأتيكم ولا يجىء بهذا التعليم ، فلا تقبلوه فى البيت ، ولا تقولوا له سلام . لأن من يسلم عليه يشترك فى أعماله الشريرة » (٢يو ١٠ ، ١١) . وهكذا منعت الكنيسة الخلطة بالهراطقة والمبتدعين ...","وكم من أناس خالطوا جماعات غير مسيحية مثل شهود يهوه والسبتيين ، فكانت النتيجة أنهم انحرفوا فى تياراتهم . وكم من أعضاء فى الكنيسة خالطوا طوائف غريبة أو ملحدين ، فتأثرت معتقداتهم بهم إلى حد بعيد .",{"h":"وحتى من جهة السلوك والروحيات ، مخالطة الشكاكين تضعف الإيمان :"},"قد تحدث لك تجربة أو مشكلة وتقبلها فى إيمان ، وتسلم الأمر لله شاكراً إياه على كل حال . ثم يزورك شخص قليل الإيمان ، فيظل يشرح لك خطورة الموضوع ، ويخيفك جداً من نتائجه ، حتى تفقد سلامك القلبى ، ويضعف إيمانك فى حفظ الله وتقلق ...","لذلك كن حريصاً جداً فى اختيار من تعاشرهم وتختلط بأفكارهم .","وهذا يقودنا إلى نقطة أخرى تضعف الإيمان وهى :"],"95":[{"h":"٥ ـ الإنقياد وضعف الشخصية :"},"من هذا النوع ، مريم المجدلية : لقد رأت القبر الفارغ ، وسمعت بشارة الملاك ، بل إنها رأت السيد المسيح نفسه بعد قيامته ، وأمسكت بقدميه ، وسمعت صوته ، وكلفها برسالة ... ولكنها مع ذلك قالت ثلاث مرات « أخذوا سيدى ، ولست أعلم أين وضعوه » (يو ٢٠ : ٢ ، ١٣ ، ١٥) . وفى هذا إنكار للقيامة . فما السر فى هذا التحول ؟ وكيف ضعف إيمانها بعدما رأت المسيح وكلمته ؟ (مر ١٦ : ٩ ، مت ٢٨ : ٩)","كانت المجدلية صغيرة فى سنها . وقد ضعفت شخصيتها أمام الشائعات التى نشرها كهنة اليهود ضد القيامة . كما ضعفت أمام عدم تصديق التلاميذ أولاً للقيامة (مر ١٦ : ١١ ، ١٣ ، ١٤) . فبدأت تلعب بها الشكوك والأوهام ، وررددت بفمها ما سمعته من شائعات .",{"h":"لم يستطع إيمان المجدلية أن يصمد أمام الشائعات وكلام الناس ..."},"فاهتزت من الداخل بسبب التأثير الخارجى الضاغط ، وانقادت إليه ... !","وكثير من الناس يهتزون من الداخل ، ويتحولون عن إيمانهم الأول ، عقيدة أو سلوكاً ، بسبب استهزاء الناس . وبسبب أن شخصيتهم أضعف من أن تصمد .","إن الله يريد أن تكون شخصياتكم قوية . وكما يقول الرسول :",{"h":"مستعدين كل حين ، لإجابة كل من يسألكم عن سبب الرجاء الذى فيكم » (١بط ٣ : ١٥) ."},"إن أولاد الله لا يليق بهم أن يكونوا ضعفاء ، من النوع الذى يهتز إيمانه ، أو تهتز روحياته ، وينقاد لأى فكر خارجى . بل إنهم يعملون بقول الرسول « إذن يا إخوتى الأحباء ، كونوا راسخين غير متزعزعين ... » (١كو ١٥ : ٥٨) .","أيضاً من النوع الذى تحول عن إيمانه بسبب الإنقياد : أمنا حواء . فالكلام الذى سمعته من الحية ، جعلها تتحول عن إيمانها ، وينتهى الأمر بطردها من الجنة !","ما أكثر الذين ينقادون وراء الشائعات ويصدقونها . وما أكثر من يرددون كلاماً عن المجىء الثانى ويصدقه الناس . ويقولون إن (المسيح الدجال) Anti Christ قد وُلد ، وأنه فى ولاية بأمريكا ، وأن عمره الآن ١٧ سنة ! ! وأن العالم سينتهى فى هذه"],"96":["السنة أو غيرها ! ! وما أكثر التواريخ التى حددها شهود يهوه والسبتيون عن المجىء الثانى ، ولم يتم منها شىء ...",{"h":"وقد يضعف إيمان البعض وينقادون وراء من يدّعى الرؤى والأحلام ."},"ويظنون أن ما يدعيه من الرؤى والأحلام ، كلها حقيقية ومن الله ! ثم ينخدعون بما يقوله من كلام ، ولو ضد معتقداتهم أو مبادئهم الروحية . ولقد حذّر الرب من هؤلاء منذ أيام موسى النبى فقال :","« إذا قام فى وسطك نبى أو حالم حلماً ، وأعطاك آية أو أعجوبة ، ولو حدثت الآية أو الأعجوبة التى كلمك عنها ، قائلاً : لنذهب وراء آلهة أخرى لم تعرفها ونعبدها . فلا تسمع لكلام ذلك النبى أو الحالم ذلك الحلم . لأن الرب إلهكم يمتحنكم لكى يعلم هل تحبون الرب إلهكم من كل قلوبكم ... » (تث ١٣ : ١ ـ ٣) .","إن الإنقياد من الأسباب التى تضعف الإيمان . وكذلك من أسبابه :",{"h":"٦ ـ الخوف :"},{"h":"الخوف يضعف الإيمان . وضعف الإيمان يؤدى إلى الخوف ."},"القديس بطرس ، الرسول العظيم ، لما خاف أنكر المسيح ، وسب ولعن وحلف أنه لا يعرف الرجل (متى ٢٦ : ٧٤) . وهكذا ضعف إيمانه . بل قال له المسيح قبلها « طلبت من أجلك لئلا يفنى إيمانك » (لو ٢٢ : ٣٢) .","وكثيرون فقدوا إيمانهم بسبب خوفهم . ولهذا فإن سفر الرؤيا وضع الخائفين فى مقدمة الهالكين فقال « وأما الخائفون وغير المؤمنين والرجسون ... فنصيبهم فى البحيرة المتقدة بالنار والكبريت » (رؤ ٢١ : ٨) . ووضعه الخائفين قبل غير المؤمنين ، ربما المقصود بها الخائفين الذين بسبب خوفهم يصيرون غير مؤمنين .","بيلاطس البنطى ، كان مؤمناً فى أعماقه أن يسوع الناصرى برىء من التهم التى ألصقها به اليهود . وكان واثقاً أنهم أسلموه حسداً . وقد حاول أن يطلقه . وقال عنه « هذا البار » ... ولكنه أخيراً استسلم لضعفه ، وأسلم المسيح للصلب ، إذ خاف أن يقال عنه إنه ضد قيصر ..."],"97":["أما الإنسان الروحى ، فهو لا يفقد إيمانه إطلاقاً ، لأنه لا يخاف ...","ومن الأمور التى تضعف الإيمان أيضاً :",{"h":"٧ ـ الشهوة :"},"كثيرون فقدوا إيمانهم بسبب الشهوة . ولعل من أمثلتهم دياس مساعد بولس الرسول فى الكرازة والتبشير ، الذى قال عنه القديس بولس أخيراً « ديماس قد تركنى ، لأنه أحب العالم الحاضر » (٢تى ٤ : ١٠) . ومحبة العالم تضعف الإيمان ، لأنها عداوة لله (يع ٤ : ٤) .","ومن أمثلة الذين فقدوا إيمانهم بسبب الشهوة : الشاب الغنى ... هذا ترك المسيح « ومضى حزيناً لأنه « كان ذا أموال كثيرة » (متى ١٩ : ٢٢) . إذن شهوة المال يمكن أن تضعف الإيمان :","وما أكثر الذين تركوا المسيح من أجل إمرأة أو منصب ...",{"h":"شهوة النساء ضيعت إيمان سليمان الحكيم ، أحكم أهل الأرض ..."},"وذلك أنه « أحب نساء غريبة » (١مل ١١ : ١) . وكان فى زمان شيخوخة سليمان و أن نساءه أملن قلبه وراء آلهة أخرى . ولم يكن قلبه كاملاً مع الرب إلهه كقلب داود أبيه . فذهب سليمان وراء عشتاروت الهة الصيدونيين ، وملكوم رجس العمونيين . وعمل سليمان الشر فى عينى الرب ... » (١مل ١١ : ٣ ـ ٦) ... إلى هذا الحد سقط هذا الحكيم العظيم ، ولو أننا نؤمن أنه تاب فى أواخر أيامه . وكان سفر الجامعة من دلائل توبته .",{"h":"وشهوة المال أضاعت إيمان حنانيا وسفيرا ، فهلكا ."},"فوقعا فى « الكذب على الله » (أع ٥ : ٤) ، وأيضاً فى « تجربة روح الرب » (أع ٥ : ٩) . وماتا الإثنان هالكين ...",{"h":"وشهوة المال أيضاً ضيّعت إيمان بلعام . وكان نبياً وله نبوءات جميلة عن المسيح (عدد ٢٢ ـ ٢٤) . وأخيراً وقع فى ضلالة لأجل أجرة الإثم » (٢بط ٢ : ١٥) . وهكذا كان معثرة لكل الشعب ، وعلّم بالاق طريق الخطية (رؤ ٢ : ١٤) ... فهلك وأهلك غيره ..."}],"98":[{"h":"وشهوة العظمة والتقدم على الآخرين ، أضاعت إيمان كثيرين :"},"لعل من بين هؤلاء « ديوتريفس » الذى كان « يحب أن يكون الأول » . لذلك قاوم القديس يوحنا الحبيب ، وطرد إخوة كثيرين من الكنيسة (٣يو ١٠) .",{"h":"وشهوة الألوهية ضيعت إيمان كاروب عظيم ، فتحول إلى شيطان ، وكان من قبل ملاكاً من نور ، له بهاء ومجد ..."},"إن الشهوات من أكبر الأمور التى تضعف الإيمان أو تضيعه .","ومن الأسباب التى تضعف الإيمان ، الضيقات وضغط الظروف الخارجية .",{"h":"٨ ـ الظروف الخارجية :"},"ولعل من أمثلة هذا الأمر جدعون لما ضعف إيمانه فى عناية الله : قال له الملاك « الرب معك يا جبار البأس . فقال له جدعون : أسألك يا سيدى إذا كان الرب معنا ، فلماذا أصابتنا كل هذه (البلايا) ؟ وأين كل عجائبه التى أخبرنا بها آباؤنا ... والآن قد رفضنا الرب وجعلنا فى كف مديان » (قض ٦ : ١٢ ، ١٣) .",{"h":"وهكذا قد تضعف الإيمان الضيقة إذا طالت ، أو إذا اشتدت ."},"التلاميذ لما اشتدت عليهم الأمواج فى السفينة ، ضعف إيمانهم وشكوا قائلين للرب « أما يهمك أننا نهلك » (مر ٤ : ٣٨ ـ ٤٠) .","وبنو اسرائيل لما طالت بهم المدة فى عبودية فرعون ، صغرت نفوسهم وضعف إيمانهم فى الخلاص (خر ٤ : ١) .","هناك سبب خطير آخر يسبب ضعف الإيمان ، وهو :",{"h":"٩ ـ ضلالات الشياطين :"},"ومن هذه الضلالات : الرؤى الكاذبة . فإن الشيطان ـ لكى يخدع البشر ـ يستطيع أن « يغيّر شكله إلى شبه ملاك نور » (٢كو ١١ : ١٤) . بل يستطيع أن يقدم عجائب كاذبة كما قيل عن المقاوم ضد المسيح فى آخر الزمان « الذى مجيئه بعمل الشيطان بكل قوة وبآيات وعجائب كاذبة ، وبكل خديعة الإثم فى الهالكين » (٢تس ٢ : ٩ ، ١٠) . وقال الرسول إن كل هذا سوف يسبب الإرتداد قبل مجىء"],"99":["المسيح (٢تس ٢ : ٣) ، أى ضياع الإيمان بسبب هذه الضلالات الشيطانية التى تخدع الناس .","إن الشيطان قد يخدع الناس بأحلام وبنبوءات كاذبة ، وبأفكار ضلالات وبدع ، لكى يحطم الإيمان فى قلوبهم ... بل قد يرسل إليهم « مُسحاء كذبة وأنبياء كذبة . ويعطون آيات عظيمة وعجائب (متى ٢٤ : ٢٤) . وقد يقول لهم هذا هو المسيح . ولذلك سبق المسيح فأنذر وقال « إن قال لكم أحد : هوذا المسيح هنا أو هناك ، فلا تصدقوا » (متى ٢٤ : ٢٣) .","وكل هذا يحتاج إلى إفراز ، وكما قال الرسول « لا تصدقوا كل روح . بل إمتحنوا الأرواح هل هى من الله . لأن أنبياء كذبة كثيرين قد خرجوا إلى العالم » (١يو ٤ : ١) .","ومن الأشياء الأساسية التى تحارب الإيمان :",{"h":"١٠ ـ الشـــــك :"},{"h":"الشك يضعف الإيمان . وضعف الإيمان يولد الشك ..."},"تماماً كما قلنا عن الخوف . وكلاهما يسبب الآخر ، أو ينتج عنه .","أ ـ وكان الشك من الحروب التى حارب بها الشيطان أبوينا الأولين ليضيع إيمانها . فقال لها « أحقاً قال لكما الله ... ؟ ! كلا ، لن تموتا » (تك ٣ : ١ ـ ٤) .",{"h":"فإن حاربتك الشكوك من جهة وجود الله أو بعض العقائد الأساسية ، فلا تخف . هذه محاربات من العدو ، وليست إنكاراً منك للإيمان . وبخاصة إن كان قلبك رافضاً لها . لذلك فى مثل هذه الحالات يجب أن تصلى لكى يرفع الرب عنك هذه الحروب . وأن تغير مجرى تفكيرك ، بأن تنقل أفكارك إلى موضوع آخر تنشغل به ."},"أما إن كانت الشكوك منك ، وأنت مقتنع بها ، فعليك أن تعالجها بفهم إيمانى سليم ، بسؤال المتخصصين فى اللاهوت ، وبقراءة الكتب المفيدة فى موضوعك .","على أن هناك حروباً أخرى للشك أخف من هذه ، نذكر منها :",{"h":"ب ـ الشك فى معونة الله ، أو فى أن الله قد تخلى عنك ."},"إن الرب يوبخ على هذا الشك قائلاً « يا قليل الإيمان ، لماذا شككت » (متى"],"100":["١٤ : ٣١) . وهنا يربط بين الشك وقلة الإيمان . لأن الإنسان القوى الإيمان لا يمكن مطلقاً أن يشك فى محبة الله ورعايته .","ولكن الضيقات الكثيرة المستمرة ، قد تضغط على القلب أحياناً فيقول : « لماذا يارب تقف بعيداً ، لماذا تختنى فى أزمنة الضيق » (مز ١٠ : ١) .","إنه عتاب ، وليس ضعفاً فى الإيمان . وقد يبدو للمرتل أن الرب يقف بعيداً . ولكنه يرقب بكل حب ، وبكل حرص على سلامة أولاده . كالنسر الذى يعلم فراخه الطيران ، وكالأب الذى يعلم إبنه العوم . يتركه قليلاً ليتدرب ويكتسب خبرة . ويرقبه بكل حرص . فإن رأى خطراً يحيق به ، يسرع إلى حمله وإنقاذه .","هناك أيضاً مثال الأم التى تعلم إبنها المشى . فتتركه ليقوم ويسقط وتشتد عظامه وتقوى عضلاته ويتعلم . أما إن كانت فى كل صرخة منه ، تسرع وتحمله على كتفها فإنها بهذا ستضره . لأنه لن يتعلم ، ولن تقوى عظامه كما ينبغى ...",{"h":"إن أزمنة الضيق ، هى مدرسة لنا ، نتدرب فيها على الصلاة والتمسك بالله . ونتدرب فيها على الإيمان ، ونرى فيها كيف أن الله يعمل ، وبقوة ..."},"ويقيناً أن الله يعمل ، مهما كنت لا تراه ولا تلمس عمله .","إن الإنسان قد يشك إن نظر فقط إلى المتاعب ، وليس إلى الله . وهكذا نرى أن بطرس قد شك حينما نظر إلى الماء الذى تحت قدميه ، ولم ينظر إلى المسيح الذى يمسك بيديه . وإذ هبط إيمان بطرس ، هبط هو أيضاً إلى الماء ، ولكن إلى لحظة ، وأنقذه الرب .","قد يكون أولاد الله « كحملان وسط ذئاب » ، ولكنهم لا يشكون ولا يخافون . فمادام الراعى الصالح وسط الحملان ، فلن تقوى عليهم الذئاب ولا حتى الأسود .","إن أبانا ابرآم لم يشك فى محبة الله وعنايته ، على الرغم من صعوبة الأمر الصادر إليه بتقديم إبنه اسحق محرقة . وكأنه يقول :",{"h":"إن قلبى ليس أحن من قلب الله على إبنى إسحق ، ولا أنا أستطيع أن أدبر مستقبل إسحق كما يدبره الله ،"},"فمادام الرب موافقاً على شىء ، فلا بد أن أوافق أنا عليه أيضاً بالضرورة ، لأنى"],"101":["لست فى حكمة الله ولا فى محبته . لتكن إذن مشيئته .",{"h":"إن الذى لا يشك ، يعيش دائماً فى راحة وفى سلام ."},"يحيا دائماً مطمئناً ، لا تتعبه العوامل الخارجية . ولا يفرض على الله حلولاً معينة ، يتضايق إن لم ينفذها الله ! بل هو يرضى بكل حل يأتى من عند الله حسب وافر حكمته الإلهية .","ما أكثر المتاعب التى تولدها الشكوك فى القلب وفى الفكر ... مثل القلق والخوف والإضطراب وقلة المحبة . مجرد الشك نفسه هو تعب . نار تحرق ...",{"h":"الشك يعالج بالثقة ويعالج بالحب . فمن يحب شخصاً لا يشك فيه . وهكذا نحن مع الله ، لا نشك فيه ، لأننا نحبه ونثق به . وإيماننا به لا يسمح لنا مطلقاً أن نشك فى معاملاته الإلهية لنا ، وفى معاملاته الأبوية لنا . مبارك هو فى كل ما يعمله ."},{"h":"إن الإيمان يقتل الخوف والشك . والخوف والشك قد يقتلان الإيمان ."},"تمسك إذن بإيمانك ، لأنه هو العنصر الأقوى ، وهو العنصر المنتصر دائماً . حينئذ سوف تحيا فى فرح وسلام واطمئنان ، بلا خوف ، بلا شك ، كل أيام حياتك ."],"102":[{"h":"الفصل العاشر"},{"h":"إختبار الإيمان : هل أنتم فى الإيمان"},"« جربوا أنفسكم : هل أنتم فى الإيمان ؟ إمتحنوا أنفسكم » (٢كو ١٣ : ٥) ."],"103":["هناك طرق كثيرة لاختبار الإيمان ، يمكن استنتاجها من كل ما سبق . ونريد أن نقول ههنا إن الرسول ـ فى حياة الإيمان ـ لا يتكلم عن مجرد الإيمان ، أى الإعتراف باسم الرب ، وإنما يذكر بالتخصيص :",{"h":"١ ـ الإيمان العامل بالمحبة (غل ٥ : ٦) :"},"إختبر إذن إيمانك بالمحبة حسبما شرحها الرسول فى (١كو ١٣) ...","المحبة تتأنى ، وترفق ، ولا تحسد ، ولا تتفاخر ، ولا تنتفخ ، ولا تقبّح ، ولا تطلب ما لنفسها ، ولا تحتد ، ولا تظن السوء ، ولا تفرح بالإثم ... وتحتمل كل شىء ، وتصدق كل شىء ، وترجو كل شىء ، وتصبر على كل شىء » (١كو ١٣ : ٤ ـ ٧) .","فهل توجد فيك كل هذه الصفات ، ليكون إيمانك سليماً ؟ لقد قال الرسول « إن كان لى كل الإيمان حتى أنقل الجبال ، ولكن ليست لى محبة ، فلست شيئاً » (١كو ١٣ : ٢) . بهذه المحبة يمكنك أن تختبر إيمانك ...","بل إنك تختبر الإيمان بالأعمال عموماً .",{"h":"٢ ـ تختبر الإيمان بالأعمال عموماً :"},"ذلك لأن الرسول يقول « وأنا أريك بأعمالى إيمانى » (يع ٢ : ١٨) . فبالأعمال تختبر إيمانك هل هو إيمان حى أم ميت لأن « الإيمان بدون أعمال ميت » (يع ٢ : ٢٠) . والإيمان الميت لا يقدر أن يخلص أحداً (يع ٢ : ١٤) .","والقديس بولس الرسول أكثر من تحدث عن أهمية الإيمان ، نراه يقول :",{"h":"« يعترفون بأنهم يعرفون الله ، ولكنهم بالأعمال ينكرونه » (تى ١ : ١٦) ."},"وفى رسالته الأولى إلى تيموثاوس يشدد كثيراً على هذه النقطة ، فيقول إن « الذى لا يعتنى بخاصته ... قد أنكر الإيمان وهو شر من غير المؤمن » (١تى ٥ : ٨) . وإن الأرامل اللائى رفضن نذر البتولية قد « رفضن الإيمان الأول » (١تى ٥ : ١٢) . وإن الذين يحبون المال ، قد « ضلوا عن الإيمان » (١تى ٦ : ١٠) . وإن"],"104":["المهتمين بالكلام الباطل الدنس « قد زاغوا من جهة الإيمان » (١تى ٦ : ٢١) .",{"h":"إذن سلوك الإنسان يمكن أن يكون اختباراً لإيمانه ."},"هوذا القديس يوحنا الرسول يقول « من قال قد عرفته ، وهو لا يحفظ وصاياه ، فهو كاذب وليس الحق فيه » (١يو ٢ : ٤) ، « من قال إنه ثابت فيه ، ينبغى أنه كما سلك ذاك يسلك هو أيضاً » (١يو ٢ : ٦) . وبهذا نقول :",{"h":"٣ ـ نختبر إيماننا بنقاوة القلب :"},"ولماذا ؟ لأن الذى يؤمن أن الله كائن أمامه ، وأن الله قدوس يكره الخطية ، وأنه عادل يجازى كل إنسان حسب أعماله ، هذا يخاف أن يخطىء أمام الله ، ويستحى أن يخطىء ، كما يستحى أن يجرح قلب الله المحب ، إن كان يؤمن بمحبة الله .","هوذا الرسول يقول « كل من يخطىء ، لم يبصره ولا عرفه » (١يو ٣ : ٦) . يقيناً إن الذى يخطىء ، لا يكون فى فكره أثناء الخطية أن الله يرى ويسمع ويسجل ... ويقيناً إن الذى يظلم ، لا يكون مؤمناً تماماً أن هناك إلهاً موجوداً « يحكم للمظلومين » (مز ١٤٦ : ٧) . ولذلك إذا قيل لظالم « ربنا موجود » يخاف ويرتعش .","ويقيناً إن المتكبر ، أو المنتفخ بالمديح ، لا يشعر مطلقاً أنه قائم أمام الله . إن هيرودس لما خاطب الشعب ومدحوه قائلين « هذا صوت إله ، لا صوت إنسان » فابتهج بهذا المديح ، لم يكن عنده إيمان أن الله أمامه ، لذلك « ضربه ملاك الرب ، لأنه لم يعط مجداً لله . فصار يأكله الدود ومات » (أع ١٢ : ٢١ ـ ٢٣) .","المؤمن الحقيقى يمكن اختباره أيضاً بالزهد وعدم اشتهاء الأمور التى فى العالم ، فالمؤمنون مكتفون بما هم فيه (فى ٤ : ١١) .","وبالنسبة لاحتياجاتهم ، لا يحتجون على شىء ، ولا يحتاجون إلى شىء .","نقطة أخرى فى حياة الإيمان هى :",{"h":"٤ ـ يُختبر الإيمان بما يمنحه من قوة :"},"هل لديك قوة الإيمان التى تشعر بها أن كل شىء مستطاع ؟"],"105":["وكما قال الرب « كل شىء مستطاع للمؤمن » (مر ٩ : ٢٣) . هل تشعر أن هناك شيئاً صعباً أو مستحيلاً ، أو لا يصدق إيمانك بأن الله يمكن أن يعمله ؟ هل تقف فى شك أمام الأشياء التى تحتاج إلى معجزة ؟ ! هل يمكنك أن تقول كما قال القديس بولس الرسول « أستطيع كل شىء فى المسيح الذى يقوينى » (فى ٤ : ١٣) . هل تهزك العقبات والصعوبات بحيث تقول « لا فائدة » ؟ ! هل يحاربك اليأس ؟",{"h":"إن اليأس ضد الإيمان ، وضد الرجاء ، من كل ناحية ."},"لا شك إن المنتحرين فقدوا إيمانهم ورجاءهم ، وشعروا أنه لا حل ، كما فقدوا الإيمان بحقيقة الحياة بعد الموت فى الأبدية ومصير المنتحرين فيها .","وكذلك الذين استسلموا للأمر الواقع ، أو للضغوط الخارجية ، وخضعوا للخطية ، لم يؤمنوا إطلاقاً أن هناك قوة يمكن أن تسندهم وتخلصهم .","إن الإيمان قوة لمن يستطيع أن يستخدمها فى ثقة بلا شك .",{"h":"أخشى أن يكون الإيمان فى أيدى البعض كعصا أليشع فى يد جيحزى (٢مل ٤ : ٣١) . وأخشى أن يكون الصليب فى أيدى البعض كذلك : يحسنون حمله ورشمه ، وليس الإيمان به . معهم الصليب وليست معهم قوته التى هى كامنة فى الإيمان به وبعمله ..."},"هل تظنون أن عصا موسى هى التى شقت البحر الأحمر ؟ أم هو إيمان موسى حامل هذه العصا ومستخدمها باسم الرب ؟",{"h":"فهل لك قوة الإيمان التى كانت لموسى حينما ضرب البحر بعصاه ؟"},"إنك كثيراً ما تصلى . ولكن هل فى صلاتك الإيمان الذى يعطى لهذه الصلاة قوة ؟ ما أعجب قول الكتاب حين قال عن إيليا إنه « صلى صلاة » (يع ٥ : ١٧) . وهذه الصلاة لم تكن عادية كصلوات باقى الناس ، إذ أنها استطاعت أن تغلق السماء مرة ، وأن تفتحها مرة أخرى ...","إختبر إيمانك إذن بالقوة التى لك نتيجة علاقتك بالله ."],"106":[{"h":"٥ ـ إختبار الإيمان فى الضيقة :"},"الضيقات تحل بكل أحد . ولكن هناك فرقاً كبيراً بين المؤمن وغير المؤمن فى الروح التى تُستقبل بها الضيقة .",{"h":"إن كانت الضيقة تفقدك سلامك ، فاعرف أن إيمانك ضعيف ."},"المؤمن يستقبل الضيقة مؤمناً أنها للخير ، وأن الله سيحلها . فلا يتضايق فى داخله ، ولا يضطرب ، ولا تنشغل أفكاره بها ، ولا يتعب قلبه بالحزن والألم . إنما يواجه الضيقة بثلاث آيات هى « كل الأشياء تعمل معاً للخير ، للذين يحبون الرب » (رو ٨ : ٢٨) ، و « إحسبوه كل فرح يا إخوتى ، حينما تقعون فى تجارب متنوعة » (يع ١ : ٢) . وأيضاً « كل شىء مستطاع للمؤمن » (مر ٩ : ٢٣) . وبهذا الإيمان يفرح قلبه فى الضيقة ، ويتعزى الناس بفرحه .",{"h":"المؤمن يضع الله بينه وبين الضيقة ، فتختفى الضيقة ويظهر الله ."},"ويذكر يد الله التى كانت مع القديسين فى كل ضيقاتهم « وملاك حضرته خلصهم » (اش ٦٣ : ٩) . يذكر ما حدث لموسى ويوسف وداود وأيوب ودانيال وللثلاثة فتية . وكل هذه الذكريات تزيده إيماناً بالله وثقة فى تدخله وعمله . وهكذا لا يتزعزع فى الضيقة ، ولا يشك ولا يحزن ولا يحمل هماً ... بل يقول مع المرتل « نجت أنفسنا مثل العصفور من فخ الصيادين . الفخ انكسر ونحن نجونا ، عوننا من عند الرب الذى صنع السماء والأرض » (مز ١٢٤) .",{"h":"يقول للرب : مادمت أنت موافق على الضيقة ، فأنا أفرح بها ."},"ليس فقط أقبلها ، أو أرضى بها ، إنما أحسبه كل فرح أن الرب يعطينى بركة هذه الضيقة ... ما أجمل ما قيل عن الآباء الرسل بعد أن جلدوهم « وأما هم فذهبوا فرحين ... لأنهم حُسبوا مستأهلين أن يهانوا من أجل إسمه » (أع ٥ : ٤١) .",{"h":"المؤمن مهما بدت كل الأبواب مغلقة ، يرى باب الله مفتوحاً ."},"إنه يؤمن بالله ، الذى بيده مفاتيح السماء والأرض « الذى يفتح ولا أحد يغلق » (رؤ ٣ : ٧) . ويرتل هذا المؤمن مع القديس يوحنا الراثى قائلاً « بعد هذا نظرت ، وإذا باب مفتوح فى السماء » (رؤ ٥ : ١) . بل اختبار الإيمان بأن ترى"],"107":["جميع الأبواب مفتوحة أمامك . وكلما ترى أمامك باباً مغلقاً ، تقول : ليس هذا هو الباب الذى يريدنى الله أن أدخل منه . هناك أبواب أخرى كثيرة مفتوحة عند الله . وهناك أبواب مغلقة الآن سيفتحها فيما بعد ... وبهذا الإيمان تستريح .",{"h":"٦ ـ إختبار الإيمان ببعض الوصايا :"},{"h":"أ ـ من الوسائل التى يُختبر بها الإيمان : العشور أو العطاء عموماً . وبخاصة إذا كان هذا المؤمن محتاجاً ، أو مطلوب منه أن يعطى من أعوازه ."},"ضعيف الإيمان يقول « إن كان المرتب كله أو الإيراد كله لا يكفى ، فكيف يكون الحال إن نقص أيضاً عشره ؟ ! » . أما المؤمن فإنه يقول : إن إعطائى العشور ، يجعل الباقى مباركاً فيكفى ويزيد ...",{"h":"إن العشور إختبار روحى عرضه الرب نفسه فى سفر ملاخى فقال :"},"هاتوا جميع العشور ... وجربونى بهذا ، قال رب الجنود : إن كنت لا أفتح لكم كوى السماء ، وأفيض عليكم بركة حتى لا توسع ... (ملا ٣ : ١٠) . فإن كان الشخص ـ على الرغم من هذا الوعد الإلهى ـ لا يدفع ، فلا شك أن إيمانه يكون ضعيفاً فى وعد الله وفى بركته . وقبل ذلك فى وصيته ...",{"h":"إن كان هذا فى العشور ، فماذا عن وصيته : من سألك فاعطه ؟ (متى ٥ : ٤٢) . وماذا عن وصية « إذهب بع كل مالك واعطه للفقراء » (متى ١٩ : ٢١) . وماذا عن وصية « بيعوا أمتعتكم [ أو مالكم ] واعطوا صدقة » (لو ١٢ : ٣٣) ؟"},"بهذا يختبر إيمانك : هل الله قادر أن يعولك بما يبقى بعد دفع نصيب الفقراء ؟ وأيضاً هل هو قادر أن يعولك دون أن تكنز لك كنوزاً على الأرض (متى ٦ : ١٩) .",{"h":"ب ـ من الوصايا التى يختبر بها الإيمان أيضاً : حفظ يوم الرب ."},"هل أنت تفرح بيوم الرب لكى تقضيه مع الرب ؟ أم أنت تفضل عليه مشغوليات أخرى عديدة ؟ هل أمورك العالمية أهم فى نظرك ؟ وهل تأجيلها أمر لا تحتمله ولا تستطيع ترتيبه بتنظيم وقتك ؟ إنه إختبار لإيمانك ."],"108":[{"h":"ج ـ وكذلك من الإختبارات الهامة : مدى محبتك للصلاة :"},"هل تنساها وتمر عليك أوقات كثيرة لا تصلى فيها ؟ وهل إذا وقفت للصلاة ، تفكر كيف تنتهى منها لتنشغل بأمور أخرى تهمك بالأكثر ؟ وهل أثناء صلاتك تسرح فى أمور أخرى ، وتنسى أنك واقف أمام الله تخاطبه ؟ إن كنت كذلك فلا يكون إيمانك قوياً بالله وبعشرته وبلذة الحديث معه ...","وهكذا إن وضعنا باقى أمور الصلاة ، وباقى بنود العمل الروحى ، لتكون مجالاً لاختبار إيمانك .",{"h":"٧ ـ إختبر إيمانك بمدى اهتمامك بأبديتك :"},"هل أنت مركز كل فكرك بقلبك فى هذا العالم الحاضر ، ومدى نجاحك فيه ، ومدى تمتعك به ؟ أم أنت تهمك أبديتك ، ويهمك مصيرك فى العالم الآخر ، وتعد العدة لتلك الحياة كما يقول الرب « لتكن أحقاؤكم ممنطقة ، ومصابيحكم موقدة . وأنتم تشبهون أناساً ينتظرون سيدهم متى يرجع من العرس ، حتى إذا جاء وقرع يفتحون له للوقت . طوبى لأولئك العبيد الذين إذا جاء سيدهم يجدهم ساهرين » (لو ١٢ : ٣٥ ـ ٣٧) .",{"h":"إن السهر الروحى إختبار عميق للإيمان ."},"أما الغافل عن أبديته ، فأين هو إيمانه ؟ ! أين إيمانه بالحياة الأخرى ، والإستعداد لها بالتوبة والعمل الصالح ، وبعشرة الله ومحبته ، وبالزيت جاهزاً فى مصباحه ... ؟ !",{"h":"٨ ـ إختبر إيمانك بصحة العقيدة :"},"هل هو إيمان سليم بعيد عن البدع وأخطاء العقيدة ، وعن المفاهيم الخاصة ؟ وهل هو « الإيمان المسلّم مرة للقديسين » (يه ٣) . الذى أودعه الرسل أناساً أمناء كانوا أكفاء أن يعلموا آخرين أيضاً (٢تى ٢ : ٢) . وهل هو موافق لكل تعليم الكتاب ، أم تتبع فيه أناساً يعلمون فكرهم الخاص ؟ بهذا إختبر إيمانك .","أقول هذا لأن العقيدة لها تأثير عملى فى حياة الإنسان الروحية ."],"109":[{"h":"٩ ـ إختبر إيمانك بصفات الإيمان السليم :"},"هل إيمانك إيمان عملى ؟ هل هو ثابت لا تزعزعه الظروف ؟ هل هو لا يضعف ولا يشك ؟ هل هو مملوء بالسلام لا يعرف خوفاً ؟ وهل تعرف حياة التسليم وطاعة الإيمان ، وهل إيمانك إيمان حى مثمر ؟ وهل هو ينمو ويزداد ؟ وهل ...","لست أريد أن أذكر باقى صفات الإيمان لتمتحن بها نفسك .",{"h":"إنما إن أردت مزيداً من الموازين ، يمكن أن تعيد قراءة هذا الكتاب من أوله ."}]}},"judge_others":{"id":"judge_others","title":"إدانة الآخرين","author":"قداسة البابا شنوده الثالث","url":"https://drive.google.com/file/d/1IInEEiWJJLOTlmYuP5l4jrSQP0fhyBlI/view","file":"إدانة_الآخرين.pdf","pageOffset":0,"review":{"status":"needs-review","note":"نُقل الكتاب (سلسلة الحروب الروحية ٤، الطبعة الثانية ١٩٩٠) بقراءة صفحات الكتاب الممسوحة بالنظر، من «قصة هذا الكتاب» إلى آخر الفصل الخامس (ص٥ إلى ص٩٣ بترقيم الملف = ترقيم الكتاب المطبوع)، دون الفهرس. صفحة ٦ في ملف المصدر مكررة من صفحة ٦٦ فأُشير إلى ذلك. بعض فقرات حواف الصفحات الباهتة (كفقرة أسفل ص٥٨) قُرئت بأفضل ما تيسر وتحتاج مطابقة نهائية مع الأصل."},"chapters":[{"title":"قصة هذا الكتاب","from":5,"to":6},{"title":"الفصل الأول: الإدانة غير الخاطئة","from":7,"to":32},{"title":"الفصل الثاني: أنواع إدانة الآخرين","from":33,"to":48},{"title":"الفصل الثالث: الإدانة خطية مركبة","from":49,"to":64},{"title":"الفصل الرابع: أقوال الآباء في الإدانة","from":65,"to":78},{"title":"الفصل الخامس: علاج الإدانة","from":79,"to":93}],"transcribed":[5,93],"pages":{"5":[{"h":"قصة هذا الكتاب"},"أصل هذا الكتاب يرجع إلى محاضرتين ألقيتهما سنة ١٩٦٥ فى القاعة المرقسية بدير الأنبا رويس بالقاهرة عن إدانة الآخرين وأقوال الآباء فيها .","وتحدثت فى هذا الموضوع أيضاً فى محاضرتين أخريين ألقيتهما فى الكاندرائية المرقسية الكبرى فى ٦٩/٣/٢١ ، ٦٩/٣/٢٨ .","ثم تعرضت لهذا الموضوع مرة أخرى ، خلال هذا العام (١٩٨٧) ، وأنا فى مجال تفسير وشرح العظة على الجبل ، فى (متى ٧ : ١ ـ ٥) . كما ألقيت محاضرتين عن الإدانة فى الكنيسة المرقسية الكبرى بالإسكندرية فى يونيو ١٩٨٧ .","ومن هذا المزيج كله ، خرج هذا الكتاب الذى بين يديك .","أقدمه لك باعتباره الجزء الرابع من (سلسلة الحروب الروحية) . وقد صدر الجزء الثالث منذ شهرين عن (الغضب) .","وإن شاء الله حينما يصدر الجزء الثانى من كتاب (تأملات فى العظة على الجبل) سنعرض لهذه النقطة باختصار . ومن يريد التوسع ، فليرجع إلى هذا الكتاب ."],"6":["(تكررت هنا في ملف المصدر الممسوح الصفحة المطبوعة رقم ٦٦، وهي واردة في موضعها الأصلي في الفصل الرابع من هذا الكتاب.)"],"7":[{"h":"الفصل الأول"},{"h":"الإدانة غير الخاطئة"},"١ ـ المسئولية والرعاية .","٢ ـ التمييز الطبيعى .","٣ ـ مفهوم وصايا كتابية .","٤ ـ إدانة الهرطقات والبدع .","٥ ـ النصح والهداية والتوبيخ .","٦ ـ النقد .","٧ ـ إدانة النفس .","من يبرىء المذنب .","شروط الإدانة غير الخاطئة .","لا تحكموا قبل الوقت .","الحكم بالحق ."],"8":["هناك حالات كثيرة تجوز فيها الإدانة ، ولا تكون خطية ، نذكر منها :",{"h":"١ ـ المسئولية والرعاية"},{"h":"تجوز الإدانة حينما تصدر من مسئول أو صاحب سلطان"},"هناك أشخاص أقامهم الله بسلطان على غيرهم . من حقهم أن يدينوا من هم تحت سلطانهم ، ولا تنطبق عليهم الآية التى تقول « لا تدينوا لكى لا تدانوا » ..",{"h":"وهؤلاء ليس من حقهم فقط أن يدينوا ، بل من واجبهم ..."},{"h":"بحيث أنهم يخطئون إن لم يدينوا من هم تحت سلطانهم ."},"من أمثلة هؤلاء : الأب والأم . وقد ائتمن الله الآباء والأمهات على تربية أولادهم . ومن حقهم أن يوبخوا أبناءهم على أخطائهم . وأن يقولوا للإبن « إن تصرفك هذا خاطىء ، وينبغى أن تتركه » . وإن لم يتركه قد يأخذ منهم عقوبة .",{"h":"لاشك إنها إدانة ، ولكنها ليست خطية إدانة ."},"لأنها صادرة من شخص صرح له الله أن يدين ، بل أمره بذلك ، كجزء من تربيته لإبنه . بل إن الأب الذى يقصر فى تربية إبنه ، ويهمل فى تنشئته وتوجيهه ، ولا يدينه ويوبخه على أخطائه ، هذا الأب يعاقبه الله ...",{"h":"ومثال ذلك العقوبة التى أوقعها الله على عالى الكاهن ."},"كان أولاده يخطئون ... وسمع عالى الكاهن بذلك ، وأدانهم ، ولكن ليس بحزم ! قال لهم : « لماذا تعملون مثل هذه الأمور ؟ لأنى أسمع بأموركم الخبيثة من جميع هذا الشعب . لا يابنىّ ، لأنه ليس حسناً الخبر الذى اسمع ... » « ولم يسمعوا لصوت أبيهم » (١صم ٢ : ٢٢ ـ ٢٥) .","وغضب الرب لأن عالى الكاهن تراخى فى إدانة أولاده ، فقال « هوذا أنا فاعل أمراً فى إسرائيل ، كل من سمع به تطن أذناه . فى ذلك اليوم أقيم على عالى كل ما تكلمت به على بيته ... وقد أخبرته بأنى أقضى على بيته إلى الأبد ، من أجل الشر الذى"],"9":["يعلم أن بنيه قد أوجبوا به اللعنة على أنفسهم ، ولم يردعهم » (١صم ٣ : ١١ ـ ١٤) .",{"h":"إذن الإدانة هنا واجب ملزم ، من يقصر فيه يعرض نفسه للعقوبة ."},"ليس فقط أن يدين الأب أولاده إن أخطأوا . بل أكثر من هذا أن « يردعهم » . أى أن يمنعهم ـ بسلطان ـ من ارتكاب الخطأ ، ومن الأستمرار فيه ...","وما أكثر الوصايا التى أعطاها الله للآباء والأمهات لتأديب أولادهم . ومعها وصايا أخرى للأبناء أن يطيعوا آباءهم فى الرب ، لأن هذا حق (أف ٦ : ١) .",{"h":"وما نقوله عن الأب الجسدى ، نقوله أيضاً عن الأب الروحى ، وعن الراعى عموماً ..."},"ومن هنا أعطى الله للآباء الكهنة ، وللرعاة ، وللأنبياء ، واجباً هو إنذار الخطاة وإدانتهم . فقال « يا ابن آدم ، قد جعلتك رقيباً ... فاسمع الكلمة من فمى ، وانذرهم من قبلى . إذا قلتُ للشرير موتاً تموت ، وما أنذرته أنت ، ولا تكلمت إنذاراً للشرير من طريقه الرديئة لإحيائه ، فهذا الشرير يموت بإثمه ، أما دمه فمن يدك اطلبه » (حز ٣ : ١٧ ، ١٨) .","إذن إنذار الخطاء وتوبيخهم وردعهم وإدانتهم طرقهم للشرير ، ليست مجرد حق للآباء والرعاة ، بل كل ذلك واجب عليهم ، يدانون إن لم يقوموا به . ولكنهم يخلصون من الدينونة ، إن هم أدانوا هؤلاء الخطاة ، وأنذروهم من جهة نتيجة شر أعمالهم . وهكذا يكمل الرب وصيته فيقول « وإن أنت أنذرت الشرير ، ولم يرجع عن شره ، ولا عن طريقه الرديئة ، فإنه يموت بإثمه . أما أنت فقد نجيت نفسك » (حز ٣ : ١٩) .",{"h":"ونفس الكلام نقوله عن المدرس مع تلاميذه ، ورئيس العمال مع مرؤوسيه ، وأيضاً عن القاضى بالنسبة إلى المتهمين ."},"كل هؤلاء لهم الحق أن يدينوا من هم تحت سلطانهم ، فى نطاق اختصاصاتهم لا يتعدونها ، وفى حدود الواجب المناط بهم ، وفى مجال عملهم ومسئوليتهم . وفى الالتزام بالحق والعدل ."],"10":["فإن قال المدرس لتلميذه إنه مهمل فى أداء واجباته الدراسية ، وإن قال رئيس العمل لأحد عماله إنه غير أمين فى عمله . وإن قال القاضى إن هذا المتهم مذنب ، لا يكون أحد من هؤلاء قد خالف وصية « لا تدينوا لكى لا تدانوا » .",{"h":"وإن سمع قول الرسول « من أنت يا من تدين غيرك » (يع ٤ : ١٢) ، يجيب « أنا المسئول عنه وعن عمله » ."},"إنه يدين ، وبسلطان . وفى عمله إدانة ، ولكنها ليست خطية إدانة . لأن الإدانة هنا من حقه ، بل هى من واجبه .","وإن قصر واحد من كل هذه الفئات فى إدانة من هم تحت سلطانه ، يرتبك العمل ، ويفسد المجتمع ، وتسود اللامبالاة",{"h":"لذلك إن اجتمع كونسلتو أطباء لفحص مريض ، وتشاوروا فى تشخيص مرضه ."},"فقال أحدهم إنه يشكو من كذا ، وقال آخر إنه مريض بكذا ، وقال ثالث إنه مصاب بكذا .. فهنا القصد التوصل إلى شفاء المريض ، وليس القصد هو إساءة سمعته أو التشنيع به .. ولعل مما يشبه هذا تماماً ما ورد فى (نسكيات باسيليوس) :",{"h":"سئل القديس باسيليوس الكبير عن الإدانة ، فقال :"},"إذا كان المقامون على الأخوة يبحثون حالة أخ فى المجمع ، وتعرضوا لأخطائه وماذا يُعمل لأجل تقويمه ، ولأجل سلامة المجمع من نتائج هذه الأخطاء ، فلا تكون هذه خطية إدانة ... بشرط أن يفحصوا اخطاءه « فى خوف الله » .",{"h":"وهذا الحق فى الإدانة ، أعطاه الرب للكنيسة :"},"فكما أعطاها سلطاناً أن تحل ، أعطاها أيضاً سلطاناً أن تربط (متى ١٨ : ١٨) . وأعطاها أن تفصل فى الخصومات . ومن لم يسمع لها فيما تحكم به ، يكون كالوثنى والعشار (متى ١٨ : ١٧) . فإن قالت الكنيسة لشخص إنه مخطىء ، لا تكون قد وقعت فى خطية إدانة ، بل تكون قد أدانته بحق وبسلطان .","يوحنا المعمدان أدان الخطاة ووبخهم (متى ٣ : ٧) . وبولس وبخ كثيرين منهم « الغلاطيون الأغبياء » (غل ٣ : ١) . وأمر تلميذه تيموثاوس الأسقف أن يوبخ"],"11":["وينتهر ويعظ (٢تى ٤ : ٢) . وقال له أيضاً « الذين يخطئون ، وبخهم أمام الجميع ، لكى يكون عند الباقين خوف » (١تى ٥ : ٢٠) .","بولس الرسول أدان خاطىء كورنثوس (١كو ٥) ، ووبخ أهل كورنثوس على أنهم لم يعزلوا الخبيث من بينهم (١كو ٥ : ١٣) . وبطرس الرسول أدان حنانيا وسفيرا وحكم عليهما ، بعد أن وصفهما بالكذب ، وبالاتفاق على تجربة روح الرب (أع ٥ : ٣ ـ ٩) .",{"h":"ولعلك تقول « أنا لست رسولاً ولا نبياً » ... لك حق . إذن اعمل فى حدود السلطان الذى وُهب لك من الله ، إن كنت صاحب سلطان ."},"اعمل فى حدود مسئوليتك ، مهما كانت ضيقة ... على أن يكون ذلك بأسلوب روحى ، كما سنشرح فيما سيأتى ...",{"h":"٢ ـ التمييز الطبيعى"},{"h":"أحياناً تكون الإدانة شيئاً طبيعياً ، مجرد تمييز للخطأ أو الشر ."},"فأنت مثلاً إن سمعت إنساناً يشتم ، لا تستطيع أن تمنع نفسك من إدراك أن هذه شتيمة . وبالمثل إن رأيت رجلاً فى ثورة غضب وقد فقد أعصابه ، وهكذا إن رأيت إمرأة فى ملابس متبرجة غير لائقة .","وبالمثل إذا سمعت إنساناً يحلف بأقسام مغلظة ، أو سمعت إنساناً يغنى أغانى عالمية ، أو يقول فكاهات رديئة جداً من الناحية الأخلاقية ، هل استطيع أن أمنع نفسى من إدانة ما أسمعه ؟! هناك إذن إدانة تلقائية بحكم الضمير ...","ينبغى أن نفهم الروحيات بطريقة سليمة بعيدة عن الوسوسة .",{"h":"فعدم الإدانة ليس معناه أن أفقد الحكم الطبيعى على الأمور ."},"فقد وهب الله للإنسان ضميراً يميز به بين الخير والشر . وليس من صالح الإنسان أن يفقد التمييز ."],"12":["إنه نور طبيعى يستطيع به أن يحكم على أعماله ، كما يحكم به على أعمال غيره ، مع فارق سنذكره فيما بعد ... وإن فقد الإنسان هذا التمييز سوف تختل أمامه القيم والمبادىء ، ولا يدرى ما يجب أن يكون ، وما لا يجب ...","وهكذا قال السيد الرب مرتين فى العظة على الجبل :",{"h":"« من ثمارهم تعرفونهم » (متى ٧ : ١٦ ، ٢٠) ."},"وشرح ذلك فقال « هل يجتنون من الشوك عنباً ، أو من الحسك تيناً ؟! هكذا كل شجرة جيدة تصنع ثماراً جيدة . وأما الشجرة الردية فتصنع أثماراً ردية . لا تقدر شجرة جيدة أن تصنع أثماراً ردية . ولا شجرة ردية أن تصنع أثماراً جيدة . إذن من ثمارهم تعرفونهم » (متى ٧ : ١٦ ـ ٢٠) .","فهل إذا رأينا الشوك فعرفنا أنه شوك ، وإن رأينا الثمر الردىء فعرفنا أنه ثمر ردىء ، أنكون آثمين واقعين فى إدانة الآخرين ؟! كلا بلا شك ...",{"h":"يقول القديس أوغسطينوس فى تفسير هذه الآية (متى ٧ : ٧) ."},"هناك شجرة تعطى ثماراً ردية ، وشجرة تعطى ثماراً جيدة . ولا يمكن أبداً لإنسان أن يخدع نفسه ، ويقول عن الردىء إنه جيد ، ولا عن الجيد إنه ردىء . فمما لاشك فيه أن بعض الأمور واضحة جداً ، لا نستطيع أن نخدع أنفسنا فيها ...","ولعله من أجل هذا التمييز قال القديس بولس الرسول :",{"h":"خطايا بعض الناس واضحة تتقدم إلى القضاء (١تى ٥ : ٢٤) ."},"هذه الخطايا الواضحة لا ذنب لك إن أدركتها : من الطبيعى أنك سوف تشعر أن هناك خطأ يتقدم إلى القضاء . وفى نطاق هذا المستوى لا تكون قد أخطأت . إنما توجد ملاحظة لابد أن نقدرها وهى :",{"h":"هناك فرق بين إدانة العمل وإدانة الشخص :"},"فإن رأيت شخصاً سكراناً يتطوح فى الطريق ، لا تستطيع أن تمنع نفسك من أن هذا خطأ . العمل خطأ ، أو الحادث أمامك خطأ . ولكن الشخص نفسه لا تستطيع أن"],"13":["تدينه ، إلا إذا عرفت ظروفه ... ربما هناك من خدعه وأسكره . ربما شرب عن طريق الخطأ . وربما العكس . من يدرى ؟!",{"h":"إذن التمييز شىء ، والحكم على الشخص شىء آخر ."},"كونى أسمع الشتيمة فأعرف أنها شتيمة ، هذا تمييز .",{"h":"أما أن اسمعها ، فأقيم فى ذهنى محكمة لصاحبها ، وأقول إنه كذا وكذا ، ويستحق ... فهنا يصبح الأمر إدانة ، لأنه انتقل من تمييز العمل والحكم التلقائى للضمير ، إلى الحكم على الشخص نفسه ."},"وإذا أخذت قصة هذا الإنسان موضوعاً لحكاياتى وأحاديثى مع الناس ، لا أقول حينئذ إنه مجرد تمييز طبيعى ، أو حكم تلقائى من الضمير . بل هنا أكون قد تطورت من إدانة الشخص إلى التشهير به . ولاشك أن كلاً منهما خطيئة .",{"h":"ومن جهة الخطايا الواضحة ، توجد أمور تبدو واضحة ، وهى على عكس ذلك ..."},"فإن رأيت شخصاً فى الصوم يشرب كوباً من اللبن ، وقلت : هذا الإنسان محب للأكل وكاسر للصوم ولاشك أن هذه خطية واضحة تقدمه إلى القضاء !! (١تى ٥ : ٤) ... فربما تكون مخطئاً فى حكمك . وقد يكون هذا الشخص مريضاً بقرحة فى المعدة أو مرض آخر ، ويحتاج إلى اللبن كدواء . وقد وافق على أوامر الأطباء متغصباً من أجل صحته ... ولا يمكن أن يحكم عليه بأنه محب للطعام وكاسر للصوم ...",{"h":"وقد علّق القديس على موضوع الأكل هذا ، فقال :"},"إن كل أنواع الطعام البشرى يمكن أن تؤخذ بنية صالحة ... وبدون شهوة وبدون تمييز . وتذكر فى ذلك قول القديس بولس الرسول :",{"h":"لا يزدرِ من يأكل بمن لا يأكل . ولا يدن من لا يأكل من يأكل ، لأن الله قبله » (رو ١٤ : ٣) ."},"ويكمل القديس بولس الرسول كلامه فيقول « من أنت الذى تدين عبد غيرك ؟! هو لمولاه يثبت أو يسقط . ولكنه سيثبت ، لأن الله قادر أن يثبته » (رو ١٤ : ٤) ."],"14":["أمثال هذه الأمور ليس من حق إنسان أن يحكم فيها . وهى ليست من الخطايا الواضحة التى تتقدم إلى القضاء . الخطايا الواضحة هى مثل الزنى والسرقة والإعتداء وأنواع النجاسات .",{"h":"أما الأمور التى تتوقف على النية والقصد ، فليس من حقنا أن نحكم عليها . الله وحده هو العارف بالنيات ."},"الله وحده هو فاحص القلوب ، وهو الذى يعرف القصد والدافع . ويستطيع أن يحكم إن كان هذا العمل صالحاً أم طالحاً ، مما لا تتوفر لنا معرفته .","نقطة أخرى نضيفها إلى عنصر التمييز وهى :",{"h":"٣ ـ مفهوم وصايا كتابية"},"وصايا وآيات تحمل الإدانة :","فهناك وصية فى الكتاب تقول لك « لا تستصحب غضوباً ، ومع رجل ساخط لا تجىء » (أم ٢٢ : ٢٤) . فكيف يمكن أن تنفذ الوصية وتبعد عن صحبة الغضوبين ، إلا لو أدركت أن هذا الإنسان بالذات هو رجل غضوب ؟! فهل هذه إدانة ؟ كلا ، بل هى لون من التمييز ، تماماً كما تميز حفرة حتى لا تقع فيها .","ومثله قول الكتاب « المعاشرات الردية تفسد الأخلاق الجيدة » (١كو ١٥ : ٢٣) . فكيف تبعد عن هذه المعاشرات ، إلا لو عرفت تماماً إنها ردية ؟ فهل هذه المعرفة إدانة ؟ كلا ، طبعاً ...","وبنفس المنطق نتكلم عن الوصية التى يحملها المزمور الأول « طوبى للرجل الذى لم يسلك فى مشورة الأشرار ، وفى طريق الخطاة لم يقف ، وفى مجلس المستهزئين لم يجلس » .","كيف يبعد عن هؤلاء الأشرار والخطاة والمستهزئين ، إن لم يعرف أنهم كذلك ؟ فهل هذه المعرفة خطية إدانة ؟"],"15":["كلا ، بلا شك . مادام الأمر قد اقتصر على المعرفة والبعد . وحتى لو تدرج الأمر إلى نصح أصدقائك ومعارفك وأقربائك وتلاميذك فى البعد عن هؤلاء لا نكون أيضاً قد أخطأت .",{"h":"أتتركهم يسقطون فى حفرة وتقول « لا أريد أن أدين الحفرة » ؟!"},"هوذا الرسول يقول « نوصيكم أيها الأخوة باسم ربنا يسوع المسيح أن تتجنبوا كل أخ يسلك بلا ترتيب ، وليس حسب التعليم الذى أخذه منا » (٢تس ٣ : ٦) . فكيف تتجنب مثل هذا الأخ ، إلا لو عرفت تماماً أنه « يسلك بلا ترتيب » . فهل هذه المعرفة خطية إدانة ؟! كلا ، لأن خطايا بعض الناس واضحة .",{"h":"وبالمثل الوصايا الخاصة بالبعد عن العثرات :"},"من المفروض أن يبعد عن العثرات كل إنسان روحى . ولكى يبعد عنها ، لابد أن يعرف أنها عثرات . وليست فى هذه المعرفة خطية إدانة . بل إن السيد المسيح يقول « إن كانت عينك اليمنى تعثرك ، فاقلعها والقها عنك ... » (متى ٥ : ٢٩) .","إن يوسف الصديق قد تعرض لإحدى هذه العثرات ، فقال",{"h":"كيف أصنع هذا الشر العظيم وأخطىء إلى الله ؟! (تك ٣٩ : ٩) ."},"وهنا نرى أن يوسف قد أدان هذا العمل ، ووصفه بأنه شر عظيم وأنه خطأ نحو الله . ومع ذلك لم يدن المرأة الثانية ، ولم يصفها بأية عبارة جارحة .","إذن إدانة العمل من حقنا . وهو نوع من التمييز الطبيعى لا خطأ فيه ، ولا داعى للتعرض للأشخاص .","والوصايا الخاصة بالبعد عن العثرات مع إدانتها ، ليست هى خاصة بالسلوكيات فقط ، إنما أيضاً هناك العثرات الخاصة بالإيمان والتعليم والعقيدة وهذا يقودنا إلى نقطة هامة وهى ."],"16":[{"h":"٤ ـ إدانة الهرطقات والبدع"},"يقول القديس يوحنا الرسول ، وهو من أشهر الرسل بالمحبة : « إن كان أحد يأتيكم ولا يجىء بهذا التعليم ، فلا تقبلوه فى البيت ولا تقولوا له سلام . لأن من يسلم عليه يشترك فى أعماله الشريرة » (٢يو ١٠ ، ١١) .","فهل الذى يرفض المبتدعين ولا يقبلهم ولا يسلم عليهم ، يكون قد وقع فى خطية إدانة ؟ محال أن يكون هذا . بل إنه يقع فى خطية إن كان يسلم عليهم ...","والسيد المسيح يقول « لا تعطوا القدس للكلاب ، ولا تلقوا دررکم قدام الخنازير ، لئلا تدوسها بأرجلها وتلتفت فتمزقكم » (متى ٧ : ٦) . فكيف نفعل هكذا ، إن لم نعرف أنهم كذلك . وهذه المعرفة ليست خطية ، لأنه بدونها لا يتم تنفيذ الوصية . وبالمثل أيضاً يقول الرب :",{"h":"« احترزوا من الأنبياء الكذبة ، الذين يأتونكم بثياب الحملان ، ولكنهم من داخل ذئاب خاطفة » (متى ٧ : ١٥) ."},"فالاحتراس من الكذبة ـ وإن كان يحمل إدانة لهم ولكذبهم ـ إلا أنه ليس خطية إدانة ، لأن الإنسان الروحى ينبغى أن يكون حريصاً ، مميزاً للأرواح حسب وصية الرسول (١يو ٤ : ١) . فالاحتراس من الأشرار ليس خطية . ومعرفة أنهم يأتون بثياب الحملان وهم ذئاب خاطفة ، ليس فيه خطأ ، بل فيه حكمة .",{"h":"ليست الروحيات أن تسير مغمض العينين ، حتى لا تبصر ولا تدرك حيل الذئاب الخاطفة !"},"فالكتاب يقول « الحكيم عيناه فى رأسه ، والجاهل يسلك فى الظلام » (جا ٢ : ١٤) . فهل السلوك فى الظلام فضيلة ؟ كلا . نحن لا نريدك أن تلعن الظلام . إنما يكفى أن تميزه ، وتبعد عنه ، وتسلك فى النور . وقد وضح السيد المسيح أن التمييز بين النور والظلمة أمر سهل ، فقال « من ثمارهم تعرفونهم » (متى ٧ : ١٦) ."],"17":["نقطة أخرى نقولها فى « الإدانة غير المخطئة » وهى :",{"h":"٥ ـ النصح والهداية والتوبيخ"},"يقول الرسول « إن ضلّ أحد بينكم عن الحق ، فردّه آخر ، فليعلم أن من ردّ خاطئاً عن ضلال طريقه ، يخلص نفساً من الموت ، ويستر كثرة من الخطايا » (يع ٥ : ١٩ ، ٢٠) . فهل معرفتك أن أحداً قد ضلّ عن الحق ، هى إدانة له ؟ كلا طبعاً ، مادمت تريد رده عن ضلال طريقه ، ولست تقصد التشهير به ...",{"h":"ونحن لا نهدى الخطاة ، إلا إذا عرفنا أنهم خطاة ."},"تماماً مثلما يعرف الطبيب نوع المريض ، لكى يصف طريقة علاجه . هكذا إذا درسنا الأخطاء التى يقاسى منها فرد أو مجموعة ، أو حتى كنيسة بأسرها ، لا نكون قد وقعنا فى خطية إدانة ، مادام الهدف هو الإصلاح وليس الإساءة إلى سمعة الغير ...","والآيات الخاصة بالنصح وهداية الآخرين كثيرة جداً ... والنصح والهداية قد يحملان التوبيخ أحياناً . ولا يحمل هذا التوبيخ خطية إدانة . وفى هذا يقول الكتاب :",{"h":"« لا تشتركوا فى أعمال الظلمة غير المثمرة ، بل بالحرى وبخوها » (أف ٥ : ١١) ."},"فليست معرفتنا أنها أعمال ظلمة خطية إدانة ، كما أن توبيخ هذه الأعمال غير المثمرة ليس هو أيضاً خطية إدانة . بل أن تبكيتنا لهذه الأعمال هو فضيلة ، لأنه تنفيذ للوصية .","بل أن تبكيتنا لهذه الأعمال هو فضيلة ، لأنه تنفيذ للوصية . على أننا نرجو أن نرجع إلى هذه النقطة فيما بعد ، لنعرف الكيفية السليمة لتنفيذ هذه الوصية .",{"h":"وتدخل فى مجال هذا التبكيت ، ما يلزم لأعمال الرعاية ."},"حسبما قال القديس بولس الرسول لتلميذه تيموثاوس الأسقف « وبخ ، انتهر ، عظ ، بكل أناة وتعليم » (٢تى ٤ : ٢) ."],"18":[{"h":"وإن كانت الإدانة فى أسلوب النصح والتوبيخ ، ينبغى أن يعرف الإنسان كيف تكون :"},"ومثال ذلك أبيجايل التى وبخت داود النبى ، ومنعته من اتيان الدماء والانتقام لنفسه ، بأسلوب كله حكمة ، بدأته بالخضوع وبالمديح ، ثم مست المشكلة بطريقة غير جارحة ، لم تخدش بها شعور داود . بل صارحته ولكن فى أدب وفى تواضع ... (١صم ٢٥) .","فى كل نصيحتها له ، كانت تقول « ياسيدى » وتقول عن نفسها « أمتك » « جاريتك » ... بدأت لقاءها معه بأن قدمت له ما كان يطلبه من الأطعمة ، وسجدت له وأعتذرت عن خطأ زوجها ، وقالت « علىّ أنا يا سيدى هذا الذنب ، ودع أمتك تتكلم فى أذنيك ، واسمع كلام أمتك » .","والعطايا التى قدمتها له لم تجرحه بها ، بل قالت « والآن هذه البركة التى أتت بها جاريتك إلى سيدى ، فلتعط للغلمان السائرين وراء سيدى ، واصفح عن ذنب أمتك » .",{"h":"وبعد كل هذا المديح وأسلوب الإتضاع مست أبيجايل خطأ داود ، مقدمة له بمديح آخر ، فقالت :"},"« سيدى يحارب حروب الرب ، ولم يوجد فيك شرّ كل أيامك » « لتكن نفس سيدى محزومة فى حزمة الحياة مع الرب إلهك ... » . وهنا دخلت فى توبيخه على نقطة الضعف فقالت « ويكون عندما يصنع الرب لسيدى حسب كل ما تكلم به من الخير من أجلك ، ويقيمك رئيساً على إسرائيل ، أنه لا تكون لك هذه مصدمة ومعثرة قلب لسيدى ، أنك قد سفكت دماً عفواً ، أو أن سيدى قد انتقم لنفسه » .","نبهته إلى أنه مقدم على الإنتقام لنفسه ، وعلى سفك دم بلا سبب يستدعى ذلك ، ونصحته بالإبتعاد عن هذا ، حتى لا يصبح هذا الأمر معثرة قلب له فيما بعد ...",{"h":"وهذا النصح المؤدب ، والتوبيخ الضمنى ، قبله منها داود وشكرها عليه ..."},"وقال لها « ... مبارك عقلك ، ومباركة أنت ، لأنك منعتنى اليوم عن اتيان الدماء وانتقام يدى لنفسى » (١صم ٢٥ : ٣٣) . وتقبل منها عطيتها ، وصرفها"],"19":["بسلام ، ورفع وجهها ولم يقم بإيذاء زوجها الخطىء إليه ، مستمعاً لنصيحتها .","حقاً ، ما أجمل النصح ، إن كان بلياقة وأدب . وهنا يسرنا أن نضع قواعد للنصح والتبكيت :",{"h":"١ ـ قد يكون من حقك أو من واجبك أن تنصح أو توبخ . ولكن ليكن هذا النصح بأدب وباتضاع وبمحبة ."},{"h":"إن التوبيخ بروح الكبرياء والتعالى و أو بأسلوب الاحتقار والاستصغار ، لا يمكن أن يكون مقبولاً . أما إذا نصحت إنساناً أو وبخته وأنت تقول له :"},"« أنت تعرف يا (فلان) مقدار محبتى لك ، ومقدار حرصى على سمعتك . لذلك أنا غير مستريح اطلاقاً لتصرفك (الفلانى) . وأشعر أنه سيضرك ويسىء إليك ، وربما يتخذه أعداؤك فرصة ليقولوا عنك إنك .. وإنك .. لذلك ابعد عن هذا الأمر ، وحاول أن تصحح ما فعلته بكذا وكذا ... » .","هذا الكلام مقبول . بعكس إنسان آخر يقابل شخصاً فيقول له « كيف تفعل كذا ؟ كيف سمح لك ضميرك ؟ هل هذه تصرفات إنسان عاقل ؟! هل هذه تصرفات إنسان يحترم نفسه ؟! إنك كذا وكذا وكذا » ويصب عليه سيلاً من الألفاظ الجارحة تشعره أنه أمام عدو ... !",{"h":"لذلك إن كلمت إنساناً من أجل خلاص نفسه ، فغضب ولم يقبل منك ، راجع نفسك : ربما نصيحتك له كانت خالية من المحبة أو من الاتضاع ."},"ومن الجائز أن نفس النصيحة يقدمها له خادم آخر ، ولكن بأسلوب مقبول يستريح له ويشكره عليه . لذلك حسناً قال الكتاب « رابح النفوس حكيم » (أم ١١ : ٣٠) .","لذلك إن قلنا إنه من أبواب الإدانة غير الخاطئة : النصح والهداية ... إنما نقصد النصح الحكيم ، المملوء حباً واتضاعاً ... ولا نقصد كل نصح مهما كان أسلوبه ...",{"h":"فحسب نوعية الأسلوب يصير النصح خطأ أو صواباً ."}],"20":["وحسب نوعية الأسلوب ، يدخل النصح والتوبيخ فى نطاق الإدانة الخاطئة ، أو فى نطاق الإدانة غير الخاطئة .","إنك تستطيع أن تدرك تماماً إن كان الذى يوبخك هو مشفق عليك ، أم هو يحتقرك ويزدريك . روحه فى الحديث ، ولهجته ، وألفاظه ومشاعره ، هى التى تترك فى نفسك أثراً ، ربما أكثر من موضوعية التوبيخ ...",{"h":"٢ ـ كذلك ينبغى أن يكون التبكيت بحق ، وليس ظلماً :"},"ولعلنا نذكر مثلاً للتبكيت الظالم ، موقف عالى الكاهن من حنة زوجة القانة . كانت عاقراً لا تنجب . وكان لضرتها فننة أولاد ، فكانت تلك تغيظها . وذهبت حنة إلى هيكل الرب ، وسكبت نفسها أمامه . كانت تصلى وهى مرة النفس ، وقد بكت بكاء ، ونذرت نذراً إن أعطاها الرب نسلاً أن تقدمه نذيراً للرب يخدمه كل أيام حياته . كانت تكلم الرب فى قلبها ، وصوتها لم يُسمع ، وشفتاها فقط تتحركان ، حتى أن عالى الكاهن ظنها سكرى ، ووجد من واجبه أن يوبخها !! فقال لها « حتى متى تسكرين ؟ انزعى خمرك عنك » (١صم ١ : ٩ ـ ١٤) .",{"h":"إنه كاهن ، وله سلطان ، وهو إنسان مسئول ، ومن حقه أن يوبخ وأن يدين . ولكنه فى هذا الموقف كان مخطئاً ."},"لم يكن يوبخ عن حق . بل كان ظالماً فى إدانته ، ظالماً فى حكمه عليها ، قاسياً وجارحاً فى أسلوبه . ومع أن حنة أجابته فى أدب شديد يليق باحترام كهنوته . ولكنه مع ذلك كان مخطئاً . ومع أنه دعا لها بالخير ، إلا أنه لم يعتذر لها عن سابق كلامه ...",{"h":"لذلك يجب أن يسبق التوبيخ ، الفحص والتدقيق ."},"ولا يجوز أن يوزع إنسان توبيخاته عفواً أو بدون أن يتأكد من صحة الخطأ ... ! إنما إن وثق تماماً أن ما يزمع أن يبكت عليه هو من « أعمال الظلمة غير المثمرة » حينئذ تنطبق وصية « ... بل بالحرى بكتوها » .",{"h":"٣ ـ كذلك لا يجوز التبكيت لنفس مرة معذبة ."}],"21":["لقد وقع فى هذه الخطية أصحاب أيوب الثلاثة ، وجرحوه أكثر من مرة ، وهو مرّ النفس ، حتى أثاروه باتهاماتهم وتوبيخاتهم ـ وكانت ظلماً ـ فقال لهم أيوب « حتى متى تعذبون نفسى وتسحقوننى بالكلام ؟ هذه عشر مرات أخزيتمونى . لم تخجلوا أن تحكرونى » « تراءفوا تراءفوا أنتم علىّ يا أصحابى ، لأن يد القدير قد مستنى » (أى ١٩ : ٢ ، ٣ ، ٢١) . وقال لهم عبارته المؤثرة « أنا أيضاً استطيع أن أتكلم مثلكم ، لو كانت أنفسكم مكان نفسى . وأن أسرد عليكم أقوالاً » (أى ١٦ : ٤) .",{"h":"الإنسان المرّ النفس يحتاج إلى كلمة تعزية ، وليس إلى كلمة توبيخ ونصائح وإدانة !"},"فإن وجدت إنساناً مرّ النفس ، مهما كان مخطئاً ، لا نسمح لنفسك أن توبخه ، لئلا يبدو توبيخك لوناً من الشماتة . قل له كلمة طيبة ، كلمة تعزية . فالتوبيخ ليس الآن وقته ، وهو حالياً لا يحتمله . يكفيه ما هو فيه . واسمع قول الحكيم « لكل شىء زمان ، ولكل أمر تحت السماوات وقت » (جا ٣ : ١) . وهنا نقول الملاحظة التالية :",{"h":"٤ ـ النصح والتوبيخ لا يصلحان إلا فى وقتهما المناسب :"},"وهنا تخطر على بالى قصة طريفة وهى : قيل إن صبياً نزل إلى البحر يستحم . وكان المكان خطراً فيه دوامات جذبت الطفل ، فكاد يغرق مصباح يطلب النجدة . فمر عليه رجل ورآه فى هذه الحال . فقال له « ياولد ... كيف تجرؤ أن تستحم فى البحر ، وأنت لا تتقن السباحة ؟ وكيف بلغ بك الجهل أن تستحم فى هذه المنطقة الخطرة ؟ وكيف ... ؟ فقال له الصبى « أنقذنى يا سيدى الآن . ثم وبخنى بعد ذلك ... » .",{"h":"حقاً تمر أوقات على الخطاة ، يحتاجون فيها إلى من ينقذهم ، وليس إلى من يوبخهم ..."},"إن للتوبيخ وقتاً ، ربما لا يكون الأول فى الترتيب . قد تبدأ أولاً بالحب وبالمعونة . وبكل عوامل الانقاذ ، وتؤجل التوبيخ إلى حين آخر . وقد يكون الخاطىء فى حالة من الندم الشديد ، وقد بكّت نفسه بتبكيت مرّ شديد ، لا يحتاج فيه إلى مزيد ."],"22":["تأمل الآب الحنون فى قصة الإبن الضال . إنه لم يبكت هذا الإبن بعبارة واحدة ، بل رآه من بعيد فتحنن وركض ووقع على عنقه وقبّله ، وألبسه الحلة الأولى ، وذبح له العجل المسمن ... (لو ١٥ : ١٧ ـ ٢٣) ... كان ذلك وقت فرح ، ولم يكن وقت تبكيت ...",{"h":"إن النصح والتبكيت قد يدخلان فى نطاق الإدانة غير الخاطئة ، ولكن بشروط ..."},"هى ما ذكرناه ... وبغير ذلك قد يتغير الأمر ، ويتحول التبكيت إلى جرح وإهانة وإدانة ، وربما يأتى بنتائج عكسية .","نقطة أخرى نقولها فى شروط النصح والتبكيت وهى :",{"h":"٥ ـ أحياناً يصلح تبكيت الخاطىء ، إن كان ذلك « فيما بينك وبينه وحدكما » (متى ١٨ : ١٥) ."},"حيث لا يتعرض للخجل أمام الناس ، وحيث لا تنكشف أخطاؤه أمام الآخرين . وحيث يستطيع أن يعترف بالخطأ . ويعتذر عنه ، ويقبل التبكيت عليه ، إذ لا يراه أحد ، فلا يراق ماء وجهه أمام الآخرين ، ولا ينفضح أمام الناس . هذا هو النصح فيما بينك وبينه ، والتبكيت المستور ، والمقبول .",{"h":"أما إن قمت بتبكيته أمام الناس ، فقد يضطر أن ينكر ، أو يدافع عن نفسه ، أو يكابر !"},"حتى لو فعلت ذلك بمحبة واتضاع . ولكن إنكشافه أمام الآخرين قد يضطره أن يحمى سمعته بالدفاع الباطل ، وربما بالكذب ... وتكون أنت قد أعثرته ، ودفعته إلى كل ذلك ، لأنك فضحته علناً ، وخدشت حياءه ، وجرحت كرامته ...",{"h":"وقد لا يخجل ، بل يتبجح ويقول « نعم قد فعلت » ."},"ليس فى انسحاق قلب ، وإنما فى تحدٍ وفى مقاومة . وفى اصرار على أن لا يبدو ضعيفاً أمام الناس !"],"23":["أما الذين قال عنهم الرسل « وبخهم أمام الجميع لكى يكون عند الباقين خوف » (١تى ٥ : ٢٠) فهؤلاء هم الذين خطيتهم معروفة للكل ، وأصبح الأمر يتعلق بسلامة الكنيسة كلها وحفظ قيمها وروحياتها ... وصار الهدف هو « لكى يكون عند الباقين خوف » ... مثال ذلك أناس وقفوا فى وسط الكنيسة يحدثون ضوضاء وهياجاً ويتكلمون بما لا يليق ، بغير مبالاة ، فهؤلاء يحتاجون إلى توبيخ عام ، وليس فيما بينك وبينهم .",{"h":"٦ ـ النقد"},"قد يكون عمل الإنسان أنه ناقد فى أية صحيفة من الصحف : ناقد روائى ، أو ناقد أدبى ، أو ناقد مسرحى ، أو ناقد رياضى ...",{"h":"فهل يترك عمله كناقد على اعتبار أنه يوقعه فى الإدانة ؟ وما الفرق بين النقد والإدانة ؟"},"كلا ، لا يترك عمله . إنما يسلك فيه بطريقة سليمة وبأسلوب روحى ، مبنية على أسس علمية . ولا يكون أسلوبه هو الهدم والتجريح . وهناك فروق بين النقد والإدانة .",{"h":"الفرق الأساسى بين النقد والإدانة ، هو أن النقد يلتزم الموضوعية . أما الإدانة فكثيراً ما تمس النواحى الشخصية ."},"النقد يتناول الموضوع ويحلله ، ويقوم بعملية تقييم عادلة ، يذكر ما فيه من المحاسن ومن العيوب على السواء . وقد يذكر أسباب النجاح وأسباب الفشل فى كل النواحى . وإن كانت هناك مساوىء ، يقترح الوضع السليم الذى كان يجب اتباعه .",{"h":"إذن النقد هو عملية تقييم . وكثيراً ما يلزم التقييم فى كل حياتنا الإجتماعية والكنسية ، بل وفى كل أنشطتنا ."}],"24":["والهدف من هذا التقييم هو الوصول إلى الأفضل ، باجتناب العيوب ، وتحسين مستوى النجاح ورفع درجته . ولذلك كثيراً ما يجلس الإنسان لتقييم أعماله . ويعرف هذا باسم (النقد الذاتى) ، ويُعرف فى الروحيات باسم (محاسبة النفس) .","والنقد علم ، له قواعده وأصوله وأسلوبه . بل له حدوده أيضاً التى لا يتعداها ، والتى إن خرج عنها لا يكون نقداً ، أو لا يكون نقداً سليماً .",{"h":"والنقد الذى لا يذكر سوى المساوىء ، هو لون من الهجوم . ولا يكون صاحبه منصفاً ."},"لذلك هناك أنواع ودرجات من النقد ، منها النقد الهادىء الرزين ذو الأسلوب العفّ . وهو النقد السليم المقبول . ومنها النقد اللاذع ، والنقد الجارح . وكل ناقد يختلف فى أسلوبه عن الآخر ، ويختلف فى اختيار الألفاظ التى يستخدمها ... والناقد المنصف يتخير الألفاظ كما بميزان دقيق جداً . فإن كنت ناقداً ، انظر من أى نوع أنت ... ؟",{"h":"كن موضوعياً ومنصفاً ، ولا تكن قاسياً فى نقدك ."},"ربما ناقد أدبى أو علمى ينقد كتاباً ، فيكون نقده تكملة لازمة لهذا الكتاب ، تحتاج إليها معلوماته . وربما ناقد ينقد كتاباً ، فيكون نقده مديحاً خالصاً ، إن كان الكتاب يستحق ذلك .",{"h":"كذلك النقد يحتاج إلى دراسة واعية ."},"يحتاج إلى معرفة واسعة جداً بالموضوع الذى ينقده ، كما يحتاج إلى معرفة بفن النقد وأصوله وليس كل إنسان يرقى إلى مرتبة الناقد ، أو يدعى لنفسه هذه الصفة . وليس كل ناقد يحترمه المجتمع ويثق به كناقد ...",{"h":"والناقد المنصف يستفيد من نقده القراء ، ويستفيد الشخص صاحب موضوع النقد . ويكون نقده للبنيان ، مقدماً فيه علماً وأدباً وفناً ..."},"يقول الرب فى سفر اشعياء النبى « ويل للقائلين للشر خيراً ، وللخير شراً . الجاعلين الظلام نوراً ، والنور ظلاماً . الجاعلين المر حلواً ، والحلو مراً » (أش ٥ : ٢٠) ."],"25":[{"h":"هل إذا طلبت فى مجال الشهادة فى محكمة : اتراك تستطيع أن تقع فى شهادة زور لكى تبرىء مذنباً ؟!"},"وهل إذا قلت الحق ، اتراك تقع فى خطية إدانة ؟! حاشا . بل أنك بتبرئة المذنب تقع فى خطية كذب . كذلك فى معاملاتك الخاصة .","إن لم تستطع أن تقول الحق ، فعلى الأقل اصمت ، فهذا أفضل من تبرئة المذنب ، تبرئة تخدع بها السامعين .","لعل من أبرز أنواع الإدانة غير الخاطئة :",{"h":"٧ ـ إدانة النفس"},"إنها فضيلة ، توصل إلى الاتضاع ، وإلى التوبة والنقاوة ، وإلى امتصاص الرغبة فى الإدانة بطريقة سليمة . وقد قال القديس مكاريوس الكبير « احكم يا أخى على نفسك قبل أن يحكموا عليك » .","قال القديس الأنبا أنطونيوس « إن دنا أنفسنا ، رضى الديان عنا » . كذلك إن الذى يدين نفسه ، ويوبخ ذاتها لكى يقومها ، هذا لا يجد دافعاً داخلياً لإدانة غيره ، لأنه يشعر أنه مخطىء مثل ذلك وربما أكثر .",{"h":"وإدانة النفس ، تحمى الإنسان من إدانته لغيره ."},"قال القديس الأنبا موسى عن انشغال الإنسان بخطاياه ، إنشغالاً لا يسمح له أن يتفرغ للحديث عن خطايا غيره :",{"h":"من من الناس يكون عنده ميت فلا يبكى عليه ، وإنما يتركه ليبكى على ميت عند جيرانه ؟!"},"نحب فى موضوع الإدانة أن نورد ملاحظة أخيرة وهى :"],"26":[{"h":"من يبرىء المذنب"},"يحدث عند البعض أحياناً ، أنهم يبرئون كل أحد ـ مهما كان مخطئاً ـ حتى لا يقعوا فى خطية الإدانة . وأمثال هؤلاء ، عليهم أن يسمعوا قول الكتاب :",{"h":"« مبرىء المذنب ، ومذنب البرىء ، كلاهما مكرهة الرب » (أم ١٧ : ١٥) ."},"ذلك لأن كليهما بعيد عن الحق ، ويتكلم بالباطل . ونلاحظ هنا أنه وضع عبارة (مبرىء المذنب) أولاً .","فلا تظن أنك تكون ذا قلب شفوق إن كنت تبرّىء المذنب . فالذنب هو ذنب . والخطأ هو خطأ . قد تدافع عن المذنب من حيث أنه فعل الذنب عن جهل ، أو عن ضعف ، أو عن خوف ، أو بسبب ظروف ضاغطة تخفف بهذا من ذنبه . ولكن لا تستطيع أن تبرئه ، أو تدعى أنه لم يخطىء ... !",{"h":"بل يحدث أحياناً أن مبرىء المذنب يثير السامعين ."},"ويجعلهم يدينونه هو فى دفاعه عن الباطل ، ويدينون المذنب بأكثر شدة حتى يوازنوا مع ما قيل فى تبرئته . وهكذا تأتى هذه التبرئة بعكس المقصود منها .",{"h":"كما أن تبرئة المذنب تساعد على الاستهتار ."},"سواء من جهة هذا المذنب ، الذى لا يشعر بتأنيب الضمير بسبب محاولة تبرئته ، فيستمر فى أخطائه ، أو من جهة استهتار من يقلدونه ، شاعرين أنهم سيجدون من يعمل على تبرئتهم .","وقد سئل القديس باسيليوس الكبير هذا السؤال .",{"h":"ما هى دينونة الذين يحامون عن المخطىء ويدافعون عنه ؟"},"قال أظن أنها دينونة ثقيلة ، أكثر من دينونة الذى يعثر غيره ، كما وردت فى الإنجيل (متى ١٨ : ٢٩ ، ٣٠) ."],"27":[{"h":"لأن الذى يدافع عن المخطىء ، يمنع المخطىء من أن يتوب ."},"ويجعله بهذا يستمر فى خطيته ، ويعلّم غيره شرّه .","وهذا حق ، لأنه إن كان هذا الذى يدافع يقول : ماذا فعل (فلان) ؟ لا يوجد خطأ فى كل ما فعله ... فهو بهذا الكلام يشجع غيره أن يفعل مثله مادام الفعل غير مدان .","هنا ويواجهنا سؤال لابد من الإجابة عليه ، وهو :",{"h":"لماذا إذن ينصحنا القديسون أن ندافع عن المخطئين ؟"},"للإجابة على هذا السؤال ينبغى أن نعرف تماماً ما هى نوعية الدفاع ؟ ليس معنى الدفاع أن نقلب الموازين الروحية ، ونقول عن الخطأ إنه صواب . كلا بلاشك . فقد قال الكتاب : ويل لمن يقول عن المرّ أنه حلو (أش ٥ : ٢٠) .",{"h":"وإنما الدفاع هنا ينصب على الظروف المحيطة ، وليس على كنه العمل ذاته ."},"كأن ندافع بسبب أن الحرب كانت ثقيلة عليهم ، مع ضعف الطبيعة البشرية ، كما نقول فى أوشية الراقدين « إذ لبسوا جسداً ، وسكنوا فى هذا العالم » وإنه « ليس أحد بلا خطية ، وإن كانت حياته يوماً واحداً على الأرض » أو نعتذر عنهم بمكر الشيطان المحارب وخديعته وكثرة حيله .",{"h":"أو ندافع بأنهم فعلوا ذلك جهلاً ...."},"كما قال السيد المسيح عن صالبيه « لأنهم لا يدرون ماذا يفعلون » (لو ٢٣ : ٣٤) . وقال القديس بولس الرسول « لأنهم لو عرفوا ، لما صلبوا رب المجد » (١كو ٢ : ٨) .","أو نقول إنه كان فى حالة إثارة ، بحيث لم يستطع أن يملك نفسه ، أو كان واقعاً تحت إغراء أو ضغوط أو عثرة ...","ولكن لا يمكننا أن ننفى الخطأ ، أو ندعى أنه ليس خطأ . بل نحدث فقط عن"],"28":["الظروف المحيطة . تماماً كالمحامى الذى ينفى التهمة ، أو الركن المادى منها ، ويتحدث فقط عن الركن الأدبى أو الحالة النفسية أو العقلية للمتهم .","ولا يكون القصد سوى التخفيف من وقع الخطأ بدافع الرحمة ، وليس انكار وجود الخطأ ، كأن يقول إنسان مثلاً « كلنا تحت الزلل » أو « كلنا معرضون للخطأ » . أو كما دافع بعضهم عن خطأ نُسب إلى شخص كبير ، فقال : هذه هى الطبيعة البشرية . والكتاب يحكى عن نبى عظيم جداً مثل إيليا فيقول :",{"h":"« إيليا كان إنساناً تحت الآلام مثلنا » (يع ٥ : ١٧) ."},"مع إنه صلى صلاة أن لا تمطر السماء ثلاث سنين وستة أشهر فلم تمطر ، ثم صلى بعدها فأعطت السماء مطراً (يع ٥ : ١٧ ، ١٨) .",{"h":"ويقع فى محاولة تبرئة المذنب من يتملق الكبار !"},"محاولاً أن يبرىء أخطاءهم مهما كانت جسيمة ، بأسلوب بعيد عن الحق . وبسبب هذا التملق ، يسقط كثير من الكبار فى أخطاء ويستمرون فيها ، ولا تبكتهم ضمائرهم ، بل قد يفتخرون بما وقعوا فيه من أخطاء !! ويدفعهم من يبرئهم إلى العزة بالإثم وإلى سياسات خاطئة ، ويشترك معهم فى أعمالهم الشريرة .","إن كان الذين يصمتون على الخطأ ، ولا يخرجون الخبيث من وسطهم ، يدانون كما دان بولس الرسول أهل كورنثوس . فماذا نقول إذن عن الذين يحامون عن الخطأ ويدافعون عنه ويبررونه ؟ لاشك أن هؤلاء دينونتهم أعظم ."],"29":[{"h":"شروط الإدانة غير الخاطئة"},{"h":"١ ـ أن تصدر من شخص مسئول :"},"وقد شرحنا هذا الأمر من قبل . ويبقى أمامك فى كل مرة تدين فيها غيرك : أن تسأل نفسك قائلاً « من أقامنى قاضياً » (لو ١٢ : ١٤) أو من أقامنى معلماً ؟ فإن وجدت أنك فى موضع المسئولية فعلاً ، فلا مانع ...",{"h":"٢ ـ الإدانة تقوم على أساس من المعرفة :"},"إن الله هو « ديان الأرض كلها » (تك ١٨ : ٢٥) ، لأنه بالإضافة إلى سلطانه الإلهى ، يوجد عدل فى دينونته لأنها قائمة على أساس من المعرفة الشاملة الأكيدة ، فهو العارف بكل شىء ، وهو الفاحص القلوب ، والقارىء الأفكار ، ويعلم ما يجول فى مشاعر الإنسان ونياته ، ويعرف الخفيات والظاهرات .",{"h":"وقضاة الأرض يبنون عدلهم فى أحكامهم على أساس من التحقيقات ،"},"توصلهم إلى ما يمكن الوصول إليه من المعرفة : تحقيقات فى مراكز الشرطة والنيابة والمحكمة ، مع فحص الأدلة ، وسماع الشهود ومناقشتهم ، وإعطاء فرصة كاملة للدفاع وللرد على أدلة الأتهام .",{"h":"أما أنت ، فما هى معرفتك حتى تحكم ؟!"},"ألا يحدث أن يدين الإنسان غيره عن طريق السماع والشائعات أحياناً ، وعن طريق الظن فى أحيان أخرى ، وبدون سماع دفاعه عن نفسه فى كل الحالات تقريباً !! ودون معرفة بظروفه ، وقصده ، وأسباب ما حدث منه ...",{"h":"وربما لو اتيح لنا أن نعرف الحقيقة كاملة ، لندمنا على أحكامنا واعتذرنا عنها !"}],"30":["من أجل هذا لا يجوز لك أن تدين إنساناً فى تصرف ما ، بدون أن تبحث وتفحص وتحقق وتعطيه فرصة أن يجيب عن نفسه . وليس من اللائق أن تلقى أحكامك بسرعة ، وتحكم على شخص قبل أن يحكم الله عليه ... وما أصدق قول الرسول :",{"h":"« لا تحكموا فى شىء قبل الوقت » (١كو ٤ : ٥) ."},"ويتابع الرسول كلامه فيقول « حتى يأتى الرب الذى سينير خفايا الظلام ، ويظهر آراء القلوب . وحينئذ يكون المدح لكل واحد من الله » .",{"h":"لا تحكموا قبل الوقت"},"قال القديس أوغسطينوس فى تفسير هذه الآية (١كو ٤ : ٥) :","هناك خطايا واضحة قال عنها الرسول « خطايا بعض الناس واضحة تتقدم إلى القضاء » (١تى ٥ : ٢٤) . هذه الخطايا الواضحة إذا صدر عنها حكم ، لا يكون حكماً متسرعاً . ولكن هناك أموراً أخرى غير واضحة ، سيعلنها الله حينما يكشف ما فى القلوب وينير خفايا الظلام (١كو ٤ : ٥) . عن هذه الأمور قال الكتاب « لا تحكموا قبل الوقت » .","لأن تصرفاً معيناً قد يبدو لنا أنه خطأ . ولكن حينما يكشف الله نيات القلوب يظهر أنه تصرف سليم . والعكس صحيح : تصرف يبدو سليماً ، وحينما يكشف الله نيات القلوب يظهر أنه خطأ . فلا تحكموا إذن قبل الوقت فى هذه الأمور التى نيتها غير واضحة ، والتى ستبقى مخفاه ، إلى أن يعلنها الله .",{"h":"إذن حكمنا هو فى الأمور الواضحة . أما غير الواضحة فنتركها لله ، إلى أن يعلنها ."},{"h":"٣ ـ لا يجوز أن تحكم على أحد وأنت مثله ، أو أسوأ :"},"وهذا واضح من قول السيد المسيح للذين طلبوا رجم المرأة المضبوطة فى ذات الفعل . فمع أن الخطيئة كانت واضحة وفاضحة وثابتة ، إلا أنه قال لهم « من كان منكم"],"31":["بلا خطية ، فليرمها أولاً بحجر » (يو ٨ : ٧) . فانصرفوا جميعاً وتركوها لأن الكل خطاة . والمثل يقول « من كان بيته من زجاج ، لا يقذف الناس بالحجارة » .",{"h":"لذلك فالإنسان المتواضع لا يدين أحداً ..."},"إنه ينصت فى انسحاق قلب إلى قول السيد المسيح « لماذا تنظر القذى الذى فى عين أخيك . وأما الخشبة التى فى عينك فلا تفطن لها ؟! ... يا مرائى اخرج أولاً الخشبة من عينك . وحينئذ تبصر جيداً أن تخرج القذى من عين أخيك » (متى ٧ : ٣ ـ ٥) .",{"h":"والمتضع إذا اضطر أن يدين ، يفعل ذلك باتضاع ."},"لا بعجرفة ، ولا بكبرياء ، ولا باحتقار وازدراء لغيره . ويكون موضوعياً ، فلا يجرح أحساس غيره ولا يخجله . وكما قال الرسول « أيها الأخوة إن إنسبق إنسان ، فأخذ فى زلة ، فاصلحوا أنتم الروحانيين مثل هذا بروح الوداعة ، ناظراً إلى نفسك لئلا تجرب أنت أيضاً . احملوا بعضكم أثقال بعض » (غل ٦ : ١ ، ٢) .",{"h":"٤ ـ لا تكون الإدانة بحقد ولا بغيظ ولا بكراهية :"},"حتى إن كان الذى يدين ، يفعل ذلك بسلطان وعن معرفة ، إلا أن ادانته إذا ما اختلطت بالكراهية والحقد تصبح إدانة خاطئة . لأن « المحبة لا تفرح بالإثم ، بل تفرح بالحق » (١كو ١٣ : ٦) .",{"h":"الحكم بالحق"},"سئل القديس باسيليوس الكبير عن معنى قول الرب « لا تدينوا لكى لا تدانوا » (متى ٧ : ١) ، فأجاب : قال الرب فى موضع آخر :",{"h":"« لا تنظر إلى الوجوه ... العدل العدل تتبع لكى تحيا » (تث ١٦ : ١٩ ، ٢٠) ."},"« لا تنظر إلى الوجوه » أو « لا تأخذ بالوجوه » معناها « لا تحابِ » . إياك والمحاباة ، بل أحكم بالعدل والحق . وهنا قال القديس :"],"32":["إن الله لم يمنعنا عن الإدانة جملةً ، بل أمرنا أن ندين بالحق ، فى الوقت المناسب وعن عمل دون عمل .","فالأشياء التى لم يحدّ الكتاب لها حداً ، بل وضعها تحت سلطان الإنسان مثل الأكل والشرب وغير ذلك ، قال الرسول فيها « لماذا تدين أخاك ... ؟ » (رو ١٤ : ١٠) وأيضاً « لا نحاكم بعضنا بعضاً » (رو ١٤ : ١٣) .",{"h":"« أما الأمور التى لا ترضى الله ... فقد لام الذين لا يدينون عليها »"},"يقصد لام المجموعة كلها The whole community ، لأنه كان ينبغى عليها أن تدين الشخص المخطىء . وذكرهم بقول الكتاب « اعزلوا الخبيث من وسطكم » (١كو ٥ : ١٣) . فربما من أجل خطية إنسان واحد ، يحل غضب الله على المجموعة كلها .",{"h":"والمجموعة مسئولة عن أن تنظف نفسها ، وتعزل الخبيث من وسطها ، لئلا يحل غضب الله على الكل بسبب خطية واحد ."},"لقد كادت السفينة كلها أن تغرق بسبب خطية واحد هو يونان ، بينما باقى ركابها ما كان لهم ذنب . وأيام يشوع بن يونان ، غضب الله على المجموعة كلها بسبب خطية واحد هو عخان بن كرمى (يش ٧) .","فمن الحق أن تدين الشر الذى فيها ، وتخرجه خارجاً ، لئلا تهلك كلها بسببه .",{"h":"ولكن هذه الخطوة تحتاج إلى حكمة ."},"قال القديس باسيليوس إن هناك بعض الأمور التى ينطبق عليها قول الكتاب :",{"h":"غيرة بيتك أكلتنى ، لأن اعداءك نسوا وصاياك » (مز ١١٩) ."},"إنها غيرة لله . ولابد للإنسان أن يفرق بين ما إذا كان الدافع للإدانة هو الغيرة المقدسة ، أم أن الدافع هو حقد شخصى ، أو كراهية شخصية ، أو شماتة بإنسان مخطىء . فإن كانت هى الغيرة المقدسة ـ وليس تكون الإدانة مقبولة ـ ولكن ...",{"h":"هذه الغيرة ينبغى أن تكون حسب المعرفة (رو ١٠ : ٢) ."}],"33":[{"h":"الفصل الثانى"},{"h":"أنواع إدانة الآخرين"},"الإدانة بالفكر","الإدانة باللسان","الاغتياب","النميمة","الإدانة","التشهير","الإدانة بالمطبوعات والتسجيلات الصوتية","الإدانة بالسماع","كلام يسهل الإدانة","أنواع أخرى من الإدانة"],"34":["إدانة الآخرين ليس لها أسلوب واحد ، ولا تكون بالكلام وباللسان فقط ، إنما قد تبدأ أولاً بالفكر ، أو تحدث عن طريق السماع . أو قد تكون مجرد شعور فى القلب ، يتطور من حال إلى حال . وربما تصدر عن طريق الملامح والحركات .","وقد تحدث الإدانة بطريق غير مباشر ، وقد تأخذ صوراً مختلفة ، وتصل إلى درجات خطيرة ، كلما ارتبطت بمشاعر أخرى .","وسنحاول أن نتناول كل هذه الأنواع والدرجات بالتفصيل ..",{"h":"الإدانة بالفكر"},"الإدانة بالفكر ، ربما تكون أخف ألوان الإدانة ، لأنها قاصرة على الشخص الذى يدين ، ولم تنتشر فى الخارج .","ولكن خطورتها أنها نقطة البدء ، وانها المصدر لكل الأنواع الأخرى من الإدانة . لذلك يجب الانتصار عليها قبل أن تتطور ، وقبل أن تسىء إلى آخرين ، وتنتقل من درجة إلى أخرى .",{"h":"على أن الإدانة بالفكر قد تكون أولاً مجرد حرب روحية ."},"وقد ينتصر عليها الإنسان ويطردها من ذهنه ، قبل أن تصبح خطية . أما إذا ترك فكر الإدانة داخله ، وبدأ يقتنع به ، ثم خلطه أيضاً بمشاعره ، فحينئذ لا تكون الإدانة مجرد حرب ، لأنها لاقت قبولاً فى الداخل .",{"h":"وقد لا يكتفى الإنسان بالرضى بفكر الإدانة ، وإنما يضيف عليه تصورات وتخيلات من عنده ، لتكبيره وتجسيمه ."}],"35":["ويحدث هذا كثيراً ، إن كان لا يحب الشخص الذى يدينه ، أو إن كان يكرهه أو يحقد عليه ... وحينئذ لا يكتفى بأن يجعل فكر الإدانة يستقر ويستمر ... ولا يكتفى بالتفكير فى أخطاء الشخص التى أمامه ، إنما يخترع فى ذهنه قصصاً يمكن أن تحدث مع هذا الإنسان : كأن يقع فى أخطاء أخرى ، وينكشف فيها أمام الناس ، أو أن يضبطوه فى كذا وكذا ، وينفضح ، أو يُحاكم .",{"h":"وهكذا يكون الفكر مجرد شاشة يعرض عليها القلب ما فى داخله من مشاعر خاطئة وتصورات بشعة ."},"المفروض أن توقف فكر الإدانة بمجرد أن يخطر على ذهنك . ولكنك إن وصلت إلى هذا الحد ، فإن الأمر معك لا يقتصر على علاج الإدانة ، وإنما بالأكثر معالجة أسبابها ، والتخلص مما فى القلب من مشاعر خاطئة ...",{"h":"والإدانة بالفكر تتبادل الموقع مع الإدانة بالقلب :"},"فالفكر حينما يدين إنساناً ، يوصل مشاعر خاصة بهذه الإدانة إلى القلب . والقلب إذا وجدت فيه أمثال هذه المشاعر ، يصدر أفكاراً إلى العقل . وهكذا يغذى كل منهما الآخر .",{"h":"الإدانة باللسان"},{"h":"خطورتها أن الإدانة تخرج من فكر أو لسان صاحبها ، لكى تصب فى آذان وأفكار ومشاعر آخرين ."},"إن الإنسان الذى يدين بالفكر ، إن تاب عن خطيته ينتهى الأمر عند هذا الحد . أما الذى يدين بلسانه ويسمعه غيره ويتأثر به ، فإن تاب لا تكون إدانته قد انتهت ، لأنها لا تزال موجودة فى فكر غيره وفى معرفته .","وما يدرينا إلى كم شخص قد وصل هذا الكلام .","على أن الإدانة باللسان ، هى أيضاً متعددة الأنواع ، منها :"],"36":[{"h":"الاغتياب"},"ومعناها أن إنساناً يتكلم بالسوء على غيره فى غيبته . وربما لا يجرؤ أن يقول شيئاً من هذا فى حضرته . وقد يحرص كل الحرص أن يظل كلامه مستوراً لا يصل إطلاقاً إلى هذا الشخص . ومن أمثلة (الغيبة) ما يقال عن الرؤساء والكبار . وعلى رأى المثل « الملك من هيبته ، يُشتم فى غيبته » ...",{"h":"ومن أضرار الاغتياب أن الشخص الذى يُساء إليه سراً ليست لديه الفرصة للدفاع عن نفسه ، لأنه لا يعرف !"},"فإن كان الذين يسمعون ، من النوع الذى يصدق كل ما يسمعه ، ففى هذه الحالة تسوء سمعته ، وهو لا يدرى ، ودون أن تكون أمامه لشرح الحقيقة ، وتوضيح الأمور وشرحها وتبرير ما يُنسب إليه .",{"h":"والغيبة تدل على أن صاحبها تنقصه الشجاعة والجرأة ..."},"بل قد تدل على أنه يتصف بالرياء والنفاق ، إن كان يقول كلاماً عكس هذا فى حضرة من يسىء إليه باغتيابه ...",{"h":"النميمة"},"وهى مسك سيرة الناس ، والتحدث عن اخطائهم ، أو نسبة أخطاء إليهم . والنميمة مرض منتشر بين الكثيرين . فإذ لا يجدون شيئاً نافعاً يتحدثون فيه ، يجعلون أخبار الناس مادة مفضلة لأحاديثهم ، وبخاصة ما تحمله هذه الأخبار من انتقادات وتحليل للمواقف ، وشرح الأخطاء والنقائص .",{"h":"ولذلك فمن ضمن أسباب النميمة الفراغ ."}],"37":["فالإنسان المشغول باستمرار ، لا يجد وقتاً يتحدث فيه عن أخبار الناس واخطائهم . والسيدة العاملة قد تكون أقل وقوعاً فى هذه الخطية من السيدات الجالسات فى البيوت ، ولا حديث لهن إلا عن أخبار الجيران . والتلميذ فى أيام الامتحانات ، وهو منشغل بدروسه ومراجعتها ، لا يجد وقتاً يجلس فيه مع زميل يتحدثان فى مساوىء الآخرين . وإذا فتح له هذا الموضوع لا يجد دافعاً داخلياً للاسترسال فيه ...",{"h":"لذلك اشغل نفسك ، حتى لا تقع فى الإدانة والنميمة ."},{"h":"وأيضاً من أسباب النميمة معاشرة النمامين ."},"لأنهم يفتحون لك أمثال هذه الموضوعات . وإن فتحتها أنت ، يشجعونك على الاسترسال فيها . ومع هؤلاء النمامين ، تشعر أن مسك سيرة الناس شىء عادى ، لا غرابة فيه . بل تشعر أنه مجال للتسلية ، وربما تجد فيه متعة إن كان مختلطاً بروح المرح ، فتستمر دون أن يستيقظ ضميرك ، ودون حرج ...",{"h":"الإدانة"},"ومعناها من جهة اللغة الحكم على الغير بأنه مذنب ...","ولكن الآباء فى بستان الرهبان يفرقون بين النميمة والإدانة ، فى أن النميمة قد تحمل الحديث عن خطأ معين قد حدث ، بينما الإدانة تحمل الحكم على أخطاء ثابتة فى الشخصية .",{"h":"وهناك يوجد فرق بين الإدانة الجزئية ، والإدانة الكلية ."},"فمثلاً يوجد فرق بين قولك إن فلاناً قد كذب ، فى موقف معين ، وبين قولك إنه شخص كذاب ، أى أن الكذب جزء من عناصر شخصيته . وبالمثل يوجد فرق بين قولك إنه قد جبن أو خاف فى إحدى المناسبات ، وبين قولك بصفة عامة إنه جبان ، أى أن الجبن من مكونات شخصيته ..."],"38":[{"h":"كذلك هناك فرق بين الإدانة الفردية والإدانة الجماعية ."},"فهناك إنسان قد يقع فى إدانة شخص ما ، وإنسان آخر قد يتطور به الأمر إلى إدانة مجموعة معينة ، أو مدينة بأسرها ، أو شعب كامل . وقد يدين البشرية فى نواح معينة .","مثال ذلك يقول لك : المدينة الفلانية تشتهر بالبخل ، أو الشعب الفلانى يتصف بالبرود ، أو الشعب الفلانى يتصف بالتهور . وهكذا يسم الشعب كله بصفة واحدة ..",{"h":"والمعروف أنه قد يوجد فى أسرة واحدة أخان أو شقيقان ، كل منهما له طبع مخالف للآخر ."},"قايين طبعه غير هابيل ، وهما شقيقان ، وكذلك طبع يعقوب يختلف عن طبع عيسو وهما توأمان . وبالمثل سليمان غير ابشالوم ، وهما شقيقان ... وهكذا فى الأسرة الواحدة طباع متنوعة . فلا نستطيع أن نحكم على طباع شخص بصفات أقربائه .","إن كان الأمر هكذا ، فما معنى الحكم على مدينة أو شعب بحكم واحد وربما يكون المقصود هو الصفة الغالبة . ومع ذلك فقد لا توجد هذه الصفة عند البعض .",{"h":"وقد يتأثر إنسان بحادث معين وقع له مع شخص ما ، لكى يصدر حكماً على هذا الشخص يشمل حياته وصفاته كلها ."},"بينما كل شخص قد تمر عليه فى حياته فترة ضعف ، أو فتور ، أو فترة يكون فيها تحت ضغطات معينة ، أو فى حالة نفسية مؤقتة نتيجة لأسباب خاصة ... ولا يمكن أن تعبر تصرفاته فى مثل هذه الفترة عن الصورة الثابتة لشخصيته ... ولكن ويل له من حكم من رآه فى تلك الفترة ، أو فى أحد مواقفها بالذات .",{"h":"ومن أمثلة الإدانة العامة : إدانة اليهود للأمم ."},"وإدانتهم أيضاً للسامريين ، وإدانتهم لكل من يتعامل مع هؤلاء وأولئك . وهكذا تعجبت المرأة السامرية من حديث السيد المسيح معها ، بينما « اليهود لا يعاملون السامريين » (يو ٤ : ٩) تعنى هنا الشعب كله ، وليس شخصاً واحداً بالذات . وهكذا نرى أن الإدانة تطورت إلى المقاطعة ، ولم تعد مجرد كلام إدانة ."],"39":[{"h":"ومن أمثلة الإدانة العامة أيضاً : إدانة الفريسيين للعشارين ."},"ربما كانت الصفة الغالبة فى العشارين هى الظلم ، ولكن ليس شرطاً أن يتصف بها كل عشار . فقد يوجد عشار تائب ... ونلاحظ من عمق إدانة الفريسيين للعشارين ، أن الفريسى وقف يدين العشار حتى أثناء صلاته . فأشار إلى العشار المنسحق القلب وقال « أشكرك يارب ، لأننى لست مثل سائر الناس الظالمين الخاطفين الزناة ، ولا مثل هذا العشار ... » (لو ١٨ : ١١) .","نوع آخر من أنواع الإدانة هو :",{"h":"التشهير"},{"h":"ومعناه أن يجعل أخطاءه مشهورة عند الآخرين ."},"والذى يقع فى التشهير ، لا يبالى بأن يحدث كل أحد عن أخطاء من يسىء إليه ، فينشر تلك الأخطاء ، أو ما يرى أنه أخطاء ، فى أوسع نطاق ممكن ، بلا حرص إطلاقاً على مشاعر وسمعة الشخص الذى يتحدث عنه ...",{"h":"وتزداد خطية التشهير بشاعة ، على قدر اتساعها وانتشارها ."},"ولا تقتصر على الأشخاص الذين يتحدث معهم هذا الذى يدين غيره ، وإنما تمتد أيضاً إلى الذين ينقل إليهم سامعوه نفس الكلام ونفس الإساءات ... وما أدرانا ربما كل منهم يضيف شيئاً من عنده ، من استنتاجاته أو مفهومه الخاص . ويصبح الأمر معروفاً لدى عدد كبير جداً يصعب إحصاؤه ...",{"h":"وربما المخطىء يتوب ، ولكن الشهرة الردية تظل تتبعه وتتعبه ."},"بل ربما هذه الشهرة الردية تكون عائقاً أمامه فى التوبة ... هذا إذا كان مخطئاً بالحقيقة ... لأنه فى أحيان كثيرة لا يكون التشهير مبنياً على أساس من الحق والصدق والعدل .",{"h":"ربما يبنى التشهير على شائعات أو إدعاءات ."}],"40":["وما أسهل أن يحدث هذا من جانب الحاقدين أو الحاسدين أو الظالمين أو أصحاب الأغراض ... !","إن آخاب الملك عندما أراد أن يستولى على حقل نابوت اليزرعيلى ، دبرت إيزابل زوجته مؤامرة للإيقاع بنابوت ، بأن يشاع عنه أنه جدف على الله ، وأرسلت رسائل إلى شيوخ وأشراف مدينته بذلك ، ونادوا بصوم ، واجلسوا نابوت فى رأس الشعب ، وشهروا به تشهيراً انتهى إلى رجمه ... وكان بريئاً ... (١مل ٢١) .","ولعل تشهيراً ظالماً مثل هذا حدث ليوسف الصديق ، انتهى إلى سجنه . بل أن تشهيراً ظالماً آخر أشاعه الكتبة والفريسيون ضد السيد المسيح نفسه ، انتهى إلى صلبه ...",{"h":"وإن كانت كل هذه الأمثلة ثبتت براءتها ، فإن تشهيرات أخرى قد لا تنال فرصة لإثبات براءتها ..."},"ومن خطية الإدانة بالتشهير ، ما يسمونه فى مواد القانون باسم « القذف العلنى » . وأحياناً لا يكون هذا التشهير باللسان ، وإنما عن طريق الصحافة مثلاً ، حيث تقوم حملة صحفية عنيفة ضد شخص ما ، أو ضد هيئة معينة ، أو بلد من البلاد ، وتؤدى هذه الحملة إلى سوء سمعة واسعة النطاق ، أو إلى فضيحة عالمية . وبعض هذه الحملات انتهت إلى سقوط رئيس دولة ، أو سقوط وزارة ، أو إقالة وزير ... فكم بالأُولى يكون تأثيرها على شخص لا يملك دفاعاً عن نفسه ؟","وهذا يقودنا إلى نوع آخر من الإدانة وهو :",{"h":"الإدانة بالمطبوعات والتسجيلات الصوتية"},{"h":"وهذه تكون أكثر خطراً ، لأنها أوسع انتشاراً ."},"فقد لا تكون الإدانة باللسان ، وإنما عن طريق منشور مطبوع تُوزع منه نسخ بعشرات الآلاف وتنتشر ، أو تكون عن طريق كتاب مطبوع أو نبذة . أو تكون هذه الإدانة فى"],"41":["مقال ينشر فى الصحف ويسىء إلى إنسان أو إلى مجموعة من الناس . أو صورة أُخذت بطريقة ما ، وتُطبع وتنشر بقصد الإساءة .","ويشبه هذا النوع ، خطابات يرسلها شخص إلى آخرين ، تحوى أخباراً فيها إساءة إلى إنسان ما ، وفيها إدانة له . والقصد بها هو التشهير .",{"h":"ويدخل فى الإدانة باللسان : التسجيلات الصوتية ."},"فهى لسان مستمر فى الكلام ، كلما شئنا له أن ينطق . وهذا النوع أكثر ثباتاً وأنتشاراً من كلمة يقولها شخص فى وقت ما ، دون تكرار لها . وهو أيضاً من الوثائق المحفوظة التى يمكن أستخدامها فى أى وقت ، ويمكن أن تطبع منها نسخ عديدة تساعد على أنتشار ما يراد سماعه .",{"h":"وتكون الإدانة باللسان صعبة ، إن صدرت من فم كاهن ."},"لأن الناس يميلون بطبيعتهم إلى تصديق الآباء الكهنة وعدم الشك فى أقوالهم . فيأخذون مثل هذه الإدانة كحكم كنسى ثابت . كما يصبح من الصعب على من أصابته هذه الإدانة أن يدافع عن نفسه ، ويشكك فى قول الكاهن .",{"h":"وصعوبتها أيضاً أن كل إنسان ينتظر من الكاهن أن يستر عليه ، لا أن يعلن أخطاءه .."},"ينتظر أن يسمع منه كلمة بركة لا كلمة دينونة ، كما قال السيد المسيح للمرأة الخاطئة « ولا أنا أدينك . اذهبى ولا تخطئى أيضاً » (يو ٨ : ١١) . وكما قال أيضاً :",{"h":"« لم آتِ لأدين العالم ، بل لأخلص العالم » (يو ١٢ : ٤٧) ."},"ولكن يستثنى من هذه القاعدة من جهة الرعاة والكهنة ، الإدانة اللازمة لسلام الكنيسة . كإدانة الهراطقة والمبتدعين ، والذين هم خطر على الجماعة . وكذلك الخارجين عن نظام الكنيسة . كما قال القديس بولس لتلميذه تيموثاوس الأسقف « الذين يخطئون ، وبخهم أمام الجميع ، لكى يكون عند الباقين خوف » (١تى ٥ : ٢٠) . ومن أجل حفظ النظام العام فى الكنيسة ، كانت إدانة بطرس الرسول لحنانيا وسفيرا (أع ٥) ."],"42":[{"h":"الإدانة بالسماع"},{"h":"يقول الآباء إن السامع شريك للمتكلم ، لأنه قد أعطاه فرصة ليتكلم ويقول ما عنده ."},"وقد نصح الآباء بعدم السماع . فقال القديس موسى « لا تمشِ مع النمام ... ولا تصدق كلام نميمة فى أى إنسان » .",{"h":"والسامع هنا يكسر وصية البعد عن المعثرات ."},"لأنه فى سماع كلام الإدانة أو النميمة عثرة . والمفروض أن تبتعد عن العثرات . فإن سمعت كلام أشخاص يمسكون سيرة الناس ، على الأقل تشوه سمعك وفكرك وقلبك . وإذا صدقت ما تسمعه ، بدون فحص ، فقد تتغير علاقتك بالآخرين . والسماع يولّد لك إدانة بالفكر ...","* وقال الأنبا موسى أيضاً :",{"h":"« أياك أن تسمع بسقطة أحد أخونك ، لئلا تكون قد دنته خفية »"},"هذا إذا صدقت ما سمعته عنه . أما إن لم تصدقه ، فعلى الأقل تكون قد دنت من يتكلم عنه . وفى كلا الموقفين تصير واقعاً فى الإدانة .","وربما الشخص الذى سمعت عنه سوءاً ، لا تدينه الآن ، وترفض قبول ما سمعته عنه . ولكن الأخبار والأفكار تتركز فى عقلك الباطن ، لكى تظهر بعد حين ...","* وقال القديس الأنبا إشعياء :","« إن سمعت أخاً يدين آخر ... فلا تستح منه أو توافقه ... لئلا يغضب الله .. بل قل باتضاع : اغفر لى يا أخى ، فإنى إنسان شقى ... وهذه الأمور التى تذكرها أنا منغمس فيها ، ولا احتمل ذكرها » ."],"43":["وطبعاً ليس المقصود أن تقول هذا الكلام حرفياً ، إنما :",{"h":"يكفى أن تهرب من السماع بأية وسيلة تناسبك ."},"يمكن أن تغير مجرى الحديث إلى موضوع آخر ، أو تسأل اسئلة تنقله إلى جهة أخرى ، أو أن تختم الكلام بعبارة « نصلى من أجله ومن أجل أنفسنا ، ليرحمنا الرب جميعاً » ...","أو أن تقول « هذه السقطات التى اسمع عنها تدل على أن الشيطان نشيط وقوى . حقاً ما أعجب حيل الشياطين .. » . وتحول الحديث إلى حيل الشياطين .","* قال الأنبا اشعياء أيضاً « لا تقبل أن تسمع عن خطايا أخيك أو أن تلومه » ...","* وهذه النصيحة نجدها أيضاً فى المزمور ٥١ .","حيث يقول « يارب من يسكن فى مسكنك ، أو من يصعد إلى جبل قدسك ، إلا السالك بلا عيب ، الفاعل البر ، الذى يتكلم بالحق فى قلبه ... ولا يصنع بقريبه سوءاً ، ولا يقبل عاراً على جيرانه » .","أى لا يقبل أن يسمع عنهم كلمة سوء . يرفض أن يسمع .","فالمفروض فيك إذن : أنك لا تتكلم بكلام نميمة أو إدانة ضد إنسان ، ولا تسمع مثل هذا الكلام .","* وهكذا يقول القديس مار أوغريس :",{"h":"الذى يسمع بالردىء ، شريك للذى يتكلم بالردىء . وهما متعاونان معاً فى إهلاك قلبيهما ..."},"ولعله يقصد الذى يكون راضياً بهذا السماع ، ومعطياً فرصة للمتكلم به أن يقول وأن يزيد . أما الرافض السماع ، فحتى إن كان موجوداً بجسده ، فإنه لا يحب أن يصغى بأذنيه ، ولا يعطى سمعه للكلام ، بل يشغل ذهنه بأمور أخرى . ولا يقبل ما يسمعه . ولا يعاود التفكير فيه ، ولا يعطيه عمقاً فى داخله .","* يكمل القديس مار أوغريس حديثه فيقول :"],"44":[{"h":"« فسد أذنيك الآن عن قول الذين يقعون فى غيرهم ، لئلا تأثم معهم وتعود ذاتك الأعراض الشريرة » ."},"« تأثم معهم » لأنك رضيت أن تجلس فى مجلس من هذا النوع ، ورضيت أن تضيع وقتك ، وتفقد نقاوة فكرك ، عن طريق هذا السماع . كما أنه لو استمر بك الأمر فى أمثال هذه المجالس ، سوف تتعود هذا الأسلوب من الأحاديث . وربما تتطور من السماع إلى الاشتراك فى الكلام .","* أما مار اسحق ، فإنه يشبه الإدانة بالنار ، ويقول :",{"h":"« اعلم أنه إن برزت منك نار واحرقت آخرين ، فإنه الله يطالبك بأنفس المحترقين » ."},"هذا إذا كنت أنت المتكلم . واستطعت أن تتلف بساطة الآخرين ونقاوتهم بما تقوله من كلام سىء عن أخوتهم . وهكذا تكون قد أعثرتهم ، يطالبك الله بأنفسهم ... ولكن ماذا إذا لم تكن أنت المتكلم بل السامع ؟ يقول مار اسحق :",{"h":"« وإن كنت باهذا ما ألقيت ناراً ، ولكن وافقت راميها ، وارضاك فعله ، فأنت تشترك معه فى الدينونة » ."},"وانصافاً للحق ، لعلنا هنا نقسم السامعين إلى أنواع :","أ ـ نوع يسمع الكلام الردىء وهو متضايق ، ويريد أن يبتعد ، ولكنه غير مستطيع خجلاً أو أدباً .","ب ـ نوع يسمع كلام الإدانة ، ويستطيع أن يهرب من الكلام وسماعه ، أو من المكان كله ...","ج ـ نوع يسمع ، وينصت جيداً ، ويناقش الكلام فى داخله بعقل وحكمة وفحص ، ويقبل ما يمكن قبوله ، ويرفض الباقى ، كمجرد أخبار ، دون أن يحكم فى داخله على أحد ، منتظراً مجالاً أوسع للفحص والتحقيق .","د ـ نوع يسمع كلام الإدانة ويقبله ويتأثر به ، ويتغير به فكره وقلبه ، ويظل صامتاً ."],"45":["هـ ـ نوع يسمع كلام الإدانة ، ويتجاوب معه بفكره ، ويشترك فيه . وهنا يخطىء بالسماع وبالكلام وبالفكر أيضاً .","و ـ وهناك نوع آخر أصعب من كل هؤلاء تحت عنوان",{"h":"كلام يسهل الإدانة"},"قد لا يتلفظ إنسان بكلمة إدانة . ولكنه يسأل اسئلة ، أو يقول كلاماً يسهل الإدانة ، عن قصد وعن رغبة .",{"h":"أى أنه لا يدين بلسانه ، ولكنه يفتح الباب للإدانة .."},"ربما يكون سمع بأن شخصاً ما قد وقع فى خطية معينة ، أو على وشك أن تدور حوله فضيحة ما ... فيسأل « أين فلان ؟ ما هى أخباره . لم أره من مدة ، وأحب أن أطمئن عليه » ... من يستطيع أن يقول أن هذه كلمات إدانة .. ولكن :",{"h":"المهم ليس فى الكلام الذى يقوله ، إنما فى الرد الذى يتوقعه ."},"لأن سامعه ما أن يتلقى هذا السؤال ، حتى يفتح ملف ذلك الشخص المراد أن يُساء إليه ، ويحكى حكايات كلها إدانة وسوء سمعه ، ويُخاض فى سيرة هذا الإنسان وفيما ينسب إليه من اتهامات ... ويكون صاحب السؤال هو السبب فى كل هذا ، يحمل مسئولية الإدانة ...",{"h":"وقد يتظاهر بالدفاع عنه ، بطريقة تعمق الإتهام وتوضحه :"},"فيقول مثلاً « من غير المعقول أن يحدث كل هذا من هذا الأخ . أنا لا استطيع مطلقاً أن أصدق » . وبهذا الكلام الذى يبدو فى ظاهره دفاعاً ، يفتح الباب أمام الأدلة والإثبات التى تؤكد كل ما ينسب إليه ... وتنتهى الجلسة بإدانة هذا الأخ إدانة تدعمها الأحداث والبراهين . وسبب كل هذا الاسئلة التى قدمها هذا الزميل فتح باب السيرة ، وفتح أبواباً للتفاصيل .",{"h":"وهكذا وقع فى خطية إدانة ، تصحبها غالباً رياء ..."}],"46":["فهو يتظاهر أمام الناس أنه لم يخطىء إلى ذلك الشخص ، بل كان يدافع عنه ، بينما كان قصده غير هذا ... وما أسهل أن يقول « من يستطيع أن يمسك علىّ خطأ قلته فى سمعة هذا الأخ ؟! .",{"h":"بالأضافة إلى خطية العثرة ، كان يخطىء ، ويحمّل غيره المسئولية"},"وما أسهل أن يذهب إلى أب اعترافه ويقول له « صدقنى يا أبى لم أقل كلمة إساءة واحدة . الإساءات صدرت ضده من فلان ، وأنا كنت أدافع وأقول إن ذلك الكلام غير معقول !",{"h":"ليس من الضرورة أن تكون خطية الإدانة مكشوفة ومباشرة ."},"من السهل أن يقع الإنسان فيها بطريقة غير مكشوفة ، وبطريقة غير مباشرة . بأن يشجع غيره على الخطأ ، أو يفتح له باب الخطأ . ويقف هو من بعيد يتفرج ويسمع ، بوجه كله (براءة) ، محتجاً على ما يقال احتجاجاً يساعد على المزيد ... إنه مجرد سأل سؤالاً ...",{"h":"وقد لا يكون السؤال عن شخص ، وإنما عن موضوع ."},"والكلام يجر بعضه بعضاً إلى أن يصل إلى الشخص . وهناك موضوعات من المعروف جيداً من هم الأشخاص المرتبطون بها ، والذين يحملون المسئولية .","من أجل هذا يقول الآباء القديسون :",{"h":"« لا تقل كلاماً يسهل اللائمة ... »"},"فإن كنت أنت حقاً شخصاً بعيداً عن الإدانة . فحتى إن فتح غيرك الموضوع ـ وليس أنت ـ ووجدت أن مجرى الحديث سينتهى إلى مسك سيرة إنسان ، حاول أن تغير مجراه إلى اتجاه آخر ."],"47":[{"h":"أنواع أخرى من الإدانة"},{"h":"قد تأتى الإدانة أحياناً عن طريق الإحراج وكشف الآخرين ."},"فربما لا تقول لإنسان إنه جاهل ، ولكنك توجه إليه بضعة اسئلة منتقاه ، تعرف مقدماً أنه لا يستطيع الإجابة عنها أو هى فوق مستواه . وبهذا تحرجه وتكشف جهله أمام الآخرين . ويكون قصدك هو هذا . وتكون قد وقعت فى خطية الإدانة ، دون أن تلفظ كلمة واحدة من كلمات الإدانة . ولكن الإدانة هى فى نيتك وفى قصدك ، وقد وصلت إليها بأسئلتك .",{"h":"كذلك قد تسأله عن بعض خصوصيات تحرجه وتدينه !"},"مثل : أين كنت فى اليوم الفلانى وفى اليوم الفلانى ؟ ومن الذى قابلته ؟ وماذا قلت له ؟ وماذا أعطاك ؟ وتبدو الأسئلة خالية من ألفاظ الإدانة . ولكن الإدانة كامنة فى أجابتها ، أو فيما تثيره هذه الأسئلة من شكوك فى أذهان الحاضرين ... إذ يقولون .. ولو فى ذهنهم ـ لابد أن فى الأمر شيئاً محرجاً ...",{"h":"وقد تكون الإدانة فى أسلوب الشكوى :"},"لأنه لا يوجد أحد يشكو إلا من أخطاء الغير إليه . فالشكوى تحمل أتهامه بهذا الخطأ . وكلما انتشرت هذه الشكوى أمام كثيرين ، تزداد سمعة الرجل سوءاً ، كإنسان يسىء إلى غيره أو يظلمه أو يهينه ...",{"h":"وقد تكون الإدانة عن طريق الملامح وليس اللسان ."},"مثال ذلك أن يسألك أحدهم عن شخص معين ، فتلوى شفتيك فى احتقار وازدراء ، أو تلوح بيدك بطريقة يفهم منها هذا المعنى ، أو تنظر نظرة خاصة ذات معنى ، أو تومىء بإيماءة لها نفس المعنى ... كل ذلك دون أن تنطق بكلمة إدانة واحدة . ولكن الملامح والإشارات تعبر تماماً عما تقصده ، دون أن تتكلم ."],"48":["والإدانة قد تصل إلى درجة التحقير والتعيير .","وهذا لون آخر من الإدانة ، ارتبطت به خطايا أخرى ، وأصبح له عمق خاصر يجعله أخطر من غيره من جهة المشاعر ...","إنه نوع يهين ويجرح ، ولا يبالى بإنسانية من يدينه !",{"h":"إن الذى يحتقر غيره ويزدريه لسقوطه ، هذا خطيته أصعب ممن يغتاب أو ينم أو يدين ."},"اعلم أن الشخص الذى تحتقره وتزدريه ، لسقوطه فى الخطية أو لضعفه ، أنت من نفس طبيعته القابلة للسقوط ، ويمكن أن تقع فيما وقع فيه ...","أتستطيع أن تدين شخصاً ، أغتصب اللصوص بيته وسرقوه ؟! أم أنت تشفق عليه ، تخاف لئلا يحدث لك مثل الذى حدث له ؟ هكذا الخاطىء هو فى وضع شبيه بهذا .",{"h":"قال القديس الأنبا إشعياء :"},"الذى يلوم أخاه ... أو يحتقره ... أو يشى به قدام آخرين ... هو إنسان قد صار بعيداً عن الرحمة ."],"49":[{"h":"الفصل الثالث"},{"h":"الإدانة خطية مركبة"},"إساءة إلى كثيرين :","١ ـ إساءة إلى الله","٢ ـ إساءة إلى الذى يدين","٣ ـ خطية ضد المُساء إليه","٤ ـ الإساءة إلى السامعين","٥ ـ إساءة إلى آخرين لا تعرفهم","الإدانة خطية مركبة :","١ ـ عدم المحبة","٢ ـ القسوة","٣ ـ الظلم","٤ ـ الكذب","٥ ـ عدم الاتضاع","٦ ـ اعثار الآخرين","٧ ـ الإهانة والتحقير","٨ ـ عدم اللياقة","٩ ـ الحكم على النيات","١٠ ـ الرياء"],"50":["كما تحدثنا عن الغضب (النرفزة) ، وقلنا إنه خطية مركبة ، كذلك نقول عن خطية إدانة الآخرين ، إنها غالباً ما تكون مجموعة خطايا مجتمعة ومركبة معاً تحت هذا الإسم . ونبدأ فنقول إنها :",{"h":"أساءة إلى كثيرين"},"فهى تحمل إساءة إلى الله ، وإلى الشخص الذى يدين غيره ، وإلى المُساء إليه ، وإلى السامع ، وإلى كل من تصلهم هذه الإدانة ولو بطريقة غير مباشرة ... فكيف ؟",{"h":"١ ـ إساءة إلى الله"},"الإدانة هى عمل من أعمال الله ، لأن الله هو الديان (مز ٥٠ : ٦) ، وهو « ديان الأرض كلها » (تك ١٨ : ٢٥) . وهو الوحيد الذى يستطيع أن يدين بعدل مطلق ، لأنه فاحص القلوب والأفكار ، ويعرف النيات والمقاصد ، كما يعرف الخفيات والظاهرات ، وعلى علم بكل الملابسات والظروف المحيطة . وهو يعرف كل هذا معرفة يقينية لاشك فيها .",{"h":"لذلك فالذى يدين غيره بغير حق ، إنما يأخذ حق الله واختصاصاته ، كما يمارس عملاً ليس فى حدود قدراته ."},"وهو بهذا يدين إنساناً قبل أن يدينه الله ، وقبل أن يأتى يوم الدينونة الرهيب ، فهو يحكم إذن قبل الوقت . كما أنه يدين عبداً لمولاه حق التصرف فيه . ومولاه هو الله .","يستثنى من هذا ، الذين منحهم الله حق الإدانة ، فقد قيل عن الحاكم مثلاً إنه « لا يحمل السيف عبثاً ، إذ هو خادم الله منتقم من الذى يفعل الشر » (رو ١٣ :"],"51":["٤) . وكذلك من اقيموا من الله للرعاية مثل الوالدين والآباء الروحيين ، وكل من هو فى مسئولية ..",{"h":"كذلك فإن الذى يقع فى خطية الإدانة ، إنما يكسر وصية الله الذى قال « لا تدينوا لكى لا تدانوا » (متى ٧ : ١) . فهو إذن يخالف الله ، ويكون بهذا قد أخطأ إليه ، بالعصيان . وبالاضافة إلى هذا فإن خطية الإدانة :"},{"h":"٢ ـ إساءة إلى الذى يدين"},{"h":"والذى يدين غيره ، ترتفع عنه النعمة والمعونة ، فيسقط ."},"وذلك لكى تسحق نفسه فى هذا السقوط ، فلا يعود ويدين غيره . ولكى يشعر أنه معرض أن يسقط فيما سقط فيه أخوه ، لولا أن النعمة تسنده . فبقاؤه قائماً فى الوقت الذى سقط فيه غيره ، ليس دليلاً على قوّته الذاتية ، إنما هو راجع إلى عمل النعمة . فلا يتكبر ويدين أخاه ، لكيلا ترتفع عنه النعمة فيسقط .","فإنه بهذه الإدانة يوقع نفسه فى الحكم ، إذ أن الرب قد قال « لا تدينوا لكى لا تدانوا . لأنه بالدينونة التى بها تدينون تدانون . وبالكيل الذى به تكيلون يكال لكم » (متى ٧ : ١ ، ٢) .",{"h":"إذن فالذى يدين غيره ، يعرض نفسه للدينونة ."},"وبنفس الكيل ، ليس أقل . بل ورد فى الإنجيل لعلمنا مرقس الرسول « يكال لكم ويزاد » (مر ٤ : ٢٤) . فالذى يقسو مثلاً فى إدانته لغيره ، إنما يعرض نفسه لنفس القسوة وأزيد . وقد يتعرض لهذا الحكم هنا على الأرض كما هناك فى السماء . مثال ذلك العبد الذى عامل بالقسوة رفيقه المدين له ، إذ قيل عنه فى الإنجيل « فدعاه حينئذ سيده وقال له : أيها العبد الشرير ، كل ذلك الدين تركته لك لأنك طلبت منى . أفما كان ينبغى أنك أيضاً ترحم العبد رفيقك كما رحمتك أنا . وغضب سيده وسلمه للمعذبين » (متى ١٨ : ٣٢ ـ ٣٤) .","قال أخ لشيخ « لماذا يا أبى شيطان الزنى يحاربنى بقسوة حتى أننى أسقط » . فأجابه الشيخ « ذلك لأنك تدين أخاك ، فتفارقك النعمة ، فتشعر بقسوة الحرب"],"52":["وتسقط » . ولعل الإنسان لأول وهلة يعجب قائلاً « وما علاقة الإدانة بالزنى ؟ » حقاً لا توجد علاقة مباشرة . ولكن هى هذه النتيجة : مفارقة النعمة لمن يدين غيره ...",{"h":"إذن لا تدن غيرك ، ليس لمجرد الشفقة عليه ، وإنما أيضاً إشفاقاً على نفسك ."},"إشفاقاً على نفسك من نتائج الإدانة بالنسبة إليك أنت . سواء تعرضك لتخلى النعمة هنا ، أو تعرضك للدينونة هناك ، أو مقاساتك من مرارة الخطية التى دنت أخاك عليها . كما حدث فى قصة ذلك الشيخ الذى قسا فى حكمة على شاب سقط فى الخطية ، فشككه حتى أخذ طريقه إلى العالم . وحينئذ سمح الله أن تقع نفس الحرب على هذا الشيخ ليقاسى فى شيخوخته ما لم يجربه فى شبابه .",{"h":"كذلك الذى يدين غيره ، قد يعامله الناس بالمثل ."},"كما قيل فى المثل « من غربل الناس نخلوه » . فكثيراً ما يحدث للذى يعيب غيره ، أن يُرد عليه بالمثل . وكما كشف ضعفات غيره ، يكشف هذا الغير ضعفاته مدافعاً بأن الكل تحت الضعف : الذى يدين كالذى يدان منه .",{"h":"إذن أنت إن دِنت غيرك ، تتعرض لكشف ضعفاتك ."},"إما أن يكشفها من تسىء إليه ، أو يكشفها أصدقاؤه واحباؤه وكل الدافعين عنه . أو تنكشف ضعفاتك بأى سبب ، بسماح من الله ، حتى لا تعود تجلس فى منصة القضاء تدين غيرك ، كأنك بلا عيب . انظر ماذا قال الرب للذين دانوا المرأة الخاطئة المضبوطة فى ذات الفعل .. قال لهم .",{"h":"« من كان منكم بلا خطية ، فليرمها أولاً بحجر » (يو ٨ : ٧) ."},"وورد فى معاملة الرب لأولئك القساة الديانين أنه « انحنى إلى أسفل ، وكان يكتب على الأرض » وقيل فى التفسير إنه كان يكتب لكل واحد منهم خطيته ، لذلك ورد بعدها « وأما هم فلما سمعوا ، وكانت ضمائرهم تبكتهم ، خرجوا واحداً فواحداً مبتدئين من الشيوخ إلى الآخرين » (يو ٨ : ٨ ، ٩) . لذلك لما سمعوا عبارة « من كان منكم بلا خطية فليقذفها أولاً بحجر » . وكأن الرب يقول لهم :"],"53":[{"h":"بدلاً من أن تنظروا إلى خطية المرأة ، انظروا إلى خطاياكم ."},"مع أن المرأة كانت خاطئة فعلاً ، وهم لم يظلموها ولم يدّعوا عليها إدعاءات باطلة لأنها « أمسكت فى الخطية » أُمسكت وهى تزنى فى ذات الفعل . ولكن السيد المسيح أراد لهؤلاء أن ينظروا إلى خطاياهم ، وليس إلى خطية غيرهم .",{"h":"الله هو وحده الديان ، أيضاً لأنه هو وحده القدوس (رؤ ١٥ : ٤) ."},"أما باقى البشر ، فينطبق عليهم المثل القائل « من كان بيته من زجاج ، فلا يقذف الناس بالحجارة » . ليتك تذكر نفسك بهذا المثل ، حتى لا يتهشم بيتك ...",{"h":"ارحم إذن مادمت محتاجاً إلى الرحمة ."},{"h":"واستر على غيرك ، مادمت محتاجاً إلى الستر ."},"وبالكيل الذى تريد أن يكال به لك ، يمكنك أن تكيل لغيرك . أتريد ستراً ، إذن استر . أتريد أن خطاياك تظل مخفاة لا يعرف بها أحد ، إذن اعمل المثل ، واترك خطايا غيرك مستورة لا يعلم بها أحد ...",{"h":"٣ ـ خطية ضد المُساء إليه"},"إنها إساءة لسمعته التى تلوكها الألسن وتصبح مضغة فى الأفواه . وهى حط لكرامته ، بينما يقول الكتاب « مقدمين بعضكم بعضاً فى الكرامة » (رو ١٢ : ١٠) .",{"h":"وفيها الحديث عن أخطائه ، دون إعطائه فرصة للدفاع عن نفسه ."},"أو لتوضيح موقفه ، أو لشرح الأسباب التى دعته إلى التصرف هكذا ... وربما يكون كل ما يقال عنه شائعات لا صحة لها ...",{"h":"وبفرض أنه أخطأ ، لماذا لا تستر عليه ؟"},"وقد قيل عن القديس مقاريوس الكبير أنه صار كملاك على الأرض ، لأنه كان يستر خطايا الآخرين ، ولا يذيع أخطاءهم فتفضح أمام الناس . فإن كنت أنت لم"],"54":["تستطع أن تستر على غيرك وتخفى فضائحه . فعلى الأقل لا تكن سبباً لنشرها بالأكثر فى محيط أوسع ، بالحديث عنها والحوار فيها ...",{"h":"كذلك بنشرك لخطايا الغير ، إنما تعرقل طريق توبته ..."},"فالإنسان الذى لم ينفضح أمره ، يمكنه أن يتوب إذا أراد ، بعكس الذى تلاحقه سمعته وأخطاؤه حيثما تذهب ... قد يجد صعوبة فى أن يغير مسلكه ! وفى أن يصير إنساناً جديداً .",{"h":"وربما الحديث عن خطايا غيره يفقده ثقة الناس فيه ..."},"وهكذا لا يستطيع أن يستعيد مكانته فى المجتمع ، ولا أن يكوّن علاقات طيبة مع الشرفاء والخيرين ، ويصبح التعامل معه موضع شك بسبب ما قيل عنه ...","وعلى رأى القديس يوحنا ذهبى الفم :",{"h":"« إن كنت لا تستطيع أن تسد فم من يتكلم على أخيه بالسوء ، فعلى الأقل لا تتكلم أنت ."},"وأنت فى خطية الإدانة لا تسىء فقط إلى الله وإلى نفسك وإلى المُساء إليه ، وإنما أنت أيضاً تتسبب فى :",{"h":"٤ ـ الإساءة إلى السامعين"},"ما ذنب السامع إن كنت تسبب له عثرة ؟","وأنت تعرف ما قاله الرب عن صانعى العثرات : « ويل لمن تأتى بواسطته العثرات . خير له لو طوق عنقه بحجر رحى وطرح فى البحر ، من أن يعثر أحد هؤلاء الصغار » (لو ١٧ : ١ ، ٢) .",{"h":"ماذنب السامع فى أن تفقده بساطته وتسبب له أفكاراً ؟!"},"وهكذا تغير صورة الآخرين فى ذهنه . وقد تثبت عنده هذه الفكرة التى غرستها فيه من جهة الغير ، وقد تؤثر على علاقته به ومعاملته له ، دون أن يدرى ذاك سبباً"],"55":["لكل هذا !! لماذا هذا الإتلاف ؟!","ولهذا قال الآباء : إن الذى يتكلم بالسوء على غيره ، يهلك أنفس سامعيه ، ونفسه أيضاً لا تفلت ...","وربما ـ دون أن تدرى ـ تحمل إدانتك لغيرك إساءة أخرى .",{"h":"٥ ـ إساءة إلى آخرين لا تعرفهم"},"فكلام الإدانة الذى قلته ، ربما لا يصل إلى سامعيك فقط ، وإنما قد تتناقله الألسن فينتشر وسط كثيرين لا تعرفهم ، وهؤلاء أيضاً بالمثل : تسبب لهم عثرة ، وتفقدهم بساطتهم ، وتتغير علاقاتهم مع المُساء إليه ... وتتسع الدائرة ...",{"h":"إن كلمة الإدانة التى تقولها ليست عاقراً ، فقد تلد بنين وبنات ، وقد ينتشر نسلها فى أماكن متعددة ، وقد يأتى بنسل آخر من استنتاجات وأقاويل وإضافات وفهم خاطىء ."},{"h":"وقد لا تلد كلاماً فقط ، وإنما أيضاً مشاعر وخلافات ."},"وأنت فى كل ذلك ، تحاول أن تحصر نطاق خطيتك فلا تستطيع ، وتحاول أن تحصى عدد الذين أعثرتهم فلا تقدر ... إنهم إسماء تعرفها ، واسماء لا تعرفها ...",{"h":"وإدانتك لغيرك قد تلد عند البعض إدانة لك ."},"لماذا يتكلم عن غيره بهذا الأسلوب ؟ ولماذا يمسك سيرة غيره ؟ ولماذا ينتقد هذا الإنسان أو ذاك ؟ وما الدافع وراء كل هذا ؟ وهل كلامه حق أم مخترع ؟ وهل يتكلم عنا نحن أيضاً بنفس الأسلوب ؟ وهل يمكن أن نسلم من لسانه أم سوف يأتى دورنا ؟ وهكذا تتحول من مسىء إلى غيرك إلى مُساء إليه .",{"h":"فالذين يسمعونك أو يصل إليهم كلامك : بعضهم سيصدّق ما يسمعه ، والبعض لا يصدق ."},"فالذين يصدقونك سوف تسوء سمعة ذلك الشخص فى نظرهم . والذين لا يصدقونك ستسوء فى نظرهم سمعتك أنت . وفى كلا الحالين خسارة لك ولهم ..."],"56":[{"h":"الإدانة خطية مركبة"},"ليست الإدانة فى جميع حالاتها حكماً بريئاً عادلاً ، من شخص له سلطان أن يدين ... وإنما قد تكون خطية حينما تصبح مجرد مسك سيرة ، وإساءة إلى السمعة . وقد ترتبط بخطايا أخرى . وربما تكون لها خلفيات وأسباب .",{"h":"وقد تكون أسباب الإدانة خطايا أبشع من الإدانة ذاتها ."},"فإدانة الآخرين لا تنشأ من فراغ ، ولابد من دوافع ، أو عوامل مساعدة ، علينا أن نعرفها ونتتبعها ونعالجها ... باحثين عن الخطايا المرتبطة بالإدانة . وقد لا تكون كلها مرتبطة بكل خطية إدانة ، وإنما بعض منها مرتبط بمناسبة أو بشخص ، والبعض بمناسبة أخرى وبشخص آخر . فما هى هذه الخطايا ؟ إنها :",{"h":"١ ـ عدم المحبة"},"يقول الكتاب « المحبة تستر كثرة من الخطايا » (١بط ٤ : ٨) .","ولعل القديس بطرس أقتبس هذه الآية من سفر الأمثال ، إذ ورد فيه « البغضة تهيج خصومات . والمحبة تستر كل الذنوب » (أم ١٠ : ١٢) . وكما يقول المثل السائر « حبيبك يبلع لك الظلط ، وعدوك يتمنى لك الغلط » .",{"h":"إن كنت تحب إنساناً ، فسوف لا تدينه ، بل ستدافع عنه ."},"وكما قيل فى المزمور عن الرجل البار إنه « لا يقبل عاراً على جيرانه » (مز ١٥ : ٣) . فكم بالأولى يصنع مع أحبائه واصدقائه وأقاربه ...","الإنسان عادة يدين واحداً من اثنين :"],"57":["فإما أنه يدين شخصاً لا يعرفه ، أو شخصاً عادياً لا ترتبطه به محبة ولا كراهية ، ولا تهمه سمعته فى شىء إن ساءت أو ارتفعت فى نظر الناس ... وطبعاً هذا الإتجاه هو ضد مبدأ المحبة من نحو الكل . إذ ينبغى أن تكون سمعة الناس ـ أياً كانوا ـ عزيزة فى أعيننا ، فهم بشر وأخوة ، حتى إن كنا لا نعرفهم ، ولا نقابلهم بلا مبالاة ...",{"h":"وإما أن تكون الإدانة مصحوبة بخطية حقد وكراهية نحو شخص يبغضه القلب ، كما كان النوع السابق مصحوباً بخطية اللامبالاة ..."},"والحقد أو الغيظ أو البغضة من الخطايا الصعبة التى ينبغى أن ينقى الإنسان قلبه منها . يقول القديس يوحنا الحبيب « كل من يبغض أخاه ، فهو قاتل نفس » (١يو ٣ : ١٥) . ويقول أيضاً « وأما من يبغض أخاه ، فهو فى الظلمة ، وفى الظلمة يسلك ، ولا يعلم أين يمضى ، لأن الظلمة أعمت عينيه » (١يو ٢ : ١١) .",{"h":"البغضة قد تكون أم الإدانة ، وهى أكثر شراً من إبنتها ."},"إنها تلد الإدانة ، وتغذيها من شرها ، وتصحبها طوال الطريق . وبها تصبح خطية الإدانة مركبة [ بغضة + إدانة ] ، أو لامبالاة بمشاعر الآخرين وسمعتهم تلد عنها خطية إدانة . أما المحبة فهى بعيدة عن كل هذا .",{"h":"فكم بالأولى إذا وصلت البغضة إلى حد الغيظ والحقد ؟!"},"وهنا تكون التركيبة قد ازدادت تعقيداً . فالبغضة ولدت غيظاً وحقداً . وهذان انجبا الإدانة . وبقيت البغضة تغذى الثلاثة !","والإدانة التى سببها البغضة ، إنما تخرج من قلب مسموم معكر . وحتى لهجة الصوت فيها ، أو ألفاظ التعبير ، تحمل فى طياتها ما فى القلب من حقد .","وهذا يذكرنا بخطية أخرى قد تصحب الإدانة وهى :"],"58":[{"h":"٢ ـ القسوة"},"هناك إدانات لا تصحبها قسوة ، مثل الإدانة التى هى مجرد ثرثرة أحاديث حول مسك سيرة الناس . وهذه قد تكون بأسلوب عادى ، وربما معه بعض التهكم والتفكه لتسلية الجلسة (!!) كما يظن هؤلاء ...",{"h":"ولكن هناك إدانات معها قسوة فى الحكم أو فى الألفاظ ."},"مثل قسوة الكتبة والفريسيين الذى أتوا بالمرأة الخاطئة ، بعد فضحها أمام الناس . ولم يكتفوا بما سببوه لها من عار ، وإنما أرادوا أن ينفذوا فيها حكم الرجم حسب الشريعة (يو ٨ : ٥) .",{"h":"ومثالها قسوة الذين أدانوا السيد المسيح بحكم الموت ."},"واصروا على ذلك صائحين « اصلبه اصلبه » « دمه علينا وعلى أولادنا » (متى ٢٧ : ٢٣ ، ٢٥) (مر ١٥ : ١٣ ، ١٤) ، إلى جوار ما صحب هذه الإدانة من جلد ولطم وبصاق وأنواع استهزاء أخرى صادرة من قلوب قاسية .",{"h":"وقد تكون القسوة فى استخدام ألفاظ جارحة ."},"أو وصف الشخص المدان بأوصاف رديئة جداً ، وتهم تمس شرفه أو شخصيته أو عقليته . ولعل من الإدانة الجارحة كلمة « يا أحمق » الذى قال الرب إن عقوبتها نار جهنم (متى ٥ : ٢٢) . وما أكثر الكلمات والعبارات التى يستخدمها الناس بنفس معنى كلمة (أحمق) ...",{"h":"وقد تكون القسوة فى أسلوب الشدة والعنف الذى يستخدمه أحدهم فى الإدانة :"},"حيث يدين غيره بغضب شديد وعصبية ظاهرة ، وربما فى ثورة وهو ساخط كل السخط على تصرفات هذا الأخ التى يصفها بأعنف الكلمات ، مما يدل على قسوة شديدة داخل القلب ."],"59":[{"h":"وقد تبدو القسوة فى عدم التماس أى عذر للذى يدينه ."},"وكذلك فى عدم تقدير ظروفه النفسية أو الصحية أو الاجتماعية ، وما أحاط بتصرفه من ملابسات وأسباب . بل يصدر الحكم فى أسلوب قاطع وهو يقول « مهما كانت الأسباب » ...",{"h":"وقد تظهر القسوة فى عقوبة شديدة يصدرها على من يدينه"},"وينفذها إن كان صاحب سلطان . أو يقترحها إن كان لا دخل له بالموضوع . ويقول فى عنف : هذا الشخص يستحق كذا وكذا من الاحكام ... ولو كنت أنا المسئول لفعلت به كذا وكذا .. !","وغير البغضة والقسوة قد ترتبط الإدانة بخطية أخرى هى :",{"h":"٣ ـ الظلم"},"ليست كل إدانة عادلة . فهناك إدانات فيها ظلم :",{"h":"كأن يدين الشخص غيره لمجرد السماع ، أو عن طريق الشائعات ."},"وقد يكون ما سمعه غير صحيح . وقد تكون الشائعات مغرضة ، أو خارجة من مصدر حاقد يريد التشهير . وربما يكون كل ما قيل عن هذا الإنسان مجرد اختراعات ، ولكنها انتشرت نتيجة تداول الكلام . وليس كل ما ينتشر يكون صحيحاً . ولا يصح الحكم على أساسه .",{"h":"وربما يكون الظلم ناتجاً عن عدم التأكد وعدم التحقيق ."},"والمفروض أن المتهم برىء إلى أن تثبت الجريمة عليه . والمفروض فى كل ما نسمعه عن أحد ، أننا لا نصدقه بسرعة وبدون فحص ، وبدون اعطائه فرصة ليجيب عن نفسه .","وقد ادين يوسف الصديق عن جريمة هو برىء منها كل البراءة ، واتهمته زوجة سيده ظلماً . ومع ذلك ألقى فى السجن وقد حمى عليه غضب سيده دون أن يتحقق"],"60":["من صحة التهمة . وربما امتلأت المنطقة بكلام سوء عن يوسف نتيجة لما قالته الزوجة الشريرة . ولعله خلال السنوات التى قضاها فى السجن كانت تلاحقه الإدانة الظالمة والسمعة الردية .",{"h":"وقد يكون الظلم عن جهل كما فعل فوطيفار بيوسف . وقد يكون بمعرفة وبنية سيئة كما فعلت زوجة فوطيفار بهذا البرىء ."},"وسواء كان الظلم عن جهل أو عن قصد سىء ، فهو ظلم يلصق الإدانة بإنسان برىء . والظلم المقصود يقودنا إلى خطية أخرى قد ترتبط بخطية الإدانة وهى :",{"h":"٤ ـ الكذب"},{"h":"وهذا الكذب قد يكون كاملاً ، أو عن طريق المبالغة ."},"والكذب الكامل هنا ، يقصد به أن شخصاً يخترع كلاماً ضد آخر للإساءة إلى سمعته ، وهو يعرف تماماً أن ما يقوله عنه هو محض افتراء . وطبعاً لا يفعل هذا إلا لو كان قد دفعه إلى الكذب شعور من الكراهية أو رغبة فى الإنتقام أو لون من الحسد . وهنا تكون خطية الإدانة مركبة من عديد من الخطايا .",{"h":"وقد تصحب الإدانة بكذب جزئى هو نوع من تضخيم الواقع بأسلوب مسىء ."},"فقد يقع إنسان فى خطأ دينى عن عدم فهم ، فيقدمه آخر للسامعين على اعتبار أنه هرطقة أو فضيحة أو عار ، ويضخم من قيمة الخطأ كما لو كان كفراً ... ويفعل ذلك إما بسبب الرغبة فى الإساءة ، أو لأنه بطبيعته مبالغ فى كل ما يتكلم عنه من أمور ...",{"h":"وربما يكون الكذب من اختراع المتكلم الذى يدين ، أو يكون نقلاً عن آخرين ..."},"وفى الحالتين كلتيهما ـ اختراع الكذب أو نقله ـ يكون الشخص المُساء إليه واقعاً تحت ظلم وهو برىء . والمفروض فى ناقل الكذب أن يتحرى جيداً فى تقبل"],"61":["الخبر ، وفى توصيله لآخرين ، وقد لا يكون من حقه هذا التوصيل ...","ننتقل إلى خطية أخرى ترتبط بالإدانة وهى :",{"h":"٥ ـ عدم الاتضاع"},{"h":"دائماً الذى يدين غيره ، يكون ناسياً خطاياه الخاصة ."},"ولو افتكر خطاياه ، ما كان يفكر فى خطايا أخيه ، أو يتحدث عنها أو يعايره بها ! ولذلك فإن الكتبة والفريسيين لما كانوا ناسين خطاياهم أثناء إدانتهم للمرأة المضبوطة فى ذات الفعل ، ذكرهم الرب بهذه الخطايا ، فلما بكتتهم ضمائرهم عليها ، تركوا إدانة الخاطئة وانصرفوا (يو ٨ : ٩ ـ ١١) .",{"h":"فى عدم الاتضاع ، يظن الإنسان نفسه أفضل من غيره ، فيدين هذا الغير ."},"ولذلك فإن الفريسى المتكبر أدان العشار فى الهيكل ، لما رأى فى نفسه أنه ليس من الناس الظالمين الخاطفين الزناة ، ولا مثل هذا العشار ، ولما تذكر بره وصومه وعشوره (لو ١٨ : ١١ ، ١٢) . أما العشار فكان منشغلاً بإدانة نفسه أمام الله ، فلم يدن غيره .",{"h":"تزيد الإدانة بواسطة الكبرياء ، إذا ما قارن الإنسان نفسه بمن هو أقل منه ."},"لذلك فإنه يدين هذا الذى هو أقل ، كما أدان الفريسى العشار . أما المتواضع الذى يرى أنه أقل من الكل ، فلا يدين غيره . كذلك بالكبرياء يظن أنه لا يمكن أن يسقط فيما سقط فيه هذا المدان . أما المتواضع فلا يعتبر أنه أقوى من أية خطية ، بل يتذكر أن الخطية « طرحت كثيرين جرحى ، وكل قتلاها أقوياء » (أم ٧ : ٢٦) لذل فهو لا يدين غيره .",{"h":"بل بالكبرياء يمكن أن الإنسان يدين من هو أكبر منه :"}],"62":["كما حدث أن مريم وهارون وقعا فى إدانة أخيهما موسى النبى العظيم حينما تزوج إمرأة كوشية . فكانت النتيجة ولذلك وبخهما الله ، وشرح لهما كيف أنهما أقل من موسى بكثير ، حتى يعودا إلى اتضاعهما ، ويعرفا قدر هذا العظيم الذى يدينانه . وضرب الله مريم بالبرص ، فأخرجوها خارج المحلة سبعة أيام كنجسة ، حتى تتعلم الاتضاع فلا تدين من هو أكبر منها (عد ١٢ : ١٥) .","وكان سبب وقوع مريم وهرون فى الإدانة هو عدم الاتضاع ، إذ قالا « هل كلّم الرب موسى وحده ؟ ألم يكلمنا نحن أيضاً » (عد ١٢ : ٢) . فكلمهما الرب بتوبيخ ليعرفا قدرهما تماماً ...","فى إدانة الآخرين خطية أخرى وهى :",{"h":"٦ ـ اعثار الآخرين"},"ونقصد هنا طبعاً الإدانة باللسان ، لأن الإدانة بالفكر أو القلب لا تعثر أحداً .",{"h":"أما الإدانة باللسان ، فتعثر السامع ، وتوقعه مع المتكلم فى نفس الخطية ."},"ويكون المتكلم الذى أدان غيره قد تسبب فى سقطة أخيه ، ويحاسبه الله على هذه العثرة . وبقدر ما يزداد عدد الذين تعرضوا للعثرة ، تكبر خطية الإدانة جداً ...","خطية أخرى ترتبط بخطية الإدانة وهى :",{"h":"٧ ـ الإهانة والتحقير"},{"h":"الإدانة هى بلا شك إقلال من شأن الشخص المدان ."},"لأنها تحكى عيوبه أو نقائصه ، خطاياه أو أخطاءه . وهى على درجات فى شدتها . وقد تصل أحياناً إلى الإهانة والشتيمة ، أو إلى التعيير والتحقير . وقد ينظر فيها الذين يدينون نظرة استصغار أو احتقار إلى من يدينه ، مشعراً إياه بضآلة قدره ، أو مبكتاً إياه بإزدراء ، أو جاعلاً الآخرين يستصغرونه أو يفقدون احترامهم له .",{"h":"وقد يجرحه بكشف أسراره وخصوصياته أمام الناس ."}],"63":["ويحكى ما يعرفه عنه من أمور مشينة . وقد يزداد الأمر خطورة بأن يشعر السامعين أن هذا الشخص لا فائدة فيه ، ولا اصلاح له ، كأن قد حكم عليه بالضياع !","وهذه النقطة ترتبط بها نقطة أخرى وهى :",{"h":"٨ ـ عدم اللياقة"},{"h":"إذا قد يتحدث بعيوب الشخص أمام أعدائه فيشمتون به ."},"أو يزداد هجومهم عليه ، إذ قد قدمت لهم مادة جديدة يحاربونه بها ، وما أكثر ما يسببه له هذا الأمر متاعب واشكالات .","أو قد يدينه أمام مرءوسيه ، أو ابنائه ، أو أمام من هم أصغر منه ، فتضيع هيبته أمامهم ، ويفقد مركزه .","وكل هذه وأمثالها أمور غير لائقة ، تضاف إلى خطية الإدانة ، فتجعل حجمها أكبر ومسئوليتها أزيد .","وقد تختلط فى كل ذلك بعدم الحكمة ، أو عدم التقدير ، أو عدم مراعاة شعور الآخرين . نقطة أخرى تحدث أحياناً وهى :",{"h":"٩ ـ الحكم على النيات"},"قد يصل الأمر بإنسان إلى أنه يدين نيات غيره ومقاصده ، فيقول : هذا الإنسان نيته سيئة ، وهو يقصد كذا وكذا من الشرور .. !",{"h":"بينما معرفة النيات والمقاصد هى من شأن الله وحده ."},"ولكن الإمتداد فى الإدانة جعله يدين النيات . وربما يقول إنه يفعل ذلك عن طريق الخبرة ، أو عن طريق الاستنتاج . ولكن لاشك أنه لا شىء من كل هذا"],"64":["مؤكد وما أسهل أن تكون كل استنتاجاته خاطئة ، وفيها ظلم ، وادعاء بمعرفة هو فيها « يرتئى فوق ما ينبغى » (رو ١٢ : ٣) .",{"h":"الحكم على النيات ، حتى لو صح ، هو خطأ روحى ."},"فكم يكون إذن من يدين مشاعر القلب ، ومن يدين أفكار الناس ، وهو لا يمكن أن يعرف المشاعر والأفكار ، إلا عن طريق الظنون : وليست الظنون صادقة باستمرار ...",{"h":"بل يوجد من يدين حياة إنسان بالجملة ، وطبيعته وخلقه ... وربما يدين مصيره أيضاً ..."},"قال أحد الشيوخ (فى بستان الرهبان) :","إن كان لا يعرف ما فى الإنسان إلا روح الإنسان الذى فيه (١كو ٢ : ١١) ، وإذا كنا نعرف أن كثيرين قد تابوا ، دون أن نعلم نحن بتوبتهم ، وإذ قد يتفق أن يتوب إنسان فى آخر حياته ، ويقبل الله كاللص ، فسبيلنا إذن أن لا ندين أحداً ... فالديان هو الله وحده ، فكيف يجرؤ أحد أن يتدخل فيما هو خاص بالله ؟!","آخر خطية اتحدث عنها كخطية مرتبطة بالإدانة هى :",{"h":"١٠ ـ الرياء"},"الشخص الذى يدين غيره على خطأ ، وهو يرتكب نفس الخطأ أو ما هو أسوأ ، يصفه السيد المسيح بالرياء .","فيقول له « لماذا تنظر القذى الذى فى عين أخيك ، وأما الخشبة التى فى عينك فلا تفطن لها ؟! ... يا مرائى ، أخرج أولاً الخشبة من عينك ، وحينئذ تبصر جيداً أن تخرج القذى الذى فى عين أخيك (متى ٧ : ٣ ـ ٥) .",{"h":"إذن من الرياء أن ندين الناس على أشياء نحن نقع فيها خفية ."},"أو نحن نقع فى أمور أخرى ، ربما تكون أكثر خطأ منها ."],"65":[{"h":"الفصل الرابع"},{"h":"أقوال الآباء فى الإدانة"}],"66":[{"h":"قال القديس دوروثيئوس :"},{"h":"« الحكم على خليقة الله ، يليق بالله ذاته لا بنا »"},"« لأنه هو وحده العارف بسّر كل إنسان وعلانيته . وله وحده إصدار الحكم فى كل أمر ، وعلى كل شخص » .","« الله وحده له الحق فى أن يبرر أو يدين ، لأنه يعرف طبع كل إنسان وقوته » .","وهو أيضاً يعرف ميوله ومواهبه وتركيبه البدنى ومقدراته .","لذلك فإن الله عندما يدين ، يدين بالعدل .","ولهذا قال الرسول لمن يتطاول على عمل الله هذا : « من أنت أيها الإنسان ، يا من تدين عبد غيرك ؟ عبد هو لسيده ، يثبت أو يسقط . ولكنه سيثبت لأن الله قادر أن يقيمه » (رو ١٤ : ٤) .","* * *",{"h":"وقال القديس دوروثيئوس أيضاً :"},{"h":"« إن سم الإدانة أحياناً يخرج من إنسان ، لكى يصب فى آخرين » ."},"نلاحظ أنه وصف الإدانة بسمّ ، أى إنها تميت من تصل إليه . وكأنه بهذا يشبه الذى يدين غيره بحية تنفث سمها ...","* * *",{"h":"قال القديس مارأوغريس :"},"« لا تميز الذين سقطوا (من الذين لم يسقطوا) . ولا تترك فكر الكبرياء يقنعك بأن تكون ديّاناً » . وهنا القديس يربط بين الإدانة والكبرياء ."],"67":[{"h":"قال القديس الأنبا إشعياء :"},"« إذا أبصرت إنساناً قد أخطأ ، فلا تحتقره ، ولا تزدرِ به ، لئلا تقع فى أيدى أعدائك » .","حقاً ، ماذا تريد أنت من وراء هذه الإدانة ؟ هل تريد أن هذا الشخص يكرهه الناس ؟ أم تريد أن الله يهلكه ، ويجازيه بحسب أعماله الردية ؟ أمامنا قصة من البستان تلقى ضوءاً على هذا الأمر ...","* * *",{"h":"قصة من البستان :"},"قيل إن راهباً كان مقصراً فى عبادته ومتهاوناً ... فلما جاءته ساعة الوفاة ، اجتمع الرهبان حوله ، لكى يروا كيف سيقابل الموت ... فوجدوه فرحاً !!","فقال له أحد الشيوخ « تشدد أيها الأخ باسم المسيح وقل لنا ما الذى يفرحك ؟ »","فأجابه ذلك الأخ : إننى رأيت أناساً مقبلين لأخذ نفسى ، ورأيت صك خطاياى . وقالوا لى « هذه خطاياك » . فقلت « خطاياى أنا أعرفها ولا انكرها . ولكننى منذ ترهبت ، وأنا لم أدن إنساناً . وأريد أن تنفذ فىّ الآية التى تقول « لا تدينوا لكى لا تدانوا » . فكيف أُدان ، وأنا لم أدن أحداً ؟ ! » . ولما قلت هذا تمزق صك خطاياى .","هذا الراهب لم يكن يعيش فى الخطية ، إنما كان مهملاً فى عبادته . ولكنه كان طيب القلب ، لا يغضب على أحد ، ولا يدين أحداً ، ولا يتكلم بالشر على إنسان . كان متضع القلب .",{"h":"واستطاع باتضاعه وعدم إدانته لغيره ، أن يخلص ..."},"بالدقة فى تنفيذ هذه الوصية ، أمكن أن ينجو من الدينونة التى كان يمكن أن تحل به بسبب تهاونه ."],"68":[{"h":"وقال القديس ايرايس :"},{"h":"إنه جيد أن يأكل الإنسان لحماً ، ويشرب خمراً »"},{"h":"« ولا يأكل لحوم الأخوة ويشرب دماءهم بالوقيعة »"},"لقد شبه الإدانة بعملية افتراس للآخرين ، افتراس لسمعتهم وكرامتهم . وقال إنه خير للإنسان أن يكون مفطراً ولا يدين غيره ، من أن يصوم ويأكل لحوم الناس بإدانتهم . وأكل لحوم الناس ابشع من أكل اللحم العادى ...","* * *",{"h":"وقال القديس الأنبا مسرا :"},"« إن التعقل (التعفف) الذى هو أفضل من إمساك البطن ... والذى يجب أن تجذب إليه نفسك ، ألا تأكل لحم إنسان ولا تشرب دمه بالوقيعة »","إنه نفس تعبير القديس إيرايس ...","ونفس التعبير يردده أيضاً مار اسحق اسقف نينوى","* * *",{"h":"قال مار اسحق :"},"« إن الذى يصوّم نفسه عن الأكل والشرب ، بينما يأكل لحوم الناس بالوقيعة ، فصومه باطل » .","* * *",{"h":"وقال القديس ايرايس أيضاً :"},"« كما أن الحية لما كلمت حواء ، أخرجتها من الجنة ... كذلك يشبهها ذلك الذى يقع بقريبه »",{"h":"« ذلك لأنه يهلك أنفس سامعيه ، ونفسه كذلك لن تفلت ... كما تفلت الحية نفسها من اللعنة » ."},"أى أنه يضيّع نفسه ، ويضيّع غيره معه ."],"69":[{"h":"أما مار اسحق أسقف نينوى :"},"فيرى أن الذى يدين غيره ، هو شخص فى المستوى النفسانى ، وليس فى المستوى الروحانى ، لذلك يدين الكل ، لأن فى قلبه شجرة معرفة الخير والشر ، يفحص بها أعمال الناس هل هى خير من شر . وهكذا يقول مار اسحق :",{"h":"« النفسانى هو قاض للأبرار والخطاة ، وديّان للأحياء والأموات . ومنصوبة فى قلبه شجرة معرفة الخير والشر ، التى مُنع رأس جنسنا آدم من أن يدنو منها أو يذوقها لئلا يموت » . هذا تغتذى معرفته منها فى كل وقت » ."},"إنه إنسان شغوف بحبة القضاه . وكل الذين يقابلهم يضعهم فى ميزان معرفة الخير والشر ، ليس الأحياء فقط بل الأموات أيضاً ...","* وبنفس الوضع يتكلم مارأوغريس ، فيقول :",{"h":"« لا تتكلم بالشر على الذى مات ، لئلا تكون ديّاناً للأموات أيضاً » ..."},"لأن الذى يفعل هذا يأخذ مكانة السيد المسيح الذى قال عنه إنه يأتى « ليدين الأحياء والأموات » .","حقاً ، كم يحدث أن إدانتنا لا تقتصر على الأحياء فقط ، بل كثيراً ما ندين الأموات أيضاً ، الذين ربما يكونون قد تابوا قبل موتهم ومحا الله خطاياهم ، ولم يعد يذكرها حسب وعده القائل « لأنى اصفح عن إثمهم ، ولا أذكر خطيتهم بعد » (أر ٣١ : ٣٤) .",{"h":"الله لا يذكر تلك الخطايا ، ونحن نذكرها !!"},"حقاً إن فى ذلك لعجباً ... ذاكرة الإنسان أحياناً تتعبه وتتعب غيره . وكذلك لسانة ، يتعبه ويتعب غيره ...","يضع الإنسان نفسه رقيباً على أعمال الكل ! بعين نقادة ، وفكر لا يهدأ ، ولسان يستطيع أن يجرح .","بينما القديسون منعوا الإدانة ، مهما كانت الأسباب ."],"70":[{"h":"قال القديس الأنبا أنطونيوس :"},"لا تعير أحداً مهما كانت الأسباب . ولا تفترِ على أخيك ، ولو رأيته عاجزاً عن إتمام جميع الفرائض .","* * *",{"h":"وقال القديس الأنبا باخوميوس :"},"« لا تحتقر أحداً من الناس ، ولا تدنه ، ولو رأيته ساقطاً فى الخطية » .","* * *","ولعل تعليم الإنجيل يؤكد لنا هذه القاعدة ، وذلك فى :",{"h":"قصة المرأة المضبوطة فى الفعل :"},"إن الذين ضبطوها وأتوا بها إلى الرب للحكم عليها بالرجم ، لم يدّعوا عليها ظلماً ، ولم ينسبوا إليها ما لم تفعله ، فقد كانت فعلاً ساقطة فى الخطية . ومع ذلك منعهم السيد من إدانتها ، وحول تفكيرهم إلى خطاياهم هم ، قائلاً « من كان منكم بلا خطية ، فليرمها أولاً بحجر » (يو ٨ : ٧) .",{"h":"وأعطانا درساً أن لا ندين أحداً ، حتى لو رأيناه ساقطاً فى الخطية ."},"نحن أيضاً ساقطون فى خطايا كثيرة ... ولا يجوز لمريض أن يعيّر مريضاً آخر بمرضه ، وكلاهما تحت الألم . إنما الأفضل ستر الناس وليس كشف عيوبهم ، فنحن أيضاً لنا عيوب ...","* * *",{"h":"قال القديس يوحنا ذهبى الفم :"},"« إن كنت لا تستطيع أن تستر أخاك ... وأن تأخذ خطيته وتنسبها إلى نفسك ، وأن تموت عنه ، فعلى الأقل ... لا تدنه » ... وقال ذهبى الفم أيضاً :",{"h":"« إن كنت لا تستطيع أن تسكت فم الذى يتكلم بالشر على أخيك ، فعلى الأقل لا تفتح فمك أنت بالشر عليه » ."}],"71":["أى أن الوضع الأمثل هو أن تمنع السمعة الردية من أن تصل من الآخرين إلى أخيك . فإن لم تستطع ، فعلى الأقل لا تشاركهم فى إدانته . وبالأحرى لا تبدأ أنت حديث الإدانة ...","* * *",{"h":"قال القديس بولس السينائى :"},{"h":"« تنهد على قريبك إذا أخطأ ، كما تتنهد على نفسك ، لأننا كلنا تحت الزلل » ."},"ذلك لأنك بهذا تعامله بترفق المحبة ، وليس بقسوة الحكم . إنه أخوك وقريبك مهما سقط . إن الآب السماوى قال فى رجوع إبنه الضال « إبنى هذا كان ميتاً فعاش ، وكان ضالاً فوُجد » (لو ١٥ : ٢٤) . وهكذا دعاه إبنه على الرغم من الموت ومن الضلال فكم بالأكثر تعامل أخاك ... على أننا نلاحظ ملاحظة هامة فى هذه القصة وهى :",{"h":"الآب السماوى غفر لهذا الإبن ، وأخوه لم يغفر !!"},"بل رفض أن يدخل ، ورفض أن يشترك فى الفرحة بعودته ، وأدانه مع الآب قائلاً « إبنك هذا الذى أكل معيشتك مع الزوانى » (لو ١٥ : ٣٠) .","عجيب هو الرب فى محبته وعطفه ... هو الذى يغفر ، مع أن له كل الحق . ونحن الذين ندين ، ولا حق لنا !","* * *",{"h":"قال القديس انسطاسيوس :"},"« لا تكن دياناً لأخيك ، لتؤهل أنت للغفران . لأن الرب يقول : لا تدينوا لكى لا تدانوا » .","نعم بكيل المغفرة والرحمة الذى نكيل به للآخرين ، يكال لنا فى يوم الدينونة","إن عدم الإدانة عامل مساعد على نوال المغفرة . لكن يشترط طبعاً الإيمان والتوبة ..."],"72":[{"h":"قال مار اسحق :"},"« احذر من أن تكون جالساً وتفكر فى أخيك بالشر ، فإن هذا يقلع جميع بنيان برج الفضيلة من قلبك ... حتى إن كنت قد وصلت إلى حد الكمال » ...","ويعلل مار اسحق هذا بقوله « ذلك لأن الهذيذ فى الأفكار الردية يقسى القلب » ...",{"h":"ويقول أيضاً : غطّ على أخيك الخاطىء ، وقوّه من غير أن تشمئز منه ، لكيما تحملك رحمة سيد الكل » ."},"أى أن الرحمة التى نقابل بها الخطاة ، تؤهلنا لأن ننال رحمة من الله ، عملاً بقول الرب : « بالكيل الذى به تكيلون ، يكال لكم ويزاد » (مر ٤ : ٢٤) .",{"h":"وقال مار اسحق أيضاً :"},"اسند الضعفاء وصغيرى القلوب والنفوس بكلمة ... فتسندك اليمين التى تحمل الكل ... كن شريكاً للموجوعين بقلوبهم ، بصلاتك الحزينة وبتتهد قلبك ... لكيما ينفتح لسؤالك ينبوع الرحمة » .","وقال أيضاً : « لا تمقت الخاطىء ، لأننا كلنا خطاة آثمون . وإن تحركت عليه من أجل الله ، فابكِ عليه ، وصلّ من أجل نفسه » .","وهكذا يضع الآباء الرحمة فى موضع الإدانة .","ويأمرون بالصلاة من أجل الخاطىء بدلاً من اساءة سمعته .","وليس هذا من أجله فقط ، بل أيضاً من أجل أنفسنا .",{"h":"حتى لا ندان بسبب إدانتنا ، بل على العكس يعاملنا الله بالرحمة بسبب رحمتنا وفى هذه النقطة اتفقت أقوال القديسين :"},"* * *"],"73":[{"h":"قال القديس الأنبا أنطونيوس :"},{"h":"« لا تدن غيرك لئلا تقع فى أيدى اعدائك » ."},"« وتفعل الخطايا القديمة التى تركتها » .","أن أن الله إذا رآك قاسى القلب فى أحكامك على الناس ، يسمح أحياناً أن تجرب بقسوة الحروب التى يعانونها من أعدائهم الشياطين . حتى إذا ما سقطت ، تعود وتشفق على غيرك ، ولا تدين ...",{"h":"وقال أيضاً : إياك أن تعيب أحداً من الناس ، لئلا يبغض الله صلاتك » ."},"حقاً ، ما أصعب هاتين النتيجتين اللتين تنتجان عن إدانة الآخرين حسب تعليم أبينا القديس الأنبا أنطونيوس :","أ ـ أن تسلم لأيدى أعدائك ، وتفعل الخطايا القديمة .","ب ـ أن يبغض الله صلاتك .","ولماذا يبغضها ؟ لأنها ليست صادرة من قلب محب .","ونفس هذا التعليم نسمعه من القديس الأنبا إشعياء المتوحد :","* * *",{"h":"وقال القديس دوروثيئوس :"},"من دان فى قلبه ، وتحدث بسيرته على لسانه ، تتخلى عنه المعونة الإلهية ، فيسقط فيما دان أخاه عليه » .","* * *",{"h":"وقال القديس مقاريوس الكبير :"},"« احفظوا ألسنتكم ، وذلك بأن لا تقولوا على أخوتكم شراً ... لأن الذى يقول على أخيه شراً ، يغضب الله الساكن فيه » .","« وما يفعله كل واحد برفيقه ، فبالله يفعله » ."],"74":[{"h":"قصة من البستان :"},"فى إحدى المرات أتى الأب اسحق القس التبايسى إلى مجمع الشركة ، وأدان أحد الأخوة على فعل أتاه . فلما عاد إلى قلايته فى البرية ، أتاه ملاك الرب ووقف أمام باب القلاية ، وقال له : إن الله ارسلنى إليك لكى أسألك :",{"h":"« أين تريد أن نلقى بنفس هذا الأخ ؟ »"},"وحينئذ أحس الأب اسحق بالخطأ الذى ارتكبه ... أنه لا يريد طبعاً أن تلقى نفس ذلك الأخ إلى الهلاك ! فتاب لوقته وقال للملاك « أخطأت ، فليغفر لى الرب بصلاتك » . فقال له الملاك « قد غفر الله لك ولكن عليك أن تحفظ نفسك ، ولا تدن إنساناً قبل أن يدينه الله » .","* * *",{"h":"قال القديس الأنبا بيمن :"},"« قد تجد إنساناً يُظن به أنه صامت . لكن فكره يدين آخرين . فمن كانت هذه صفته ، فهو أبداً يتكلم » .","ويقصد القديس أن الإدانة ليست باللسان فقط ، إنما بالفكر أيضاً . وصمت اللسان وامتناعه عن كلام الإدانة ، لا يمنع أنه واقع فيها بالفكر .",{"h":"ومع ذلك فالإدانة بالفكر أقل دينونة من الإدانة باللسان ."},"وذلك لأمرين : أولهما أنك بسقطة الفكر لا تعثر سامعين .","وثانيهما أنك لا تسىء إلى سمعه غيرك . فسقطة فكرك قاصرة عليك وحدك ، وليس لها نتائج خارجك ، إلا إذا تطورت ووصلت إلى اللسان .","* * *",{"h":"وقال أحد الآباء :"},"إن رأيت شخصاً يخطىء اليوم ، فلا تتكلم باكر فى إدانته ، لأنك لا تعرف ، ربما رجع فى هذه الليلة ، وبكى على خطيته وتاب ، ومحاها له الله ..."],"75":[{"h":"وقال القديس مقاريوس الكبير :"},"لا تضعوا فى ذهنكم ، ولا تقبلوا فى فكركم أن إنساناً ما شرير . لأن بطرس الرسول يقول « قد أرانى الله أن لا أقول عن إنسان ما أنه دنس أو نجس » (أع ١٠ : ٢٨) .","* * *",{"h":"قال القديس مارافرام :"},{"h":"إن التلذذ بعيوب الآخرين ، يدل على أننا ممتلئون ببغضه ."},"وقال كذلك « من يشمت بسقطة أخيه ، يسقط هى أيضاً سقطة مثلها » . وقال « لا تترفع على أخيك فى ذهنك ، لأنك لا تعلم ماذا سيحدث فى اليوم المقبل . فمن الجائز أنه يتوب وتسقط أنت » .","وقال مارافرام أيضاً : إن الذى يسب رفيقه له صفتان : الوقيعة والبغضة » « ومثل هذا يعتبر فاقداً للتحنن وعادماً الرحمة » .",{"h":"وقال : لا تكن دياناً لغيرك ، لأن كل واحد منا سيعطى اجابة عن أعماله . وأنت سوف لا تعطى أجابة عن أعمال غيرك » ."},"* * *",{"h":"وقال القديس سمعان العمودى :"},"إن وجدت واحداً من أخوتك قد مال قليلاً ، فلا تقطع رجاءه . لأن الكتاب يقول « عزوا بعضكم بعضاً » (١تس ٤ : ١٨) . « المنتظر منك أن تقيم الإنسان الساقط ، لا أن تقضى عليه » .","وقال القديس سمعان العمودى أيضاً « إن كنت تدين أخاك ، فماذا تقول لك عن نفسك .","* * *",{"h":"قال القديس الأنبا بيمن :"},"إذا دنا أنفسنا ، لا يبقى لنا وقت ندين فيه آخرين ."],"76":[{"h":"قال مار اسحق :"},"« لا تدن غيرك ، لئلا تُمتحن بما أُمتحنوا به »","أى لكى لا تقع فى نفس الحرب الروحية الصعبة التى تعرضوا لها . وهكذا توقع نفسك فى التجارب .","وقال أيضاً « اذكر أنك من الطبيعة الأرض ، مشترك معهم فى جسد آدم ، وفى نير هذه الطبيعة » .",{"h":"وقال مار اسحق أيضاً :"},"« الإنسان البعيد عن ذكر الله ، هو المهتم بقول السوء على أخيه » .","أى أن الإنسان إذا كان منشغلاً بالصلاة والتأمل ، وقراءة الكتاب ، والمداومة على ذكر الله فى قلبه ، لا يبقى لديه وقت يتفرغ فيه لذكر أخطاء الناس . أما الإنسان المقصر فى عبادته ، فإن الفراغ يساعده على كلام الإدانة .","* * *",{"h":"قال القديس يوحنا القصير :"},{"h":"كن حزيناً على الذين هلكوا . وكن رحيماً على الذين سقطوا ."},"لعله يشبه هذا بما قاله القديس بولس الرسول فى رسالته إلى العبرانيين « اذكروا المقيدين ، كأنكم مقيدون معهم . واذكروا المذلين ، كأنكم أنتم أيضاً فى الجسد » (عب ١٣ : ٣) .",{"h":"نعم ، ليس المفروض أن ندين الساقطين ، بل أن نقيمهم ."},"وفى ذلك يقول الكتاب « شددوا الأيادى المسترخية ، والركب المرتعشة ثبتوها » (أش ٣٥ : ٣) . وأيضاً يقول الرسول « شجعوا صغار النفوس . اسندوا الضعفاء . تأنوا على الجميع » (١تس ٥ : ١٤) .",{"h":"قال « اسندوا الضعفاء » ولم يقل أن تدينوهم أو تحقروهم أو تشهروا بهم أمام الآخرين ."}],"77":[{"h":"وقال مار اسحق :"},"« الذى ينظر الخشبة التى فى عينه ، لا يتفرغ لأن ينظر القذى الذى فى عين أخيه » . وقال أيضاً :",{"h":"« الذى يعتنى بأن يقوم فى ذاته المناقص التى تظهر له فى الآخرين الذين هو سالك بينهم ، هذا قد وجد مرآة روحية داخل نفسه » ."},"أى أننا عندما نرى خطأ ما يرتكبه البعض ، نفحص أنفسنا جيداً ، ربما نرى هذا الخطأ فينا ، فنعالج فى أنفسنا ما نرى غيرنا يدانون عليه .","وهذا المعنى نفسه ردده القديس مارأوغريس .","* * *",{"h":"قال القديس مارأوغريس :"},"« الذى يفحص نقائص الآخرين ، هو لم يفحص بعد أعماله الخاصة بحرص . لأنه لو فحص نفسه جيداً ، لوجد أن العيب الموجود عند الناس ، هو موجود عنده أيضاً » .","وهذا المعنى ليس فقط لمار اسحق ومارأوغريس ، وإنما :","* * *",{"h":"قال الأنبا ميلوس :"},"« إذا نظرنا فى أمور أنفسنا ، ندين آخرين . لأن أموراً كثيرة هى فينا ، ونحن نلوم بها غيرنا » .","* * *",{"h":"وقال أحد الآباء :"},"إن الله هو الديان . وقد أعطى الدينونة كلها للإبن (يو ٥ : ٢٢) . ومع ذلك قد أجّل تلك الدينونة إلى اليوم الأخير الذى يأتى فيه فى مجده ليدين الأحياء والأموات . فلماذا تتعجل الأمر ، وتبدأ أنت فى الدينونة من الآن ."],"78":[{"h":"وقال القديس مقاريوس الكبير :"},"« احفظوا ذواتكم من كلام النميمة والوقيعة ، لكى تكون قلوبكم طاهرة . لأن الأذن التى تسمع النميمة ، لا تستطيع أن تحفظ طهارة القلب بدون دنس » .","أى اجعل أذنك نظيفة ، لكى يصير قلبك نظيفاً ، لأن الأذن توصل إلى القلب .",{"h":"فإن كان الذى يسمع فى خطر ، فكم بالأكثر الذى يتكلم ؟ وكم بالأكثر الذى ينقل الكلام الردىء ."},"وماذا عن الذى يسىء العلاقات بين الناس بما ينقله من كلام ؟ لاشك أنه يكون بعيداً عن الله ، لأن الكتاب يقول « طوبى لصانعى السلام ، لأنهم يدعون أبناء الله » (متى ٥ : ٩) . فالذى لا يصنع سلاماً ، بل يصنع خصومة ، ليس هو إبناً لله .","* * *",{"h":"سئل القديس يوحنا الأسيوطى :"},"هل الذى يدين الشر هو الذى يبغضه ؟","فأجاب : كلا لأن كل الناس تقول إنها تبغض الشر . وإنما أعمالك هى التى تثبت أنك تكره الشر .","* * *",{"h":"وقال القديس أوغسطينوس :"},"إن الإنسان الذى استطاع أن يروض الوحوش ، لم يستطع أن يروض لسانه (كما قال معلمنا يعقوب ٣ : ٨) .","من ذا الذى لا يخاف من قول الرب : من قال لأخيه يا أحمق ، يكون مستحقاً لنار جهنم » .","* * *"],"79":[{"h":"الفصل الخامس"},{"h":"علاج الإدانة"},"تعوّد احترام الناس .","معالجة مشكلة الفراغ .","البعد عن سماع الإدانة .","الاتضاع ولوم النفس .","حجة اصلاح الآخرين .","تداريب أخرى كثيرة ."],"80":[{"h":"تعوّد احترام الناس"},"إن عرفنا أسباب الإدانة ، يمكن أن نعرف علاجها . وأول سبب هو أن الإنسان يبيح لنفسه أن يخوض فى سمعة الآخرين ، ويجرح بهذا كرامتهم .",{"h":"إذن عليك أن تتعود إكرام الناس ومحبتهم ، سواء فى حضورهم أو غيبتهم ."},"عوّد نفسك عدم الإساءة إلى أحد ، سواء فى الحديث معه ، أو فى الحديث عنه . إن كانت لديك كلمة طيبة ، قلها . وإلا ، فالأصلح أن تصمت ... تعود عدم إهانة أحد ، وعدم الحديث عنه بالسوء . ولا تضع أحداً على ميزان النقد ، ولا تشرّح شخصيات الناس . وفى هذه الحالة لن تدين أحداً .",{"h":"إن الشخص الذى تعود احترام الغير ، لا يمكن أن يدين الغير ."},"فى الحياة الاجتماعية يلقبون هذا الشخص بأنه « إنسان مهذّب » . يكلم كل أحد بلياقة وباحترام وبأسلوب لطيف . ولا يعرف العيب طريقاً إلى لسانه . فلسانه لم يتعود أن يهين أحداً ، ولا أن يتكلم على أحد كلمة سوء ، وبالتالى لا يدين أحداً .","انظر ماذا يقول القديس يعقوب الرسول عن هذه النقطة بالذات فى حديث عن أخطاء اللسان :",{"h":"« به نبارك الله الآب . وبه نلعن الناس الذين قد تكوّنوا على شبه الله » (يع ٣ : ٩) ."},"فاعتبر أن خطية الإدانة لعنة ، وإنها لعنة ضد أناس خُلقوا على صورة الله وشبهه ومثاله (تك ١ : ٢٦ ، ٢٧) . وتابع الرسول كلامه معاتباً فقال « من الفم الواحد ، تخرج بركة ولعنة ! لا يصلح يا أخوتى أن تكون الأمور هكذا » (يع ٣ : ١٠) ."],"81":["إن كان الرب يقول « باركوا لاعنيكم » (متى ٥ : ٤٤) ، فهل نحن نلعن أخوتنا ؟!","وهوذا الكتاب يقول « باركوا ، ولا تلعنوا » (رو ١٢ : ١٤) .","ليكن فمك إذن نقياً ، وليكن لسانك طاهراً عفيفاً ، تخرج منه كلمات البركة ، ولا تخرج منه كلمة إدانة : شتيمة كانت أم لعنة أم إهانة ...",{"h":"تدرب أنك لا تتكلم إلا عن فضائل الناس بقدر استطاعتك ."},"ركز على النقط البيضاء التى فى حياتهم ، واترك الباقى . حاول أن تتناساه . أما الأشخاص الذين اسودت صورتهم فى ذهنك جداً ، وصاروا مثل « اسكندر النحاس » عند بولس الرسول (٢تى ٤ : ١٤) ، فالأفضل أنك لا تأتى بسيرتهم على لسانك ، أقول أيضاً « على قدر طاقتك » ... إلى أن يصلح الله أمرهم ، إن أمكن ذلك ، وحينئذ ستتغير صورتهم فى فكرك ..",{"h":"يستثنى من هذا أعداء الكنيسة وأعداء الإيمان ."},"أولئك الذين ينبغى أن تحذر الكنيسة منهم ، وتشرح أخطاءهم اللاهوتية حتى لا يقع أحد فيها . وعن مثل هؤلاء قال السيد الرب « احترسوا من الأنبياء الكذبة » (متى ٧ : ١٥) وأيضاً « احذروا من الناس » (متى ١٠ : ١٧) .",{"h":"معالجة مشكلة الفراغ"},{"h":"فى كثير من الأحيان ، إذ لا يجد الناس موضوعاً يتحدثون فيه ، يكون حديثهم عن أخبار الناس وأخطائهم وفضائحهم وسقطاتهم ."},"وهكذا تكون سيرة الناس هى الموضوع الأساسى للحديث فى البيوت ، وفى النوادى والمقاهى ، وفى كثير من الجلسات حيثما وجدت .","ليس لأنهم يريدون أن يدينوا غيرهم ، وإنما لأنهم لا يجدون موضوعاً آخر ـ غير أخبار الناس ـ يتحدثون فيه ."],"82":[{"h":"وقد يدينون رؤساء دول لمجرد قراءة أخبار تسهم فى الجرائد ، دون معرفة مدى صحة هذه الأخبار !"},"أو يدينون شخصاً ذكرت الجرائد أنه قد قبض عليه فى حادث معين . وربما تذكر الجرائد بعد شهور أن القضاء قد براه ، بعد تحقيق ما قد نُسب إليه . ولكن هذا الإنسان تكون سمعته قد وصلت إلى التراب خلال تلك الشهور . وربما يكون البعض قد قرأ خبر القبض عليه ، ولا يكون قد قرأ خبر الحكم ببراءته ...",{"h":"ليت الناس يجدون مواضيع دسمة ومفيدة يشغلون بها وقت فراغهم ."},"يقيناً إن وجدوا هذا ، لا يكون أمامهم مجال لشغل وقتهم بمسك سيرة الناس .","انظروا إلى طلاب الكليات والمعاهد والمدارس ، فى أيام امتحاناتهم ، وهم مشغولون بالمذاكرة والمراجعة والاستعداد للامتحان ، أتراهم لديهم وقت للحكايات ، أو لتقليد المدرسين والتندر عليهم ، أو للحديث عن أخبار زملائهم وأخطائهم وفضائحهم ؟ كلا بلاشك ، لأنهم مشغولون ...",{"h":"كذلك المرأة العاملة ليس لديها وقت كاف ، للجلوس مع جاراتها والحديث عن أخبار باقى الجيران ..."},"مع ما تحمل أمثال هذه الأخبار من التعرض لبعض الأخطاء وإدانتها . وإن وجدت وقتاً لهذا ، يكون ـ بالمقارنة ـ أقل بكثير جداً من زميلتها التى لا تعمل ، وأمامها فراغ طويل المدى لا تعرف كيف تقضيه ، واحتمال الوقوع فى مسك سيرة الناس ، محتمل أمامها جداً ووارد ...",{"h":"ولكننا نقول إن الفراغ هو نصف السبب والنصف الثانى هو كيفية قضاء الوقت فى هذا الفراغ ."},"فقد يستغل أحدهم الفراغ فى قراءة مفيدة ، ينتفع بها ، وينفع بها غيره فى أحاديثه معهم . والبعض قد يستغل الفراغ فى عمل اليد ، أو فى التدريب على مهنة أو مهارة معينة ، أو يستغل فراغه فى خدمة الآخرين . أو فى زيارة مريض ، أو فى تعزية حزين ، أو فى مساعدة محتاج ."],"83":[{"h":"وفى الاجتماع مع الناس ، ما أحوج الكل إلى موضوع نافع يتحدثون فيه ."},"ويمكن هذا ، إن قصد أحدهم هذا الأمر ، واستطاع أن يدير الحديث فى موضوع نافع ، يكون قد درسه ، وأصبح مستعداً للكلام فيه ، والإجابة عن كل سؤال يدور حوله . وإدارة دفة الحوار بطريقة تفيد الكل . وذلك قبل أن يبدأ غيره فيطرح سيرة توقع الكل فى الإدانة ...",{"h":"ويمكن أن يحدث هذا أيضاً فى محيط الأسرة ."},"بطريقة بسيطة وتلقائية ، لا تشعر أحداً بأنه أمام مدرس أو محاضر ... وذلك بطرح موضوع علمى ، أو دينى ، أو قصة أو خبر نافع ، أو اكتشاف مفيد ، أو ملخص لباب قرأه فى أحد كتب الثقافة أو كتب التاريخ ، أو أمر جديد ممتع من أمور المعرفة ، أو بعض التسليات والألغاز حول الكتاب المقدس أو سير القديسين .",{"h":"إن الجلسة العائلية تحتاج إلى استعداد ، وكذلك جلسات الأصحاب ..."},"أما ترك تلك الجلسات فى فراغ ، فإنه يقود إلى أمثال هذه الإدانات ، أو إلى الثرثرة الفارغة التى هى مضيعة للوقت ، أو الحديث فى أى منازعات قد تتحول إلى صياح وشجار . ذلك لأنه لا يوجد موضوع نافع يتحدثون فيه ، أو لا يوجد من يتولى دفة الحوار بمهارة .",{"h":"ألا ترون أن السبب ليس مجرد فراغ فى الوقت ، وإنما فى الفكر أيضاً ..."},"ونعود إلى السؤال مرة أخرى : لماذا تمتلىء البيوت والنوادى والجلسات بمسك سيرة الناس ؟ ونجيب :",{"h":"لأنهم فى فراغ ، لا يجدون موضوعاً آخر يتحدثون فيه ."},{"h":"عدم السماع"},"حاول بقدر امكانك ، أن لا تسمع ما يقال عن أخطاء الآخرين ."],"84":["ابعد عن المجالس التى تعرف أنها ستدور حول هذه الموضوعات وأمثالها . وإن اضطررت للجلوس ، فلا تجعل ذهنك مركزاً فيما تسمعه ، بل حاول أن تشغل نفسك بشىء آخر ، أو حاول أن تغير مجرى الحديث .",{"h":"وما تسمعه عن أخطاء الناس ، لا تصدقه كله ."},"ربما الراوى الذى روى الحديث لم يراع الدقة ، أو ربما أن الخبر قد تناقل من شخص إلى آخر ، حتى وصل أخيراً بطريقة مختلفة عن الواقع . وربما أن الطرف الآخر له رد على كل هذا الذى يقال . ونحن لا نستطيع أن نحكم على أمر من جانب واحد . وقل لنفسك أيضاً :",{"h":"حتى إن كان كل ما قيل صدقاً ، ما شأنى أنا به ؟"},"استخدم هذه العبارة « أنا مالى خلينى فى حالى » .","اخبار الناس ليست من اختصاصى ، ولا أنا مسئول عنها أمام الله والناس ، وهذا الذى سمعته ، كأننى لم اسمعه ولا علمت به .",{"h":"وهكذا لا تعاود التفكير فيما تسمعه من إدانات ."},"لأن التفكير يثبت الإدانة فى ذهنك ، وربما يتطور الأمر معك . فليكن ما سمعته إذن لا يعدو أن يكون كلاماً عابراً ، لا تعطه عمقاً فى داخلك . ولا تتحدث فيه مع آخرين ، ولا تنقله إلى أحد ، حتى لا يكبر حجمه ...",{"h":"وحاول أن تصلى من أجل الشخص المدان ، ليستر الله عليه ."},"اطلب له المغفرة ، واطلب له الرحمة ، واسأل الله أن يصلحه . ولكن أياك أن تحتقره أو أن تدينه .","قال القديس الأنبا موسى الأسود « إياك أن تسمع بسقطة أحد أخوتك لئلا تكون قد دنته خفية .","* * *"],"85":[{"h":"حجة إصلاح الآخرين"},"إن اتاك فكر أنك إنما تدين لأجل اصلاح الآخرين ، وبدافع من الغيرة المقدسة ، حينئذ قل لنفسك :",{"h":"ليس من أجل إصلاح الآخرين ، أنا أخسر نفسى !"},"وقل أيضاً : هل أنا الذى أقيم نفسى مصلحاً للآخرين ؟ أم إننى مكلف بذلك رسمياً أمام الله ، بحيث يتعبنى ضميرى إن لم أفعل ؟ ثم هل وصلت أنا إلى المستوى الذى أصلح فيه غيرى ؟","وإن كنت قد اؤتمنت فعلاً على وكالة (١كو ٩ : ١٧) ، فلتضع أمامك هذه القاعدة الروحية الهامة :",{"h":"الذى يريد أن يصلح الآخرين ، ينبغى أن يصلحهم بطريقة صالحة ."},"ويأتى ذلك بالحب ، وبالاتضاع ، وبالكلمة اللطيفة الهادئة ، وعدم جرح شعور أحد فيما تريد صلاحه . وأيضاً عدم كشف عيوبه أمام الناس .",{"h":"ولا يمكن أن تصلح أحداً بتعييره أو مسك سيرته ."},"وفى هذا الأمر ما أجمل قول الرب « فيما بينك وبينه وحدكما » (متى ١٨ : ١٥) . ويقول القديس يوحنا ذهبى الفم فى تأملاته حول هذه الآية « اسمعوا ما يقوله المسيح ... وبخه فيما بينك وبينه ، ولم يقل بينك وبين كل المدينة ، ولا بين كل الشعب ... إنه توبيخ فى السر ، لكى يكون الاصلاح سهلاً » .",{"h":"والله يفعل معك مثل هذا ، فى السر أيضاً :"},"فهو حينما يريد أن يبكتك على خطيئتك ويقودك إلى التوبة ، يفعل هذا فى سرّ من الأسرار الكنسية ، فيما بينك وبين كاهنه سراً ، وليس فى اعتراف علنى ..."],"86":[{"h":"وفى الدفاع عن الحق واصلاح الآخرين أذكر قول بولس الرسول :"},"« أيها الأخوة إن إنسبق إنسان ، فأخذ فى زلة ، فاصلحوا أنتم الروحانيين مثل هذا بروح الوداعة ، ناظراً إلى نفسك لئلا تجرب أنت أيضاً » (غل ٦ : ١) .","وأيضاً قول القديس يعقوب الرسول « من هو حكيم وعالم بينكم ، فلير أعماله بالتصرف الحسن فى وداعة الحكمة . ولكن إن كانت لكم غيرة مرة وتحزب فى قلوبكم ، فلا تفتخروا وتكذبوا على الحق . ليست هذه الحكمة نازلة من فوق ... » (يع ٣ : ١٣ ـ ١٥) .","نقطة أخرى وهى : عليك أن تختبر نفسك جيداً :",{"h":"أحقاً أنت تدين من أجل اصلاح الآخرين ؟"},"هل دوافعك هى مجرد غيرة مقدسة خالصة ، غير مختلطة بمشاعر أخرى :","أم أن الدافع الحقيقى هو عدم محبة هذا الشخص ، وحقد مستتر ، أو شماته بإنسان مخطىء ، أو محاولة اظهار أنك تعرف أكثر ، وأنك بالمقارنة أفضل ، وأنك فى موقف المعلم والمؤدب والقائد ... ! اختبر نفسك جيداً .","وإن كنت فى غيرتك تدعى أنك تأخذ حق الله من الناس ،",{"h":"فهل أخذت أولاً حق الله من نفسك ؟"},"هل بدأت باصلاح نفسك ، قبل أن تقوم باصلاح غيرك ؟ هل أصبحت « تبصر جيداً » (متى ٧ : ٥) بحيث تستطيع اخراج القذى من عين أخيك ، دون أن تتلف عينه ؟ على أنه فى موضوع اصلاح الآخرين ، نحب أن نضع أمامك :",{"h":"مثل الزوان والحنطة"},"لقد جاء الخدام إلى الرب يسألونه هل يذهبون فيخلعون الزوان من الحقل ، فأجابهم « لا ، لئلا تقلعوا الحنطة مع الزوان وأنتم تجمعونه . دعوهما ينميان كلاهما معاً إلى يوم الحصاد » (متى ١٣ : ٢٨ ـ ٣٠) ."],"87":[{"h":"إن الله لا يريدنا أن نضيع جهودنا فى خلع الزوان ، بقدر ما يريدنا أن ننمو كحنطة ."},"حتى إذا جاء يوم الحصاد ، نجد سنابلنا مملوءة بثلاثين وستين ومائة ، فتمتلىء أهراؤه قمحاً ...","كثيرون شغلوا أنفسهم بجمع الزوان ، باسم الغيرة المقدسة والاصلاح . وبسبب هذا امتلأوا غضباً وعصبية وصياحاً . وملأوا الجو بالإدانة والانتهار وتوبيخ الآخرين ، والحديث عن أخطاء الكنيسة والجمعيات والخدام والكهنة ، بألفاظ كلها قسوة ، وخالية من الاحترام ومن الأسلوب اللائق المهذب .","ونظر الناس إلى هؤلاء (المصلحين) وصورتهم العصبية وأساليبهم المهينة ، وقالوا : إنها تذكرنا تماماً بصورة الزوان .",{"h":"نعم ، أخشى عليك فى جمع الزوان ، أن تصير أنت نفسك زواناً !"},"إذ تفقد وداعتك واتضاعك ، وتتعلم الشتيمة والإهانة ، ومسك السيرة ، والتعالى على الناس ... كما تتعود قسوة القلب فى احكامك ، بل قد تكره البعض وتعاديهم . وتثور وتضج ... عجباً اتراك من أجل الرب فى كل تلك الخطايا ؟!","نعم احترس ، لئلا فيما تخلع الزوان من الناس ، تخلع أيضاً الحنطة التى فيك : تخلع هدوءك ، وسلامك القلبى ، ودمائة خلقك . وتخلع أيضاً ثمار الروح التى عندك « المحبة والفرح والسلام والوداعة واللطف والتعفف » (غل ٥ : ٢٢) .",{"h":"ومع فقدك كل هذا تجد أنك لم تصلح أحداً !"},"وإنك لاكسبت سماء ولا أرضاً ، ولاكسبت قيادة الناس ، إلى الملكوت ، ولا كسبت هدوءك وعلاقتك مع الناس على هذه الأرض . لاكسبت الناس ، ولا ربحت نفسك ... لأن اصلاح الناس لا يأتى عن طريق الإدانة والتشهير ...",{"h":"يقول القديس أوغسطينوس :"},"« إننا عندما نغتاظ من الأشرار ، فلسنا بعد سوى بشر . وعلينا أن نصغى إلى قول الرسول : من يظن أنه قائم ، فلينظر لئلا يسقط (١كو ١٠ : ١٢) »"],"88":["فلنكن نحن حنطة ، ولا نضيع أوقاتنا فى جمع الزوان . وإذا أردنا أن نجمع زواناً ، فلنجمع الزوان الذى فينا . لنجمع الخطية التى فينا ونخرجها خارجاً .",{"h":"لئلا فيما نحاول اصلاح غيرنا ، ننسى اصلاح أنفسنا ."},{"h":"عجيب أن كل أحد أصبح يقيم نفسه مسئولاً عن الناس !"},"يفكر فى الناس وأعمالهم ، وما ينبغى أن يصدر على أعمال الناس من أحكام ! أما نفسه فهى آخر ما يفكر فيه !","صدقونى إنها حرب من الشيطان أن يشغلنا عن أنفسنا ، بالتفكير فى خطايا الناس ، وأن يشغلنا عن التوبة ، بالتفكير فى أعمال الناس .",{"h":"إن الله فى اليوم الأخير سوف لا يحاكمك على خطايا غيرك . إنما سيحاكمك عن أخطائك وحدك ."},{"h":"الاتضاع وإدانة النفس"},"يمكن معالجة خطية إدانة الآخرين ، عن طريق إدانة النفس ..","* وقد شرح القديس مارأوغريس كيف أن كلاً منهما ضد الأخرى ، فقال :",{"h":"« إن دنا أنفسنا ، وحكمنا على أنفسنا أننا أشرار ، يبدو الناس أمامنا أطهاراً وملائكة . وإذا دنا الناس وحكمنا عليهم بأنهم أشرار ، نبدو نحن أمام أنفسنا أننا ملائكة وقديسين » ."},"* فى إحدى المرات مدح بعض الأخوة شخصاً أمام القديس الأنبا بيمن ، وقالوا فى سياق الحديث إنه يكره الأعمال الشريرة . فسألهم عن معنى عبارة « يكره الأعمال الشريرة » . فلما ارتبكوا فى الإجابة ، قال لهم : « كراهية الأعمال الشريرة هى كراهية الأعمال الشريرة التى نعملها نحن ، وليست الأعمال التى يعملها الناس » ."],"89":["* قال القديس الأنبا باخوميوس « إن الإدانة تأتى من تعظم القلب . أما المتضع ، فإنه يعتبر كل الناس أفضل منه » .","وقال القديس باخوميوس :","« احفظ نفسك من ذلك الفكر الذى يجلب عليك تزكية ذاتك وازدراء أخيك ، لأنه مغبوط جداً قدام الله ذلك الإنسان الذى يكرم غيره ويرذل نفسه »","لذلك كلما يأتيك فكر إدانة لأحد ، تذكر خطاياك . وقل : هذا الإنسان أبر منى ، لأنى فعلت كذا وكذا . ولا يمكن أن يكون هو قد وصل إلى هذه السقطات التى وقعت فيها أنا .","إنك إذا لم تفكر فى عيوبك ، فسوف تقع فى عيوب غيرك .","* لذلك يقول مار إشعياء : إن تركت الاهتمام بخطاياك ولم تنشغل بها ، وقعت فى خطايا غيرك .","* سأل أحد الأخوة شيخاً من شيوخ الرهبنة « ما هو السبب فى أنى أدين الأخوة دائماً ؟ » . فأجابه الشيخ : لأنك لو عرفت نفسك ، لما تفرغت لغيرك . لأن الذى يهتم باخراج الخشبة من عينه ، لا يتفرغ لاخراج القذى من عين أخيه .",{"h":"ولهذا إن فكرت أن تدين إنساناً ، قل لنفسك « أنا أيضاً خاطىء » ."},{"h":"« إن فحصت نفسى جيداً ، ووجدت إننى بلا خطية ، فلأقذفه بهذا الحجر ... »"},"* فى إحدى المرات طردوا أخاً من المجمع ، وأخرجوه خارجاً . فسأل القديس بيساريون عن السبب ، فقيل له بسبب الخطية التى وقع فيها . فقام القديس بيساريون وخرج هو أيضاً خارج المجمع ، وهو يقول : « وأنا أيضاً رجل خاطىء » .","* ومعروفة قصة القديس موسى الأسود ، الذى دعى إلى المجمع لمحاكمة أخ أخطأ . فحضر وهو يحمل على ظهره كيساً مثقوباً ومملوءاً بالرمل . فسألوه لماذا فعل هكذا ؟ فقال « هذه خطاياى وراء ظهرى تجرى ، وقد جئت لأدين أخى على خطيئته !! » ...","* أخ سأل الأنبا بيمن قائلاً « كيف استطيع أن لا أقع فى الناس ؟ »"],"90":["فأجابه : إذا لام الإنسان نفسه ، فحينئذ يكون أخوه عنده أكرم وأعظم . أما إذا نظر إلى نفسه بأعجاب ، يكون أخوه فى نظره خاطئاً ومداناً .","* قال مار اسحق : « مغبوط هو الإنسان الذى يكرم أخاه ، ويدين نفسه . ومغبوط هو الذى يرى فى عيوب الآخرين سقطات نفسه » .","أى أنه كلما يرى عيباً فى الآخرين ، يبحث داخل نفسه ، فسيجد أن هذا العيب فيها . فليلم نفسه بدلاً من أن يدين غيره ...","وإذا رأى الناس يوبخون شخصاً على خطأ معين ، يقول لذاته « هذا القلم على خدك يا ارسانى » .","* * *",{"h":"تدريب لمعالجة الإدانة"},{"h":"١ ـ درب نفسك على معالجة خطايا اللسان جملةً ..."},"فستجد أنك قد تخلصت من خطية الإدانة ضمناً . اسلك فى بعض تداريب الصمت . أو فى تدريب عدم التدخل فيما لا يعنيك ، ولاشك أن خطية الإدانة ستكون ضمن تدخلك فى شئون غيرك .","هذا التدريب سوف يساعدك على مقاومة (الإدانة باللسان) . وسيكون خطوة فى مقاومة الإدانة بالفكر أيضاً بمرور الوقت ، لأنه سيغرس فى قلبك البعد عن الإدانة .","* * *",{"h":"٢ ـ تذكر قول الرب « اذكر من أين سقطت وتب » (رؤ ٢ : ٥)"},"وذلك بأن تجلس فيما بينك وبين نفسك ، وتعرف من هم الأشخاص الذين تدينهم باستمرار ؟ وما هى الموضوعات التى توقعك فى الإدانة ؟ وما هى الجلسات أو الشخصيات التى تكون عثرة لك . ثم تحترس من جهة هذه المصادر التى تتسبب لك فى إدانة الآخرين ."],"91":[{"h":"٣ ـ يمكن معالجة الإدانة بالمحبة :"},"فإن كنت قد فقدتها بالنسبة إلى البعض ، أو فقدت بعضها ، فحاول بقدر إمكانك أن تسترجع ما فقدته . لأن الكتاب يقول عن المحبة إنها « لا تقبّح » « ولا تظن السوء ، ولا تفرح بالإثم » (١كو ١٣ : ٥ ، ٦) ، وبالتالى لا تدين","وتأكد من أن الإدانة تزيد العلاقات سوءاً فبدلاً من أن تسترجع المحبة القديمة ، قد تزداد الهوة عمقاً بينك وبين الذى تدينه ، وبخاصة إذا كان هناك من يوصلون الكلام ، ومن يزيدون عليه . وحتى بدون هؤلاء ، أمام ضميرك وقلبك لن ترتاح ...","* * *",{"h":"٤ ـ تذكر اضرار الإدانة عليك :"},"وما قاله القديسون من أنه بالدينونة قد تفارقك النعمة والمعونة الإلهية ، وهكذا تتعرض للسقوط . وكذلك ما قاله السيد الرب إنه بالكيل الذى به تكيلون ، يكال لكم ويزاد » . كذلك ما توقعك فيه الإدانة من خطايا أخرى تصاحبها .",{"h":"قال القديس بفنوتيوس :"},"احذر أن تقول كلمة ردية على أخيك ، لكى لا يمنعك الله من أرض الميعاد ، وتحرم من أكل ثمرتها ... كما جرى مع شعب اسرائيل بالنسبة إلى موسى ابيهم ويشوع وكالب أخويهم » .",{"h":"وقال شيخ :"},"« إن خطية الوقيعة من شأنها أن لا تترك صاحبها يحضر قدام الله ، لأنه مكتوب « إنى كنت اطرد من يغتاب قريبه سراً » (مز ١٠١ : ٥)",{"h":"وابتعد عن الإدانة خوفاً من السقوط ، وخوفاً من العقوبة ."},"ولا مانع من أن تضع فى ذهنك بعض آيات الكتاب الخاصة بالإدانة : تحفظها وتردد ها ، وتتأملها بين الحين والآخر .","* * *"],"92":[{"h":"٥ ـ تدرب أنك لا تظن السوء بالناس ، ولا تحكم حكماً سريعاً ."},"فقد يكون الظن السىء فيه ظلم ، وكذلك الحكم السريع . ولذلك لا تحكم على أحد دون فحص ، وبسرعة . بل تعوّد التروى والتأنى فى أحكامك عموماً ، سواء ما لك حق فيه ، وما ليس لك فيه حق .",{"h":"واحترس من أن تلبس نظارة سوداء ، تنظر بها إلى الناس ."},"* * *",{"h":"٦ ـ تعود الشفقة على الناس فى أحكامك :"},"حاول أن تأخذ الجانب الذى يتراءف ، وليس الذى يقسو . وفكر فى قلبك ، ربما تجد عذراً يخفف من الحكم . وفى اشفاقك صلّ من أجل المذنب ، فالصلاة تزيد مشاعر الشفقة ، كما أن الشفقة تدفعك إلى الصلاة .","* * *",{"h":"٧ ـ ولا تكون الإدانة حسب الظاهر :"},"فربما تجد رجلاً يبكى أمام كنيسة أو جمعية ويطلب مالاً لأنه لا يجد طعاماً لنفسه وأولاده ، ومع ذلك لا يعطيه أحد . فتقول « ما أقسى هؤلاء الناس الذين لا يرحمون جائعاً !! بينما لو سألت لعلمت أنه يأخذ كثيراً ، ربما أكثر من حاجته ، ولا يكتفى . ويقوم بمثل هذا الموقف الباكى المستغيث لمجرد الاحراج والضغط أمام الناس ، لأخذ المزيد بدون استحقاق !","* * *",{"h":"٨ ـ درّب نفسك أن تحتمل من يسيئون إليك :"},"فأحياناً عدم احتمالك لهم ، يجعلك تتبرم بهم ، وتشكوهم ، وتتحدث عن أخطائهم أمام كل أحد ، وتدينهم بمقدار ما أنت متضايق منهم .","أعرف أننا لا نعيش فى عالم كله مثالية . بل توجد أخطاء . وإن ثار قلبنا على كل خطأ ، وانتقلت الثورة إلى ألسنتنا ، فأخذت تدين وتنشر أخطاء الناس ، وتهدد"],"93":["وتعاقب ... لاشك أننا أنفسنا لن نستريح ، كما أننا لا نريح أحداً .",{"h":"كثير من أخطاء الناس ، تحتاج منا أن نجوز مقابلها ، ونمررها بالصبر والاحتمال كأن لم نتحدث ، دون أن ندين أصحابها ..."},"* * *",{"h":"٩ ـ احترس من إدانة شخص على عيب خَلْقى لا ذنب له فيه :"},"أو تجعله مجالاً للهزأة والاستهتار والتهكم بسبب شكله ، أو عقله ، أو تشويهه ، أو قصره ، أو سمنته الزائدة ، أو ما شابه ذلك . لأنه ليس من العدل أن يحكم على إنسان بسبب شىء هو خارج ارادته .","* * *",{"h":"١٠ ـ كن حريصاً جداً فى الإدانة بطريق العتاب :"},"لأنه وإن كان الله قد صرح بالعتاب (متى ١٨ : ١٥) ، إلا أنه ليس كل إنسان يحتمل العتاب . وكم من عتاب أتى بنتائج سيئة جداً . ولذلك قال الكتاب « من يوبخ مستهزئاً يكسب لنفسه هواناً ، ومن ينذر شريراً يكسب عيباً . لا توبخ مستهزئاً ، لئلا يبغضك . وبخ حكيماً فيحبك » (أم ٩ : ٧ ، ٨) .","* * *",{"h":"ـ ختاماً : لا تجعل خطية الإدانة تصبح طبعاً من طباعك :"},"فهناك فرق بين الإدانة العابرة . والإدانة التى تصير منهج حياة ، أو صفة ملازمة لإنسان . حيثما يوجد يدين ويحكم ويتناول سير الناس بالنقد والتحليل ، بسبب وبدون سبب !!","* * *"]}},"shukr_life":{"id":"shukr_life","title":"حياة الشكر","author":"قداسة البابا شنوده الثالث","url":"https://drive.google.com/file/d/1jpgfORhVhisGktXRc0sGCWjOCxGdPDCO/view","file":"حياة_الشكر.pdf","pageOffset":5,"review":{"status":"needs-review","note":"نُقل الكتاب (من مقدمة الناشر إلى الخاتمة، ص٣ إلى ص٢٦ بترقيم الملف) بقراءة الصفحات الممسوحة بالنظر؛ الأصل مطبوع بالآلة الكاتبة بلا همزات فأُثبتت الهمزات والتشكيل الإملائي المعتاد، وبعض الكلمات في حواف الصفحات المضببة قُرئت بأفضل ما تيسر وتحتاج مطابقة نهائية مع الأصل."},"chapters":[{"title":"مقدمة الناشر","from":3,"to":3},{"title":"حياة الشكر والإيمان","from":4,"to":12},{"title":"الإرادة البشرية والتدبير الإلهي وعشر بركات للشكر","from":13,"to":22},{"title":"حياة الشكر تستلزم الاتضاع والخاتمة","from":23,"to":26}],"transcribed":[3,26],"pages":{"3":[{"h":"مقدمة"},"تحوى هذه النبذة إحدى محاضرات قداسة البابا المعظم الأنبا شنودة الثالث التى ألقاها ـ وأربعاً أخرى غيرها ـ بالمؤتمر الأول لخدام التربية الكنسية بالإسكندرية عام ١٩٦٨ بكنيسة القديس مارمينا بالمندرة ـ وكان قداسته عندئذ أسقفاً للتعليم ـ وقد سبق لمكتبة كنيسة السيدة العذراء بمحرم بك أن طبعت المحاضرات الخمس المذكورة طبعة أولى عام ١٩٧١ ـ وهو أول عام لتبوا قداسته السدة الرسولية .","ولقد نفذت الطبعة الأولى لتلك المحاضرات وإزاء الإلحاح فى طلبها رأينا أن نقوم بإعادة طبعها واحدة بعد الأخرى وها نحن نقدم الطبعة الثانية لهذه المحاضرة عن",{"h":"حياة الشكر"},"راجين الرب أن يجعلها لخير القراء ولبركة حياتهم وشركتهم فى الرب . ببركة صلوات قداسة البابا المعظم الأنبا شنودة الثالث أطال الله حياته ورئاسته للكنيسة سنين عديدة وأزمنة سالمة مديدة ـ آمين .","الكنيســــة"],"4":[{"h":"حياة الشكر والإيمان :"},"إن حياة الشكر مرتبطة بأمور أخرى تسبقها وتندمج معها ... فحياة الشكر تلزمها حياة الإيمان ، الإيمان بالله فى صفات معينة بدونها لا يمكن أن نصل إلى حياة الشكر ... فلابد أن تؤمن أولاً أن الله صانع للخيرات ، وثانياً أنه محب البشر . فالله لابد أن يصنع خيراً ـ لا يستطيع أن يصنع إلا الخير ـ وهو باستمرار يصنع خيراً معك ومع باقى الناس . ولابد أن تؤمن ثالثاً أن الله قادر على كل شىء ـ هو يحبك ويريد أن يصنع معك خيراً ، وهو قادر على صنع الخير ... هذه الصفات الثلاث تجعلك تثق بأن الله يصنع دائماً خيراً .","وهنا تقابلنا مشكلة وهى أن الله مع أنه يصنع الخير ، إلا أنه أعطى حرية للناس ، والناس قد يصنعون شراً ... فربما يأتيك الشر من الناس فاعلى الإثم وليس من الله . وهنا لابد أن تؤمن رابعاً أنه توجد صفة أخرى لله تضعها إلى جوار هذا فتستريح وهى صفة الله كضابط الكل ،"],"5":["يرقب كل أحد ... فالحرية التى أعطاها للناس لا تعنى أنه تخلى عن إدارته للكون ، وترك كل إنسان يفعل ما يريد . إنما الله يعطى الحرية ويرقب ويقود ويلاحظ كل شىء ، ويغير ما يحتاج إلى تغيير ، ويمنع ما يراه ضاراً ... هو ضابط الكل . هذه الصفة تريحك من جهة حرية الناس وحرية الشياطين وأيضاً حريتك الشخصية ... لأن الشر الذى يأتيك ربما يكون صادراً عن حرية الناس الأشرار أو عن حريتك الشخصية التى بها تضر ذاتك ، أو عن محاربة الشياطين ... والله ضابط الكل يتدخل فى كل هذه الأمور وينفذ مشيئته الصالحة الطوباوية . فالله لا يمنح الحرية مطلقة ... وإلا هلك العالم . حتى الشياطين الأشرار الذين هم بطبيعتهم الملائكية الروحية لهم قوة تفوق الطبيعة ، إلا أنهم ليسوا أحراراً فيما يعملون ... ففى قصة أيوب مثلاً نلاحظ أن الشيطان كانت حريته محدودة . كان يقترح أموراً ، والله يسمح له أو لا يسمح ، ويضع له حدوداً وقيوداً معينة ... قال له أولاً هوذا كل ما لأيوب فى يدك ، وإنما إليه لا تمد يدك (أى ١ : ١٢) . وفى المرة الثانية سمح له أن يمد يده إلى جسد أيوب دون عقله أو نفسه ... حتى الشيطان ، يحدد له الله عمله ويقيده ولا يترك له الحرية المطلقة ... فلهذا اطمئن ، لأن الله صانع الخيرات ، محب البشر ، ضابط الكل ، يرعاك ويهتم بك ولا يسمح أن يأتيك ما يضرك ، وإن آمنت بهذا لابد أن تشكره على عنايته ."],"6":[{"h":"الشر وصانع الخيرات"},"وهل نشكر الله على الشرور التى يسمح بها ؟ ... طبعاً نشكره . نحن نشكر الله على كل حال ومن أجل كل حال وفى كل حال . أشكر الله الذى يستطيع أن يحول الشر إلى خير ... بعين الإيمان انظر إلى هذه المتاعب فى ضوء تدخل الله وتحويله لها إلى الخير ... وإليك المثل :","يوسف الصديق : فعل به إخوته شراً ، باعوه كعبد ... ولكن الله الذى يخرج من الجافى حلاوة ، استطاع أن يحول هذا الشر إلى خير . لذلك قال يوسف لإخوته أخيراً « أنتم قصدتم بى شراً والله قصد به خيراً » (تك ٥٠ : ٢٠) . إمرأة فوطيفار الشريرة أرادت بيوسف شراً ، ودفعت له تهمة كاذبة ألقت به فى السجن ... ومع ذلك فالله حول هذا الشر إلى خير بالنسبة ليوسف شخصياً ولأرض مصر والعالم كله ... ! لأن يوسف كان سبب بركة لمصر فى المجاعة وللعالم المحيط بها الذى انتفع من تدبير يوسف لها . فلو آمنت بالله أنه يحول الشر إلى خير ستعيش فى حياة شكر كامل ، على كل ما يحل بك . لذلك لا تتعب أبداً ... إن كان الذى يحدث لك خيراً فى ذاته ، فسيصلك هذا الخير . وإن كان شراً ، فإن ضابط الكل سيقابله فى الطريق ويحوله إلى خير ليصلك خيراً ."],"7":[{"h":"الصبر وحياة الشكر"},"إننا بحياة الإيمان نرتاح ونشكر الله على كل أعماله الصالحة معنا . وإلى جوار هذا لابد أن تكون صبوراً وطويل الأناة ... لأن هناك أعمالاً تتحول إلى خير فى مدى زمن طويل يحتاج منك صبراً . ففى قصة يوسف الصديق : بيعه كعبد لم يتحول إلى خير فى نفس السنة . القاؤه فى السجن لم يتحول إلى خير فى نفس السنة ... ولكن بالمدى الزمنى وبمرور الوقت رأينا الخير الذى نتج عن ذلك . فعليك أن تكون طويل الأناة واثقاً فى حكمة الله ورحمته وتدخله فى الوقت المناسب بالطريقة المناسبة .",{"h":"الأهواء الشخصية وحياة الشكر"},"من الأمور المهمة فى شعور الإنسان بالخير وبالشر وما يترتب عليه من شكر أو تذمر ، رغباتنا الداخلية ونوع تقييمنا للأمور ... كتب القديس يوحنا ذهبى الفم مقالاً جميلاً عنوانه « لا يستطيع أحد أن يضر أحداً إلا إذا أضر الإنسان نفسه » ... بدون فهم هذا الموضوع لا تستطيع الوصول إلى حياة الشكر . ما الذى يستطيع إنسان ـ أو حتى شيطان ـ أن يضرك به ... ؟ لو كنت أنت إنساناً قديساً ، صالحاً ، باراً ، تحب الله ... سيكون لك هدف واحد فقط هو الإلتصاق بالله ورغبتك هى فقط فى"],"8":["ملكوت السموات . وهذا لا يستطيع أحد أن يضرك فيه . أما إذا جمعت لنفسك أهدافاً ورغبات أخرى أضفتها إلى الله ... فهذه هى التى تضرك . قلبك من الداخل ـ المحب لهذه الرغبات ـ هو الذى يضرك وليس الناس . قد يستطيع أحد أن يأخذ منك مالاً ، فإذا كنت لا تهتم بالمال فى كثرته أو قلته فلا تضر . قد يستطيع أحد أن يزج بك فى السجن ، فإذا كنت لا تهتم إلا بحرية ضميرك وفكرك وقلبك فى علاقتك مع الله ، ولا تهتم بالمكان الذى تعيش فيه ولا بالحالة الأرضية ، عند ذلك سوف لا تشعر بضرر . فبولس الرسول كان فى أعماق السجن وكان يرتل بفرح ... ماذا يصنع بك الناس من الخارج ؟ أيقتلونك ؟ وماذا يضرك هذا إن كان لا هدف لك سوى الحياة مع المسيح ؟! ... الشهداء عذبوا وقتلوا ، ولم يشعروا أنهم قد أصيبوا بضرر ، لأن الضرر الوحيد هو الإنفصال عن الله وهذا يتعلق بالقلب من الداخل وليس بالناس ... يوسف الصديق صار عبداً ولم يتعب ، لأن الحرية لم تكن هى هدفه ، وكذلك السجن لم يفصله عن الله ... الضرر الوحيد هو انفصالك عن الله ، وهو لا يأتى إلا بانحراف إرادتك الشخصية نحو الشر ، وتكون أنت الذى آذيت نفسك وليس إنسان آخر ."],"9":[{"h":"التجارب وحياة الشكر"},"قد يفقد الناس حياة الشكر عندما يقعون فى أحزان ومتاعب متنوعة . أما رجال الله القديسون الذين لا تتعبهم كل هذه الأمور ، ولا يتعبهم إلا الإنفصال عن الله ، فكل ضيقات العالم لا تتعبهم . هم يعيشون فى شكر دائم فى كل حال ، فى الفقر وفى الغنى ، فى السعة وفى الضيق ، فى المرض وفى الصحة ، فى الموت وفى الحياة ... دائماً يشكرون لأن الهدف الوحيد وهو الإلتصاق بالله ، لم يفقدوه فى كل هذه الحالات . لذلك هم فرحون متهللون شاكرون . لو ضاع منى كل شىء وبقى لى الله وحده ، فماذا معى كل شىء ، لأن الله هو الكل فى الكل ، فما الذى يحزننى ؟ ... يقول بولس الرسول « لذلك أسر بالضعفات » (٢كو ١٢ : ١٠) ... لماذا ؟ لأن الضيقات تقربنى إلى الله أكثر ، وتجلب لى أكاليل أكثر ... فما الذى يحزننى ؟ أشكر الله على كل حال ... فى الصحة وفى المرض ... ولماذا أشكر الله فى المرض ؟ لأنه ليس شراً فى ذاته « لعازر المسكين المذكور فى قصة « الغنى ولعازر » كان مثقلاً بالأمراض ، وكانت عنده قروح كثيرة والكلاب تلحس هذه القروح ... لكن هذا كله لم يكن شراً فى ذاته ولم يفصله عن الله ، بل على العكس كان للفائدة . فعندما اتكأ فى"],"10":["أحضان إبراهيم ، قدم عنه تقريراً أنه « استوفى بلاياه على الأرض لذلك هو يتعزى » (لو ١٦ : ٢٥) . هكذا فلتشكر الله فى المرض لأنك قد تستوفى به البلايا وتأخذ نصيب لعازر المسكين ."],"11":[{"h":"لا نعلم ما نصلى لأجله"},"قال القديس باسيليوس الكبير « وإن كنت مريضاً لا تطلب من الله صحة ، لأنك لا تعرف ما هو المفيد لك ـ الصحة أم المرض ؟ » . طبعاً نحن بضعفنا البشرى نطلب الصحة لكننا لا نعرف روحياً ما هو المفيد ... ربما يتعبنى المرض على الأرض لكنه يضمن لى ملكوت السموات إذا كان استغلالى له حسناً . من المعروف عن المهاتما غاندى أنه كان يكره الطب والمستشفيات ـ لا نريد مناقشة الرأى كله وإنما نعرض فقط وجهة نظر غاندى فى المستشفيات . إنها تعطى الإنسان صحة جسدية ربما يغضب بها الله ... وربما ينهمك بها فى الإثم ويخسر الله ! . ولذلك كان غاندى يهتم بالعلاج الروحى والنفسى أكثر من العلاج الجسدى . ما معنى أن شاباً مريضاً يعطى صحة يستغلها فى الزنى والفسق ! . ما معنى أن إنساناً شريراً يعطى صحة يستغلها فى الظلم والسرقة والفساد ! ... هل كانت هذه الصحة للفائدة أم للضرر ؟ فالمهم إذن الصحة الروحية . حكى فى بستان الرهبان عن أحد الرجال الأثرياء النبلاء أن كانت له ابنة وحيدة مريضة مشرفة على الموت ، فطلب من أحد القديسين أن يصلى من أجلها لتشفى . فحاول القديس أن يعتذر بشتى الطرق ، ولكن الرجل ألح عليه ، فصلى القديس وعاشت"],"12":["الفتاة . إلا أنها سلكت فى سيرة شريرة أضاعت بها كرامة أبيها ، لدرجة أنه عاد إلى القديس وقال له « صلّ لكى يأخذ الله الفتاة » ... فأجابه « أنت طلبت مشيئتك الخاصة » نحن لا نعرف يا إخوتى ما هو المفيد لنا ... ومع ذلك كثيراً ما نطلب الصحة ، ولا يكون طلبنا هذا خاطئاً ، ولكن لو تمسكنا به نخطىء . بولس الرسول أعطى شوكة فى الجسد لئلا يرتفع من فرط الإعلانات . وقد طلب إلى الله أن يفارقه هذا المرض إذ قال : « إلى الله تضرعت ثلاث مرات أن يفارقنى » (٢كو ١٢ : ٨) . ولكنه لم يستجب !! رفض الله صلاة بولس الرسول قائلاً : « تكفيك نعمتى » (٢كو ١٢ : ٩) . فالمرض كان صالحاً له ."],"13":[{"h":"الإرادة البشرية والتدبير الإلهى"},"إن مشكلتنا فى حياة الشكر هى أننا نريد أن ندبر أمورنا بعقليتنا وطريقتنا الخاصة ـ فإذا لم تمط طلباتنا نغضب . وقد لا نغضب ولكن أيضاً لا نشكر وهناك فرق بين إنسان شاكر وبين إنسان غاضب . فإذا شكرنا الله فمعنى ذلك أننا نرى الخير فى كل عمل الرب معنا .","وإذا كان الله يقول فى كتابه المقدس : من يعرف أن يعمل حسناً ولا يعمل فذلك خطية له (يع ٤ : ١٧) فبالحرى ـ يعمل هو الخير إذ باستطاعته أن يعمل ـ وبالضرورة لابد أن أؤمن بأن الله يصنع خيراً معى وهو فعلاً يصنع ذلك .","ولماذا إذن تتتابنى أتعاب ـ كل ذلك بسبب إرادتى أنا المنحرفة . لأن الله يصنع دائماً معى خيراً ، لكنه لا يرى من الخير أنه يسلبنى هذه الإرادة التى بها أضر نفسى أحياناً . أما هو فينبغى أن أشكره فى كل حين ... إن كانت حالتى سيئة ، فكان ممكناً أن تكون أسوأ لو تخلت عنى نعمة الله . الله يصنع معى خيراً ، ولكننى لا أصنع خيراً مع نفسى ، فينبغى أن أشكر الله وألوم نفسى ... ولنطرق بعض نواحى تفصيلية ."],"14":[{"h":"لماذا أشكر الله ... ؟!"},"لعل من أجمل القطع الروحية التى سمعتها وقرأتها فى حياتى فى نواحى الشكر هى القطعة الموجودة فى القداس الغريغورى « قدوس قدوس أنت أيها الرب وقدوس فى كل شىء » وأولها التى يبدأ فيها الكاهن نيابة عن الشعب فى شكر الله على كل شىء إذ يقول ... « خلقتنى إنساناً كمحب البشر ولم تكن أنت محتاجاً إلى عبوديتى بل أنا المحتاج إلى ربوبيتك . من أجل تعطفاتك الجزيلة كونتنى إذ لم أكن . أقمت السماء لى سقفاً وثبت لى الأرض لأمشى عليها . من أجلى لجمت البحر . من أجلى أظهرت طبيعة الحيوان . أخضعت كل شىء تحت قدمى . لم تدعنى معوزاً شيئاً من أعمال كرامتك ... الخ » .","ومن هذه القطعة نستطيع أن نتأمل بركات :","١ ـ أشكر الله لأنه خلقك : من منا يشكر الله لأنه خلقه وأنعم عليه بالوجود ؟ توجد أشياء كثيرة ننساها ، ليتنا نتذكرها ... هل تشكر الله لأنه أوجدك ؟ كان ممكناً ألا تخلق على الأرض . الله لم يكن مطالباً بأن يزيد العالم واحداً ! . كان ممكناً أن تكون والدتك عاقراً ولا تلد بنين ، وكثير من النساء عواقر . إن مجرد ولادتك نعمة عظيمة من الله إذ"],"15":["يقول فى المزمور : « البنون ميراث من الرب » وكان ممكناً ألا يعطى والدك هذا الميراث ، أو أن ينجبا إخوتك فقط ولا ينجباك أنت بالذات .","٢ ـ أشكر الله لأنه خلقك فى اليوم السادس : الله قبل أن يخلقك صنع من أجلك أشياء كثيرة ... نحن نشكر الله ليس لأنه خلقنا فقط ، بل أيضاً لأنه خلقنا فى اليوم السادس ... لماذا لأنه أعد كل شىء لراحتنا قبل أن يخلقنا . لذلك نقول فى القداس « أقمت السماء لى سقفاً وثبت لى الأرض لأمشى عليها . من أجلى لجمت البحر ! من أجلى أظهرت طبيعة الحيوان ، أخضعت كل شىء تحت قدمى » فالله أعد كل شىء قبل أن يخلق الإنسان : خلق السماء وزينها بالشمس والقمر والكواكب وخلق النور ، خلق الأرض والنبات والحيوان ... خلق الإنسان بعد أن أعد له كل نواحى الراحة ، وبعد أن ضبط القوانين الطبيعية سواء قوانين الفلك والسماء أو القوانين الأرضية من جهة الأمطار والرياح والحرارة والرطوبة ... الخ . بعد أن دبر كل شىء خلق الإنسان ... أشكر الله من أجل المواهب الإنسانية التى أعطاك إياها ... الذكاء والعقل والنطق والمشاعر والحواس ... من أجل كل الأشياء الطبيعية التى كثيراً ما ننساها عندما نشكر الله ."],"16":["٣ ـ أشكره لأنه خلقك مسيحياً : أشكر الله أيضاً لأنه جعلك تولد مسيحياً لأن كثيرين يشتهون هذا الإيمان ولا يجدونه . بل ويتعبون من أجله كثيراً ، ولا يستطيعون الوصول إليه ، إذ تقف أمامهم كثير من المشاكل العقائدية والمتاعب والمشاكل الاجتماعية وغير الاجتماعية ... أما أنت فوجدت فى هذا الإيمان وفى هذه العقيدة ...!! أشكر الله على هذا .","٤ ـ أشكره لأنه وهبك الصحة والحواس وجميع الأعضاء : أشكر الله أيضاً على الصحة التى أنت فيها ، من منا يشكر الله لأنه يبصر ؟ لكن إذا تعبت عيناك وبدأت تعالجهما ، تبدأ فى الشعور بنعمة البصر التى لم تشكر الله عليها من قبل . أنا لا أبدأ أشكر الله على رجلى التى أسير بهما حسناً إلا بعد أن تبدأ فى التعب وابتدىء أحتاج إلى عصا استند إليها ...!! أنت لم تشكر الله لأن معدتك تهضم الطعام جيداً ، ولكن إذا حدث لها تعب أو نقص فى العصارات ! أو أصبت بقرحة فى المعدة ... حينذاك تبدأ تشعر أنك كنت فى نعمة لم تشكر عليها ...! صدق الحكيم فى قوله « الصحة تاج فوق رؤوس الأصحاء لا يعرفه إلا المرضى » نحن لا نحس قيمة الشىء الذى عندنا إلا عندما"],"17":["نفقده ، فنندم لأننا لم نشكر عليه ... كثير من الناس يشتهون الوضع الذى أنت فيه ولا يجدونه . فاشكر الرب .","٥ ـ أشكره لأنه يعطيك فرصة الحياة من أجل التوبة : أشكر الله لأنك لازلت فى الحياة ... قال أحد الكتاب كلمة تستحق التسجيل « إن ملايين الملايين من الذين فى الجحيم يشتهون ساعة من حياتك أنت على الأرض » ... على الأقل يتوبون فيها ، يقدمون له اعترافاً وانسحاقاً ويكسبون ملكوت السموات ... أما أنت فعندك حياة طويلة لا تشكر عليها . ولو حلت بك سكتة قلبية تقول يا رب دقيقة واحدة فقط أشكرك عليها ، دقيقة واحدة أتوب فيها ... لا توجد . ضاعت الفرصة وعندما تذهب إلى الجحيم تقول لو كان اعطانى الله دقيقة أقول فيها عبارة المشار ... ولو أقول عبارة اللص اليمين ... ولو أقدم توبته ...!! ملايين الملايين من الذين فى الجحيم يشتهون دقيقة واحدة من عمرك ، ولا يجدون . لو أن الله أخذ منك الروح الآن ، ألا تشتهى هذه الدقائق ، وتتمنى لو أعطاك الله نصف ساعة فقط ! وتقول أعترف فيها بكل شىء بالتفصيل حتى بالذى أخجل منه ، حتى بما لا يقال ، حتى بما يقف على لسانى ... أقوله بدون حرج وآخذ عنه حلاً ... لو أعطانى الله نصف ساعة أتصالح فيها مع من أخاصمهم ، وأعتذر لهم ، وأقدم لهم مائة مطانية ( سجود ) تحت أرجلهم ، حتى لو كانوا هم المخطئين ..."],"18":["نصف ساعة يا رب ... لا يوجد ـ أغلق الباب . لماذا إذا لا تشكر الله على الحياة التى لك ؟ ... وعلى هذه الساعات التى مازالت لك فى العمر وتستطيع أن تعمل فيها الكثير ، وتضمن ملكوت السموات ، وتتوب وتحيا حياة روحية ؟ ... ألا تشكر الله إلا إذا نزل لك كنز من السماء ...؟! وما أدراك ـ ربما إذا نزل لك كنز من السماء يكون سبباً فى هلاكك وتفقد الملكوت بسببه .","٦ ـ أشكره لأنه يهيىء لك الحياة فى بيئة مسيحية : هناك أشياء كثيرة تستحق الشكر ، لا نشكر الله عليها . من منكم يشكر الله لأنه موجود الآن فى الكنيسة ؟ كثير من الشبان فى هذه اللحظة فى أماكن اللهو المختلفة وفى خطايا كثيرة ، وأنتم موجودون فى الكنيسة . فمن منكم يشكر الله ؟ لمجرد وجوده حتى لو كان لا يفهم الكلام أو لا ينسجم منه ... أشكر الله على هذا . من منا يشكر الله لأنه أوجد له بيئة مسيحية صالحة من أبوين مباركين لم يمنعاه عن طريق الرب ؟ وهيأ له بيئة مسيحية من خدام فى الكنيسة يعتنون به حتى وصل إلى هذا الوضع من المعرفة الروحية والسلوك الروحى ؟ ... توجد أشياء كثيرة تستلزم الشكر ونحن لا نشكر عليها ."],"19":["٧ ـ أشكره لأنه يرعى كل أمور حياتك : يوجد أيضاً عنصر آخر هو إحسانات الله إليك ... الإحسانات الشخصية فى حياتك عموماً وفى حياة أحبائك . كم مرة طلبت من الله طلباً واستجاب ؟ فى ضيقات انتقذك منها ، فى امتحانات أنجحك فيها ، فى مشاكل وفى قضايا كانت نتيجتها فى صالحك ، فى أمراض شفاك منها ، فى ضيقات انتقذك منها ، فى خطايا لم تكتشف أمام الناس ... أريد أن أذكر كم بمثل بسيط ... فى سنة ١٩٤٧ كان مرض الكوليرا منتشراً وكان يحصد بالآلاف . وأغلقت كثير من المدن خوفاً من نقل العدوى وكان الرعب حالاً فى البلاد ... دخلت مرة إحدى هذه المدن المغلقة بتصريح بعد التطعيم ضد الكوليرا طبعاً ، ولم أسمع أحداً يضحك ، ولا يبتسم ، ولم يكن يسمع صوت راديو ولا أغانى ... وكانت المدينة حزينة مكتئبة . وكثيرون صلوا وقالوا « يارب لو أنقذتنى من الكوليرا سأبنى مثل مارجرجس ، مثل الملاك ميخائيل ، مثل الأنبا أنطونيوس أب الآباء » ... وأنقذنا الله من الكوليرا وعشنا إلى الآن ، من منا يشكر الله لأنه نجا من الكوليرا ؟ راحت ونسيت وضاعت ... ومن هذا كثير .","نحن ننسى إحسانات الله ـ وعندما ننساها يقل شكرنا وأيضاً تقل محبتنا . لأنك إذا تذكرت جميل أحد عليك ،"],"20":["تحبه . وعندما تنسى هذا الجميل تفقد المحبة . لذلك من التداريب الجميلة أن يجلس الإنسان إلى نفسه وبعد إحسانات الله إليه ... خذ ورقة طويلة واجلس أكتب إحسانات الله إليك منذ ولادتك إلى الآن ، وإحساناته إلى أحبائك ، وعدد الصلوات التى استجيبت فى حياتك ، والخيرات التى أتتك بدون صلوات ـ من الله رأساً ... عدها كلها ، ثم قف واشكر الله على كل أمر واحد فواحد .","٨ ـ أشكره من أجل الفداء العظيم : يوجد أمر أعظم من هذا كله بكثير ولا يقاس إلى جواره آخر ويحتاج إلى شكر ، الليل والنهار ... وهو الخلاص العظيم الذى قدم إلينا على الصليب ... من منا يشكر المسيح لأنه صلب من أجلنا ... ؟ لأنه تجسد من أجلنا وسكب دمه من أجلنا ... ؟ إن حكم الموت الذى وقع على البشرية ، ما كان ممكناً لأحد أن يخلص منه بدون تجسد الإبن وبدون صلبه وموته ... فالإنسان أخطأ إلى الله ... وكانت خطيته غير محدودة لأنها موجهة ضد الله غير محدود ، وعقوبتها غير محدودة . إن قدمت من أجلها كفارة ، فلابد أن تكون كفارة غير محدودة . ولا يوجد غير محدود إلا الله ... فكان لابد أن يتجسد الله وأن يموت عنا ـ والله دفع هذا الثمن ...! لو فرضنا أن الله لم يدفع هذا الثمن ، فماذا تكون النتيجة ؟ كلنا إلى الهلاك الأبدى . ولكن المسيح أنقذنا جميعاً ... من"],"21":["منا كل يوم وكل ليلة يذكر صليب المسيح ويشكره لأنه دفع الثمن نيابة عنا ؟ بدون هذا الثمن ماكان ممكناً أن تنفع الأعمال الصالحة ولا التوبة ولا أى شىء ... الله فينا نحن خطاة ، فيما نحن محكوم علينا بالموت ، مات المسيح من أجلنا ونحن فجار . أعطانا خلاصاً لا نستحقه ولم نبذل فيه جهداً ... خلاصاً مجانياً على الصليب « متبررين مجاناً بالنعمة ... » من منا يشكر المسيح على هذا ؟ لقد وضعت لنا الكنيسة أن نذكر هذا الأمر فى مناسبات عديدة حتى لا ننساه ... فى كل سنة تقيم لنا أسبوع الآلام ، أسبوع البصخة ويوم الجمعة العظيمة بذكرياته الجميلة المؤثرة حتى لا ننسى الصليب . فهل يكفى هذا التذكار السنوى ؟ لا يكفى ، لأننا ننسى ... ماذا تعمل الكنيسة ؟ جعلت كل يوم جمعة فى الأسبوع صوماً لنتذكر فيه صليب المسيح لئلا ننسى ... فهل يكفى هذا التذكار الأسبوعى ؟ لا يكفى أيضاً . جعلت لنا الكنيسة صلاة الساعة السادسة من كل نهار وفيها نقول « يا من فى اليوم السادس وفى الساعة السادسة سمرت على الصليب من أجل الخطية ... الخ » لابد أن نتذكر هذا الصليب كل يوم لكى نمتلىء بحياة الشكر ، وفى كل يوم نشكر الله لأنه أعطانا خلاصاً هذا مقداره ... وإلا نكون غير شاعرين بهذا الخير ولم نفهمه ..."],"22":["٩ ـ أشكره من أجل عطيته السماوية : من منا يشكر الله لأنه أعطانا هذا الكتاب المقدس ؟ أليست هذه نعمة تستحق الشكر ... !! العالم عاش فى ظلمة الوثنية زمناً طويلاً لم توجد فيه كلمة خلاص واحدة ـ والله أرسل لنا الأنبياء وأرسل لنا الرسل وعلمونا وأفهمونا وتركوا لنا هذه الذخيرة العظيمة ... فى صلاة القداس الغريغورى يقول الكاهن « أعطيتنى علم معرفتك . » ويقول أيضاً « أرسلت لى الناموس عوناً ... » نحن نشكر الله من أجل أنبيائه ومن أجل رسله ومن أجل كتابه المقدس ومن أجل هذا التعاليم . لو عاش الإنسان حياة الشكر ، يشكر الله على كل شىء .","١٠ ـ وأخيراً شكر بلا حدود ... فإنا لا أستطيع مطلقاً أن أحصى إحسانات الله ... أو أن أحصرها ، أو أن أعطيك قائمة بها . إنما ذكرت فقط بعض الأمور الجوهرية التى تنير لنا السبيل . أما أنت لو عشت حياة الشكر ، تستطيع أن تشكر الله عن كل نفس تتنسمه ، على كل خطوة تخطوها ، على التوبة ، على قيامك من سقطتك ، على جميع مواهبه لك ، على روحه القدوس الذى يعمل فيك ، على نعمته التى تفتقدك كلما تسقط وكلما تخطىء ، وتفتقدك فى حالة قوتك لكى تزيدك قوة وتنميك ... تشكر الله على كل حال ومن أجل كل حال ."],"23":[{"h":"حياة الشكر تستلزم الإتضاع"},"ولكى تشكر جيداً تحتاج فى حياة الشكر إلى الإتضاع والإنسحاق . فالشخص المتضع يشعر أنه لا يستحق شيئاً ... لذلك هو يشكر على كل شىء . لو اعتبرت أنك تستحق أشياء كثيرة ، لأوصلك هذا إلى حياة التذمر والضجر ... لماذا ؟ من أجل الكبرياء وليس من أجل الضيقات الخارجية ! الإنسان فى كبريائه يشعر أنه يستحق أشياء كثيرة ، يستحق حياة أفضل ، فيتذمر على ما هو فيه ... لو كان متضعاً ، لشعر أنه لا يستحق شيئاً ، فكل ما يعطى له من الله مهما كان قليلاً يشكر عليه ، لأنه لا يستحقه . الرجل الفقير الذى تعطيه قرشاً يشكرك عليه لأنه شاعر أنه لا يستحق . ليس له عليك شىء ... فكل ما تعطى له ـ حتى كسرة خبز ـ يشكرك عليها ... فلو كان لك هذا الشعور ـ تقول يارب ليس لى عليك شىء ولا أطالبك بشىء ـ كل شىء من عندك حسن . القليل حسن لأنى لا أستحقه ، والكثير حسن لأنى لا أستحق حتى القليل . فتعيش فى شكر دائم .","يقول القديس مار اسحق عبارة خطيرة ... « الشخص الذى لا يشكر على القليل كاذب هو أن تالَ أنه يشكر على الكثير . الذى لا يشكر على الدرهم ، لا يستطيع أن يشكر"],"24":["على الألف دينار » . الشكر عنده غير موجود ... الذى لا يملك الشكر فى طبيعته ، يتذمر لو أعطيته ألف دينار ، ويقول غيرى عنده مليون دينار . تقول له أنت أصبحت وزيراً ، يقول ولماذا لا أصير رئيس وزراء ...! لا يوجد شكر بالمرة . من الذى يشكر ؟ ... الشخص المتضع الذى يشعر أنه لا يستحق شيئاً على الإطلاق . فكل ما يعطى له من الله يشكر عليه . والمتضع لا يشعر فقط أنه لا يستحق شيئاً من الخير ـ بل أكثر من هذا يشعر أنه يستحق عقوبات كثيرة وتأديبات عنيفة ... ولو أعطيت له جميع البلايا يشكر ، ويقول أنا أستحق بلايا أكثر من هذه لأنى إنسان خاطىء . إنها لرأفة عظيمة من الله أن يعطينى هذه فقط ... مثال لذلك أن مجرماً ارتكب جرائم مرعبة ، وحكم عليه القاضى بالأشغال الشاقة المؤبدة ، فصرخ فى المحكمة وقال له أشكرك ... ! لماذا ؟ « لأنى أستحق الإعدام ! يا لك من قاض رحيم وحنون ... إن هذا المجرم شاعر بخطيئته ، ويعرف أن جريمته تستحق الإعدام . إنه يذهب إلى المحامى أيضاً ويشد على يده فى حرارة ، ويقول له « أشكرك يا أستاذ على المجهود الكبير الذى بذلته من أجلى ، وجعلتنى أصل إلى الأشغال الشاقة المؤبدة ... كانت رأسى فى المشنقة وأنت أنقذتنى ...! » هكذا يكون الإنسان المتضع : كلما"],"25":["تأتيه بلية ، يقول أشكرك يارب . أشكرك لأنك حنون جداً وتعطينى عقوبات خفيفة للغاية ... يا لشفقتك العجيبة ... ! حقاً يارب ، إن يدك علىّ لا عصاك .","قد تعترض وتقول : نفرض أن الله أعطى له ضيقة لا تحتمل ، مرضاً من الأمراض المؤلمة التى لا تحتمل ، فكيف يشكر الله ولا توجد ضيقة أعظم من هذه ؟ إنه يجيب « لا ـ هناك توجد البحيرة المتقدة بالنار والكبريت . فإن كنت آخذ عذابات على الأرض لا تحتمل ، فهذا أفضل من العذاب الأبدى الذى لا يحتمل » ... فالإنسان المتضع هو الإنسان الشاكر ."],"26":[{"h":"خاتمـة"},"إن حياة الشكر تحتاج إذن إلى إيمان بالله ، وإلى الغرض الواحد ، أعنى ألا يكون للإنسان هدف سوى محبة الله فقط والإلتصاق به ، لذلك لا يهتم بأى شىء آخر بل يشكر على كل شىء . وحياة الشكر تحتاج إلى ذاكرة لا تنسى إحسانات الله ، وتحتاج إلى اتضاع وإلى محبة . لو كانت بينك وبين الله محبة ، تشكره على كل شىء ، تشعر أن كل شىء هو من يده المملوءة حناناً ومن قلبه المملوء محبة ... فتبقى سعيداً به . حياة الشكر تصل بالإنسان إلى حياة السلام والفرح ، ولا شىء ينزع فرحه منه .","ولله المجد دائماً أبدياً آمين ..."]}},"wars_demons":{"id":"wars_demons","title":"حروب الشياطين","author":"قداسة البابا شنوده الثالث","url":"https://drive.google.com/file/d/1rEOeeeiVHXZtaT12cQtKr6STTb5JmAJR/view","file":"حروب_الشياطين.pdf","pageOffset":1,"review":{"status":"needs-review","note":"نُقل الكتاب كله (من ص٨ إلى ص١١٨ بالترقيم المطبوع، أي المتن بفصوله الخمسة بلا الغلاف والفهرس) بقراءة صفحات الكتاب الممسوحة بالنظر وبنفس إملاء الطباعة (بما فيها أخطاؤها الطباعية)؛ يحتاج مطابقة نهائية مع الأصل. عناوين الفصول الرابع والخامس قُرئت من صفحات عنوان مطبوعة بخط مزخرف."},"chapters":[{"title":"الفصل الأول: طبيعة حروب الشياطين","from":7,"to":13},{"title":"الفصل الثاني: صفات الشيطان في حروبه","from":14,"to":31},{"title":"الفصل الثالث: حيل الشيطان","from":32,"to":89},{"title":"الفصل الرابع: كيفية الإنتصار على حروب الشياطين","from":90,"to":113},{"title":"الفصل الخامس: فوائد الحروب الروحية","from":114,"to":117}],"transcribed":[7,117],"pages":{"7":["الحروب الروحية سمح بها الله لفائدتنا ... ووراءها أكاليل . وعلى رأى أحد القديسين الذى قال :",{"h":"لا يكلل إلا الذى انتصر . ولا ينتصر إلا الذى حارب ."},"فهى من جهة الله إختبار لحرية إرادتنا ، وإعطاؤنا الفرصة التى نستحق بها خيرات الملكوت ، إذا انتصرنا... أما من جهة الشيطان ، فمن طبيعته أن يقاوم ملكوت الله ، ويحارب الساعين إليه . وهو يحارب الله فى شخص أولاده . ويشتكى عليهم كما حدث فى قصة أيوب الصديق (أى ١ ، ٢) . وهو يحسد السالكين فى حياة البر ، لكى لا ينالوا البركة الإلهية التى حُرم هو منها .",{"h":"وحروب الشياطين هى ضد الكل ، لم ينجُ منها أحد ."},"ونحن حينما نتكلم عن هذه الحروب ، إنما نقصد الحرب التى يثيرها الشيطان وكل جنوده وأعوانه .","منذ أيام آدم وحواء وإبنها قايين ، والشيطان قائم يحارب ، يحاول بكل جهده أن يلقى البشرية تحت حكم الموت الأبدى . وقد أسقط أنبياء ورسلاً ، وأشخاصاً حلّ عليهم روح الرب مثل داود وشمشون اللذين تابا ، ومثل شاول الملك الذى رفضه الرب ، وفارقه روح الله « وبغته روح ردىء من قبل الرب » (١صم ١٦ : ١٤) .",{"h":"فلا تظنوا أن حروب الشياطين هى للمبتدئين فقط أو للخطاة ."},"كلا ، فهو يحارب الكل ، مهما كانوا نامين فى النعمة ، بل يحارب هؤلاء بالأكثر . لذلك على كل إنسان أن يحترس ، وأن لا يظن بأنه قد ارتفع فوق مستوى حروب معينة . ولنتذكر أن معلمنا داود النبى حورب بخطية زنا وسقط فيها ، مع أنه كان قد حلّ عليه روح الرب وصار مسيحاً له... إن الشيطان يريد أية فريسة .","وقد وصفه القديس بطرس الرسول بعبارة خطيرة قال فيها :","« إبليس خصمكم كأسد زائر ، يجول ملتمساً من يبتلعه هو » (١بط ٥ : ٨) ."],"8":["وهو دائم الجولان لصيد فرائسه . ولما سأله الرب (فى قصة أيوب) « من أين جئت ؟ » أجاب فى صراحة « من الجولان فى الأرض ومن التمشى فيها » (أى ١ : ٧ ، ٢ : ٢) . وطبعاً الغرض من هذا الجولان هو البحث عن أية فريسة يسقطها...",{"h":"والشيطان لا ييأس ، مهما كان الذى يحاربه قوياً ."},"بل قيل عن الخطية إنها « طرحت كثيرين جرحى ، وكل قتلاها أقوياء » (أم ٧ : ٢٦) . والشيطان لم يتورع عن محاربة حتى رسل المسيح الإثنى عشر. وقد قال الرب فى ذلك للقديس بطرس الرسول « هوذا الشيطان طلبكم لكى يغربلكم كالحنطة . ولكنى طلبت من أجلك لكى لا يفنى إيمانك » (لو ٢٢ : ٣١ ، ٣٢) . ولنتذكر أن إيليا النبى العظيم الذى أصعده الله إلى السماء ، قال عنه القديس يعقوب الرسول « إيليا كان إنساناً تحت الآلام مثلنا » (يع ٥ : ١٧) .","بل إن الشيطان تجرأ أن يجرب السيد المسيح نفسه .","فقدم له ثلاث تجارب على الجبل (متى ٤) . ولم يثنه عن ذلك كل الذى كان يعرفه عن المسيح . ولم تثنه الإعلانات الإلهية التى سبقت ذلك وقت العماد (متى ٣ : ١٣ - ١٧) . بل حاربه طوال الأربعين يوماً (مر ١ : ١٣ ، لو ٤ : ٢) .","وقيل عن السيد المسيح إنه « كان مجرباً فى كل شىء مثلنا ، بلا خطية » (عب ٤ : ١٥) . وإنه « فيما هو قد تألم مجرباً يقدر أن يعين المجربين » (عب ٢ : ١٨) .","حقاً إن تجارب المسيح من الشيطان عزاء لنا فى كل تجاربنا... إن حلّت بك تجربة فلا تتضايق ، إن المسيح قد جرب من قبلك ، وكما انتصر المسيح سوف تنتصر أنت أيضاً .",{"h":"إن حروب الشياطين موجهة ضد الله نفسه وضد ملكوته ، وضد هياكله المقدسة التى هى نحن ."},"فهو يريد أن يقاوم هذا الملكوت بكافة الطرق . ويفرح إن أمكنه أن يسقط « حتى المختارين أيضاً » (متى ٢٤ : ٢٤) .","وإن كانت ملائكة السماء تفرح بخاطىء واحد يتوب (لو ١٥ : ١٠) ، فلا شك أن الشياطين تفرح ببار واحد إذا سقط ، بل تفرح بسقوط أى أحد يخضع لهم .","والقديس بولس الرسول ، يشرح هذه الحروب الروحية فيقول :"],"9":["« إلبسوا سلاح الله الكامل ، لكى تقدروا أن تثبتوا ضد مكايد إبليس . فإن مصارعتنا ليست مع دم ولحم ، بل مع الرؤساء مع السلاطين ... مع أجناد الشر الروحية فى السماويات ... » (أف ٦ : ١١ ، ١٢) .","وشرح كيف أن هذه الحروب الروحية تحتاج إلى أسلحة روحية لمقاومتها ، ذكرها الرسول فى نفس الأصحاح بالتفصيل... ولابد لها من معونة الله ، الذى قال « بدونى لا تقدرون أن تفعلوا شيئاً » (يو ١٥ : ٥) . وفى هذه الحرب الروحية ما أجمل أن نتذكر قول داود النبى « الحرب للرب » (١صم ١٧ : ٤٧) .",{"h":"والحروب الروحية حروب دائمة . قد تتنوع ، ولكن لا تنتهى ."},"طالما أنت فى الجسد ، فأنت معرض لهذه الحروب ، التى تظل معك حتى الموت . ولذلك قال القديس بطرس الرسول « سيروا زمان غربتكم بخوف » (١بط ١ : ١٧) . ولا يقصد بالخوف ، الرعب من الشياطين... إنما الخوف الذى يدعو إلى الحرص والتدقيق .","بالنسبة إلى الفرد ، الحرب تستمر حتى الموت . وبالنسبة إلى العالم ، تستمر مدى الدهر ، إلى نهاية العالم . حتى أن الشيطان حينما يُحل من سجنه ، يخرج ليضل الأمم (رؤ ٢٠ : ٧ ، ٨) . وفى نهاية الأيام سيكون هناك ارتداد عن الإيمان (١تى ٤ : ١) ، « وستأتى أزمنة صعبة » (٢تى ٣ : ١) . وقبل مجىء المسيح سيكون الإرتداد العام (٢تس ٢ : ٣) . وسيبذل الشيطان كل جهده ، وسينزل إلى الأرض « وبه غضب عظيم ، عالماً أن له زماناً قليلاً بعد » (رؤ ١٢ : ١٢) .",{"h":"والحرب الدائمة التى للشيطان قد تشتد فى الأوقات المقدسة ."},"فالشيطان يتضايق جداً ، حينما نبدأ فى أى عمل روحى . ويسعى بكل الحيل لئلا تفلت الفريسة من يده . فنحن نبدأ العمل الروحى ، ويبدأ هو معنا حروبه وحيله ومعطلاته الكثيرة .",{"h":"فنحن نبدأ العمل الروحى ، وهو يبدأ المقاومة ."},"لأنه لا يستريح لأية صلة لنا مع الله . يظن أن هذه تهدد ملكه بالضياع . ومن العبارات الجميلة فى بستان الرهبان : إنه عندما يدق جرس الصلاة فى نصف الليل ، فإنه لا يوقظ الرهبان فقط للصلاة و إنما أيضاً يوقظ الشياطين لكى يحاربوا الرهبان"],"10":["ويمنعوهم عن الصلاة... ولذلك قال القديس مارأوغريس :",{"h":"إذا بدأت الصلاة الطاهرة ، فاستعد لكل ما يأتى عليك ."},"إننا إذا بدأنا فى الوسائط الروحية أياً كانت ، سواء فى عمل الصلاة ، أو التأمل ، أو التسبيح ، أو القراءات الروحية ، أو المطانيات... فإن الشيطان لا يقف مكتوف اليدين أو متفرجاً ، إنما يعمل هو أيضاً عمله ، وله أنواع حروب يحارب بها . وما أصدق قول الكتاب فى سفر يشوع بن سيراخ :",{"h":"يا إبنى ، إن تقدمت لخدمة ربك ، فهيىء نفسك لجميع التجارب ."},"وهذه الآية نقولها ضمن فصل نتلوه فى سيامة الراهب الجديد . كما إنها إحدى قراءات الساعة الثالثة من يوم الثلاثاء من البصخة المقدسة . فالذين يستعدون لقتال الشيطان ، من الطبيعى أن يستعد الشيطان أيضاً لقتالهم . لذلك لا تتعجبوا للحروب التى تصاحب العمل الروحى... وحذار أن تجعلكم هذه الحروب تتراجعون... بل اثبتوا فى قوة ، مهما نالكم من تعب ، متذكرين قول القديس بولس الرسول « كونوا راسخين ، غير متزعزعين ، مكثرين فى عمل الرب كل حين ، عالمين أن تعبكم ليس باطلاً فى الرب » (١كو ١٥ : ٥٨) .",{"h":"نحن نبدأ الجهاد ، وهو يبدأ الحرب . نبدأ الروحيات ، فيبدأ المقاومة ."},"الشيطان مثلاً يتضايق من الصوم ، لأنك فيه تريد أن تقمع جسدك وتستعبده (١كو ٩ : ٢٧) ، لكى ترتفع روحك وتلتقى بالله... والشيطان لا يقبل هذا . كما أنه يتضايق من الصوم الكبير بصفة خاصة ، لأن الناس يسلكون فيه بنسك شديد ، كما أن هذا الصوم يذكّر الشيطان بصوم السيد المسيح وكيف قهر الشيطان فيه (متى ٤) . لذلك يجاهد الشيطان أن يعرقل هذا الصوم ، أو أن يثير فيه مشاكل ، حتى ينشغل الناس بالمشاكل ، ويتركوا العمل الروحى .","ولهذا فالبعض يربطون بين هذا الصوم ، والمشاكل والتجارب .",{"h":"ولا شك أن العمل الروحى يثير حسد الشياطين ..."},"إن الشيطان يحسد الإنسان الروحى على صلته بالله ، التى حُرم هو منها . ويحسده لأنه هو إنسان ترابى مرتبط بجسد ، يحاول أن يجعل روحه تسمو وتعلو ، بينما الشيطان وهو روح (متى ١٢ : ٤٥) بعيد عن الله ، وروحه روح نجسة (مر ١ : ٢٧) !","ومنذ البدء حسد الشيطان أبوينا آدم وحواء وأوقعها فى الخطية وفى حكم الموت ."],"11":["وهكذا نقول فى صلوات القداس الإلهى « والموت الذى دخل إلى العالم بحسد إبليس » .",{"h":"والشيطان لا يحسد إلا الناجحين فى عملهم الروحى ."},"يحسد المقتربين إلى الله ، والذين لهم دالة عنده . ويحسد التائبين فى حرارة التوبة ، والعابدين وهم فى عمق الصلة . ويحسد المتضعين والودعاء والأنقياء . ويحارب كل هؤلاء . أما الخاضعون له وللخطية ، والفاترون فى حياتهم الروحية . فلماذا يحاربهم ؟! يكفيهم ما هم فيه . أو إنه يضعهم تحت المراقبة ، أو يورطهم فى حالة أسوأ .",{"h":"وهنا نذكر بعض أنواع من الحروب الروحية ."},"ونذكر هنا ثلاثة أنواع رئيسية وهى :","أ ـ حالة إنسان يحاربه الشيطان حرباً خفيفة أو ثقيلة .","ب ـ إنسان تحاربه شهواته من داخل . ربما الشيطان قد وضع نقطة البدء ، ثم ترك هذه الفريسة المسكينة يحاربها فسادها الداخلى ، أو تحاربها عاداتها المتوطنة فيها ، المسيطرة عليها . هناك إنسان يحارب من جسده ومن غرائزه ، وآخر يحارب من نفسه أو من فكره .","ج ـ أما الحالة الثالثة فهى لإنسان يحاربه إخوة كذبة ، أو أناس أشرار ، أو بيئة شريرة تحيط به ، ويمكن أن نسميهم جميعاً « أعوان الشياطين » و « كل جنده » ...","ولهذا تعلمنا الكنيسة أن نصلى فى آخر صلاة الشكر ونقول : كل حسد ، وكل تجربة ، وكل فعل الشيطان ، ومؤامرة الناس الأشرار ، وقيام الأعداء الخفيين والظاهرين... إنزعها عنا وعن سائر شعبك... » .",{"h":"وهناك نوع يمكن أن نسميه إمتحاناً أو إختباراً ، وليس حرباً ."},"وكمثال لهذا يقول الكتاب « وحدث ... أن الله إمتحن إبراهيم . وقال له ... خذ إبنك وحيدك الذى تحبه إسحق ... وأصعده ... محرقة ... » (تك ٢٢ : ١ ، ٢) . وهنا لم يكن الله يحارب أبانا إبراهيم ، حاشا... بل كان يمتحن قلبه ليرى عمق محبته له وعمق طاعته... ونجح أبونا إبراهيم فى هذا الإختبار...",{"h":"القديس والخاطىء كلاهما معرضان للحرب . ولكن ما الفرق بينها ؟"}],"12":["الفرق الأساسى هو أن القديس له حرب من الخارج فقط . أما داخله فإنه نقى ، لا يتفق مع الحرب الخارجية بل يرفضها ويقاوم بكل قوته لكى ينتصر عليها .","أما عن الخاطىء أو الشرير فقد تكون الحرب بالنسبة إليه مزدوجة ، من الخارج ومن الداخل معاً . تحاربه إغراءات الشيطان من الخارج ، وتحاربه شهواته من داخل قلبه وفكره . لذلك هو يستسلم لحرب الشيطان ، ويفتح له أبوابه الداخلية . ويقبل أفكاره ومقترحاته مرحباً بها . وإن قاوم ـ لبقية ضمير فيه ـ فإنها تكون مقاومة هزيلة لا تستمر طويلاً ، ولا تكون جادة فى صد أفكار العدو الخارجى .","وحروب القديسين تظهر فيها قوتهم وانتصارهم . أما الخطاة فينهزمون ...",{"h":"وقد يسمح الله أحياناً بانهزام القديسين ، مؤقتاً ، لفائدتهم ..."},"فالإنسان المنتصر على طول الخط ، ربما تحاربه الكبرياء ، ويظن فى نفسه أنه شىء !! لذلك سمح الله أحياناً أن ينهزم القديسون ، لكى تنسحق قلوبهم من الداخل ، ويعيشوا فى اتضاع . ولكى يعرفوا قوة العدو وقسوته فى الحروب ، فيشفقوا على أخوتهم المحاربين . وكما قال القديس بولس الرسول :",{"h":"« أذكروا المقيدين كأنكم مقيدون معهم . و ( اذكروا ) المذلين كأنكم أنتم أيضاً فى الجسد » (عب ١٣ : ٣) ."},"إن الإنسان الذى لم يجرب بحروب الشياطين ، ربما يدين الذين يسقطون أو يحتقرهم ، بعكس الذى قاسى وتعب ، فإنه يحن عليهم ويشفق ، ويصلى لأجل خلاصهم . وكما قال الرسول « عالمين أن نفس هذه الآلام تجرى على أخوتكم الذين فى العالم » (١بط ٥ : ٩) ... حقاً ما أرهب قول الكتاب فى سفر الرؤيا عن الوحش :",{"h":"« وأعطى أن يصنع حرباً مع القديسين ويغلبهم » (رؤ ١٣ : ٧) ."},"بل ما أرهب أيضاً ما قيل بعد ذلك « وأعطى سلطاناً على كل قبيلة ولسان وأمة . فسيسجد له جميع الساكنين على الأرض... » (رؤ ١٣ : ٧ ، ٨) . ولكن لئلا ييأس البعض من ذلك ، ذكر أن هؤلاء الساجدين هم : الذين ليست أسماؤهم مكتوبة منذ تأسيس العالم فى سفر الحياة... أى أبناء الهلاك... ومع ذلك هم عدد كبير بلا شك يدل على عنف حرب الشيطان وجنوده... ومما يعزينا فى ذلك أيضاً ، أن الوحش هو والشيطان مُطرحان فى بحيرة النار والكبريت (رؤ ٢٠ : ١٠)..."],"13":[{"h":"ولكننا ذكرنا كل هذا ، لكى يكون لدينا حرص ."},"مادام عدونا بهذه الوحشية ، فلنستمع إذن إلى قول الرسول « أنظروا كيف تسلكون بتدقيق ، لا كجهلاء بل كحكماء ، مفتدين الوقت لأن الأيام شريرة » (أف ٥ : ١٥ ، ١٦) . إنتصارات الشيطان لا تدفعنا إلى الخوف ، بل إلى الحرص والتدقيق . وأيضاً تدفعنا إلى عدم الإعتماد على أنفسنا ، وإنما :",{"h":"فى حروبنا نلتصق بالرب ، لأن من عنده المعونة والنصرة ."},"هو الذى يحارب الشيطان فينا ، وهو الذى يغلب العالم فينا . أليس هو القائل « ثقوا ، أنا قد غلبت العالم » (يو ١٥ : ٣٣) . نعم غلب العالم فى حرب الشيطان معه . ويغلب العالم الآن وكل أوان ، فى حربه معنا . وكذلك :",{"h":"« شكراً لله ، الذى يقودنا فى موكب نصرته » (٢كو ٢ : ١٤) ."},"إنه انتصر على الشيطان فى طبيعتنا البشرية . فقدّس هذه الطبيعة وباركها ، وأعطاها روح النصرة . وهكذا نقول له فى القداس الغريغورى « باركت طبيعتى فيك » ... لقد انتصر الشيطان من قبل ، على هذه الطبيعة البشرية . ولكن السيد المسيح أعاد إلى هذه الطبيعة البشرية صورتها الإلهية ، وهيبتها فى نظر الشياطين ، حينما هزم الشيطان فيها .",{"h":"فلم يعد الشيطان يرى أن هذه الطبيعة هى لعبته ، ينتصر عليها متى يشاء... وإذ انهزم أمامها ، بدأ يخشاها..."},"وبهذا أيضاً أنقذنا من روح الفشل ، وأعطانا قوة من عنده فى حروب الشياطين لنا . وأصبح لنا الرجاء كل حين ، أن المسيح يغلب الشيطان فينا ، حينما « يحل المسيح بالإيمان فى قلوبنا » (أف ٣ : ١٧) .","وبسبب هذا نحن لا نتضايق من حروب الشياطين ، مادامت يد الرب تكون معنا فيها ، ويحارب عنا وينصرنا...",{"h":"الله لا يمنع عنا حروب الشياطين ، إنما ينصرنا فيها ."},"هو الذى يحارب عنا ، وهو الذى يغلب الشياطين . وبعد ذلك يكللنا ، لأننا سلمناه إرادتنا أثناء حربه عنا ضد الشياطين .","هذه مقدمة بسيطة ننتقل بعدها إلى الحديث عن الشيطان وحيله..."],"14":[{"h":"الفصل الثانى"},{"h":"صفات الشيطان فى حروبه"}],"15":[{"h":"ينبغى أن نعرف صفات عدونا ، وأسلوبه فى القتال ، لنعرف كيف نحاربه ."},"فما هى صفات الشيطان ؟ وكيف يحارب ؟ وهل له أسلوب ثابت ، أم أنه يتغير فى أساليبه حسب تغير الحالة ؟ هذا ما نريد أن نفحصه ، حتى نستطيع أن نواجهه . وكما قال بولس الرسول « لئلا يطمع فينا الشيطان . لأننا لا نجهل أفكاره » (٢كو ٢ : ١١) .","ونستطيع أن نعرف مما رواه لنا الكتاب عن الشيطان أنه :",{"h":"١ ـ صاحب قتال لا يهدأ"},"صار عمله منذ سقوطه هو المقاتلة والمحاربة . فهو دائماً مقاتل fighter حتى قبل إسقاطه لأبوينا الأولين آدم وحواء ، إستطاع أن يُسقط مجموعات من ملائكة السماء ، تبعوه وصاروا من جنده من طغمات كثيرة .",{"h":"ومن ذلك الحين أصبحت هوايته إسقاط الآخرين ."},"صار يقاتل الكل . وكما أسقط طغمات ملائكية من الكاروبيم والسلاطين والرؤساء والقوات... كذلك رأيناه يقاتل أنبياء الله ورسله ومسحاءه ، ويقاتل المتوحدين والسواح والرهبان وكل محبى الله ، وكل من يسمع أنه فى خير ، أو فى برّ .","وقد سمى المعاند والمقاوم ، لأنه دائماً يقاوم ملكوت الله و يعاند مشيئته . كما سمى أيضاً التنين ، والحية القديمة ، وإبليس ، والشيطان (رؤ ١٢ : ٩) ، وقبل الصليب كان يسمى رئيس هذا العالم (يو ١٤ : ٣٠) .",{"h":"وهو فى قتاله لا يهدأ مطلقاً ولا يملّ ولا يستريح ."},"دائماً « يجول كأسد يزأر » (١بط ٥ : ٨) . وقد قال للرب مرتين فى قصة أيوب إنه مشغول « بالجولان فى الأرض والتمشى فيها » (أى ١ : ٧ ، ٢ : ٢) . إنه ساهر"],"16":["باستمرار يرقب حالة ضحاياه ، ويلقى بذاره فى كل مكان . وحيثما يزرع الرب حنطة ، يأتى هو « ويزرع زواناً وسط الحنطة ، فيما الناس نيام » (متى ١٣ : ٢٥) .",{"h":"وليس البشر فقط ، بل حتى الملائكة يحاربهم ."},"فقد وقف ضد الملاك ميخائيل يحاججه من جهة جسد موسى النبى (يه ٩) . ووقف ضد أحد الأرباب الذى عمل على أن ينقذ منه يهوشع الكاهن (زك ٣ : ١ ، ٢) . كذلك وقف واحداً وعشرين يوماً ضد الملاك الذى أرسله الرب لدانيال النبى ، لولا تدخل رئيس الملائكة ميخائيل لإعانته (دا ١٠ : ١٢ ، ١٣) . بل ما أعجب قول الإعلان الإلهى فى سفر الرؤيا :","وحدثت حرب فى السماء : ميخائيل وملائكته حاربوا التنين ... وملائكته (رؤ ١٢ : ٧) . إنه يحارب فى الأرض وفى السماء ، مع أن كل حروبه تنتهى أخيراً إلى هلاكه وهزيمته ولكنه لا يستطيع أن يبطل الحرب ، لأنها صارت جزءاً من طبيعته .","ومن صفات الشيطان أيضاً أنه قوى .",{"h":"٢ ـ قوى"},"لأنه أحد الملائكة « المقتدرين قوة » حسبما وصفهم المرتل (مز ١٠٣ : ٢٠) .",{"h":"هو كملاك فقد طهارته ، لكن لم يفقد طبيعته القوية ."},"لذلك وصفه الرسول بأنه « أسد زائر » (١بط ٥ : ٨) . وهكذا نراه فى سفر أيوب إستطاع أن « يضرب به بقرح ردىء من باطن قدمه إلى هامته » (أى ٢ : ٧) ، كما إستطاع أن يثير ريحاً شديدة صدمت زوايا بيت أيوب ، فسقط على الغلمان فماتوا (أى ١ : ١٩)... وهناك دلائل روحية كثيرة على قوته ، منها :",{"h":"إنه استطاع أن يضل العالم كله أيام الطوفان ."},"ولم تنجُ من ضلاله سوى أسرة واحدة هى أسرة أبينا نوح (تك ٦) . ورأى الله أن الحل الوحيد لتطهير الأرض من الفساد ، هو إبادة كل نفس حية على وجه الأرض .",{"h":"ونفس الوضع نقوله عن مدينة سادوم ."},"فلم يجد الله فيها عشرة من الأبرار ، حتى يرحم المدينة من أجل العشرة (تك ١٨ : ٣٢) . ولم يوجد فيها سوى أسرة لوط فقط (أربعة أشخاص) . هلكت من بينهم إمرأة"],"17":["لوط خارج المدينة . وأخطأت البنتان بعد خروجها من سادوم . ولوط نفسه قيل عنه حينما كان فى سادوم إنه « كان بالنظر والسمع ـ وهو ساكن بينهم ـ يعذب يوماً فيوماً نفسه البارة بالأفعال الأثيمة » (٢بط ٢ : ٨) .",{"h":"وقوة الشيطان تظهر فى إلقائه العالم كله فى الوثنية ."},"كيف استطاع أن يلقى العالم كله فى الوثنية فى العهد القديم ، ماعدا شعباً واحداً ؟! هذا أمر خطير . بل حتى هذا الشعب الواحد وقع فى عبادة الأصنام هو أيضاً ، حينما كان موسى النبى على الجبل ، إذ صنعوا لأنفسهم عجلاً ذهبياً ، وقدموا له الذبائح . وقالوا « هذه آلهتك يا إسرائيل التى أصعدتك من أرض مصر » (خر ٣٢ : ١ ـ ٦) .","وفى أيام إيليا النبى فى عهد آخاب الملك ، كان فى شعب الله ٤٥٠ نبياً للبعل ، و ٤٠٠ نبياً للسوارى أى ثمانمائة وخمسون نبياً كاذباً كانوا يأكلون على مائدة الملكة إيزابل (١مل ١٨ : ١٩) . وحدث أن كثيراً من ملوك يهوذا وإسرائيل وقعوا فى عبادة الأصنام « وجعلوا إسرائيل يخطىء » كما تروى لنا أسفار الملوك وأخبار الأيام .",{"h":"ومن قوة الشيطان إسقاطه لسليمان الحكيم فى عبادة الأصنام ."},"سليمان أحكم أهل الأرض ، الذى أخذ الحكمة من الله نفسه (١مل ٣ : ١٢) ، الذى تراءى له الله مرتين (١مل ٣ : ٥ ، ٩ : ٢) . يقول عنه الكتاب « وكان فى زمان شيخوخة سليمان ، أن نساءه أملن قلبه وراء آلهة أخرى ... فذهب سليمان وراء عشتاروت إلهة الصيدونيين وملكوم رجس العمونيين » (١مل ١١ : ٤ ـ ٨) .","حقاً إنها لمأساة عجيبة وخطيرة ، ترينا مدى قوة الشيطان .",{"h":"ومن دلائل قوة الشيطان ما سيفعله فى آخر الأيام ."},"وذلك عندما « يُحل من سجنه » ، ويخرج ليضل الأمم الذين فى أربع زوايا الأرض (رؤ ٢٠ : ٧) . بل يضل لو أمكن المختارين أيضاً عن طريق من يرسلهم من مسحاء كذبة وأنبياء كذبة ، يعطون آيات عظيمة وعجائب (متى ٢٤ : ٢٤) . ومن خطورة عمله العنيف فى تلك الفترة الصعبة قول الرب عنها :",{"h":"ولو لم تقصّر تلك الأيام ، لم يخلص جسد » (متى ٢٤ : ٢٢) ، « ولكن لأجل المختارين تقصر تلك الأيام » . وفى تلك الأيام سيرسل الشيطان أيضاً من عنده ضد"}],"18":["المسيح ، إنسان الخطية المقاوم والمرتفع على كل ما يدعى إلهاً « الذى مجيئه بعمل الشيطان ، بكل قوة و بآيات وعجائب كاذبة ، وبكل خديعة الإثم فى الهالكين » (٢تس ٢ : ٩ ، ١٠) .",{"h":"ومن نتائج قوة الشيطان هذه ، يحدث الإرتداد العام ."},"وذلك قبيل مجىء المسيح (٢تس ٢ : ٣) . ولكن نشكر الله الذى سيقصر تلك الأيام الصعبة . وسيبيد هذا الأثيم (ضد المسيح) بنفخة فه ، ويبطله بظهور مجيئه (٢تس ٢ : ٨) ... إلى هذا الحد وصلت قوة الشيطان .",{"h":"ومن أمثلة قوة الشيطان أيضاً :"},"إنه استطاع أن يتكلم على فم رسول عظيم كبطرس ، فانتهره الرب قائلاً « إذهب عنى يا شيطان . أنت معثرة لى » (متى ١٦ : ٢٢ ، ٢٣) .","ومن أمثلة ذلك أيضاً أنه غربل الإثنى عشر رسولاً . وقد طلب الرب من أجل بطرس لكى لا يفنى إيمانه (لو ٢٢ : ٢١ ، ٣٢) .","ومن أمثلة قوته أنه أسقط جبابرة مثل داود وشمشون ، وأهلك نبياً كبلعام ، وضيع تلميذاً من تلاميذ بولس كديماس ... « وكل قتلاه أقوياء » (أم ٧ : ٢٦) . حقاً كما قال داود النبى « كيف سقط الجبابرة ، و بادت آلات الحرب » (٢صم ١ : ٢٧) .",{"h":"ومن أمثلة قوته أيضاً صرعه لأناس كثيرين ."},"هؤلاء الذين احتاجوا أن يخرج الشيطان منهم ، وقيل إنه كانت عليهم أرواح نجسة . وعنهم قال الرب لتلاميذه « إخرجوا شياطين » (متى ١٠ : ٨) . وكان على واحد من المرضى فرقة من الشياطين « لجئون » (مر ٥ : ٩) ، « ولم يقدر أحد أن يذلله » . وبعض هذه الشياطين لم يقدر تلاميذ الرب وقتذاك على إخراجها . فقال لهم الرب « هذا الجنس لا يمكن أن يخرج بشىء إلا بالصلاة والصوم » (مر ٩ : ٢٩) .",{"h":"ولعله بسبب قوة الشيطان ، قيده الله ألف سنة ."},"« وطرحه فى الهاوية ، وأغلق عليه وختم عليه ، لكى لا يضل الأمم فى ما بعد ، حتى تتم الألف سنة . وبعد ذلك لا بد أن يُحلّ زماناً يسيراً » (رؤ ٢٠ : ٢ ، ٣) .",{"h":"ولكن ليس معنى الحديث عن قوة الشيطان ، أن تخافوا منه !! كلا ."}],"19":[{"h":"فإن كان الشيطان قوياً ، فالله أقوى منه ..."},"وليس فقط أن الله أخضعه لنا ، بل إن كثيراً من الآباء قد غلبوه ، وكان يخاف منهم . وسنتحدث عن هذه النقطة فى حينها بمشيئة الرب .","نقطة أخرى مهمة فى صفات الشيطان كمحارب لنا ، وهى أنه :",{"h":"٣ ـ خبير بالحروب وبنا"},"تصوروا الشيطان يحارب الإنسان منذ أكثر من سبعة آلاف سنة ، منذ آدم ... أية خبرة تكون له فى حربه مع البشرية . لا شك أنه أقدر مخلوق على فهم النفس البشرية وطريقة محاربتها . لقد درس النفس البشرية جيداً ، ويعرف نواحى القوة والضعف فيها . و يعرف الأسلوب الذى يمكنه أن يحاربها به .",{"h":"أكبر عالم نفسانى ، وأكبر محلل نفسانى ، هو الشيطان ..."},"علم النفس عنده ، ليس مجرد نظريات ، إنما هو خبرات ، على المستوى العملى والعلمى أيضاً ، وبنطاق واسع جداً ، شمل البشرية كلها . لذلك هو يعرف متى يحارب ، وكيف يحارب ؟ ومتى ينتظر ؟ ومن أى الأبواب يدخل إلى الفكر أو إلى القلب ... ؟","من صفات الشيطان الأخرى التى تظهر فى حروبه أنه :",{"h":"٤ ـ ذكى وصاحب حيلة"},"لقب الشيطان بأنه « الحية القديمة » (رؤ ٢٠ : ٢ ، ١٢ : ٩) . وقال الكتاب عن الحية إنها كانت « أحيل حيوانات البرية » (تك ٣ : ١) . إنه ذكى وحكيم فى الشر . وقد قال الكتاب « كونوا حكماء كالحيات » (متى ١٠ : ١٦) . وحكمة الشيطان كلها خبث ومكر وحيلة ...","ومن مظاهر ذكاء الشيطان أنه قد يغير خطته وأساليبه لتوافق الظروف . ومن حيله الصعبة : الكذب والخداع والأضاليل ، يسبكها بطريقة ذكية لا يشعر بها الإنسان المحارب ، أو أنه يقدم الخطية فى أسلوب فضيلة ... الخ . ما أكثر حيل الشيطان . إننا سنفرد"],"20":["لها فصلاً خاصاً فى هذا الكتاب ، قد يكون الفصل الأساسى فيه .","ومن الصفات البارزة فى حروب الشيطان أنه :",{"h":"٥ ـ كذاب"},"لقد كذب على أبوينا آدم وحواء حينما قال لها « لن تموتا » وكذلك فى قوله لها « تصيران مثل الله ... » (تك ٣ : ٤ ، ٥) . وصفة كذاب بارزة فى الشيطان ، لذلك قال عنه السيد الرب إنه « كذاب وأبو الكذاب » (يو ٨ : ٤٤) . قال هذا لكى لا نصدق كل ما يقوله الشيطان ، ولا ننخدع به . وليس الكذب عند الشيطان هو فقط ما يقوله من كلمات ، وإنما هناك ما هو أخطر بكثير من كل هذا :",{"h":"هناك من يرسلهم من أنبياء كذبة ومسحاء كذبة ..."},"ولقد حذرنا الرب من كل هؤلاء ، فقال « إن قال لكم أحد هوذا المسيح هنا أو هناك فلا تصدقوا . لأنه سيقوم مسحاء كذبة وأنبياء كذبة ، و يعطون آيات عظيمة وعجائب حتى يضلوا لو أمكن المختارين أيضاً » (متى ٢٤ : ٢٣ ، ٢٤) . وطبعاً سيمطون تلك الآيات والعجائب من الشيطان ، كما قيل عن المقاوم ضد المسيح « الذى مجيئه بعمل الشيطان بكل قوة وبآيات وعجائب كاذبة » (٢تس ٢ : ٩) .",{"h":"ومن أمثلة ذلك تكلم الشيطان من أفواه الأنبياء الكذبة :"},"قوله عن إغواء آخاب الملك ليهلك « أنا أغويه ... وأكون روح كذب فى أفواه جميع أنبيائه » (١مل ٢٢ : ٢٢) . فكما أن الروح القدس هو الناطق فى أفواه الأنبياء القديسين ، كذلك الشيطان هو الناطق فى أفواه الأنبياء الكذبة .",{"h":"كذلك يعلن الشيطان كذبه فى الأحلام والرؤى الكاذبة ..."},"وما أكثر الحروب التى تعرض لها الآباء الرهبان ، ووردت فى بستان الرهبان ، عن هذه الأحلام والرؤى الكاذبة . ومن أمثلتها ظهور الشيطان لأب راهب وقوله له « أنا الملاك غبر يال ، أرسلنى الرب إليك » فأجابه الراهب فى اتضاع « إننى إنسان خاطىء ، لا أستحق أن يظهر لى ملاك . فلعلك أرسلت إلى غيرى وأخطأت الطريق » . وظهر كذب الشيطان ، فمضى واختفى عنه ."],"21":["أو كمثال آخر قصة الشيطان الذى ظهر لراهب وقال له « أنا المسيح ، فاسجد لى » . فقال الراهب فى قلبه « أنا فى كل يوم أسجد لسيدى المسيح . فلماذا يطلب هذا منى السجود » . وهكذا كشف حيلة وكذب الشيطان ، وانتهره فمضى .","وما أكثر الأحلام الكاذبة التى يضل بها الناس ظانين أنها من الله ! وقد قال القديس بولس الرسول عن الرؤى الكاذبة التى من الشيطان :","« لأن الشيطان نفسه يغيّر شكله إلى شبه ملاك نور » (٢كو ١١ : ١٤) .","وفى قصة الأنبا غاليون السائح ظهرت له الشياطين بهيئة آباء سواح يريدون ضمه إليهم . ولم يكتشف أنهم شياطين ، إلا بعد أن أتاهوه فى البرية ، ثم سخروا به وتركوه هازئين به ، إلا أن رحمة الرب أدركته من أجل نسكه ، و ببساطة قلبه ، وماضى تعبه ...",{"h":"وكذب الشيطان يظهر أيضاً فى أقوال السحرة والعرافين وأمثالهم ."},"ولذلك أوصى الرب قائلاً « لا تتعلم أن تفعل مثل رجس أولئك الأمم . لا يوجد فيك من يجيز إبنه أو إبنته فى النار ، ولا من يعرف عرافه ... ولا ساحر ، ولا من يرق رقية ، ولا من يسأل جاناً أو تابعة ، ولا من يستشير الموتى . لأن كل من يفعل ذلك مكروه عند الرب . و بسبب هذه الأرجاس ، الرب إلهك طاردهم من أمامك » (تث ١٨ : ٩ ـ ١٢) . ولعل هذه الآية تكشف لنا شيئاً آخر هو :",{"h":"كذب الشيطان فى استشارة الموتى ، أو فى ( تحضير الأرواح ) ."},"فقد ينطق فى أمثال هذه الجلسات ، مدعياً أنه روح فلان من الناس . ويقول للحاضرين بعض معلومات تخدعهم مما يعرفه عن أخبار ذلك الشخص أو أسرته . فإذا صدقوه ، يبدأ بالتدريج يقول لهم ما يضلهم ... وكل هذا من كذب وادعاء الشيطان ليضل الناس ...",{"h":"ولعل من كذبه أيضاً ، ما يقوله على أفواه المنجمين ومدعى معرفة الغيب ..."},"سواء عن طريق التنجيم ، أو قراءة الكف ، أو ضرب الرمل ، أو قراءة فنجان القهوة ، أو معرفة البخت والطالع بأنواع وطرق شتى ...","وواضح لاهوتياً أنه لا يعرف الغيب سوى الله وحده . فمن يدعى معرفة الغيب ، لا يكون صادقاً فيما يدعيه ..."],"22":[{"h":"وإغراءات الشيطان كلها ألوان من الكذب ..."},"حيث يصور للإنسان سعادة تأتيه من وراء الخطية ، سواء فى لذة أو سلطة أو مكسب أو جاه أو مجد ... وبعد أن يسقط الشخص يجد أن كل إغراءات الشيطان هى سراب زائل ، وأنها أشياء زائفة ، كما صور لحواء وآدم أنها سيصيران مثل الله ... وكما صور لسليمان أنه سيسعد بكثرة ألوان المتعة والترف التى تحيط به ، فوجد أن الكل باطل وقبض الريح (جا ٢) .","ولكن هذا أسلوب الشيطان دائماً ، يزخرف طريق الخطية ، و يضفى عليه أوصافاً من الجمال تغرى من يسقط فى حبائله . وتكون كل زخارفه أكاذيب يخفى بها بشاعة الخطية ونتائجها السيئة ...",{"h":"أيضاً أحلام اليقظة التى يقدمها لضحاياه ، كلها أكاذيب ..."},"ولكنه يقدمها لهم كنوع من اللذة تخدرهم عن العمل الإيجابى النافع ، فيعيشون بهذه الأحلام فى خيال غير واقعى ، يبنون قصوراً من رمال ، وأمجاداً وأفراحاً ومتعاً . ثم يستيقظون فلا يجدون شيئاً . و يكون الشيطان بهذا الكذب قد أضاع وقتهم ، وعطلهم عن العمل المجدى ، وأراحهم راحة كاذبة .",{"h":"ومن أكاذيب الشيطان إيهامه المنتحر أن الموت سيريحه من متاعبه ."},"و يظل يركز على هذه النقطة : إنه لا فائدة من هذه الحياة ، ولا حل لمشاكله . والحل الوحيد هو الموت ، حيث يتخلص من كل تعبه و يستريح . وإذ يصدقه المنتحر و يقتل نفسه ، لا يجد هذه الراحة ، بل يجد نفسه فى الجحيم ، فى تعب وألم لا نجاة منه ، ولا تقاس به كل متاعب الدنيا . و يجد أن الموت ليس هو نهاية لحياته المتعبة ، بل هو بداية لحياة أكثر تعباً . و يكون الشيطان بهذا الكذب قد خدعه وضلله وأضاعه ...",{"h":"ونقريباً غالبية الخطايا ، يضع الشيطان وراءها أكذوبة من أكاذيبه ."},"فهو يوحى للسارق بأن لا أحد سوف يرى أو يكتشف سرقته ، وكذلك يوحى للمهرب وللمرتشى وللغشاش . والشيطان فى كل هذا يكذب ، لأنه حتى إن لم ير البشر ، فالله يرى وكل شىء مكشوف أمامه . وهو يوحى للقاتل بأن المقتول يستحق القتل ، وحياته خطأ يجب تصحيحه ، أو أن القتل غسل للعار الذى يلوث شرفه ، أو أن قتله يريح نفس قريب له قد مات ..."],"23":["بل لعل الإلحاد هو أكبر أكذوبة قدمها الشيطان للبشرية . وقد كذب على الوجوديين حينما صور لهم أن وجود الله يعطل وجودهم ، كما كذب على الماركسيين إذ صور لهم أن الله يعيش فى برج عالٍ ولا يهتم بالمجتمع الإنسانى ، بل يترك فيه الظالم يظلم ، والغنى يستعبد الفقير... !!","من صفات الشيطان أيضاً فى حروبه أنه :",{"h":"٦ ـ لحوح"},"أى أنه كثير الإلحاح جداً ، لا يملّ . وربما الفكر الواحد يظل يعرضه مرات ومرات . ومهما رفضه الناس ، يستمر أيضاً فى عرضه .",{"h":"ربما من كثرة الضغط المستمر والإلحاح ، يستسلم الإنسان له ويخضع ."},"لقد قيل فى بستان الرهبان إن الشيطان ظل يحارب راهباً بخطية واحدة مدى خمسين عاماً ، لا يهدأ ، ولا ييأس ، ولا يملّ ...","وحتى فى حربه مع السيد المسيح ، لم يهدأ بعد فشله فى التجربة الأولى والثانية والثالثة . ولما انتهره الرب ومضى قال القديس لوقا الإنجيلى عن ذلك « ولما أكمل إبليس كل تجربة ، فارقه إلى حين » (لو ٤ : ١٣) . وعبارة « إلى حين » تعنى أنه رجع إلى تجربته مرة أخرى أو مراراً عديدة .",{"h":"الشيطان لا ييأس من الفشل أبداً ، ولا يخجل ، بل يعود !"},"لما فشل فى التجربة الأولى مع أيوب ، رجع مرة أخرى يطلب تجربته بأسلوب أصعب ... ولما فشل مع السيد المسيح فى كل التجارب ، أتاه وهو على الصليب يقول له « إن كنت إبن الله ، إنزل من على الصليب » (متى ٢٧ : ٤٠) .",{"h":"والشيطان فى إلحاحه على إسقاط الناس لا يعترف بعقبات ."},"لا يهمه أن آدم وحواء خلقا على صورة الله ومثاله (تك ١) .","ولا يهمه أن داود مسيح الرب ، ولا أن سليمان هو أحكم أهل الأرض كلها ، ولا أن بطرس رسول متحمس جداً للمسيح . ولا يهمه أن يهوشع هو الكاهن العظيم (زك ٣) ، ولا أن هارون هو رئيس الكهنة (خر ٣٢) . ولا أن شمشون هو نذير الرب « وأن روح الرب"],"24":["يحركه » (قض ١٣) ... لا يهمه مراكز الناس ولا روحياتهم ... بل يضرب ضربته ، وليحدث بعد ذلك ما يحدث ... إن كان قد تجرأ أن يجرب المسيح له المجد ، فهل يهتم بالبشر ؟!",{"h":"إنه يلقى سمومه كل حين على كل أحد . وربما الذى لا يهلك بها اليوم ، قد يهلك بها غداً ، أو بعد سنة ، أو بعد عشرين ... !"},"إن الشيطان مثابر ، نشيط ، لحوح ، دائب على العمل ، لا يثبط الفشل همته . ولا ييأس من علو قدر الناس فى الروحيات . هو ماض فى خطته لتحطيم الملكوت ، ولكى يضل حتى المختارين أيضاً ... والذى لا يستطيع أن يدنس جسده ، فعلى الأقل يدنس فكره . والذى لا يقبل طعنه فى روحياته ، على الأقل يلطمه بشوكة فى الجسد (٢كو ١٢ : ٧) . وإن لم يستطع أن يسقط أولاد الله ، فعلى الأقل يشتكى عليهم . لذلك قيل إنه :",{"h":"٧ ـ المشتكى"},"وقد قال عنه سفر الرؤيا إنه « المشتكى على أخوتنا ، الذى كان يشتكى عليهم أمام إلهنا نهاراً وليلاً » (رؤ ١٢ : ١٠) .",{"h":"إنه يشتكى على القديسين ، مدعياً أنه لم يأخذ فرصته لمحاربتهم ! ... أو أن فرصته التى أخذها قبلاً ، لم تكن كافية !"},"وقد وقف فى القديم يشتكى على أيوب أمام الله ، مدعياً أنه لم يأخذ فرصة لمحاربته . وقال لله « أليس إنك سيجت حوله ... باركت أعمال يديه ... ولكن إبسط الآن يدك ومس كل ماله ، فإنه فى وجهك يجدف عليك » (أى ١ : ١٠ ، ١١) .","ومع أن الله واجه الشيطان بقسوته وظلمه فى شكواه ، وقال له عن أيوب « إلى الآن هو متمسك بكماله . وقد هيجتنى عليه لأبتلعه بلا سبب » (أى ٢ : ٣) ، إلا أن الشيطان استمر فى شكواه للمرة الثانية ، وطلب فرصة أوسع ، وأخذ سماحاً لضرب أيوب فى جسده بقرح ردىء (أى ٢ : ٧) ...","عجيب أن الشيطان يفعل كل ما يريد ، و يظل يشكو !","وهو يشكو على الرغم من مواهبه العديدة ، فهو :"],"25":[{"h":"٨ ـ كثير المواهب"},"إنه كثير القدرات إلى حد بعيد . يعرف أشياء كثيرة و يتقنها .",{"h":"فالمواهب التى منحت له وهو ملاك ، لم يسحبها الله منه ..."},"معرفته واسعة جداً فى كل مجال . حتى آيات الكتاب المقدس ، يعرفها جيداً ويحارب بها ، وكأنه من اللاهوتيين . وفى التجربة على الجبل ، إستخدم الكتاب المقدس بطريقته الخاصة (متى ٤ : ٦) . بل إنه هو صاحب جميع البدع والهرطقات ، وهو الذى وضع أفكارها فى أذهان المراطقة ، وقدم لهم مفاهيم خاطئة لآيات الكتاب . وصدق القديس أثناسيوس الرسول حينما قال : إن عدونا ليس هو الأريوسيين ، إنما هو الشيطان .","والشيطان يعرف الشعر . بل إن كثيراً من الشعراء يتحدثون عن شيطان الشعر ، وأنه ملهمهم أفكارهم ... لذلك ليس غريباً إن قال أحد علماء الأرواح ، إنه استحضر روح شاعر مشهور وسمع منه قصيدة بنفس أسلوبه ... ليس غريباً أن يكون الشيطان قد تدخل ، وأملى الوسيط شعراً بنفس الأسلوب !",{"h":"والشيطان يعرف الموسيق والفن والنحت والرسم والأغانى ."},"ويمكنه أن يلهم المشتغلين بالملاهى كل ما يحتاجونه فى فنونهم لإغراء الناس وإسقاطهم ، أو إبعادهم بها عن عملهم الروحى .",{"h":"والشيطان من علماء النفس البارزين ، بل هو فى مقدمتهم جميعاً ، بسبب خبرته العملية . وهذه الخبرة تساعده فى حروبه . كما أن حروبه أيضاً تزيد من خبرته ومن علمه . وكما أنه من علماء النفس ، هو أيضاً من علماء الأرواح ، لأنه روح ، يعرف ما للروح أكثر مما يعرف البشر ."},{"h":"غير أن علم الشيطان يسير وفق أغراضه ."},"فالعلم الخالص شىء ، واستخدام هذا العلم لتحقيق غرض هو شىء آخر . وغرض الشيطان معروف وهو مقاومة الله وملكوته . لذلك هو يستخدم كل معارفه لتحقيق هذا الهدف الشيطانى .","ومن صفات الشيطان فى حروبه مع الإنسان ، أنه :"],"26":[{"h":"٩ ـ قاس"},"إنه يعمل بكل قسوة ، بلا رحمة . وقسوته واضحة جداً فى قصة أيوب الصديق . كما أنه جرّ كثيرين إلى الهلاك وأضاعهم ، كالذين هلكوا بالطوفان ، وبنار سادوم ، والذين ابتلعتهم الأرض أحياء (عد ١٦) .","وقسوته واضحة فى الذين يصرعهم ، و يصبحون فى حالة جنون بسببه . ومثال ذلك مجنون كورة الجدريين الذى « كان فيه شياطين ... وكان لا يلبس ثوباً ، ولا يقيم فى بيت بل فى القبور ... وقد ربط بسلاسل وقيود محروساً . وكان يقطع الربط و يساق من الشيطان إلى البرارى » (لو ٨ : ٢٦ ـ ٢٩) ، « وكان يصيح ويجرح نفسه بالحجارة » (مر ٥ : ٥) . وأمثلة هذا المصروع كثيرون ...",{"h":"وتظهر قسوته كذلك فى محارباته للقديسين ، وفى المناظر المخيفة ."},"ففى حربه مع القديس أنطونيوس الكبير كان يظهر له فى مناظر مفزعة جداً ، وأحياناً فى هيئة وحوش مخيفة تصيح حوله بأصوات مرعبة . وفى إحدى المرات ضرب القديس بضربات شديدة مؤلمة للغاية ، وتركه بين حى وميت ... والذى يقرأ سيرة القديس قرياقوس السائح ، يجد أمثلة أخرى تشبه هذا النوع أو أشد ...",{"h":"وهو قاس فيما يثيره على العالم من حروب وويلات وجرائم ."},"ومعروف جداً نتائج كل هذه ... ولكن الشيطان يفرح بكل ويلات العالم ، ويحسب ذلك انتصاراً له ، إلى جوار تحطيمه للنفوس وللعقول ، وبثه للخصومات وأسباب الإنشقاق والتمزق . فهو عامل تخريب لا يهدأ ، بكل عنف . وهو سعيد بتخريبه .","صدقونى ، إننا لو قرأنا عن قسوة الشيطان فى حروبه المفزعة للقديسين ، نقول عن أنفسنا إننا لم نُحارب أبداً من الشيطان . فحروبنا الحالية شىء تافه إلى جوار حروبهم ... والعجيب أنه فى كل قسوة الشيطان ، يتظاهر بالعطف أحياناً ، ولكنه :",{"h":"١٠ ـ خبيث فى تظاهره بالعطف"},"عبارات العطف عنده وسيلة ماكرة لإسقاط الناس ..."],"27":["فهو (يعطف) عليك حينما تصوم ، و يدعوك إلى الأكل ، من أجل صحتك ! محذراً إياك من المرض ومن الضعف ! و يقول لك إحذر من أن تقتل جسدك ، فهو وزنة تمجد بها الله . وقد قال الرسول « إنه لم يبغض أحد جسده قط بل يقوته و يربيه » (أف ٥ : ٢٩) .","وهو يعطف عليك حينما تنشط روحياً ، وتسهر فى الصلاة والقراءة والمطانيات ، و يدعوك فى عطف إلى النوم من أجل راحتك .",{"h":"وهو (عطوف) يخشى عليك من (التطرف) فيدعوك إلى الإقلال من الجهاد ."},"وفى عمق عملك الروحى ، يقول لك : لا داعى لكل هذا ، فإن الآباء يعلموننا أن الطريق الوسطى خلصت كثيرين ... وهكذا يقول لك : إحترس من التطرف ، لئلا الشيطان يضربك ضربة يمين وهى أقسى ، ولئلا تقع فى المجد الباطل وهو شر الرذائل كلها . بل يقول لك : لا شك أن تطرفك هذا فى الجهاد هو من عمل الشيطان ، وهو لا يقصد بك خيراً ! فاستمع لقول الكتاب « لا تكن باراً بزيادة ... لماذا تخرب نفسك ؟ » (جا ٧ : ١٦) .",{"h":"والشيطان (العطوف) يشفق عليك من البكاء على خطاياك ..."},"يقول لك : لماذا تبكى وتحيا فى الكآبة . ليس هذا هو طريق الله ... أليس أن خطاياك قد غُفرت ، ومحاها الرب بدمه ؟! لماذا تبكى عليها إذن ؟! أتريد أن تظل فى البكاء حتى تتلف أعصابك ونفسيتك ، وحتى تنكشف أمام الناس ؟! أليس أن الكتاب يقول « إفرحوا فى الرب كل حين » (فى ٤ : ٤) ... و يظل بك حتى تفقد إنسحاق القلب ، وتفقد دموع التوبة ، وتفتر حرارتك ... وإذ تفعل هذا ، تسهل عليك الخطية وربما تعود إليها . وطبعاً ينسيك قول الكتاب « بكآبة الوجه يصلح القلب » (جا ٧ : ٣) .",{"h":"والشيطان (العطوف) يبرر لك أخطاءك ، حتى لا تتعبك ضميرك ."},"إنه يمنع عنك التبكيت ، حرصاً على مشاعرك ! وإشفاقاً عليك من الحزن ومن اليأس ! ولذلك فى كل أخطائك يقدم لك العديد من الأعذار ومن التبريرات ، و ينصحك قائلاً : لا تقل على كل شىء إنه خطأ ، ولا تبالغ فى تبكيت نفسك ، لئلا يقودك هذا إلى الوسوسة .... حقاً إن هذا خطأ ، ولكنك لم تكن تقصد ، ونيتك طيبة ، وهى تشفع لك . والله ينظر إلى النيات .... وهذا خطأ ، ولكن ماذا كان بإمكانك أن تفعل ؟! الظروف"],"28":["كانت ضاغطة . وصدقنى لو أنا فى موضعك ما كنت أستطيع أن أفعل غير هذا . والله لا يطلب منك فوق طاقتك . لذلك لا تكتئب ...","وبتبرير أخطائك ، تجعل ضميرك واسعاً يبلع الجمل ، و يبعدك عن التوبة وعن الحرص والتدقيق ، وعن الأمانة فى القليل ...","إن (العطف) عند الشيطان ليس حباً ، إنما وسيلة للإسقاط . فاحترس منه ، ولا تسمع له . وكن حازماً مع نفسك . واسلك بتدقيق ... وتأكد أن الشيطان فى كل حروبه معك يكون غير مخلص . كل نصائحه غير مخلصة ، حتى لو كانت بمظهر الخير . إنه لا يريد سوى ضياعك .","من صفات الشيطان أيضاً أنه حسود .",{"h":"١١ ـ حسود"},"قلبه لا يستريح مطلقاً أن يرى إنساناً ناجحاً ، أو إنساناً باراً ، فيعمل كل ما يستطيعه لإسقاط هذا وذاك .",{"h":"وفى حسده يضرب ضرباته بلا رحمة ..."},"لقد حسد يوسف الصديق على ما رآه من رؤى ، فنقل الحسد إلى قلوب أخوة يوسف حتى باعوه كعبد . ثم حسده على نجاحه وثقة فوطيفار به ، فدبر له حيلة ألقاه بها فى السجن كفاعل إثم ...","وحسد العالم على إيمانه بالله ، فألقاه فى الوثنية ، وفى تعدد الآلهة وفى الإلحاد . ودبر لذلك كل صنوف الفكر والفلسفة ، وأيضاً العبادات البدائية . وصدق المزمور حينما قال « لأن كل آلهة الأمم شياطين » (مز ٩٦ : ٥) .",{"h":"والشيطان يحسد المعرفة والحكمة ، ويحسد العفة ، ويحسد الإتضاع ..."},"لذلك فهو ينشر فى العالم الجهل والزنا والكبرياء ، بكل ما عنده من حق . لقد حوّل سليمان عن حكمته وأسقطه . وألقى فى العالم كثيراً من المعارف الخاطئة ، حتى « قال الجاهل فى قلبه ليس إله » (مز ١٤ : ١) . وأصبح الزنا من الحروب الخطيرة"],"29":["التى تحارب العالم كله . كما صارت الكبرياء حرباً يقع فيها من لم يقع فى باقى الخطايا ومن يقع فيها أيضاً .",{"h":"إن حسد الشيطان هو حسد مدمّر ، وليس مجرد مشاعر ."},"فهو إذ يحسد ، يضرب بكل قوة . كما حسد أيوب على كماله ، فضربه بكل قسوة ، واشتكاه أمام الله . وكما حسد سكان البرارى على زهدهم ونسكهم فأثار ضدهم أعنف الحروب . وكما حسد أوريجانوس أعلم أهل عصره وأستاذ اللاهوت الأول فى عصره ، فألقاه فى كثير من البدع حرمته من أجلها الكنيسة ، حتى قيل عنه « أيها البرج العالى ، كيف سقطت ؟! » ...",{"h":"لذلك فى كل ما تعمله من بر ، توقع حسد الشياطين ."},"وتوقع أنهم لا يبقونك مطلقاً فى برك ، بل يحاولون إسقاطك بشتى السبل . فإن ضربوك ضربة فى يوم روحى عميق ، لا تيأس بل قل : هذا ما كنت أتوقعه . ولكنى أطلب من رحمة الله أن تعيننى حتى لا أسقط ثانية .",{"h":"وإن منحك الله موهبة ، فنوقع أيضاً حسد الشياطين ."},"فهم إما أن يحاولوا إسقاطك فى الكبرياء ، أو استخدام الموهبة فى غير موضعها . وبهذا يكونون قد أضاعوا هدفها الروحى ونفعها لك ولغيرك ...","من صفات الشيطان الأخرى أنه :",{"h":"١٢ ـ نهاز للفرص"},"الشيطان يحاول أن يستغل الفرص ، ليلقى فيها تجاربه . كما استغل جوع السيد المسيح بعد صوم أربعين يوماً ، لكى يجربه بتجربة الخبز .","وكما انتهز فرصة خوف بطرس ليلقيه فى إنكار المسيح .","وانتهز أيضاً فرصة تمسك اليهود بالسبت ليجعلهم ينكرون معجزات للمسيح لم يعملها أحد من قبل ، بل يتهمونه بالخطية (يو ٩ ، ١١) .","من صفات الشيطان أيضاً أنه :"],"30":[{"h":"١٣ ـ غير مخلص وغير أمين"},"قلنا قبلاً إن الشيطان قد يأخذ موقف الشفوق على صحتك ، سواء من جهة الصوم أو السهر ، أو تعب الجسد جملةً . و ينصحك فى ذلك بالراحة الجسدية ، حرصاً على سلامة صحتك ... !",{"h":"ولكنه ليس أميناً حقاً من جهة إهتمامه بصحة جسدك ."},"إنه ينصحك بالراحة ، ويمنعك من السهر ، إن كان سهرك فى الصلاة أو التأمل ، أو القراءة الروحية ، أو فى ليالى الصلاة . ولكنك إن سهرت فى اللهو أو فى وسائل الترفيه المتنوعة ، فلا يحدثك عن مضار السهر خوفاً على صحتك !",{"h":"وإن تعبت فى أمور العالم الباطلة ، لا ينصحك بالراحة ..."},"إن تعبك فى جمع المال ، وفى الجرى وراء السهر والجاه ، وفى السعى وراء ملاذك ومتعك ، وفى تنظيم الحفلات الصاخبة ، وفى اللعب والرياضة ، وفى كافة الأنشطة العالمية ... كل هذا لا يثير إشفاقه عليك ، ولا يدعوك فيه إلى الراحة ... !","إنما ينصحك بالراحة ، إن كان تعبك فى أى عمل روحى . جهادك الروحى فقط هو الذى يثير إشفاقه عليك وعلى صحتك ؟",{"h":"لذلك إن دعاك إلى الراحة وقت جهادك الروحى ، فلا تطعه ."},"إنها فى حقيقتها دعوة منه إلى الكسل والتراخى ... أما أولاد الله ، فكانوا يفرحون بالتعب ، بل و يفتخرون به (١كو ١٥ : ١٠) . وكما قال القديس بولس الرسول « فى الأتعاب أكثر ... فى تعب وكد . فى أسهار مراراً كثيرة » (٢كو ١١ : ٢٣ ، ٢٧) . وقال أيضاً « كل واحد سيأخذ أجرته بحسب تعبه » (١كو ٣ : ٨) .",{"h":"إن عرفت هذا ، إتعب من أجل الله ، على قدر طاقتك ."},"واعلم أن نصيحة الشيطان لك بالراحة ، نصيحة غير مخلصة ، وغير أمينة ، وغير صادقة . لقد تعب القديس الأنبا بولا الطموهى فى النسك ، إلى أن ظهر له ربنا يسوع المسيح وقال له « كفاك تعباً يا حبيبى بولا » . فرد عليه القديس « وماذا يكون تعبى هذا ، إلى جوار كل تعبك يارب لأجل خلاصنا ؟! » ."],"31":[{"h":"خير لك أن تتعب ههنا على الأرض ، لتنال أكاليل الجهاد ."},"من أن تستريح ههنا على الأرض ، وتتعب هناك فى الأبدية ...","واعلم أن تعبك هنا ليس منسياً أمام الله ، لأنه « ليس بظالم حتى ينسى تعب المحبة » (عب ٦ : ١٠) . وكل تعب تتعبه ههنا ، مكنوز لك هناك فى الأبدية .",{"h":"ليس ههنا مكان الراحة . إنما هنا مكان الجهاد والتعب ."},"لذلك حينما يموت إنسان ، يقولون إنه تنيح أى استراح ...","فالشيطان ليس أميناً فى دعوتك إلى الراحة . إنه يخدعك ...",{"h":"إنه يحدثك عن الصحة وقت النسك ، وليس وقت الفساد !"},"إن صمت ، يلبس الشيطان ملابس الأطباء ، و يلقى محاضرة مستفيضة عن أهمية البروتين الحيوانى والأحماض الأمينية الأساسية . و يظهر إهتمامه بجسدك وسلامته .","ولكنه لا يتحدث عن سلامة جسدك إذا داومت على التدخين أو المسكرات ، أو الشهوات الشبابية الضارة بالصحة . إنه ليس مخلصاً فى دعوتك إلى الصحة .",{"h":"لذلك إن حاربك براحة الجسد وصحته ، فقل : ليس هذا وقته ."},{"h":"إن كانت حرب الراحة من الشيطان ، فإن حرب الكسل أشد ."},"إننا حينما نتعب بالجسد ، نشعر براحة نفسية . والعكس صحيح .","حينما نكمل واجباتنا نشعر براحة وفرح ، مهما تعبنا بالجسد . وانتصارنا على جسدنا فى الصوم والسهر والمطانيات والعفة ، يعطينا راحة لا توصف ."],"32":[{"h":"الفصل الثالث"},{"h":"حيل الشيطان"},"« نجنا من حيل المضاد ... » ،","« وإبطل سائر فخاخه المنصوبة لنا » .","( تحليل صلاة الغروب )"],"33":["ما أكثر حيل الشياطين ! إنها لا تنتهى . إن لم تصلح حيلة منها ، يستبدلها بغيرها ، وبثانية وثالثة ... إلى أن يصل إلى غرضه . وليست هناك خطة واحدة أمامه لتوصّله . بل هو يتخذ لكل وضع ما يراه مناسباً ، دون أن يتقيد بشىء ...","على أنه من أشهر خططه الواضحة المتكررة ، بضعة أساليب صارت معروفة ومحفوظة ، نذكر من بينها ما يأتى ...",{"h":"١ ـ خطية تلبس ثوب الفضيلة"},{"h":"ما أسهل أن يقدم لك الشيطان بعض الخطايا بأسماء غير أسمائها ، بأسلوب يسهل قبوله . بحيث تلبس الخطايا ثياب فضائل ..."},"وكما قال السيد الرب « يأتونكم فى ثياب الحملان وهم ذئاب خاطفة » (متى ٧ : ١٥) .","فالتهكم على الناس والإستهزاء بهم ، يقدمه على اعتبار أنه لطف وظرف ، ومحبة ودالة ، وخفة روح ، ومحاولة للترفيه ... !","والدهاء يسميه باسم الذكاء ... !","و يقدم لك القسوة فى معاملة أولادك أو إخوتك الصغار ، باسم التأديب والتربية والتقويم . ويجعل ضميرك يوبخك إن لم تؤدبهم .","والتزين غير اللائق والتبرج ، يقدمها لك باسم الأناقة والنظافة .",{"h":"إن الشيطان لا يقدم الخطية مكشوفة ، لئلا يرفضها الإنسان ."},"بل يقدمها باسم آخر ، وهى هى ، ولا فارق ...","يقول إننى سأدخل مع ( فلان ) فى حرب مسميات ، وأسقطه فيما أريد ، ربما دون أن يشعر ... أو قد يشعر ولكن ضميره لا يبكته ."],"34":["لو أننى قدمت له الرياء بهذا الإسم المنفر ، فلن يقبله . إذن ماذا أفعل ؟ سأجعله مثل القبور المبيضة من الخارج (متى ٢٣) ، بحيث يكون فى الداخل شيئاً ، وفى مظهره الخارجى عكس ذلك تماماً . ولكننى سأدعو الرياء باسم مقبول : أسميه عدم إعثار الآخرين ، أو أسميه القدوة الحسنة .","ليس من ( الحكمة ) أن يسمى الشيطان الخطية خطية ، فيكشف حينئذ أوراقه ، ولا يصل إلى هدفه !","يقول السيد الرب فى حديثه مع تلاميذه :",{"h":"تأتى ساعة ... يظن فيها كل من يقتلكم ، أنه يقدم خدمة ( قرباناً ) لله !! (يو ١٦ : ٢) ."},"ويقيناً أن الشيطان قدم خطية القتل إلى هؤلاء ، باسم « الغيرة المقدسة » أو « الدفاع عن الدين » أو « الجهاد المقدس » أو « تطهير الأرض من الخطاة » . وربما كان هذا هو شعور الكتبة والفريسيين وشيوخ الشعب ، فى تقديمهم السيد المسيح للصلب .","إن الذين انتهروا الأطفال ومنعوهم من الذهاب إلى المسيح (لو ١٨ : ١٥) ، ما كانت هذه قسوة فى نظرهم ، أو عدم إهتمام بالصغار . إنما لبس هذا التصرف ثياب الحملان ، وتسمى باسم فضيلة ، ربما إسمها « حفظ النظام » أو « حفظ كرامة المعلم الصالح » .",{"h":"والكذب يمكن أن يقدمه الشيطان تحت إسم « الحكمة » !"},"يقدمه كنوع من حسن التصرف ، أو إنقاذ المواقف . والطبيب قد يكذب على المريض مرات عديدة ، و يسميها أمام ضميره « حفظ معنويات المريض » ، وحمايته من الإنهيار ، لكى يشفى .","والبعض يسمى بعض أنواع الكذب باسم « الكذب الأبيض » . وربما يسميه فى أول أبريل باسم : الدعابة أو الفكاهة والتندر ، أو أى إسم مشابه .",{"h":"وبهذا الشكل ، ما أسهل على الشيطان أن يسمى الرقص فناً !"},"و يسمى الصور العارية والماجنة فناً أيضاً . وكذلك التماثيل التى من نفس النوع . و يدخل تحت هذا الإسم كل ما فى السينا والمسرح من التمثيل مهما كان خاطئاً ... وكل"],"35":["ما فى الغناء والموسيق ، مهما كان معثراً أو مثيراً ...","وتحت إسم الفن يخفى الشيطان مجموعة كبيرة من الخطايا والعثرات ، لا تستحق هذا الإسم الجميل !",{"h":"إلباس الخطية ثوب الفضيلة ، هو حيلة ماكرة من حيل الشيطان ."},"أتراه يدعو البخل بخلاً ؟! ما كان أحد إذن يقبله . إنما الشيطان قد يسميه « حسن تدبير للمال » أو « حفظ المال لحاجة المستقبل » أو يسميه « عدم التبذير » أو « عدم الإسراف » . وإذا أراد الشيطان أن يمنع غنياً من أن يدفع للفقراء ، يقول له : ليس من الخير أن تعوّدهم الشحاذة ، أو أن تعودهم التشرد والتواكل . إن عدم إعطائهم هو حكمة ، وعين الحكمة ، لكى يبحثوا عن عمل ، ولكى يأكلوا من عرق جبينهم حسب وصية الرب الإله (تك ٣ : ١٩) .",{"h":"إعطاء الخطية إسم فضيلة ، يجعل الناس يستمرون فيها ..."},"فليس فقط من جهة الماضى ، لا يتبكت الإنسان من ضميره . وإنما أيضاً من جهة المستقبل يستمر الخاطىء فيما هو فيه ، بهذا الخداع من الشيطان .",{"h":"أتراه كان يطلق إسم هرطقة على أفكار أريوس ومقدونيوس وسابيليوس وأمثالهم ؟!"},"كلا ، بل كان يقنعهم أن هرطقاتهم هى الدفاع عن الإيمان السليم !! وكان يزوّدهم بالتفسير الخاطىء لآيات الكتاب ، لكى يقبلوا أفكاره ، ولكى يقنعوا أيضاً غيرهم بها ...","إحترس إذن من المسميات الخاطئة ، ولا تسمح للشيطان بأن يخدعك . فإن الخطية هى الخطية مهما اختفت وراء إسم آخر ...","كذلك إحترس من حرب أخرى يلجأ إليها الشيطان ، وهى :",{"h":"٢ ـ تحطيم فضيلة لاكتساب غيرها"},"إن الشيطان يتضايق من فضائلك الثابتة التى صارت وكأنها من طبيعتك . لذلك يحاول أن يحطمها بكل حيلة . وليس أسهل من أن يقدم لك فضيلة أخرى جديدة ، إن"],"36":["لم تسلك فيها بإفراز ـ لقلة الخبرة ـ تضيع الفضيلة الأولى الثابتة . ومثال ذلك :",{"h":"أ ـ إنسان يحيا فى وداعة وهدوء وسكون وسلام قلبى ودماثة خلق ..."},"يريد الشيطان أن يفقده كل ما فيه من رقة ، ومن كلمة طيبة ، ومن تواضع قلب . فماذا يفعل ؟ إنه لا يستطيع طبعاً أن يذم له الوداعة ، أو أن يقول له : أترك طبعك هذا المحبوب من الكل ... ولكنه يصل إلى ذلك عن طريق الإحلال ... يقدم له فضيلة بديلة ، دون أن يقول له إنها بديلة ... وكيف ؟",{"h":"يشرح له أولاً أهمية الآية القائلة « غيرة بيتك أكلتنى » ."},"وكيف أن داود المشهور بالوداعة (مز ١٣٢ : ١) هو الذى قالها . وكيف أن التلاميذ تذكروها حينما صنع السيد المسيح الوديع « سوطاً من حبال ، وطرد الباعة من الهيكل ، وطرد الغنم والبقر ، وكبّ دراهم الصيارف وقلب موائدهم » (يو ٢ : ١٥ ، ١٧) . وقال لهم مكتوب : بيتى بيت الصلاة يدعى ، وأنتم جعلتموه مغارة لصوص » (متى ٢١ : ١٣) .",{"h":"ويدعوه إلى محاربة الأخطاء ، ويزوده بكل الآيات اللازمة ."},"يقول له إن السيد المسيح وبّخ الكتبة والفريسيين بشدة ، وقال لهم فى أصحاح كامل « ويل لكم أيها الكتبة والفريسيون المراءون » (متى ٢٣) ، وواجههم بكل أخطائهم . وقال لهم « أيها القادة العميان » أكثر من مرة . وقال لهم « إنكم تشبهون القبور المبيضة من الخارج » . وقال « هوذا بيتكم يترك لكم خراباً » (متى ٢٣ : ٣٨) . ويوحنا المعمدان قال موبخاً قادة اليهود فى أيامه « يا أولاد الأفاعى . من أراكم أن تهربوا من الغضب الآتى ... » (متى ٣ : ٧) .","ثم يقول له : إسمع قول القديس بولس الرسول . إنه أمر :",{"h":"يأمرك قائلاً « وبّخ . إنتهر . عظ » (٢تى ٤ : ٢) ."},"ولا يكمل له الآية « بكل أناة وتعليم » . ولا يقول له إنها موجهة إلى القديس تيموثاوس الأسقف (أسقف أفسس) ، وليس لكل أحد . ولا يشرح له كيف كان القديس بولس نفسه يوبخ . وكيف قال لكهنة أفسس « ... لم أفتر أن أنذر بدموع كل أحد » (أع ٢٠ : ١٧ ، ٣١) ... وهكذا يلح عليه أن يوبخ وينتهر ...",{"h":"كأنه المسيح أو المعمدان ، أو القديس بولس ، أو تيموثاوس الأسقف ."}],"37":["ويقتنع هذا « الضحية » المسكين . ويظل يوبخ الكل ، وهو لا يعرف الطريقة الروحية للتوبيخ . ولا من يوبخ من ؟ ولا بأى سلطان يفعل هو هذا ؟ وفى توبيخه يقع فى إدانة الآخرين ، وفى الغضب ، وفى القسوة ، وفى التشهير ، وتسوّد صور الناس فى نظره ، وربما بهذا الأسلوب يبعد الكثيرين عن الكنيسة ... و يتحول إلى قنبلة متفجرة ، تقذف شظاياها فى كل اتجاه ... !",{"h":"وهكذا يفقد وداعته ورقته ودمائته ، ويكره الناس ويكرهونه ."},"ثم ما يلبث أن يتعب من هذا الأسلوب الذى لا يتفق مع طباعه ، ويحاول أن يعود إلى حاله الأول . ولكنه لا يجد قلبه نفس القلب ، ولا فكره نفس الفكر . بل يرى أنه قد فقد بساطته ونقاوة قلبه وفكره ، كما فقد حسن علاقاته مع الآخرين ، وفقد أمثولته الصالحة التى كان يستفيد بها غيره .",{"h":"لقد أطمعه الشيطان فى فضيلة لا يعرفها ، وأفقده فضيلته الأولى ."},"فما احتفظ بالأولى ، وماكسب الثانية . وصار فى بلبلة !","وهو يسمح له بممارسة الثانية ، لأنها غير راسخة فيه ، ولا تتعب الشيطان الذى يستطيع أن يزعزعه عنها بسهولة .","من أجل هذا ، كان آباؤنا ينصحون أولادهم بقولهم : إن أية فضيلة يقدمها لك الشياطين ، و يقصدون بها أن يهدموا فضيلة أخرى عندك ، أرفضها وقل لهم :",{"h":"هذه الفضيلة جيدة . ولكننى من أجل الله لا أريدها ."},"حقاً ، إن عمل الله لا يهدم بعضه بعضاً . وكل إنسان له شخصيته التى قد تختلف عن غيره . وقد لا يناسبه ما يناسب غيره . وليس كل أحد له سلطان أن يرتب وينظم ، وأن يوبخ وينتهر ، وأن يحكم ويدين . ومن يعطه الله هذا السلطان ، لابد سيمنحه أيضاً كيف يستخدمه حسناً ، دون أن يخطىء ...","وليس كل إنسان يستطيع أن يقول « ويل لى إن كنت لا أبشر » . فقد قال هذه العبارة القديس بولس الرسول الذى قال فى شرح ذلك « إذ الضرورة موضوعة علىّ » وأيضاً « قد استؤمنت على وكالة » (١كو ٩ : ١٦ ، ١٧) . وأنت ، ما هى الضرورة الموضوعة عليك ؟! ومن الذى استأمنك على وكالة ، كما استؤمن القديس بولس من فم المسيح نفسه . وكما أخذ المعمدان رسالته فى بشرى الملاك لأبيه (لو ١ :"],"38":["١٥ ـ ١٧) . وكما أخذ القديس تيموثاوس مسئوليته بوضع اليد (٢تى ١ : ٦) .","مثال آخر للفضيلة الجديدة ، المقصود بها إضاعة فضيلة أخرى :",{"h":"ب ـ إنسان يعيش فى نقاوة القلب ، بعيداً عن العثرات الجسدية :"},"يعيش محترساً تماماً ، لا يقرأ قراءات تعثره ، ولا ينظر إلى أية مناظر تعثره ، ولا يختلط بأية خلطة معثرة ، ولا يستمع إلى أية أحاديث معثرة . وهكذا يحتفظ بأفكاره نقية ، لا تُدخل إلى قلبه أى شىء غير طاهر ...","هذا الإنسان الطاهر ، يريد الشيطان أن يحاربه . ولا يستطيع أن يقدم له عثرة مكشوفة ، لأنه سيرفضها حتماً . فماذا تراه يفعل ؟",{"h":"يفتح أمامه الباب ليكون مرشداً روحياً ، يقود الشباب للطهارة ."},"إذ كيف يعيش فى الطهارة وحده ، و يترك أولئك المساكين يسقطون كل يوم ، ولا يقدم لهم مشورة صالحة تنقذهم مما هم فيه ؟! و يقول له إستمع إلى قول الرسول « من رد خاطئاً عن ضلال طريقه ، يخلص نفساً من الموت ، و يستر كثرة من الخطايا » (يع ٥ : ٢٠) . ويظل به يقنعه لكى يقبل هذه الخدمة الروحية الحيوية ، حتى يقتنع ، ويقبل أن يرشد الذين يأتون إليه ... ثم تأتى بعد هذا الخطوة الثانية ، وهى :",{"h":"لكى يكون إرشاده عملياً ، لا بد أن يستمع إلى مشاكلهم وأخطائهم ."},"و يظل هؤلاء يضعون فى أذنيه أخبارهم وقصص سقوطهم . وقد يقولون كل شىء بالتفاصيل . وربما يكون فى ما يحكونه ما يعثر ... و يستمع ( المرشد ) الطاهر إلى كل ما كان يبعد عن سماعه ، و يعرف ما كان لا يحب مطلقاً أن يعرفه . وما كان يحاول أن يبعد عنه ، أصبح الآن ينصبّ فى أذنيه ، بكامل رضاه ... وكل واحد يقدم صورة جديدة ، أو صوراً عديدة من الخطأ .",{"h":"وعن طريق الإرشاد ، يجد صاحبنا عقله وقد امتلأ بصور دنسة !"},"وأصبح يعرف أشياء صارت تشوه طهارة تفكيره ، وتدنسه بأخبار وقصص « ذكرها أيضاً قبيح » (أف ٥ : ١٢) ... وحتى إن لم تعثره وتغرس فيه إنفعالات خاطئة ، فعلى الأقل ستنجس فكره . وكأنه قد قطف أثماراً غريبة من شجرة معرفة الخير والشر ...",{"h":"فإن حاول أن يبتعد ، يقال له : ما ذنب هؤلاء الشبان ؟"}],"39":["وقد يكونون قد تعلقوا به ، واستراحوا إلى إرشاده . وربما يتعبون ضميره بأنه إن تخلى عنهم سيرجعون إلى خطاياهم مرة أخرى . وقد يلحون عليه فى أن يظل يسندهم حتى يقفوا على أرجلهم ... وهكذا يحدث له ما حدث للوط البار ، إذ قيل عنه « إذ كان البار بالنظر والسمع ـ وهو ساكن بينهم ـ يعذب يوماً فيوماً نفسه الباره بالأفعال الأثيمة » (١بط ٢ : ٨) . وهذا الأخ قد يكون بالسمع فقط وليس بالنظر . وربما ما يسمعه يضع فى ذهنه صوراً لم ينظرها من قبل ، وكأنه نظرها فعلاً ...",{"h":"وما أدرانا ، ربما هذا الأخ المرشد ، يسقط ، ولو بالفكر والقلب !"},"كان يمكن من أول القصة أن يحيلهم إلى أب اعتراف ويريح نفسه . ولكن الشيطان ورّطه ، أو قذف به فى أول الطريق ، فقبل ذلك بسلامة نية ، دون أن يعرف كيف يتطور به هذا الموضوع .","وقد ينجح أخيراً فى تحويل هؤلاء إلى آباء اعتراف . ولكن بعد أن يكون فكره هو قد صار مخزناً لقصص كثيرة وأخبار ، ضيعت نقاوته الأولى ، وأدخلت فى ذهنه معلومات جديدة عليه ، ينطبق عليها قول الحكيم « الذى يزيد علماً ، يزيد حزناً » (جا ١ : ١٨) .",{"h":"ج ـ وقد تأتى حيلة الشيطان فى الإرشاد بصورة أخرى ، يقدم فيها لا أخباراً تدنس القلب ، بل شكوكاً تتعب العقل"},"إذ يكون القلب فى بساطة الإيمان ، وتكون القراءات كلها روحية تعمّق صلته بالله . و يأتى إليه من يطلبون معونته وارشاده فى شكوك تتعبهم . وتتوالى هذه الشكوك من هنا وهناك ، لكى تجد لها حلاً . و يبدأ إيمان هذا ( المرشد ) يتحول شيئاً فشيئاً من القلب إلى الفكر والبحث العلمى ... وقليلون من يحتفظون بالإثنين معاً ... ويجد الشكوك تتكاثر عليه . وليست له موهبة الرد على الشكوك ...",{"h":"وينبغى أن نعرف أنه ليس كل أحد على مستوى الإرشاد ."},"الذين لهم هذه الموهبة ، لا يصيبهم ضرر سواء فى المشاكل الروحية وسماع الخطايا الجسدية ، أو فى المشاكل العقائدية وسماع الشكوك .","ولكن حيلة الشيطان الماكرة فى هذا الأمر أنه :",{"h":"يقدم الإرشاد للذين ليست لهم الموهبة ، ويصيبهم منه ضرر ."}],"40":["و يقدمه بأسلوب ضاغط ، يشعرهم به أنه ضرورة ملحة ، وأنه واجب مقدس وأن « من يعرف أن يعمل حسناً ولا يفعل ، فتلك خطية له » (يع ٤ : ١٧) . وما أسهل على القلب المتضع أن يقول فى انسحاق « ولكننى هنا لا أعرف » ، « أنا الذى لم أستطع أن أرشد نفسى ، كيف يمكننى أن أرشد آخرين ؟! » ...",{"h":"والشيطان قد يقدم عملاً روحياً ، ليزيل به تأثر عمل روحى آخر ."},"فإن رأى إنساناً قد صلّى صلاة روحية عميقة ، وانسكب فى تأملات حارة أمام الله ، قد يرسل إليه إنساناً يطلب عمل المصالحة بين متخاصمين . لكنها إذا جلس وسط هؤلاء المتخاصمين ، بكل ما فى تصفية الجو من ضوضاء أو شوشرة أو شجار أو عتاب قاس ، تزول آثار الصلاة والتأملات . و يعود هذا المصلى إلى بيته ، وليس فى ذهنه سوى ما سمعه من مناقشات حامية ، ربما تجعل عقله يسرح إذا صلّى . وتحتاج أمثال هذه المواقف إلى إدماج الصلاة فيها ، وإلى تمهيدات روحية بعدها قبل الوقوف أمام الله للصلاة ...",{"h":"وقد يرى الشيطان أن صلاتك حافلة بالتأملات ، فيريد تشتيتها :"},"فماذا يفعل ؟ يقول لك وأنت تصلى « إن هذا التأمل عجيب جداً وعميق ، وإن سمعه آخرون سيستفيدون منه . فلئلا تنساه ، قم الآن واكتبه . وهكذا يكون قد أخرجك من الصلاة إلى الكتابة ، وقطع وقفتك المتخشعة ـ أمام الله ، لكى تجلس وتكتب ، مهتماً بالآخرين أكثر من اهتمامك بالوقوف فى حضرة الله ...","وفى كل ما يجذبك إليه الشيطان من فضائل أخرى ، يكون هدفه :",{"h":"يفقدك ما عندك ، مغرياً إياك بفضائل أخرى ليست معك ."},"أو هو يفقدك الثابت الذى فى يدك ، من أجل وعود فى أشياء قد لا تتم . أو قد يسمح لك ببعضها لكى يسحبه منك فيما بعد ...",{"h":"٣ ـ إستخدام الفضائل فى غير موضعها"},"يقول الكتاب « لكل أمر تحت السموات وقت » (جا ٣ : ١) . فإذا استخدمت الفضائل فى غير وقتها وفى غير موضعها ، ربما تأتى بنتيجة عكسية ، ولا تخدم الغرض الروحى . وهذا بعض ما يقدمه الشيطان ضمن حيله الكثيرة ."],"41":[{"h":"فى وقت التوبة ، حينما يلزم الإنسحاق ، يقدّم فضيلة الفرح ."},"و يورد كل الآيات الخاصة بالفرح ، حتى يضيع الندم والإنسحاق والدموع ، كل هذه الأمور اللازمة لحفظ التوبة . وفى نفس الوقت يخفى الآيات الأخرى مثل « طوبى للحزانى الآن ، لأنهم يتعزون » (متى ٥ : ٤) .",{"h":"وفى منهجه هذا ، يستخدم طريقة الآية الواحدة ..."},"وقد رفض السيد المسيح هذا المنهج . فعندما قال له الشيطان على الجبل « ... لأنه مكتوب ... » أجابه الرب « مكتوب أيضاً ... » (متى ٤ : ٦ ، ٧) . وهكذا أرانا أن منهج الآية الواحدة الذى يستخدمه الشيطان ، لا يمكن أن يوصل إلى حقيقة روحية سليمة ، طالما هناك آيات أخرى توضح الموضوع .",{"h":"وقد يستخدم الشيطان آيات كثيرة فى اتجاه واحد يخدم غرضه ."},"إنه يذكر الآيات الخاصة بالرحمة ، حينما يلزم الحزم وتلزم العقوبة . و يذكر الآيات الخاصة بالعقوبة حينما يلزم العفو والحنو والرحمة .","ويحاول أن يقنع الإنسان بالصمت ، و يورد نصوصاً عديدة من الكتاب ، مستخدماً إياها فى الوقت الذى يجب فيه الكلام . كذلك يورد آيات عن فائدة الكلام وأهميته ، فى الوقت الذى يحسن فيه الصمت ...",{"h":"كذلك يورد للإنسان آيات لا تناسبه ، وهى خاصة بغيره ."},"فهناك آيات خاصة بالرسل ورجال الكهنوت ، لا تنطبق على العلمانيين ، يقدمها لشخص عادى كما لو كانت تخصه هو ... مثل قول المسيح لتلاميذه الإثنى عشر « لا تدعوا لكم أباً على الأرض ... » (متى ٢٣ : ٩) .","ومثال ذلك أيضاً ذلك الشخص العنيف الذى كلما كان يرى شخصاً مخطئاً ، كان ينهال عليه ضرباً !! وذلك لأن الشيطان وضع فى أذنيه الآية التى تقول « فى أوقات الغدوات كنت أقتل جميع خطاة الأرض ، لأبيد من مدينة الرب جميع فاعلى الإثم » (مز ١٠١ : ٨) . من حيل الشيطان أيضاً فى محاربة البشر :"],"42":[{"h":"٤ ـ التشكيك"},"إن الشيطان يزرع الشكوك فى كل مجال من مجالات الحياة . لأن الإنسان فى حالة الشك يكون ضعيفاً يمكن للشيطان أن ينتصر عليه .",{"h":"فهو مثلاً يغرس الشك من جهة التوبة ."},"سواء من جهة إمكانية التوبة ، أو من جهة قبول الله لها .","فهو يصور للإنسان أنه ليس من السهل عليه أن يتخلص من هذه الخطايا ، التى صارت طبيعة فيه ، أو عادة من عاداته ، أو صارت محبوبة لديه لا يمكنه مطلقاً الإستغناء عنها . وإذ يغرس فيه الشك الكامل فى قدرته ، يخفى عنه تماماً معونة الله ، أو يشككه فيها أيضاً ، كما قال داود النبى « كثيرون قاموا علىّ . كثيرون يقولون لنفسى : ليس له خلاص بإلهه ... » (مز ٣) .","أما إن صمم الإنسان على التوبة ، فإنه يشككه فى قبول الله لتوبته : إما لأنها أتت بعد فوات الفرصة ، أو لأنها توبة غير حقيقية ، أو لأن خطاياه بشعة من الصعب مغفرتها ! وتحتاج إلى عقوبات فوق احتماله !",{"h":"وكل هدف الشيطان هو إلقاء التائب فى اليأس ."},"لكى تخور عزيمته ، ويبقى فى الخطية حيث هو ...","وكذلك يشككه الشيطان فى رحمة الله ، و يورد له آيات لا تحصى عن عدل الله ، وعن عقوباته . وربما تكون عقوبات عن خطايا أقل من خطاياه هو بكثير .","وشكوك الشيطان قد تدخل فى الحياة الشخصية أيضاً .",{"h":"فهو يغرس الشك فى أيها أفضل : البتولية أم الزواج ."},"وأى طريق منها يختاره الإنسان يشككه فيه كذلك .","فإن اختار البتولية يشككه فى إمكانية الحياة فيها ، وكيف أنها صعبة جداً ، وهى فقط « للذين أعطى لهم » (متى ١٩ : ١١) ، « وكل واحد له موهبته الخاصة من الله » (١كو ٧ : ٧) . فما أدراك أن هذه موهبتك ؟! و يشرح له السقطات التى وقع فيها القديسون . و يقول له : هل أنت أفضل من داود ومن شمشون ، وكلاهما حل روح الرب عليه ؟!"],"43":["وإن اختار الزواج ، يقول له : لقد فقدت إكليل البتولية . و يضع أمامه قول القديس بولس الرسول « غير المتزوج يهتم فيما للرب كيف يرضى الرب . أما المتزوج فيهتم فيما للعالم كيف يرضى إمرأته » (١كو ٧ : ٣٢ ، ٣٣) ، « ومن لا يزوج يفعل أحسن » (١كو ٧ : ٣٨) .","وهكذا يتركه فى بلبلة لا يعرف أى الطريقين يختار ... !",{"h":"وهو يغرس الشكوك أيضاً فى موضوع الوحدة والخدمة ."},"إن اختار الإنسان طريق الوحدة ، يشرح له أمجاد الخدمة ، وكيف أنها طريق الرسل وأبطال الإيمان ، وأن « الذين ردوا كثيرين إلى البريفسيون كالكواكب إلى أبد الدهور » (دا ١٢ : ٣) ، وأنه « لا يوقدون سراجاً و يضعونه تحت المكيال ، بل على المنارة ، فيضىء لكل من فى البيت . فليضىء نوركم هكذا قدام الناس ... » (متى ٥ : ١٥ ، ١٦) .","وإن اختار الإنسان طريق الخدمة ، يقول له الشيطان : لقد فقدت طريق الملائكة الأرضيين ، وحياة السكون والهدوء التى يتفرغ فيها الإنسان لله وحده . أما أنت فقد اخترت طريق مرثا التى وبخها الرب بقوله « أنتِ تهتمين وتضطربين لأجل أمور كثيرة ولكن الحاجة إلى واحد » . ولم تختر طريق مريم التى جلست عند قدمى المسيح ، واختارت النصيب الصالح (يو ١٠ : ٤١ ، ٤٢) . و يذكره بالرؤيا التى ظهر فيها أن أرسانيوس المتوحد كان أفضل من موسى الأسود محب الأخوة وخادمهم .","وهكذا يستمر الشيطان فى غرس الشكوك . وكما قال يوحنا الدرجى : الراهب الذى يعيش فى الوحدة ، يحاربه الشيطان بمحبة الأخوة وخدمتهم . والراهب الذى يخدم الأخوة فى المجمع ، يحاربه الشيطان بمحبة الوحدة وحياة السكون والصلاة والتأمل .",{"h":"والشيطان يغرس الشكوك فى العلاقات الإجتماعية كلها ."},"فهو يغرس الشكوك بين الزوج وزوجته ، وبين الصديق وصديقه ، وبين الشركاء فى العمل ، وبين الرئيس ومرؤسيه . يشكك فى محبة الواحد للآخر ، أو فى إخلاص وأمانة الواحد للآخر . بل يشككك فى كل تصرفات الناس ، وفى نياتهم ومقاصدهم . وكل ذلك لكى يزعزع صلات الناس ببعضهم البعض ، ويحولها إلى إنقسامات ونزاعات ، و يضيع الحب الذى هو عماد الحياة الروحية والإجتماعية كلها ..."],"44":["حتى الأمور التى يمكن أن تمر ببساطة ، يعقدها الشيطان بشكوكه العديدة ، وقد يخلق منها مشاكل عويصة ... !",{"h":"وهو يشكك أيضاً فى الإيمان ذاته وفى العقائد ."},"وكل البدع والهرطقات التى قاست منها البشرية هى من صنع الشيطان ومن أفكاره ، وكذلك كل المذاهب المتعددة وما بينها من صراعات . والإلحاد أيضاً هو من صنع الشيطان ...",{"h":"والشيطان أيضاً يشكك فى إمكانية الحياة مع الله ."},"و يشرح أن الحياة الروحية صعبة وغير ممكنة . فمن من الناس يستطيع أن يسير فى الطريق الكرب ، أو أن يدخل من الباب الضيق (متى ٧ : ١٣ ، ١٤) . ومن يستطيع أن يصل إلى حياة الكمال التى يطلبها الرب منا (متى ٥ : ٤٨) . ومن يستطيع أن ينجو من حروب الشياطين ؟!","وفى كل ذلك يخفى عمل النعمة وعمل الروح القدس فى خلاص الإنسان ، ويخفى معونات الله الكثيرة !!",{"h":"والشيطان قد يغرس فى القلب شكوكاً حول أب الإعتراف ."},"فيشككك فى مدى إهتمام أب الإعتراف بالمعترف ، ومدى محبته له ، ومدى كتمانه لأسراره ، و يشككك فى إرشاداته وصحتها وصلاحيتها للنمو الروحى . يشككك فى معرفته ، وأيضاً فى روحانيته . وهو يريد بكافة الطرق أن يبعد ضحيته عن أب الإعتراف ، الذى يكشف له حروب الشياطين وحيلهم ومكرهم . و يبقى المسكين بلا مرشد فيصبح فريسة سهلة للشياطين .","إنه يشككه فى أب الإعتراف ، لكى يخالفه ، أو يتركه ، أو أن يخفى عنه تدابيره . وكلها وسائل خاطئة . وقد يشككه أيضاً فى سر الإعتراف ذاته . و يقول له : لماذا تعترف على إنسان مثلك ؟!",{"h":"وقد يشككه فى الفضيلة ذاتها ..."},"فيقول له مثلاً ما لزوم الإتضاع والوداعة ؟ إنها يضعفان شخصيتك ! وما معنى أن تترك حقك ، ولا تأخذه بالقوة ، حتى يتلاعب بك غيرك ... ؟ وهكذا مع باقى الفضائل .","أما أنت فلا تقبل الشكوك . وكلما أتاك شك ، قل : هذا من عمل الشيطان ..."],"45":[{"h":"ولا تقبل الشك داخلك ، ولا تستعمله ، ولا تدعه يستمر ..."},"إن كنت كفؤاً لمناقشته ، ناقشه واثبت زيفه ، واطرحه خارجاً . وإلا ، أطلب من الله أن يرفعه عنك . وتذكر قول الكتاب « كونوا راسخين ، غير متزعزعين » (١كو ١٥ : ٥٨) .","وأرجو بنعمة الله أن أحدثك عن الشكوك فى مناسبة أخرى ، بنطاق أوسع ، حينما نتحدث عن الحروب الروحية ، واحدة فواحدة بالتفاصيل .","سلاح آخر من أسلحة الشيطان فى حروبه ، هو :",{"h":"٥ ـ حرب اليأس"},"اليأس حرب يلجأ إليها الشيطان بعد مقدمات طويلة تمهيدية ...","* وربما تكون هذه المقدمات سقطات متتالية يوقع فيها ضحيته ، بلا هوادة ، حتى يصرخ أخيراً ويقول لا فائدة فى . من المستحيل أن أخلص طالما أنا هكذا ... !","* وقد تكون هذه المقدمات إيحاءات يغرسها فى نفسه باستمرار ، باسم التواضع ! يقول فيها لنفسه كل يوم « أنا ضعيف وعاجز ، وكلى خطية » ... ولكن بدلاً من أن يوصله إلى الإتضاع ، يقوده إلى صغر النفس ، والشعور بأنه لن يقوم ثانية ...","* وربما تكون مقدمة حرب اليأس ، هى سقطة كبيرة (مثل سقطة يهوذا) يشعره الشيطان بعدها بأنه لا مغفرة ! أو قد لا تكون السقطة بهذه الدرجة ، ولكن ...",{"h":"من عادة الشيطان أن يضخم فى الأخطاء ليوقع صاحبها فى اليأس ."},"والشيطان ماكر جداً فى هذه الناحية . فهو قبل السقوط يسهّل موضوع الخطية جداً ، حتى لتبدو شيئاً عادياً ، و يضع لها مبررات ... أما بعد الخطية ، إما أن يستمر فى سياسة التهوين لكى تتكرر ، وإما أن يدخل فى أسلوب التهويل ليوقع صاحبها فى اليأس . و يقول له : هل من المعقول أن يغفر الله خطية مثل هذه ؟",{"h":"وربما يشعر الخاطىء أنه وقع فى التجديف على الروح القدس !"},"وهكذا لا تكون له مغفرة إلى الأبد (مر ٣ : ٢٩) . وطبعاً لا تكون لتلك الخطية أية علاقة بالتجديف على الروح القدس . فالتجديف على الروح هو طرد الروح القدس"],"46":["من القلب ، طرداً كاملاً دائماً مدى الحياة . وهكذا لا تكون للإنسان توبة ، وبالتالى لا مغفرة . لأن المغفرة مرتبطة بالتوبة ، والتوبة مرتبطة بعمل الروح فى القلب .",{"h":"وقد يجره إلى اليأس ، بإشعاره أنه لن يتوب ... !"},"يقول له : « هل من المعقول أنك ستترك الخطية ؟! مستحيل . لقد صارت تجرى فى دمك . عزيمتك إنتهت ، وإرادتك إنحلت . بل حتى مجرد الرغبة فى التوبة أصبحت غير موجودة عندك ... كم مرة حاولت أن تتوب ، وفشلت ؟! كم مرة إعترفت بخطاياك ، ورجعت إليها وربما بدرجة أسوأ ؟ ... » وهكذا يحطم معنوياته إلى أن يستسلم له ، و يتوقف عن المقاومة .","يقول له : إنك قد صرت بكليتك فى يدىّ . أنقلك من هذه اليد إلى الأخرى ، بكل سهولة ، كما أشاء . فلا داعى إذن لصراع فاشل لا تكسب منه شيئاً .",{"h":"وطبعاً كل هذه تخاويف لا أساس لها ، وتهديدات زائفة ..."},"فإن الله قادر أن يمنح الإنسان التوبة ، مهما كانت حالته سيئة . والتاريخ يحكى لنا الحالات السيئة جداً التى كانت فيها مريم القبطية ، وبيلاجيه ، وأغسطينوس ، وموسى الأسود . ومع ذلك تابوا . وليس هذا فقط بل صاروا قديسين ...","ومع ذلك فكلما سقط الإنسان ، يحاول الشيطان إلقاءه فى اليأس .",{"h":"ويقنعه بأن هذا سقوط دائم أبدى ! وليس سقوطاً طارئاً ."},"فما أجمل كلمة العزاء فى سفر ميخا النبى « لا تشمتى بى يا عدوتى . ( فإنى ) إذا سقطت أقوم » (مى ٧ : ٨) . والكتاب يقول إن « الصديق يسقط سبع مرات و يقوم » (أم ٢٤ : ١٦) . ومع هذا السقوط الكثير ، سماه الكتاب صديقاً ...",{"h":"ومن وسائل الشيطان فى اليأس ، ضربه لنا فى أوقات روحية ."},"وهذه من حيله المشهورة ، حتى باتت معروفة للكثيرين . ومثال ذلك :","تكون فى سهرة روحية طول الليل فى الكنيسة ، فى بدء عام جديد ، وكلك رغبة وتصميم أن تبدأ حسناً بعام مبارك مقدس . وتحضر السهرة والقداس وتتناول . ثم تخرج لكى يرسل لك الشيطان إنساناً متعباً جداً يعكر دمك و يشيرك ، ويجعلك تغضب وتخطىء . وحينئذ يضربك الشيطان باليأس ، فتقول : أبعد كل هذا أسقط ! إذن لا فائدة ."],"47":[{"h":"كلا ، لا تيأس . فهذه هى حيله المعروفة ."},"قل كما قال النبى « إنى إن سقطت أقوم » ...","واعرف أن الشيطان لا يهدأ فى حربه . فى أول كل عام جديد ، وفى كل يوم روحى ، وبعد كل صلاة روحية ، وفى بداية كل صوم ، وبعد كل تناول ... توقّع منه ضربة لإسقاطك فإن فعل ، قل له إلعب لعبة أخرى ، فقد صارت ألاعيبك هذه مكشوفة ...","صدقونى إن الحروب فى المناسبات الروحية ، لا تحصى ... وقد تكون هذه الحروب مجرد حسد من الشيطان لعملك الروحى أو لنجاحك .",{"h":"ومن وسائل اليأس ، أن الشيطان يغرى الإنسان بمستويات أعلى منه ."},"يضربه ضربات يمينية ، ويقنعه بمستويات روحية لا يستطيع الوصول إليها ، ويشجعه على ذلك بكل قوة . فإن نصحه أب اعترافه بالتدرج حتى يصل ، وأراد أن يقلل من هذا المستوى ، يشككه فى أب اعترافه ومستواه الروحى .","وما أسهل أن يسلك الإنسان يومين أو ثلاثة أو أكثر فى درجة عالية ، على غير أساس ، ثم لا يستطيع أن يستمر ، و يفشل . وهنا يبدأ الشيطان أن يعيّره و يلقيه فى اليأس ، و يقول له : إنك لا تصلح للطريق الروحى ! طبيعتك لا تتفق مع الحياة الروحية السليمة . و يستمر فى تحطيم نفسيته ... بينما لو تدرج ، كما نصحه أب الإعتراف ، لاستطاع أن يصل إلى هذا المستوى الذى أراده الشيطان أن يبدأ به .",{"h":"لقد استطاع الشيطان أن يقنع الكتبة والفريسيين بأن يسلكوا بأسلوبه ."},"فكانوا فى إرشادهم الروحى « يحزمون أحمالاً ثقيلة عسرة الحمل ، و يضعونها على أكتاف الناس . وهم لا يريدون أن يحركوها بأصبعهم » (متى ٢٣ : ٤) . وهذه الأحمال الثقيلة تدفع أحياناً إلى اليأس ، إذ قد يقول حاملها : من يقدر على هذا ؟ من يستطيع أن يخلص ؟!",{"h":"أما الرسل القديسون فلم يفعلوا هكذا ، بل رأوا فى قبول الأمم « أن لا يثقّل على الراجعين إلى الله من الأمم » (أع ١٥ : ١٩) ، وأرسلوا إليهم قائلين « لا نضع عليكم ثقلاً أكثر ، غير هذه الأشياء الواجبة » (أع ١٥ : ٢٨) . وقد قال القديس بولس الرسول « سقيتكم لبناً لا طعاماً ، لأنكم لم تكونوا بعد تستطيعون » (١كو ٣ : ٢) ."}],"48":[{"h":"لذلك إن أغراك الشيطان بما فوق مستواك ، فلا تقبل ."},"قل له : إذهب عنى يا شيطان ، فإن لى مرشدى الروحى الذى أسمع له . أما أنت فلا تقصد بى خيراً . ولك طرقك بلا نظام ، ولا توصل .","يروى عن القديس الأنبا أنطونيوس أن الشيطان أيقظه ذات ليلة لكى يصلى ، فلم يقبل القديس نصيحته . وقال له : أنا أصلى حينما أريد ، ومنك لا أسمع ...","إن الشيطان يرفع الإنسان لكى يسقطه . وإن سقط يدفعه إلى اليأس فى شماتة . وحرب اليأس هامة بالنسبة إلى الشيطان ...",{"h":"فالإنسان حينما ييأس ، تتحطم روحه المعنوية ، ويفقد ثقته بنفسه ، وثقته بالله ، وثقته بإمكانية الحياة الروحية ، ويستسلم للسقوط ..."},"وهذا هو عين ما يريده الشيطان . لكيلا تقاومه فريسته ، فتهلك . وكأنه يقول لهذا الإنسان اليائس المستسلم له : إنك لن تفلت من يدى . أنت ذاهب إلى جهنم لا محالة . فلا فائدة . ولذلك نصيحتى لك أن تتمتع بالدنيا بضمة أيام ، بدلاً من أن تخسرها دنيا وآخره ... !",{"h":"يقنعه الشيطان بصعوبة الحياة الروحية ، وبأنه ضعيف وطبيعته فاسدة ! كما يقنعه بأنه لن يفلت من يده ، ولا من العدل الإلهى ..."},"هذه هى أكبر أسلحة الشيطان فى حرب اليأس . والرد على كل ذلك بسيط . وهو أننا لا نحارب بإرادتنا الطبيعية ، لأن الحرب للرب (١صم ١٧ : ٤٧) ، وهو الذى يقودنا فى موكب نصرته (٢كو ٢ : ١٤) . وإن كنا نحن لا نستطيع ، بسبب ضعفنا وفسادنا وصعوبة الطريق ، فإننا نستطيع كل شىء فى المسيح الذى يقوينا (فى ٤ : ١٣) . يسندنا عمل النعمة ، وقوة الروح القدس العامل فينا ، وملائكة مرسلون لمعونتنا (عب ١ : ١٤) . وتسندنا شفاعة القديسين فينا ...","أما الشيطان فلا سلطان له علينا ، ولا نعبأ بتهديده ، وما أجمل قول الرسول « قاوموا إبليس فيهرب منكم » (يع ٤ : ٧) . أما العدل الإلهى فقد وفاه الرب على الصليب ، وقد قدّم لنا فى حبه خلاصاً هذا مقداره (عب ٢ : ٣) . ونحن « إن اعترفنا بخطايانا ، فهو أمين وعادل ، حتى يغفر لنا خطايانا ، و يطهرنا من كل إثم » (١يو ١ : ٩) . و يغسلنا فنبيض أكثر من الثلج (مز ٥٠) . وهو الذى قال لنا « إن كانت"],"49":["خطاياكم كالقرمز ، تبيض كالثلج ... » (إش ١ : ١٨) .",{"h":"إن حرب الشيطان هى اليأس ، بالطرق التى وحدنا عليها ."},{"h":"أما الكتاب فإنه يشجعنا . ويجعل الرجاء من الفضائل الكبرى (١كو ١٣ : ١٣) ."},"وكثيرة هى وعود الله لنا وللكنيسة : إن أبواب الجحيم لن تقوى عليها (متى ١٦ : ١٨) . وإننا « بقوة الله محروسون » (١بط ١ : ٥) . وأنه قد نقشنا على كفه (إش ٤٩ : ١٦) . والكتاب يقول إن « الله لم يعطنا روح الفشل ، بل روح القوة ... » (٢تى ١ : ٧) . ولذلك نصحنا الرسول أكثر من مرة بأننا « لا نفشل » (٢كو ٤ : ١٦ ، غل ٦ : ٩) .",{"h":"إن كنت ماشياً فى الطريق الروحى ، ووقعت ، لا تظن أنك لا تعرف المشى ، وتيأس ! بل قم وأكمل المسير ..."},"إن الشيطان يحسد خطواتك ويريد أن يعرقلها . فلا تدفعك عراقيله إلى اليأس . بل على العكس ، قم بقوة أكثر . واعرف أنه لولا نجاحك فى العمل الروحى ، ما كان الشيطان يحاربك ! حقاً ، لماذا يتعب الشيطان نفسه فى محاربة الساقطين ؟! إنه يتصدى بالحرى للقائمين ، وللذين يخاف جهادهم ضده .","إستمع إذن إلى قول الرسول « كونوا راسخين غير متزعزعين » (١كو ١٥ : ٥٨) .",{"h":"كن قوى القلب بالله ، ولا تيأس ..."},"لا تيأس مهما كانت حروب الشيطان قوية .","ولا تيأس مهما سقطت ، ومهما نسيت الوصية ، ومهما فشل التدريب .","لا تيأس إذا كانت البداءة التى بدأت بها بداءة ضعيفة ، أو بداءة ساقطة ، أو بداءة ضائعة .","قل لنفسك : كل هذه مجرد حروب ، وأنا سأثبت فى الله .",{"h":"سأسير نحو الله ، وإن كنت أجرّ رجلىّ جراً إليه ..."},"مهما سقطت مائة مرة فى الطريق ، سأقوم وأكمل طريق ...","ولن أقبل اليأس مطلقاً . إنه من عمل الشيطان .","ننتقل إلى حيلة أخرى من حيل الشيطان وهى أن :"],"50":[{"h":"٦ ـ الشيطان يغير خططه"},{"h":"إن الشيطان لا يصر على خط معين فى محاربته للإنسان . إنما ما أسهل أن يغيّر خطه وخططه ، إن كان ذلك يوصله إلى إسقاط من يريد ."},"وسنضرب لذلك بعض أمثلة :","أ ـ شاب كان يحاربه الشيطان بالزنا حرباً عنيفة ويتعبه فيها ويسقطه أحياناً . فبدأ هذا الشاب فى حياة توبة ، وأصبح يحترس من هذه الخطية بالذات إحتراساً شديداً : يبعد عن كل أسبابها . ويسد كل الأبواب التى تأتى منها الخطية ، سواء كانت من القراءات أو السماعات أو اللقاءات . وفى نفس الوقت يقوى نفسه من الداخل بكل الوسائط الروحية ، و يصلى إلى الله بدموع لكى ينقذه ...","فماذا يفعل الشيطان إزاء هذا الحرص الشديد من خطية الزنا ؟",{"h":"يقول : أتركه الآن ، لا أحاربه بهذه الخطية فترة طويلة ، حتى يظن أنه انتصر عليها تماماً ، فلا يحترس من جهتها . ولنحارب حالياً بخطية أخرى ..."},"و يتركه سنة أو إثنتين أو ثلاثاً ، بلا حروب فى هذه الخطية ، بلا عثرات ، بلا أفكار . و يلقيه مثلاً فى خطية كالكبرياء ...","يرى المسكين أنه نجا من الزنا ، فيفرح . و يغريه الشيطان بمستوى عال فى الصوم ، فى القراءة ، ثم فى الخدمة ، وفيما هو مستريح الفكر من الخطية ، ومستريح فى منهجه الروحى ، يدعوه الشيطان إلى تطبيق هذا المستوى على غيره . و يريه أنهم مقصرون ، وأنه فاقهم بمراحل ، فيوقعه فى الكبرياء . ويدعوه الى توبيخهم وتبكيتهم وإدانتهم : أبوك لا يصلى . أمك لا تصوم . إخوتك لا يتناولون . أسرتك لا تقرأ الكتاب . إذهب وبّخهم ، وبشدة ...","ويمتد نطاق التوبيخ واحتقار الآخرين ، وشتيمة واحتقار هؤلاء وأولئك ، لأنهم بعيدون عن الله ، مع تعالى القلب بما وصل إليه . وفيما هو يحاول أن يخلع الزوان ، يصير هو نفسه زواناً . إذ أصبح باسم الحق يشتم ، ويحتد ، ويدين ، ويحتقر ، ويتعالى على غيره ، ويسبح فى الغرور والكبرياء ، يقول كالفريسى « أشكرك يارب إنى لست مثل سائر الناس ... » (لو ١٨ : ١١) ."],"51":["وتسأل الشيطان عن خطية الزنا التى أراح منها هذا الشاب ؟",{"h":"فيجيب : الذى يهلك بالكبرياء ، كالذى يهلك بالزنا . كلاهما هالك ."},"أليس أن الذى يموت بالسلّ ، كالذى يموت بالسرطان ، كالذى يموت فى عملية جراحية ؟ كله موت ... والنهاية واحدة ... « تعدد الأسباب ، والموت واحد » ...","أما حرب الزنا التى يظن هذا الشاب أنه قد نجا منها ، ففى الحقيقة أن لها يوماً تعود فيه إليه ، حينما يقل إحتراسه من جهتها ، و يقل حرصه واجتهاده فى مقاومتها . حينئذ نضربه الضربة فلا يفيق منها . وتسأله كيف ؟ فيقول :","فى الفترة التى استراح فيها الشاب من حرب الزنا ، ظن أنها فارقته بلا عودة ، ولم يعد لها وجود فى حياته ، وأنها من الخطايا التى تحارب المبتدئين فقط . ولا يعقل أن تحارب المستويات العليا التى وصل إليها ! بل إن كثيرين أصبحوا يسترشدون به فى مقاومة هذه الخطية .","وهكذا أصبح يسمع تفاصيل عن هذه الخطية ما كان يسمح لنفسه أن يسمعها من قبل . وبعض أمور خافية عن معرفته ، صار يقرأ لها كتباً فى هذا الموضوع المعثر ، ليرد على أسئلة سائليه ، وما كان يقرأ هذه القراءات مطلقاً فى فترة حرصه واحتراسه !","وهكذا امتلأ ذهنه بأفكار صارت تترك فى نفسه مشاعر وتأثيرات ، تنمو بمرور الوقت وهو لا يدرى . إلى جوار أنه بسبب الكبرياء وإدانة الآخرين ، بدأت النعمة تتخلى عنه . وهنا أتت الساعة التى يضربه فيها الشيطان بهذه الخطية بالذات . و يسهل عليه إسقاطه . وتكون خطة الشيطان قد نجحت على الرغم من تغييرها فى الطريق ...",{"h":"وهنا يقول الشيطان : إننى أرحته زمناً من هذه الخطية ، لكى لا يستعد لها . وحينما لا يستعد لها ، لا يدقق . وفى عدم تدقيقه يتساهل مع الخطية وأفكارى . وفى هذا التراخى وتساهله معى ، أضربه بالخطية التى استراح منها سنوات ، فيسقط بسهولة ."},"هذا هو الشيطان ... ! قد لا يحاربك الآن بخطية معينة ، ليس محبة منه لك ، إنما لأنه يجهز لك فخاً من نوع آخر .","ب ـ مثال آخر : إنسان آخر ساقط فى خطية الغضب ، وخطية الإدانة ، وخطايا السب والكلام الجارح . بدأ يستيقظ لنفسه ، ويدخل بقوة فى تداريب صمت ،"],"52":["ليتخلص من خطايا اللسان جملة . فماذا يفعل الشيطان ؟",{"h":"يقول : لا مانع من أن نغير الخطة . وبدلاً من محاربته بخطايا اللسان والغضب ، نحاربه بخطية الغرور مثلاً ..."},"بحيث يقتنع تماماً ، أنه لا يوجد إنسان أفضل منه . وكيف ذلك ؟ نريحه من خطايا اللسان تماماً ، فلا نحاربه بها الآن مطلقاً . وننصحه بشىء من النمو الفجائى فى العمل الروحى ، بلون من المغالاة ، ولا نحاربه فى ذلك .","و يظن أن لا يوجد مثله ، فيسلك فى الغرور . وربما يختلف مع أب اعترافه الذى لا يوافقه على تطرفه وغروره ، فلا يأبه . و يصبح فى وضع لا يخضع فيه لأحد ، ولا يطيع أحداً ، ولا يستشير أحداً ، ولا يحترم أحداً .","والغرور يسقطه ويهلكه ، بدون السقوط فى خطايا اللسان .","ومع ذلك فالغرور سيجعله يصطدم بالآخرين . ولا بد سيقع فى خطايا اللسان ، حتى بدون شيطان ! فكم بالأولى إذا حاربه الشيطان بها ...",{"h":"إن الشيطان يعدّل خطته باستمرار . ينظر إلى حالة الإنسان ، ويختار له السقطة التى تناسبه . إنه يعرف متى يحارب ، وكيف يحارب ، وبأى نوع ... ؟"},"والذى لا يسقط بهذه الطريقة يسقط بغيرها .","والذى لا يسقط فى هذه الخطية الآن ، مصيره أن يسقط فيها هى بذاتها ، فيما بعد ، والفخاخ كثيرة ، موجودة ومنصوبة .","ج ـ مثال ثالث فى كيف يغيّر الشيطان خططه :","بدأ الصوم الكبير . وكان الشيطان فى العام الماضى يقاتل شاباً بترك الصوم ، فلم تنفع معه كل المحاربات :","* قال له ليشككه فى الصوم : ما معنى أن تصوم عن الأطعمة الحيوانية ؟! صم بالأحرى عن الخطية ، وحارب الحيوان الذى فى داخلك ... لأنه ما فائدة الصوم بدون طهارة ونقاوة ؟! ألا يكون صومك غير مقبول ؟!","ـ فأجاب الشاب : بل أنا أنفذ قول الكتاب « إفعلوا هذه ، ولا تتركوا تلك » (متى ٢٣ : ٢٣) . فأحاول أن أصوم الصومين معاً . أصوّم جسدى عن الطعام ، وأصوّم نفسى عن شهوة الخطية « أقمع جسدى وأستعبده » (١كو ٩ : ٢٧) بمنعه عن الأطعمة"],"53":["الشهية ، وأتعود بذلك قهر النفس فلا تخطىء .","* قال الشيطان : ولكنك ضعيف ، وصحتك لا تحتمل الصوم . ولا بد تحتاج إلى البروتين الحيوانى لتعيش ، وبخاصة وأنت فى فترة نمو","ـ فأجابه الشاب بقول الرب « ليس بالخبز وحده يحيا الإنسان » (متى ٤ : ٤) . وتذكّر أن آدم وحواء كانا يعيشان على الثمار والبقول ، ثم عشب الأرض (تك ١ : ٢٩ ، ٣ : ١٨) . ولم يقل الكتاب إنها مرضا لنقص البروتين الحيوانى ! ...","* قال الشيطان : لا مانع إذن من أن تصوم . ولكن لا داعى لأن تصوم الصوم كله من أوله ، فهذا كثير . وأيضاً لا تضغط على نفسك فى الصوم ، لئلا يحاربك الشيطان بالمجد الباطل ! وأنت تعرف حروب الشياطين ، وخطورة ضربات اليمين .","ـ أجاب الشاب : لا أريد أن أتهاون . فالرب يدعونا إلى الكمال (متى ٥ : ٤٨) . ومهما صمت ، ماذا يكون صومى إذا قورن بأصوام القديسين ؟! إنه لا شىء ...","وصام الشاب . وحل الصوم هذا العام ، والشاب فى تصميمه .",{"h":"ورأى الشيطان أن محاولة منع هذا الشاب عن الصوم ستكون محاولة عقيمة . لذلك بدأ يغيّر خطته إلى العكس ."},"* فقال للشاب : ما أفيد الصوم ! إن عمق فائدته تأتى من طول فترة الإنقطاع . ومن رأيى أن تنقطع كل يوم إلى الغروب من بدء الصوم .","ولكن لا بد أن تستشير أب اعترافك وتأخذ موافقته (وكان يعلم يقيناً أن أب الإعتراف لن يوافق) ... وهنا نصب له فخاً .","ولم يوافق أب الإعتراف ، ودعا الشاب إلى التدرج ...","* وهنا تدخل الشيطان ليقول : إن أب اعترافك هذا ، لا خبرة له بالصوم . وهو بإرشاده يعطل حياتك الروحية . و بطريقته هذه لا يمكن أن تنمو ، ولا أن تذوق حلاوة الصوم . بل أخشى عليك إذا ضغطت الظروف ، أن ينصحك يوماً بأن تفطر فى أسبوع الآلام !! والأفضل أن تغير أب اعترافك . ومن الممكن فى أمور الصوم وأمثالها ، أن لا تستشير أب الإعتراف ! أترك هذه الأمور أصرّفها معك بنفسى !","وهكذا غيّر الشيطان خطته ، من تشكيك فى الصوم ، إلى تشكيك فى أب"],"54":["الإعتراف . ليس المهم عنده نوع الحرب ، إنما أن يسقط من يحاربه .","وبتحويل الشاب عن أب اعترافه ، جعله يسلك حسب هواه بلا مرشد ، مع كبرياء فى القلب يظن بها أنه أفضل من مرشده ، مع إدانة لهذا المرشد . وكل هذه وسائل تجره فى طريق السقوط إلى أسفل .","د ـ مثال رابع : شيطان المجد الباطل :","إنه شيطان يغيّر أسلوبه باستمرار ، ليطابق أى حال يراه ...",{"h":"وصف بأنه شيطان مكوّر ، أى كالكرة يتقلب فى أى وضع ."},"وهو فى ذلك غير المكعب الذى لا بد أن يستقر على قاعدة معينة . أما المكور فحيثما تقلبه أو توجهه ، يتحرك ، على كل وجه ، كالكرة .","إن كنت جالساً إلى المائدة ولم تأكل ، يقول لك « يعجبنى نسكك هذا ، إنك لا تأكل كسائر الموجودين . وإن أكلت مثلهم تماماً ، يقول لك « هكذا القديسون : يتظاهرون بالأكل وهم صائمون ، لكى يخفوا فضائلهم » .",{"h":"إن تكلمت ، يقول : إنه كلام الحكمة ، موضع إعجاب السامعين ..."},{"h":"وإن صمتّ ، يقول : الصمت فضيلة القديسين مثل القديس أرسانيوس !"},"فكن حكيماً مع هذا الشيطان . ولا تصدقه فيما يقوله ، ولا تتأثر بكلامه وأحكامه . وإن حاربك بمديح نفسك لنفسك ، تذكّر خطاياك وضعفاتك ، وبكّت ذاتك عليها . أو تذكر ما ينقصك فى حياة البر ، حتى تقيم توازناً مع ما تسمعه من مديح ...",{"h":"وعموماً ـ بالنسبة إلى أى شيطان ـ إذا غيّر خططه معك ، يمكن أن تغيّر أنت أيضاً خطتك معه ."},"ومثال ذلك ، القديس يوحنا القصير : كان الشياطين يمدحونه على ما وصل إليه من فضيلة ، حتى أن الإسقيط كله كان يطلب منه كلمة منفعة . فيجيبهم : ومن أنا المسكين ؟ ألعلى وصلت إلى ما وصل إليه الأنبا أنطونيوس أو الأنبا بوا ؟! إننى كل خطية . فإن قالوا له : حقاً إنك خاطىء وستهلك ، يجيبهم : وأين ذهبت محبة الله ورحمته ؟!","فكان الشياطين يقولون له « لقد حيرتنا . إن رفعناك إتضعت . وإن وضعناك إرتفعت » ... فكن أنت هكذا فى تعاملك مع الشياطين ."],"55":["إن مدحوك ، تذكر خطاياك . وإن أراحوك من محارباتهم ، قل : لعلهم يعدّون لى ، فخاً لا أعرفه . فليرحم الرب ضعفى ...","بل أذكر أنك لم تصل إلى المستوى الذى يحاربك فيه الشيطان . مثل ذلك الأخ الذى شكا للقديس الأنبا بيشوى محاربة الشيطان له . فظهر الشيطان للقديس ، وقال له : من هو هذا الأخ لأحاربه ؟ أنا لم أسمع بعد بأنه قد ترهب !","إن حرب الشياطين الحقيقية حرب شديدة . وربما غالبيتنا لم يتعرضوا لها . والحروب التى تعرض لها القديسون كانت عنيفة ، لا يسمح الله أن نكابدها نحن .","إن شيطان المجد الباطل ، يقدم حرباً أساسها المديح . ولكن هناك طريقة عكسية لهذه تماماً يحارب بها الشيطان أحياناً ، وهى : حرب الكآبة ...",{"h":"٧ ـ الكآبة"},"هى نوع من المبالغة الشديدة يحارب بها الشيطان التائبين ، أو الشاعرين بخطاياهم ، أو المنسحقين بقلوبهم ، لكى يجرهم إلى الضياع ...","يختار لهم الشيطان من بين كل آيات الكتاب المقدس آية واحدة يضمها أمامهم باستمرار وهى « بكآبة الوجه يصلح القلب » (جا ٧ : ٣) . و يقول لهم إن الكتاب لم يذكر مطلقاً أن المسيح قد ضحك ، ولكن ذكر أنه بكى مرات ...","وكلما يقع هذا الإنسان فى خطية ، أو يُحارب بشدة فى خطية ، يظل الشيطان يزيده كآبة . و يقول له : أنت لست إبناً لله ، لأنك خاطىء ، والكتاب يقول إن « المولود من الله لا يخطىء » (١يو ٣ : ٩ : ٥ : ١٨) .",{"h":"و يقول له : وليس الله فقط ، بل حتى أب اعترافك القديس لا تستحق أن تكون له إبناً . إنك عار عليه . تسىء سمعته ."},"والأفضل أن تترك هذا الأب البار ، حتى لا يعيره الناس قائلين : أنظر ، هذه هى عينة أبنائك . وأيضاً أتركه حتى لا يأخذ دينونة بسببك ، وحتى لا تحزن نفسه باستمرار ، كلما يراك هكذا .","وهكذا يبعده عن الله ، والشعور بأبوته ، و يبعده عن أب الإعتراف ."],"56":["وحتى إن أمسك الكتاب المقدس ليقرأ ، يقول له : وهل تتجرأ تمسك كتاب الله بيدك هذه غير الطاهرة . إن كل كلمة فى هذا الكتاب دينونة عليك . لأن السيد المسيح نفسه يقول عنك وعن أمثالك « الكلام الذى تكلمت به هو يدينه فى اليوم الأخير » (يو ١٢ : ٤٨) . وهذا يملأ نفسه بالكآبة ، حتى يترك الكتاب بنفس مُرّة يائسة ...",{"h":"وحتى الخدمة ـ إن كان خادماً ـ يبعده عنها كغير مستحق ."},"فيقول له : إن الخدمة هى عمل القديسين وليس الخطاة . وأنت خاطىء لا تستحق أن تجلس فى مكان المعلمين ، وإلا ستكون عثرة ، كما أن الخدمة ستنسيك خطاياك التى يجب أن تضعها أمامك فى كل حين ، وتكتئب عليها ليلاً ونهاراً .",{"h":"حتى إن وقف يصلى ، يمنعه قائلاً : « صلاة الأشرار مكرهة للرب » (أم ١٥ : ٨ ، ٢٨ : ٩) ..."},"و يقول له : هوذا المشار وقف بعيداً ، لا يجرؤ أن يرفع نظره إلى فوق (لو ١٨ : ١٣) . وأنت بكل استهتار ولا مبالاة ، تتحدث مع الله ، وأنت كاسر لكل وصاياه . ليتك تخجل من نفسك ، وتبعد عن هذه الصلاة الأثيمة !",{"h":"وهكذا يبعده بالكآبة عن كل وسائط النعمة ، لينفرد به ."},"ينفرد به وهو وحيد ، بنفس محطمة ، وليس حوله إنجيل ولا صلاة ، ولا أب اعتراف ، ولا خدمة ولا اجتماعات كنسية ، بل ربما وليس حوله أيضاً أصدقاء ، إذ بعدوا عنه بسبب كآبته ، أو بعد هو عنهم ... وهكذا يصير فريسة سهلة للشيطان .",{"h":"وما أسهل أن يقول له : أترك الوسط الدينى لأنه سبب كآبتك !"},"أو ما أسهل أن يرسل له هذه العبارة على أفواه أقاربه ، أو على فم طبيب معالج . و يجذبه بالتدريج إلى وسائل من اللهو للترفيه عنه من كآبته ، ولو إلى فترة مؤقتة ، يطيلها الشيطان بحيله الأخرى ، إلى أن يبعده عن الله تماماً ...","أو أن ألشيطان يسقطه بوسيلة أخرى وهى اليأس . وتكون الكآبة ممهدة لذلك .",{"h":"وحيلة الشيطان فى الكآبة ، أنه أبعد فريسته عن الرجاء والمغفرة ."},"أبعده عن وجه الله المحب ، الذى استقبل إبنه الضال بكل ترحاب ، وفرح به ، وجعل الكل يفرحون ، وألبسه الحلة الأولى (لو ١٥ : ٢٢ ـ ٢٤) . بل إن الرب يقول إنه « يكون فرح قدام ملائكة الله بخاطىء واحد يتوب » (لو ١٥ : ١٠) ... حقاً إن"],"57":["القديسين بكوا على خطاياهم ، ولكن ليس بغير رجاء . بل إن الكتاب يقول :","« لا تحزنوا كالباقين الذين لا رجاء لهم » (١تس ٤ : ١٣) .","الحزن على الخطية ، لا يفصلنا عن الله ، بل يقربنا منه . و يزيد محبتنا له ، لأنه على الرغم من خطايانا ، غفر لنا . بل قال بالأكثر « لأنى أصفح عن إثمهم ، ولا أذكر خطيتهم بعد » (أر ٣١ : ٣٤) . والله لا يسر بموت الشرير ، بل بأن يرجع ويحيا (حز ١٨ : ٢٣) .",{"h":"مشكلة الذى فقد الرجاء بالكآبة ، أنه أخذ مشورة الحية ، الشيطان ."},"أما كلمة الله ، فإنها مملوءة عزاءً . وقلب الله باستمرار مملوء حباً . والكآبة جُعلت لكى تقود إلى التواضع والإنسحاق ، وليس إلى اليأس والإنفصال عن الله . أما إذا استخدم الشيطان هذه الكآبة بطرقه الشريرة ، فإنه لا شك يضيع صاحبها .","ها هو بطرس الرسول بعد أن أنكر المسيح ، ومع أنه بكى بكاءً مراً ، إلا أن السيد المسيح المجد ظهر له ، وقال له « إرعَ غنمى . إرعَ خرافى » (يو ٢١ : ١٥ ، ١٦) . أى رجاء يمكن أن يقال أكثر من هذا . لذلك فإن كآبة الوجه التى تصلح القلب ، ينبغى ألا تنفصل عن الحب وعن الرجاء .","ننتقل إلى نقطة أخرى من حروب الشياطين ، وهى :",{"h":"٨ ـ السرعة"},"أعمال الشيطان تتصف بالسرعة ، أو بما يسمونه فى العامية ( جة ) ... بعكس أعمال الله التى تتميز بالهدوء والروية وطول الأناة . وقد تأخذ وقتاً ، ولكنها تكون متئدة وهادئة ، كقصة الخلاص ، ووعود الله ...",{"h":"الشيطان يقدم لك فكراً ، ويظل يلح ويلح على تنفيذه بسرعة ..."},"وتشعر حينما يكون الفكر الشيطانى فى داخلك ، بحماس شديد للتنفيذ ، وبنار تتقد فى داخلك ، وحافز يدفعك دفعاً للتنفيذ ، الآن ، وبلا إبطاء ، ودون أن يأخذ الفكر فترة حضانة داخلك ، تناقشه وتفحصه وتبحثه ، وتنظر إليه من جميع الزوايا الأخرى ، وتراجع رأيك فيه ..."],"58":[{"h":"إنه يقصد بالسرعة أنك لا تفكر ، وأيضاً لا تستشير ."},"يريد بالسرعة أن ينفرد بك ، دون أن يدخل أحد بينكما ، تستشيره وتستفيد برأيه وخبرته وروحياته ، لا صديق ولا قريب ، ولا أب اعتراف ، ولا مرشد روحى ، ولا أى إنسان صاحب خبرة ، إنما بسرعة عليك أن تنفذ ...",{"h":"وهو يريد بالسرعة أيضاً ، عدم عرض الأمر على الله بالصلاة ."},"لا يريد أن يعطيك فرصة تصلى فيها من أجل هذا الموضوع ، وترى ماذا يقول الله فيه ، ولا فرصة ترفع فيها قداساً من أجل الموضوع ، أو تصوم طالباً إرشاد الرب ... إنما يلح عليك بالفكر إلحاحاً ، ويقنعك به كأنه بديهية لا تقبل النقاش ... ولذلك قال الآباء :",{"h":"كل فكر ، يلح عليك أن تنفذه بسرعة ، هو من الشيطان ."},"وطبعاً لا يقصد بهذا الرغبة فى التوبة والرجوع إلى الله ، والإلتصاق به بالحب ، بل الأفكار الأخرى التى تحتاج إلى مناقشة ، وليست عاجلة (كإنقاذ غريق أو إطفاء حريق) ... وكم من أمور أسرع الإنسان فى تنفيذها . وحينما رجع إلى نفسه ندم على ذلك جداً . وأحياناً تكون أفكار الخطية والشهوة ملحة جداً ، لا تعطى صاحبها فرصة للتفكير وتغيير مجرى مشاعره ...",{"h":"الشيطان يقصد بالسرعة أيضاً ، أنه لا ينكشف ..."},"ربما تكون وراء فكرته أو اقتراحه كذبة أو حيلة لا يريد لها أن تنكشف بالتفكير أو بالإستشارة أو بالصلاة . فيلح على إتمامها بسرعة قبل كشفها . ولذلك فإن وجود أب الإعتراف مفيد هنا فى كشف حيل العدو . وقد قيل « الذين بلا مرشد ، يسقطون مثل أوراق الشجر » . لأنهم ينفذون بسرعة قبل أن يستشيروا . يلح عليهم الشيطان إلحاحاً ، فينمرمون فكره ، قبل أن تنكشف حيلته .",{"h":"أما أولاد الله ، فإنهم لا يطيعون كل فكر يأتيهم ..."},"مثال ذلك الفكر الذى جاء للقديس مقاريوس لكى يذهب إلى البرية الجوانية ليرى الآباء السوّاح . يقول القديس « فبقيت مقاتلاً لهذا الفكر ثلاث سنوات ، لأعرف هل هو من الله أم لا » ... ما أعجب هذا الأمر ، بالنسبة إلى قديس عظيم كالقديس مقاريوس الكبير ، وبالنسبة إلى فكر روحى كزيارة السوّاح ... !"],"59":[{"h":"لم ير القديسون فى الإبطاء ضرراً ، بل فيه فائدة ..."},"إنهم لا ينفذون بسرعة لئلا يكون الفكر من الشيطان . وإبطاؤهم فى التنفيذ يعطيهم فرصة للتأكد ، ينتظرون فيها إلى أن يعلن الله رأيه فى الموضوع . وهم فى ذلك يقولون تلك العبارة الجميلة :",{"h":"الذى من عند الله يثبت . والذى ليس من الله يزول ."},"وهكذا نرى أن القديس الأنبا غاليون لما ظهر له الشيطان فى هيئة راهب ، وقال له إنه أحد السوّاح ، وأن زملاءه السواح قد ضموه إلى صحبتهم ، ودعاه للسير معه . وأطاعه الأنبا غاليون ، دون أن يأخذ فرصة لعرض الأمر على الله وعلى أب الإعتراف ... حدث أن الشياطين الذين ظهروا فى هيئة سواح أتاهوه فى البرية ، ثم تركوه وهم يهزأون . وقالوا له « ستموت هنا وحدك ، فى هذا القفر » لولا أن الله أنقذه ...","هناك حيلة أخرى للشيطان غير السرعة ، أو هى عكسها . وهى :",{"h":"٩ ـ التدرج الطويل"},"تتعدد وسائل الشيطان فى حروبه . وقد يبدو أحياناً شىء من التناقض بين أسلوب وآخر . ولكن يجمعها كلها هدف واحد ، وإن كانت الوسيلة تختلف بحسب نوعية الحالة ... وعموماً فالشيطان لا يحب الوتيرة الواحدة لئلا يألفها الناس .",{"h":"فهو أحياناً يضرب ضربة سريعة فجائية ، لا يكون الشخص مستعداً لها . وأحياناً يسير فى تدرج طويل ، بحيث لا يشعر به صاحبه ..."},"والتدرج يلزمه وقت قد يطول . ولكن الشيطان لا يهمه الوقت ، إنما يهمه السقوط . والتدرج يصلح غالباً للأشخاص الذين لا يقبلون خطية معينة بسهولة . ولكنه يوصلهم إليها تدريجياً فى هدوء ، بجرعات قليلة ، أو قليلة جداً ، تزداد بالوقت ، حتى تقضى عليهم .",{"h":"وقد يقسم الخطية إلى مراحل . كل مرحلة تثبت أقدامها بالوقت ."},"وربما تكون الخطوة الأولى إلى الخطية ، ليست خطية على الإطلاق ، ولا تتعب الضمير . فالمرحلة الأولى فى سقوط داود النبى ، كانت فى عدم خروجه إلى الحرب"],"60":["بنفسه : يرسل الجيش و يبق هو فى بيته . والمرحلة الثانية كانت شيئاً من الترف دخل إلى حياته ، بعد أن كان مشرداً من برية إلى برية أيام مطاردة شاول الملك له ... وهاتان المرحلتان عبرهما داود دون أن يشعر بخطأ .",{"h":"ولكن عوامل نفسية كانت تأخذ مجراها داخله وتفقده حرارته الروحية ."},"ثم دخل فى مرحلة ثالثة وهى الإكثار من الزوجات . وكان محللاً فى أيامه ، ولكنه بلا شك هبط به إلى مستوى الجسد . وإن كان مستوى الحلال ، ولكن ليس مستوى الكمال . وصار للجسد سيطرة عليه شعر أو لم يشعر .","المرحلة الرابعة ، أنه صعد إلى السطح ، يتمشى و يتفرج ، ولا مانع من أن ينظر إلى مساكن غيره ، و يبصر خصوصيات الناس . وهنا بدء إنحراف .","المرحلة الخامسة ، كانت ضربة شديدة من الشيطان أوقعت رجل المزامير العظيم فى خطية الشهوة ، ثم فى خطية الزنا .","المرحلة السادسة ، كانت التورط ، الذى أراد به إخفاء خطيئته بجملة من الخطايا أفقدته روحانيته ، وهبطت به من سىء إلى أسوأ .",{"h":"وربما هذه المراحل ، كان الشيطان يعد لها منذ زمن ..."},"إنه يحب ـ حينما يضرب الضربة ـ أن تصيب مقتلاً . وهذا يتطلب منه أحياناً تمهيدات طويلة المدى . بحيث حينما يأتى ، يجد البيت مزيناً مفروشاً ، مهيئاً لعمله ، ويجد الضحية جاهزة بلا مقاومة ... وحتى إن قاومت تكون بلا قدرة على الإطلاق ، فتسقط أمامه بسهولة !",{"h":"قصة يعقوب المجاهد :"},"إنها تشبه قصة سقوط داود ، فى أنها مثلها تعطينا فكرة واضحة عن خطة الشيطان فى أسلوب التدرج الطويل . وفيها استطاع أن يسقط ناسكاً عظيماً ، وقديساً له موهبة إخراج الشياطين . ولكن الشيطان هنا أمكنه أن يضرب القديس ثلاث ضربات قاتلة ، وكاد يهلكه لولا أن رحمة الله إقتادته إلى التوبة . فكيف حدث ذلك ؟","فتاة ( إبنة ملك ) ، صرعها روح نجس . وعجز الكل عن إخراجه ، فأتوا بها إلى"],"61":["القديس يعقوب المجاهد . فصلّى عليها فخرج الروح النجس . ولكن ما أن رجعت إلى بلدها حتى عاد إليها مرة أخرى . فسافروا وأتوا بها إلى القديس ، فصلى عليها فخرج الروح . ولكن ما أن رجعت إلى بلدها حتى عاد إليها . فسافروا إلى القديس مرة ثالثة .",{"h":"وتكررت لعبة الشيطان مرات عديدة ، حتى يئسوا من كثرة الأسفار ."},"وأخيراً ، قرر الملك أن تبقى الأميرة إلى جوار القديس . فبنوا لها حجرة . وكان الشيطان كلما يصرعها يدخلونها إليه . وتطور الأمر إلى أن أبقوها معه . ولما اطمأنوا على هدوئها تركوها معه . ومضوا ...","وبمرور الوقت تكونت دالة بينهما ، تطورت إلى الخطيئة . ثم حملت الفتاة منه . ورأى أن الخطية ستنكشف وتضيع سمعته ، وربما يقتله الملك . فوسوس له الشيطان أن يقتلها ، فقتلها ودفنها فى مكان بعيد فى الصحراء .","ومرت شهور ، وجاء رسل الملك للإطمئنان عليها . ولما سألوا القديس ، أخفى جريمته الثانية بالكذب . وقال لهم صرعها الشيطان مرة ، فانطلقت بسرعة هاربة فى الجبل ولم أستطع اللحاق بها ، واختفت ... وصدقوه لأنه لم يكن موضع شك .",{"h":"وهكذا ضربه الشيطان ثلاث ضربات ، وأوقعه فى الزنا والقتل والكذب ."},"كل ذلك فى تدرج طويل ، ما كان أوله يوحى مطلقاً بآخره . ولكنها حيل الشيطان الذى يسبك مكيدته فى صبر عجيب .","وسياسة التدرج هذه لها حكمة كبيرة وهى :",{"h":"فى كل خطوة يقترب الإنسان إلى جو الخطية ، ويعتاده ، ويضعف . إرادته تكون قوية جداً ، وهو خارج مجال الخطية . وقد يكون نافراً جداً من كل مجالاتها . وبالوقت يألفها ، ولا تصبح غريبة عليه . وبالتدريج تدخل إلى فكره ، ثم إلى مشاعره . وفى كل خطوة تضعف إرادته عن المقاومة أحسّ أو لم يحسّ ..."},{"h":"ومن أمثلة التدرج الطويل موضوع العادات ."},"كل عادة مسيطرة على الإنسان ، لم تبدأ هكذا مطلقاً . وربما كان هو المسيطر عليها أولاً و يستطيع إبطالها . ولكن بالتدرج الطويل فقد سيطرته ، ثم سيطرت هى عليه . وربما الشيطان فى أول خطوة ، قال له عبارة واحدة وهى جرّب أو إختبر ... الحياة كلها خبرات . والأمر كله بيدك ، تستطيع أن تمتنع وقتما تشاء . وظل به هكذا إلى أن أتى"],"62":["الوقت الذى فيه سلّم إرادته بالتمام ولم يعد يقاوم ، بل لا يشاء أن يقاوم !!",{"h":"على أن التخلص من العادات ممكن لمن يريد ."},"الشيطان قد يقول لك لن تستطيع . وإن استطعت ستعود إليها مرة أخرى . إنها ضمن حرب اليأس . ولكن لا تستسلم . فإن العادة تكونت نتيجة عمل إرادى متكرر . و يمكن أن تتخلص منها بعمل إرادى عكسى متكرر ، أى تثبت فيه .","ونصيحتنا لمقاومة سياسة التدرج هذه من جانب الشيطان ، أن تبعد عن الخطوة الأولى ، بكل حزم ، مهما كانت تبدو بريئة ، أو يقنعك الشيطان بأنها بريئة .",{"h":"واحترس من كذبه ، إن قال لك إنها خطوة واحدة ولن تتطور ."},"إن الشيطان لا يقبل على نفسه أن يتركها عند حدود الخطوة الواحدة ، دون أن يتقدم بها باستمرار نحو أغراضه البعيدة ... فاحترس منه .","بل احترس حتى من الخطوة الأولى ، وليس فقط من تطورها ، مهما بدت هذه الخطوة فى نظرك من الأمور الصغيرة . وهنا أحذرك من حيل شيطان ماكر ، هو شيطان الأمور الصغيرة .",{"h":"١٠ ـ الأمور الصغيرة"},"هذا يحذرنا منه سفر النشيد قائلاً « خذوا لنا الثعالب ، الثعالب الصغيرة ، المفسدة للكروم » (نش ٢ : ١٥) . وهنا نجد تحذيراً هاماً وهو :",{"h":"مع أنها صغيرة ، إلا أنها مفسدة للكروم ."},"أول خطر لهذه الثعالب الصغار أنها تستطيع الدخول إلى النفس . الثعالب الكبيرة ربما لا تجد فتحة مناسبة لها فى سياج البستان تدخل منها . أما الصغيرة فدخولها سهل .","الخطايا الكبيرة ربما يحترس منها الإنسان جداً ، و يبتعد عنها ، و ينفر منها ، لذلك فالشيطان قد يؤجل محاربته بها ، مادام هو متنبهاً لها . أما الأمور الصغيرة ، فيحاربه بها :",{"h":"يحاربه بها ، لأنه لا يحترس منها ، ولا يهتم بها ."},"تقول لإنسان مثلاً : إحذر من العثرات . فيقول لك فى استغراب : « عثرات ؟!"],"63":["وهل مثلى يخاف من هذه الأمور الصغيرة ؟! إنها قد تحارب الصغار أو المبتدئين . أما نحن فقد كبرنا عن أمثال هذه الأمور » ... لهذا يحاربه الشيطان بها ...","من كان يظن أن أبانا إبراهيم حبيب الله ، يخاف و يقول عن زوجته ساره إنها أخته ، فيأخذونها و يستبقونه ؟! لا شك أن الخوف والكذب من الأمور الصغيرة بالنسبة إلى رجل روحانى عظيم مثل أبينا إبراهيم أبى الآباء والأنبياء ... !",{"h":"إن تنجيس الإنسان لا تلزمه خطية كبيرة مثل الزنا ، إنما يكفى لذلك خطية من اللسان الذى « يدنس الجسم كله » (يع ٣ : ٦) ."},"إنه « عضو صغير » ولكنه « عالم الإثم » ، « شر لا يُضبط ، مملوء سماً مميتاً » (يع ٣ : ٥ ـ ٨) . إنه ينجس الإنسان ، كما قال الرب « ليس ما يدخل الفم ينجس الإنسان ، بل ما يخرج من الفم ينجس الإنسان ... أما ما يخرج من الفم ، فمن القلب يصدر . وذاك ينجس الإنسان » (متى ١٥ : ١١ ، ١٨) . والعجيب أن خطية اللسان يقنعك الشيطان أنها من الأمور الصغيرة .",{"h":"حقاً إن شيطان الأمور الصغيرة ، يمكن أن يهلك الإنسان ."},"فيمكن أن تغرق سفينة بسبب ثقب صغير فى قاعها ...","والإنسان لا يشترط أن يكون موته بواسطة وحش كبير يفترسه ، إنما يكفى لموته ميكروب صغير لا يُرى بالعين المجردة ... لقد قال السيد الرب فى عظته على الجبل :","« ومن قال يا أحمق ، يكون مستوجب نار جهنم » (متى ٥ : ٢٢) .","ما أسهل أن يقنعك الشيطان بأن كلمة ( أحمق ) وأشباهها هى من الأمور الصغيرة ! وربما كان حنانيا وسفيرا يظنان أن خطيتها أيضاً هى من الأمور الصغيرة ، وقد هلكا بها (أع ٥ : ١ ـ ١١) . وربما ظن سليمان أن زواجه بالأجنبيات هو من الأمور الصغيرة ، وقد رأينا نتائجه الخطيرة جداً على خلاص سليمان نفسه (١مل ١١ : ١-١١) .",{"h":"إن « الأمور الصغيرة » قد لا تكون صغيرة فعلاً ."},"الشيطان يسميها هكذا ، ولكنها قد لا تكون كذلك ... وربما توصل إلى أخطر النتائج ، كما حدث مع سليمان وداود وحنانيا . وقد تتحول هذه الأمور الصغيرة إلى أشياء خطيرة جداً ..."],"64":["إن الله يختبر إرادتنا بأى اختبار مهما بدا بسيطاً ، لكنه يكشف نفسيتنا من الداخل ، كما اختبر آدم وحواء بثمرة من ثمار الجنة .",{"h":"فما هى هذه الأمور الصغيرة ؟ ما أمثلتها ؟"},"ربما تكون مثل تمسك الإنسان برأيه ، وعدم إستشارته لأحد . وقد يقول له الشيطان « وماذا فى ذلك ؟ أى خطأ فيه ؟ وهل لا بد أن تستشير ؟ وهل عقلك لا يكفى ؟! » . وقد تكون الأمور الصغيرة مثل قليل من التساهل مع الحواس والقراءات والسماعات ... أو عدم التدقيق فى الكلام ، أو عدم لوم النفس فى كل أخطائها .",{"h":"طريقة الخلاص من شيطان الأمور الصغيرة هى حياة التدقيق ."},"كذلك التمسك بفضيلة « الأمانة فى القليل » فالرب يقول « الأمين فى القليل ، أمين أيضاً فى الكثير » (لو ١٦ : ١٠) .","تحدثنا عن الأمور الصغيرة . ومن حيل الشيطان أيضاً :",{"h":"١١ ـ التأجيل"},"إن الشيطان يريد بكل جهده أن يمنعك عن العمل الروحى .",{"h":"أما إن وجدك مصراً على العمل ، فإنه يدعوك إلى التأجيل ."},"يقول لك : لماذا الإسراع ؟ الأمر فى يدنا نستطيع أن نعمله فى أى وقت . ربما التريث يعطينا فكرة لفحص الأمر أكثر ، أو لاختيار أسهل السبل الموصلة إليه ، أو يعطينا مزيداً من الإقتناع ... على أية الحالات عندنا بعض أمور هامة فى أيدينا ، ننتهى منها أولاً . ثم نأتى إلى هذا الموضوع .",{"h":"والمقصود بالتأجيل هو إضاعة الحماس للعمل ، أو إضاعة الفرصة ، أو ترك الموضوع فترة لعلك تنساها ، أو يحدث ما يغطى عليه ..."},"كأن تأتيك مشغولية كبيرة تأخذ كل اهتمامك ووقتك ، أو يحدث حادث يعطلك ، أو تحدث عوائق معينة تضع صعوبات أمامك فى التنفيذ ، أو يلقى الشيطان فى طريقك بخطية تفتر بها حرارتك الروحية ، فلا تنفذ ما كنت قد نويت عليه وأجلته ...","نتذكر أن الإبن الضال لما أتاه الشعور أن يقوم ليذهب إلى أبيه ، قام فعلاً وذهب"],"65":["(لو ١٥ : ١٨ ، ٢٠) . ولو أنه أجّل ، ما كنا نضمن كيف تنتهى قصته .",{"h":"ومن أمثلة مضار التأجيل ما حدث لفيلكس الوالى والملك أغريباس :"},"بينما كان القديس بولس الرسول يتكلم عن البر والتعفف والدينونة العتيدة أن تكون ، إرتعب فيلكس وقال للقديس بولس « أما الآن فاذهب . ومتى حصل لى وقت أستدعيك » (أع ٢٤ : ٢٥) . وبالتأجيل ضاع التأثر الذى كان عند فيلكس هذا . ولم يحصل له وقت ، ولم يستدع بولس .","كذلك أغريباس الملك ، بينما كان القديس بولس يترافع أمامه ، قال له : أتؤمن أيها الملك أغريباس بالأنبياء ؟ أنا أعلم أنك تؤمن . فقال أغريباس لبولس « بقليل تقنعنى أن أصير مسيحياً » . وبالتأجيل ، لم يحصل أغريباس على هذا القليل ليقتنع . ولم يذكر الكتاب أنه آمن .",{"h":"ربما إحدى زيارات النعمة تدعوك ، فإن أجّلت ضاع تأثيرها ."},"إن الفرصة فى يدك ، والحماس فى قلبك ، فاعمل عمل الرب ولا تتهاون ولا توّجل ، لأن التأجيل ربما يكون خطوة إلى الإلغاء . والشيطان يقصد به ذلك . إنه لا يريد أن يمنعك فى صراحة . ولكنه فى لباقة يمنعك فعلاً ... بالتأجيل . فاحترس منه .",{"h":"لا توّجل التوبة ، ولا الصلاة ، ولا عمل الخير جملة ."},"والكتاب يقول « لا تمنع الخير عن أهله ، حين يكون فى طاقة يدك أن تفعله . لا تقل لصاحبك : أرجع فأعطيك غداً ، وموجود عندك » (أم ٣ : ٢٧ ، ٢٨) .","هذا عن عمل الخير من نحو الغير . وكذلك من نحو نفسك . فكلما يتكلم روح الله فى داخلك ، لا توّجل الإستجابة لنداله . فالرسول يقول أكثر من مرة « إن سمعتم صوته ، فلا تقسوا قلوبكم » (عب ٣ : ٧ ، ١٥) .",{"h":"إذن التأجيل لون من ألوان قساوة القلب ."},"والشيطان يدعوك إلى هذه القساوة ، فيما يدعوك إلى التأجيل ، أو هو يجعلك تعتاد قساوة القلب لتستمر بعيداً عن الله .","ومن ضمن الوسائل التى يقدمها الشيطان كسبب للتأجيل : المشغولية ."],"66":[{"h":"١٢ ـ المشغولية"},"بمشغوليات كثيرة يريد الشيطان أن يعطلك عن أى عمل روحى تعمله . هو لا يريدك مطلقاً أن تجلس مع الله ، أو أن تجلس مع نفسك . لأنه يخشى أن هذا الأمر يفصلك عنه و يلصقك بالله ، وهذا أخشى ما يخشاه ...","فإن رآك الشيطان سواظباً على صلواتك وقراءاتك ، ومواظباً على الإجتماعات الروحية وكل وسائط النعمة التى تنمى محبة الله فى قلبك ، حينئذ يحاربك بالمشغولية . وتكون إما مشغولية مؤقتة لتعطيل عمل معين ، أو مشغولية دائمة ، وهذه أخطر ...",{"h":"قد تكون المشغولية عملاً إضافياً ، يأتيك منه ربح مادى ."},"بحيث لا توجد معه وقتاً تتفرغ فيه لله . و يقنعك أن هذا العمل لازم جداً لمعيشتك ولا يمكنك الإستغناء عنه . ومثل ذلك أيضاً ما يعرضه على البعض من دراسات عليا ، أو بحوث ، لتحسين مستواه العلمى ، بحيث ينتهى من بحث ليجد آخر أمامه ...",{"h":"وقد تكون المشغوليات التى يقدمها خدمات كنسية تعطل وقت الصلاة ."},"الذى يرفض المشغوليات المادية ، يقدم له خدمات كنسية ، ويقنع ضميره بأهميتها . ونحن لا نعارض الخدمة ، إنما المفروض أن تكون فى حدود معينة بحيث لا تعطل الصلاة ولا التأمل ولا القراءة الروحية ، ولا الصلة الخاصة بالله .",{"h":"ليس فقط من أجل روحانية الخادم ، بل أيضاً لنجاح الخدمة ."},"فالخادم إذا كثرت مشغولياته بحيث تفتر معها روحياته ، لا تكون خدمته ناجحة ولا يكون لها تأثير قوى . لأن جفاف حياة الخادم الروحية ، يجعل خدمته روتينية أو عقلانية ، لا تدخل إلى أعماق القلب ، ولا تخاطب الروح ...","وما أكثر الخدام الذين تجدهم مشغولين كل الوقت بأنواع أنشطة لا تنتهى ، ولا يجدون وقتاً يصلون فيه صلاة ، أو مزموراً ، أو ينفردون فيه مع الله . يعيشون على الرصيد الروحى القديم الذى كان لهم ، دون جديد يضيفونه إليه . وحياتهم مهددة بالضياع ...",{"h":"هنا الشيطان لا يحارب العمل الروحى . ولكن لا يعطيه وقتاً ."},"لا يمنعك من الصلاة ولا من التأمل والقراءة ، ولا من الترتيل والتسبيح ، ولا من"],"67":["المطانيات ولا من محاسبة النفس ، بل قد يجعلك تلقى دروساً ومحاضرات عن هذه الوسائط الروحية وفائدتها . ولكنه لا يترك لك وقتاً لممارستها . وتصبح ـ كما قال أحد الأدباء الروحيين ـ مثل الأجراس التى تدعو الناس إلى دخول الهياكل ، دون أن تدخل هى إلى الهياكل ! حقاً ما أجمل قول أحدهم « قضيت عمرك فى خدمة بيت الرب ، فمتى تخدم رب البيت ؟! » ...",{"h":"هذا بالنسبة إلى الخدام . أما الأشخاص العاديون ، فما أكثر مشاغلهم ."},"هناك مشغوليات الزيارات ، والأحاديث والجدل والمناقشات . ومشغوليات الجرائد والمجلات ، والأخبار والتعليق عليها . ومشغوليات التسلية وهى كثيرة تشمل الكبار والصغار . أنظر إلى مباريات الكرة مثلاً ، وتأمل كم تأخذ من وقت الناس ومن مشاعرهم ومن حماسهم ومن تعليقاتهم ... ! وهناك أيضاً المشغوليات الفكرية ، والإجتماعية ، ومشغوليات المشاكل وهموم العالم الحاضر ، والمشغوليات المالية والإقتصادية ...","حتى الأطفال تشغلهم برامج التلفزيون ، ورواياته ، وقد تعطلهم عن الكنيسة . والكبار أيضاً تشغلهم هذه البرامج وتعطلهم !",{"h":"إن الله يطل من سمائه على العالم ، فيجده عالماً مشغولاً ."},"إنه عالم يجرى بسرعة ، لا يجد وقتاً يتوقف فيه ليفكر إلى أين هو ذاهب ... ! وهو أيضاً عالم صاخب ، كله أحاديث وضوضاء ومناقشات وانفعالات ... وأين الهدوء اللازم للعمل الروحى ؟ غالباً ما تبحث عنه فلا تجده ... !","حتى أن كثيراً من رجال الإكليروس الذين كرسوا أنفسهم للرب ، وأصبحوا « نصيب الرب » ، تجدهم أيضاً مشغولين عن الرب بأمور كثيرة ! إن حرب ( مرثا ) حرب قائمة ودائمة ، كما يبدو فى عالمنا الحاضر « أنت تهتمين وتضطربين لأجل أمور كثيرة ، والحاجة إلى واحد » (لو ١٠ : ٤١ ، ٤٢) . أما أنت يا إبن الله وصورته ، فينبغى أن يكون لك الطابع الروحى .",{"h":"ليكن الله فى مقدمة مشغولياتك ، إن لم يكن شاغلك الوحيد ."},"عملك الروحى ، وصلتك بالله ، وحياتك الروحية ، ينبغى أن تكون باستمرار فى مقدمة مشغولياتك وفى توزيع وقتك ، وبعد ذلك كل شىء . ضع خلاص نفسك أولاً ،"],"68":["وأبديتك أولاً . ثم رتّب باقى مسئولياتك مهما كانت أهميتها . وتذكّر فى ذلك قول الرب :",{"h":"ماذا ينتفع الإنسان ، لو ربح العالم كله وخسر نفسه ! » (متى ١٦ : ٢٦) ."},"وإن خسرت نفسك ، ماذا تعطى عوضاً عن نفسك ؟! وكل أولئك الذين ماتوا وتركوا هذا العالم ، بماذا نفعتهم مشغولياتهم ؟! ولما تركوا هذه المشغوليات بموتهم ، هل ارتبك العالم ؟ كلا ، طبعاً . هذا العالم قال عنه الحكيم :",{"h":"« الكل باطل وقبض الريح . ولا منفعة تحت الشمس » (جا ٢ : ١١) ."},"إبدأ صباحك بالله ، قبل أية مشغولية أخرى . ليكن الله « فى البدء » . قل له « يا الله أنت إلهى . إليك أبكر . عطشت نفسى إليك » (مز ٦٣ : ١) . ونظم وقتك ، بحيث لا تطغى أية مشغولية على الوقت الذى تقضيه مع الله . ولا تخرج من منزلك قبل أن تقوم بكل واجباتك الروحية . ولا تجعل شيئاً يفوق روحياتك مهما كان ربحه ، ومهما كانت قيمته أو أهميته ...",{"h":"إن الشيطان دائماً يضخّم فى أهمية المشغوليات التى تعطلنا ."},"أو يضخم فى إغراءنا بهذه المشغوليات . ولكن لا يوجد مطلقاً ما هو أهم من الله فى حياتك . ولا يصح أن تضحى بعلاقتك مع الله من أجل أى شىء ، أو أى شخص ، أياً كان . هوذا الرب يقول « من أحب أباً أو أماً ... أو إبناً أو إبنة أكثر منى ، فلا يستحقنى » (متى ١٠ : ٣٧) . فكم هى أقل ، باقى الأمور !",{"h":"لذلك إن أتتك مشغولية جديدة ، فكّر كثيراً قبل قبولها ."},"لأن الشيطان قد لا يكتفى بمشغولياتك الحالية التى تعطلك ، فيحاول أن يضيف إليها مشغوليات أخرى ، لكى ترتبك ... ويقدم لك فى كل يوم عروضاً ربما تكون سخية ، ليشغلك بها . أما أنت فكن محترساً . وضع روحياتك أمامك ، قبل كل المشغوليات ...","إن كانت المشغولية حيلة من حيل الشياطين ، لتبعدك عن الله ، فهناك حيلة أخرى أكثر مكراً ، وهى :",{"h":"١٣ ـ الفهم الخاطىء لمحبة الله"},"لا يناقش أحد فى محبة الله لنا ، وفى أهمية محبتنا له . ولكن الشيطان قد يقدم"],"69":["مفهوماً خاطئاً لهذه المحبة . بحيث أنه يمكن للإنسان أن يخطىء كما يشاء ، معتمداً على محبة الله ورحمته ومغفرته ، ومعتمداً على الخلاص الذى قدمه على الصليب !",{"h":"وكأن محبة الله تقود إلى الإستهتار وإلى التراخى !"},"حاشا ، فإن الكتاب يقول « أم تستهين بغنى لطفه وإمهاله وطول أناته ، غير عالم أن لطف الله إنما يقتادك إلى التوبة . ولكنك من أجل قساوتك وقلبك غير التائب ، تذخر لنفسك غضباً فى يوم الغضب ... » (رو ٢ : ٤ ، ٥) . و يقول أيضاً « هوذا لطف الله وصرامته . أما الصرامة فعلى الذين سقطوا . وأما اللطف فلك إن ثبتّ فى اللطف ، وإلا فأنت أيضاً ستقطع » (رو ١١ : ٢٢) .",{"h":"إن الشيطان يقدم محبة الله ، بأسلوب يضيع مخافته !"},"و يستغل إلى أبعد الإستغلال ـ بتفسير خاطىء ـ قول القديس يوحنا « لا خوف فى المحبة . بل المحبة الكاملة تطرح الخوف إلى خارج » (١يو ٤ : ١٨) . وهكذا يحاول أن ينزع مخافة الله من قلوب الناس باسم المحبة ، بينما الكتاب يقول « رأس الحكمة مخافة الرب » (مز ١١١ : ١٠) .","هنا وأستأذنكم فى طبع كتاب لى عن ( مخافة الله ) ، وعلاقة هذه المخافة بالمحبة . كنت قد جهزته منذ أكثر من عام ، وأعلنت عنه ، ثم أرجأت طبعه . وفى صميمى أرى نشره لازماً ، لأن كثيرين يستغلون محبة الله إستغلالاً خاطئاً يبعدون به عن الحرص الروحى ، وربما يقعون به فى اللامبالاة . وكل هذا من حيل الشياطين !!",{"h":"حقاً إن الله محب جداً وغفور ، ولكنه أيضاً عادل وقدوس ."},"وإن كان الله غير محدود فى محبته ، فهو أيضاً غير محدود فى عدله ، وغير محدود فى قداسته . وقداسة الله لا تقبل الخطية . وعدله يعاقب عليها ...","هذا من جهة محبة الله لنا . وماذا عن محبتنا نحن لله ؟",{"h":"الشيطان يصوّر محبتنا لله ، كمجرد مشاعر ، لا أكثر !"},"بينما محبتنا لله هى فى مفهومها السليم ، المحبة العملية « لا نحب بالكلام ولا باللسان ، بل بالعمل والحق » (١يو ٣ : ١٨) . ومن يحب الله ، لا يخالفه ، لا يعصاه ، لا يفعل ما يغضبه . ولذلك إرتبطت محبتنا لله بطاعته وحفظ وصاياه . والرب قد قال"],"70":["« إن حفظتم وصاياى ، تثبتون فى محبتى » (يو ١٥ : ١٠) ، « إن أحبنى أحد يحفظ كلامى » (يو ١٤ : ٢٣) . وقد قال القديس يوحنا الحبيب « هذه هى محبة الله ، أن نحفظ وصاياه » (١يو ٥ : ٣) . ومحبتنا لله ، معناها أننا لا نحب العالم وكل شهواته . لأن الكتاب يقول « إن أحب أحد العالم ، فليست فيه محبة الآب » (١يو ٢ : ١٥) . و يقول أيضاً « محبة العالم عداوة لله » (يع ٤ : ٤) .",{"h":"فلا يخدعنك الشيطان ويقول لك : يكفى أن تحب الله ، وإفعل ما تشاء !"},"و يقصد تفعل ما تشاء من الأخطاء أو التقصيرات ! إن هذا فكر شيطانى ، يقصد به أنك لا تلوم نفسك على أخطائك ، وبالتالى تبقى فيها غير شاعر بأهميتها ! كما أنه يصور المحبة بمفهوم خاطىء ، كأنها مجرد مشاعر ، بلا عمل يدل عليها . وهو بهذا يهز القيم الروحية فى نظرك ...","حيلة أخرى من حيل الشياطين هى :",{"h":"١٤ ـ هز المبادىء والقيم"},"الشيطان يشن على العالم الآن حرباً فكرية ، يريد بها أن يقدم مبادىء جديدة ومفاهيم جديدة ، تخدم أغراضه التى يريدها .",{"h":"وفى هذه الحرب يحاول أن يهدم القيم والتقاليد ، وكل المسلّمات ."},"يشكك الناس فيها كلها . و يتهم كل من يتمسك بالتقاليد القديمة ، بأنه رجعى أو متخلف ، أو « دقة قديمة » غير متحضر !! كما لو كان القديم سُبّة ينبغى التخلص منها !",{"h":"إنها ثورة من الشيطان على القيم ، وعلى العقائد أيضاً ."},"يريد الشيطان أن يكوّن تياراً عاماً خاطئاً ، كل من لا يسلك بمفاهيمه ، يهاجمه المجتمع و يتهكم عليه ! حتى أصبح كثير من المسلمات موضع جدل ونقاش ! ما هى الفضيلة ؟ وما هو الدين ؟ وما هى الحقوق وما هى الواجبات ؟ بل ما هى العلاقة بين الأب وإبنه فى مفهوم الحرية ؟",{"h":"لقد أعطى الشيطان فى جيلنا مفهوماً منحرفاً للحرية ..."},"أراد فى هذا المفهوم أن يقنع الإنسان بأنه حرّ يفعل ما يشاء ، و يعتنق ما يشاء من"],"71":["أفكار أو عقائد ، و ينشرها ، بلا أى قيد على الإطلاق ، مهما كانت آراؤه أو معتقداته أو تصرفاته خاطئة ، ومهما كانت خطرة على المجتمع ... !","والمعروف أن الحرية المطلقة لا يوافق عليها أحد ...",{"h":"فالإنسان له أن يمارس حريته ، بحيث لا يعتدى على حريات وحقوق الآخرين ، وبحيث لا يسىء إلى المجتمع ، ولا يحطم ما فيه من قيم وأخلاقيات ."},"أما أن يمارس حرية بلا شروط ولا تحفظات ، فإن الحرية حينئذ ستكون مجالاً للإباحية والإستهتار ، ومجالاً للإنحراف الفكرى ، دون ضوابط !","وإن كان الله قد منح الإنسان حرية ، فإنه وضع له إلى جوار هذه الحرية وصايا ينفذها . كما أن الله سيحاسب الإنسان على مدى استخدامه لهذه الحرية ، و يعاقبه إن كان قد أساء بها إلى نفسه أو إلى غيره .",{"h":"والحرية المطلقة التى يدعو إليها الشيطان ، لها أخطار سلوكية وعقائدية :"},"فالأخطار السلوكية نذكر كمثال لها الحرية التى أراد أن يسلك بها الهيبز والبيتلز وبعض الوجوديين الملحدين . بحيث لا مانع من أن يسيروا عراة فى الطريق العام ، أو أن يمارسوا الجنس بلا خجل ، ويخدشوا حياء المجتمع ... !","ومثال هذه الأخطاء أيضاً كل المناهج الإباحية ، وكل العثرات التى يصادفها المجتمع ، وتدفعه دفعاً إلى الفساد . ولا مانع عند الشيطان من ذلك ، باسم الحرية . وفى الواقع هذا خداع . فهناك مفهوم سليم للحرية من الناحية الروحية ...",{"h":"فالحرية الحقيقية هى أن يتحرر الإنسان من الداخل ، من الأخطاء :"},"يتحرر من الشهوات والرغبات الخاطئة ، ومن العادات المسيطرة عليه التى تفقده حرية إرادته . أما إن حقق الإنسان رغباته ونزواته بكل ما فيها من انحراف ، واستمر مستعبداً لها ، خاضعاً للجسد وللمادة التى تقوده ، فماذا ستكون النتيجة إذن ؟!",{"h":"حتماً إن العالم المستعبد لنزواته سيصل إلى كراهية الله الذى يقف ضد هذه النزوات . وهذه هى خطة الشيطان الماكرة !"},"أن يسعى إلى أن يكره الناس الله ، و يعتبرونه عدواً لهم ، لأنه يضيّع حرياتهم ، ويلغى وجودهم ، ويقف ضد رغباتهم ... ! وبدلاً من أن يصححوا رغباتهم ويصيروا أنقياء ، فإنهم يتمسكون بهذه الرغبات ويعادون الله بسببها !"],"72":[{"h":"والشيطان أيضاً ينشر حرية بلا قيد فى الفهم اللاهوتى ."},"بحيث أن كل إنسان يفسر الكتاب كما يشاء ، ويفهم منه ما يشاء ، وينشر ما يفهمه . وبهذا تتبلبل الأذهان وسط مفاهيم خاصة . وأمكن بهذه الحيلة أن توجد مئات المذاهب داخل المسيحية . سببها هذه الحرية الخاطئة التى يقولون فيها إن كل إنسان له حرية الإعتقاد دون الخضوع لسلطة دينية !!",{"h":"إن الكنيسة لها إيمان واحد . وليست هى مجموعة متناقضات ."},"هذا الإيمان الواحد علّم به الكتاب المقدس ، فقال « رب واحد ، إيمان واحد » (أف ٤ : ٥) . وللجمهور المؤمنين « قلب واحد ، ونفس واحدة » (أع ٤ : ٣٢) . والكنيسة هى جسد واحد ، مهما تعددت أعضاؤه ، وهذا الجسد رأسه المسيح (أف ٥ : ٢٣) . ومادام رأسها هو المسيح ، فباستمرار لها فكر المسيح (١كو ٢ : ١٦) . وفكر المسيح واحد لا تناقض فيه .",{"h":"فماذا إذن عن حرية الإعتقاد ؟ ما حدودها ؟"},"نحن لا نعارض أن كل إنسان له حرية الإعتقاد . ومحال أن يعتقد شيئاً على الرغم منه . فالذى له اعتقاد الكنيسة يصير عضواً فى الكنيسة . ومن ليس له اعتقادها يبق خارجاً عنها ، بكامل حريته . ويبق للكنيسة إيمانها الواحد .","والكنيسة لا تعتدى على حرية أحد ، ولا ترغمه على الإيمان . ولكن :",{"h":"ليس لأحد أن يدعى عضويته فى كنيسة لا يؤمن بمعتقداتها ."},"وهنا يكون دفاع الشيطان عن الحرية لا معنى له . فالحرية موجودة . ولكن كل من يقبل أن يكون عضواً فى كنيسة عليه أن يلتزم بعقائدها . وهذا أمر بدهى . فإن لم يلتزم بعقائدها ، يكون قد خرج منها بإرادته . و ينطبق عليه قول القديس يوحنا الحبيب « منا خرجوا . ولكنهم لم يكونوا منا . لأنهم لو كانوا منا ، لبقوا معنا » (١يو ٢ : ١٩) .","نقول هذا ، لأنه باسم حرية الإعتقاد ، نجد أنه فى بعض كليات اللاهوت ، فى جهات كثيرة من العالم ، يدرس المحاضرون ما يشاءون دون الإلتزام بعقيدة الكنيسة التى ينتمون إليها ، أو التى يدرسون عقائدها . فيدخل الأستاذ إلى المحاضرة ، ويقول الذى يعجبه !",{"h":"وهكذا وُجد فى بعض الكليات أساتذة لاهوت ملحدون !!"}],"73":["وأفلح الشيطان ، باسم الحرية الزائفة ، أن يضرب ضربته و ينجح !!","أما الكنيسة المقدسة الجامعة الرسولية ، الملتزمة « بالإيمان المسلّم لنا من القديسين » (يه ٣) ، فلم تسمح بهذا مطلقاً ، بل كانت تحكم بحرم المبتدعين والمنحرفين وإخراجهم ، لكى تبقى الكنيسة بإيمان واحد ، تسلمه سليماً للأجيال المقبلة . وهكذا قال القديس بولس الرسول فى قوة :",{"h":"« إن بشرناكم نحن ، أو ملاك من السماء ، بغير ما بشرناكم به ، فليكن أناثيما » (غل ١ : ٨) ."},"وقال القديس يوحنا الحبيب « إن كان أحد يأتيكم ، ولا يجىء بهذا التعليم ، فلا تقبلوه فى البيت ، ولا تقولوا له سلام . لأن من يسلم عليه يشترك فى أعماله الشريرة » (٢يو ١٠ ، ١١) . إنه حزم شديد من أكثر الرسل حديثاً عن المحبة .","لذلك كانت الكنيسة حريصة على الإيمان ، تدافع عنه ضد أى إنحراف . ولا تقبل مطلقاً أى إنحراف إيمانى يدخل إلى الكنيسة باسم الحرية ! لينشر أفكاراً خاصة ... !",{"h":"لذلك فإن الشيطان لا يقبل سلطان الكنيسة ، ويحارب السلطان الكهنوتى ."},"خذوها قاعدة ثابتة على مدى أجيال التاريخ : كل من ينحرف فى عقيدته ، إذا لم يتب ، لابد أن يحارب السلطان الكهنوتى ، أى يحارب القوة التى تحكم على إنحرافه بسلطان من الله (متى ١٨ : ١٨ ، يو ٢٠ : ٢٣) .","ولما كان الشيطان ينشر أفكاره وانحرافاته فى كل ميدان ، وليس فى محاربة الكنيسة وحدها ، لذلك فقد لجأ الشيطان إلى حيلة معروفة وهى :",{"h":"الوقوف ضد السلطة عموماً ، فى كل مجالاتها ..."},"و يقصد طبعاً أن يقف ضد كل سلطة سوف لا تقبل الإنحراف أو الخطأ ، بل تحاربه وتمنعه أو تعاقبه ، وذلك لكى يستمر الخطأ ...","فهو يحارب سلطة الأب فى الأسرة ، دفاعاً عن شخصية الأبناء !","وهو يحارب سلطة المعلم فى الكلية أو المدرسة ، لخلق جيل قوى !","وهو يحارب سلطة الدولة ، باسم الديمقراطية وحقوق الشعب !","وهو أيضاً يحارب سلطة الله ، لكى يشعر الإنسان بوجوده هو !","و بالتالى يحارب سلطة الإكليروس ، كوكلاء الله على رعيته (تى ١ : ٧) ."],"74":[{"h":"الشيطان لا يريد وجود رقيب يضبط الأخطاء ويقوّمها ."},"بينما الله يقول « قد جعلتك رقيباً ... فاسمع الكلمة من فى ، وانذرهم من قبلى » (حز ٣ : ١٧) . يريد الشيطان أن تبقى كل الأمور ، بلا ضابط ، بلا رقيب ، بحرية طائشة ، كما يقول الكتاب عن عهد القضاة : ولم يكن ملك فى إسرائيل فى تلك الأيام . وكان كل واحد يفعل ما يحسن فى عينيه » (قض ١٧ : ٦) ... كل واحد يعمل ما يعجبه ، وينشر ما يعجبه من آراء ومعتقدات . وإن وقفت ضده سلطه يهاجمها ، بل يهاجم مبدأ السلطة عموماً !! وهذه خطة الشيطان ...","ومن ضمن خطط الشيطان أيضاً :",{"h":"١٥ الإنقياد للتيار العـــام"},"قد يكون التيار العام كله خاطئاً ، ويدعوك الشيطان أن تخضع لهذا التيار ، وتكون مثله ! وقد يهمس فى أذنيك :",{"h":"الكل هكذا ... لماذا تشذ أنت ، ويكون لك أسلوب خاص ؟!"},"والجواب أننا نتبع الحق أياً كان موقعه ، فى جانب الأغلبية أو الأقلية . فإن كانت أغلبية الناس فى خطأ ، فإننا لا نتبعها . وهكذا فعل أبونا نوح : كانت كل الناس فى عهده أشراراً ، وكان هو وحده البار مع أسرته .",{"h":"ما أسهل أن تكون الغالبية كلها مخطئة ، أو الجيل كله ."},"الغالبية فى وقت الصلب كانت مخطئة وصاحت أصلبه أصلبه (لو ٢٣ : ٢١) . بل الجيل كله ، قال عنه السيد المسيح « جيل فاسق وشرير » (متى ١٢ : ٣٩) . وغالبية الناس أيام آخاب الملك ، كانت تعبد الأصنام ، إلا سبعة آلاف ركبة فقط من بين مئات الآلاف (١مل ١٩ : ١٨) . وفى أيام موسى النبى ، حكم الرب على الشعب كله بأنه متمرد وصلب الرقبة ، ولم يدخل منه إلى أرض الموعد إلا إثنان فقط هما يشوع بن نون ، وكالب بن يفنة (عد ١٤ : ٢٠ - ٣٠) .","وإن رجل الله الثابت فى وصاياه ، هو الذى ينشد قائلاً :",{"h":"سأطيع الله حقّ لو أطعت الله وحدى"}],"75":[{"h":"ولكن الشيطان يدفع دفعاً فى التيار العام بطرق شتى :"},"أحياناً يجعل الناس يجارون الخطأ من باب المجاملة ، أو من باب الخجل ، أو من باب التقليد ، أو خوفاً من تهكم الناس ومن تعييرهم ، أو نتيجة لضغط الظروف الخارجية وإلحاح الآخرين . أو أن يقول لهم الشيطان « هذه المرة فقط ، ولن تتكرر » ! ثم تتكرر طبعاً ... أو أن شخصاً قد يجارى التيار خضوعاً لسلطة أقوى منه أو خضوعاً لرئاسة ... وقد يجارى التيار جهلاً . وقد يقول له الشيطان :",{"h":"هل من المعقول أن يكون كل الناس مخطئين ، وأنت الوحيد المصيب ؟!"},"هل من المعقول أن كل هؤلاء لا يعرفون أين يوجد الخير والحق ، وأنت الوحيد الذى تعرف ؟! إتضع يا أخى ... (و يتضع) الأخ ! و ينجرف فى التيار .","وقد يسير فى التيار نتيجة لصداقة أو صحبة خاطئة إستطاعت أن تؤثر عليه وتجذبه إلى طريقها ، كما سار سليمان الحكيم فى طريق نسائه (١مل ١١ : ٤) .",{"h":"وقد يخضع الإنسان للتيار نتيجة لضعف شخصيته ..."},"وهكذا لا يقدر على المقاومة ، أو يقاوم قليلاً ولا يثبت . والعجيب أن أهل العالم يكونون أقوياء جداً فى دفاعهم عن طريقهم الخاطىء ، وفى سخريتهم من أولاد الله الذين لا يجارونهم . ويظلون ينعتونهم بشتى النعوت ، حتى يضعف هؤلاء ويخضعون ... ! يا للأسف ...","إن أولاد الله يجب أن يكونوا أقوياء فى مبادئهم ، ثابتين راسخين ، لا يتزعزعون أمام تهكمات الأشرار . وليتذكروا قول الكتاب :",{"h":"« لا تشتركوا فى أعمال الظلمة غير المثمرة ، بل بالحرى وبخوها » (أف ٥ : ١١) ."},"فإن لم يستطيعوا أن يوبخوا أعمال الظلمة ، فعلى الأقل لا يشتركون فيها ... وليكن لهم أسلوبهم المميز فى الحياة ، الذى قال عنه القديس يوحنا الحبيب « بهذا أولاد الله ظاهرون ، وأولاد إبليس (ظاهرون) » (١يو ٣ : ١٠) . وكما قيل « من ثمارهم تعرفونهم » (متى ٧ : ١٦) . وقيل أيضاً « لغتك تظهرك » (متى ٢٦ : ٧٣) . وقد قال القديس بولس الرسول عن عدم الخضوع للتيار العام :",{"h":"« لا تشاكلوا هذا الدهر » (رو ١٢ : ٢) ."},"أى لا تصيروا شكله . لا تصيروا مثله . لأن شكلكم معروف ، فأنتم صورة الله"],"76":["ومثاله . وما أجمل قول الله فى ذلك « نعمل الإنسان على صورتنا ، كشبهنا » (تك ١ : ٢٦) . فكيف تتنازل عن صورتك الإلهية ، لتصير كصورة عالم ساقط منحرف .",{"h":"إن دانيال والثلاثة فتية ، كانوا أقوى من التيار العام ."},"ليس فقط فى انفرادهم عنه بعبادة إلههم ، حتى لو أدى الأمر أن يلقى دانيال فى جب الأسود ، و يلقى الثلاثة فتية فى أتون النار ... بل حتى منذ بدء تعيينهم فى قصر الملك ، إذ رفضوا الطعام الملكى ، ولم يأكلوا مع سائر الفتيان . وما أجمل قول الكتاب « أما دانيال فجعل فى قلبه أن لا يتنجس بأطايب الملك ولا بخمر مشروبه » (دا ١ : ٨) .","صمم دانيال والثلاثة فتية على هذا الأمر ، مع أنهم كانوا أسرى حرب ، وتحت سلطان ، يخدمون وهم عبيد فى قصر الملك . ولكن قلوبهم وأرواحهم كانت حرة طليقة ، لا تخضع للتيار العام ، بل لمشيئة الرب .",{"h":"لذلك كن شجاعاً ، وصاحب مبدأ ، وقاوم التيار العام إذا أخطأ ."},"لا تخضع للشيطان وكل نصائحه ، بل وكل مخاوفه . وارفض الخطأ مهما رأيت كباراً يسيرون فيه ! وإن وجدت الذين يسيرون فى طريق الحق قليلين ، فلا يضعف قلبك . فهذه هى القلة المختارة . وقد قال الرب « ما أضيق الباب وأكرب الطريق الذى يؤدى إلى الحياة . وقليلون هم الذين يجدونه » (متى ٧ : ١٤) . واعلم أنه :",{"h":"لو وقعت الغالبية فى الخطأ ، فهذا لا يجعل الخطأ صواباً ."},"الخطأ هو الخطأ . ووقوع الأغلبية فيه لا يبرره . والمعروف أن الصواب طريقه صعب ، وقد لا يستطيعه كل الناس ، بل القلة المتميزة بمبادئها . فإن وجدت الشيطان قد ألقى الكل فى الخوف ، لا تخف أنت . وإن وجدت الغالبية تعلمت التملق والرياء ، فلا تكن أنت كذلك . وإن وجدت الكل قد استعملوا أساليب العالم فى لهوه وترفيهاته ورفاهيته وأزيائه ، فلا تكن كذلك . وإن وجدت لغة الناس قد تغيرت ، وأصبحت ليست كذى قبل ، فلتكن أنت بنفس لغتك الأولى .","وإن ضعفت مقاومتك للتيار ، فقل مع المرتل فى المزمور :",{"h":"نجنا يارب من هذا الجيل ، وإلى الأبد آمين » (مز ١٢ : ٧) ."},"والرب قادر أن ينجيك من التيار العالم ، فلا يجرفك .","حيلة أخرى من حيل الشياطين لإسقاط أولاد الله ، وهى :"],"77":[{"h":"١٦ الإغـــراءات"},"منذ الخطية الأولى ، والشيطان يقدم إغراءات ليسقط ضحاياه . وكان أول إغراء قدمه لأبوينا الأولين هو « تصيران مثل الله ، عارفين الخير والشر » (تك ٣ : ٥) . واستمر يقدم إغراءات للبشر « شهوة الجسد ، وشهوة العين ، وتعظم المعيشة » (١يو ٢ : ١٦) . وقدم هذه كلها لسليمان الملك (جا ٢ : ١ - ١٠) .","وعلى الجبل قدم للسيد المسيح ثلاثة إغراءات : الخبز ، حمل الملائكة له على أجنحتها ، وكل ممالك الأرض ومجدها (متى ٤) . ورفض السيد كل هذا ، وأخزى الشيطان وطرده .",{"h":"إن إغراءات الشيطان لا تسقط إلا قلباً يميل إليها ..."},"أو يمكن أن يميل إليها ... أما القلب القوى فإنه يرفض تلك الإغراءات ، أو قل إنها لا تغريه . إن الملكة إيزابل أرادت أن تؤثر على ياهو الملك وتغريه ، كما كان آخاب الملك تحت سيطرتها من قبل « فكحلت بالإثمد عينيها ، وزينت رأسها » (٢مل ٩ : ٣٠) . أما ياهو ، فلم يغره هذا الجمال الزائف ، بل احتقره وأمر بقتلها ...",{"h":"والشيطان أحياناً ينتقى إغراءاته ، وأحياناً يجس النبض ..."},"يجس النبض لكى يرى هل محاربه يضعف أمام هذا الإغراء أم لا . فإن وجده لا يهتم ولا يتأثر ، يجرب إغراء آخر ، كما فعل مع السيد المسيح ، فوجده قوياً أمام كل إغراءاته . ومن خبرة الشيطان الطويلة ، أنه ينتقى لكل نوع من الناس ما يرى أنه يناسبه ...",{"h":"وقد يغرى بالشىء الذى يرى الشخص محتاجاً إليه ."},"كما قدم للسيد المسيح تجربة الخبز ، حينما قيل عنه إنه « جاع أخيراً » (متى ٤ : ٢ ، ٣) . وقدم تجربة العرافة لشاول الملك فى الوقت الذى رآه فيه محتاجاً الى مشورة ولم يجد (١صم ٢٨ : ٤ - ٧) . وقدم تجربة العجل الذهبى لبنى إسرائيل فى وقت رآه مناسباً ، وقد غاب عنهم موسى النبى ، وغاب معه الإرشاد الروحى وهيبة النبوة (خر ٣٢ : ١ - ٤) ."],"78":[{"h":"والشيطان يقدم الإغراء قوياً مؤثراً ، يمنع التوبة والعمل الروحى ."},"فإن وجد إنساناً قد عزم على التوبة بكل عزم وقوة ، يقدم له خطية كان يشتهيها منذ زمن ، ويبحث عنها فلا يجدها . فيضعها أمامه فجأة تسعى بنفسها إليه من حيث لا يدرى ، فيغريه بها ليسقط ... وإن كان إنسان قد أبطل قراءة كتب معينة معثرة ، لا مانع فى هذا اليوم من أن يرسل إليه صديقاً ، يهديه كتاباً كان هذا (الضحية) يشتهى شراءه شهوراً طويلة ولا يجده فى السوق . فيجد نفسه أضعف من الإغراء ، فيقرأ ويسقط .","وإن تاب شاب عن خطية الزنا ، يجد خطية سمت إليه سمياً .",{"h":"بحيث يظن المسكين أنها فرصة لا تعوّض . ويقول له الشيطان :"},{"h":"لا تترك هذه الفرصة ، ويمكن أن تتوب بعدها ... !"},"وهكذا إن وجد الشيطان إنساناً يبعد عن الخطية ، يأتى إليه بأكبر إغراءات للخطية بالنسبة إليه . لأنه يعرف تماماً أين يوجد الجرح الذى يدوس عليه فيؤلمه ... فإن ثبت ووجدت خطية تسعى إليك فى إغراء عجيب ...",{"h":"لا تقل هذه فرصة . بل قل : هذا بلا شك فعل الشيطان ."},"ليس هذا شيئاً طبيعياً ، ولا هو أتى عن طريق الصدفة . بل هى خطة مدبرة محكمة من عمل الشيطان . ومبارك هو الرب الذى كشفها لى لأهرب منها ... وكما قال الراهب القديس عبد المسيح الأثيوبى المتوحد ببرية شيهيت « فغ يا أباقى فغ » ...","نقطة أخرى بارزة فى حرب الشياطين هى :",{"h":"١٧ التخـديـر"},"حينما يكون الإنسان متيقظاً ومتنبهاً لخلاص نفسه ، صاحياً عقلاً وروحاً ، فإنه من الصعب أن يسقط ... ولذلك قال أحد القديسين : إن الخطية تسبقها إما الشهوة ، أو الغفلة ، أو النسيان . فحالة الغفلة والنسيان ، هى تخدير من الشيطان للإنسان ...",{"h":"فينساق إلى الخطية ، كأنه ليس فى وعيه !"},"ولذلك حسناً قيل فى توبة الإبن الضال إنه « رجع إلى نفسه » (لو ١٥ : ١٧) ."],"79":["وكلمة (رجع) تعنى أنه لم يكن فى وعيه ، أو على الأقل لم يكن فى كامل وعيه ، طوال فترة الخطية . ولهذا لما رجع إلى نفسه بدأ يفكر بأسلوب آخر ، يختلف عن أسلوبه فى الخطية .",{"h":"الشيطان يخدر الإنسان بحيث ينسى كل شىء ، ما عدا الخطية ."},"تكون كل حواسه وأفكاره ومشاعره مركزة فى الخطية وحدها . أما كل ما عداها فلا يحس به الإنسان اطلاقاً ، وكأنه قد نسيه تماماً تماماً ...","ينسى أنه صورة الله . ينسى الوصية . ينسى نتائجها . ينسى وضعه الروحى . ينسى تدرايبه الروحية . ينسى عبادته واحتراسه . ينسى وعوده لله وتعهداته ونذوره . ينسى إحترامه . بل قد ينسى أنه صائم ، أو أن هذه أيام مقدسة . و ينسى عقوبات الله وإنذاراته ... يكون كأنه مخدر تماماً . والشيطان قد خدره بالخطية ، بحيث أصبح لا يعى شيئاً غيرها ...",{"h":"ولا يفيق إلا بعد السقوط ، حينما يكون كل شىء قد انتهى ."},"هكذا كان داود النبى مخدراً ، حينما أخطأ ، وجرته الخطية إلى خطية . ولم يفق من هذا التخدير إلا على صوت ناثان النبى يقول له « أنت هو الرجل » (٢صم ١٢ : ٧) . حينئذ فقط أفاق ، وأحس كم كانت أعماق خطيئته !","لعل قايين كان أيضاً مخدراً حينما قام على أخيه وقتله . ولم يفق إلا على قول الرب له « أين هابيل أخوك ؟ » (تك ٤ : ٩) . حينئذ فقط أفاق ، وشعر ببشاعة ما قد فعل ونتائجه وقال « ذنبى أعظم من أن يحتمل » (تك ٤ : ١٣) .",{"h":"قد يفيق الإنسان بعد الخطية مباشرة ، وربما بعد مدة طويلة ."},"الإبن الضال لم يفق من تخديره ، إلا بعد أن أنفق كل ماله واعتاز ، وشعر بسوء حالته (لو ١٥ : ١٦ ، ١٧) . والغنى الذى عاصر لعازر المسكين لم يفق إلا فى الجحيم . ولكن هناك من يفيق بعد الخطية مباشرة ، مثل القديس بطرس الذى بعد إنكاره بكى بكاءً مراً (متى ٢٦ : ٧٥) . ويهوذا لم يفق إلا بعد فوات الفرصة .",{"h":"هناك من يفيق من تخديره فيتوب . وهناك من يفيق فييأس ."},"الإبن الضال ، وداود النبى ، وبطرس الرسول ، لما أفاقوا تابوا ."],"80":["أما يهوذا فلما أفاق ، أسلمه الشيطان إلى اليأس « فمضى وخنق نفسه » (متى ٢٧ : ٣ - ٥) . ومات فى خطيئته فهلك ...",{"h":"لذلك هناك نصيحتان أقدمهما لك ، إذا خدّرك الشيطان :"},"الأولى ، أن تفيق بسرعة . كما قال المرتل « أنا أستيقظ مبكراً » (مز ٥٧ : ٨) . واحذر من أن تستمر مخدراً بالخطية إلى أن تصبح عادة ، أو يصير من الصعب عليك أن تفيق ، أو أن تصحو من تخديرك بعد أن تكون قد وصلت إلى نتائج سيئة جداً ...","النصيحة الثانية : هى أنك حينما تفيق ، إنما تفيق إلى توبة حقيقية وسريعة ، وليس إلى يأس أو صغر نفس ... واستغل الندم والإنسحاق لنفعك الروحى .","نقطة أخرى أقولها لك فى حروب الشياطين وهى :",{"h":"١٨ تحـويـل الدين الى فلسـفة"},{"h":"السيد المسيح أراد أن يكون الدين روحاً وحياة ."},"ولذلك قال « الكلام الذى أكلمكم به هو روح وحياة » (يو ٦ : ٦٣) . نفهم روح الكلمة ، ونحولها إلى حياة فينا . وهكذا يصير الدين طريقاً لتنقية القلب ، ومرشداً إلى الإلتصاق بالله ، ولكى تكون للإنسان حياة أبدية . ولعل هذا ما أراده الرب بقوله « أتيت لتكون لهم حياة ، وليكون لهم أفضل » (يو ١٠ : ١٠) .",{"h":"ولكن الشيطان يريد أن يحول الدين إلى جدل ومناقشات ..."},"يريد أن العقل يحل محل الروح ، والجدل يحل محل الممارسة . وتصبح الحياة الدينية هى مجرد عقلانية . وكأن المسيحية هى فلسفة تُدرّس وتُحلّل ، وتصبح مجرد منهج للتعليم ، وليس حياة نحياها . والعقل لا يضر الشيطان فى شىء إن بقى مجرد عقل لا تحركه الروح . وهذا ما يريده الشيطان ...",{"h":"بودى أن أترجم لكم كتاب ( ضد الأكاديميين ) للقديس أوغسطينوس ."},"إسم كتابه Contra Acadimos ليتنى أستطيع أن أترجم لكم بعض فقرات منه كمثال . والمعروف عن القديس أوغسطينوس أن له منهجاً روحياً عميقاً .",{"h":"والمنهج العقلى الذى يريده الشيطان ، حاربه القديس بولس الرسول ."}],"81":["وهذا واضح جداً فى الأصحاحين الأولين من رسالته الأولى إلى أهل كورنثوس ، فهو يقول « أتيت ليس بسمو الكلام أو الحكمة » ، « وكلامى وكرازتى لم يكونا بكلام الحكمة (الإنسانية) المقنع ، بل ببرهان الروح والقوة » (١كو ٢ : ١ ، ٤) ، « لا بحكمة كلام ، لئلا يتعطل صليب المسيح » (١كو ١ : ١٧) . فالتركيز على صليب المسيح عمل روحى ، يعطله الإنشغال بالفكر والجدل .",{"h":"إن الهرطقات كانت لعبة شيطانية عقلية لتعطيل العمل الروحى ."},"العمق الروحى الذى عاشته الكنيسة فى عصر الإستشهاد ، طوال القرون الثلاثة الأولى ، وفى أوائل القرن الرابع ، والعمق الروحى الذى كان قد بدأ بالرهبنة منذ أواخر القرن الثالث ، وازدهر فى القرنين الرابع والخامس ، بكل ما فيه من حب لله ، وبكل ما فيه من الإرشاد الروحى من أقوال الآباء ... كل ذلك أثار حسد الشيطان ، فأراد أن يشغل العالم بالجدل والنقاش على مدى قرنين طويلين ... وهكذا ظهرت هرطقات أريوس ، وأبوليناريوس ، وسابيليوس ، ومقدونيوس ، ونسطور ، وأوطاخى ، وغيرهم ... كل ذلك فى فترة مركزة جداً دوّخت العالم فكرياً . وأصبح النقاش حول لاهوت الإبن وطبيعته يدور فى الشوارع حتى بين العامة . وألهم الشيطان مفاهيم للهراطقة وتفاسير لآيات الكتاب . وانشغل آباء الكنيسة فترة طويلة بالرد على البدع والهرطقات .",{"h":"والشيطان يتمنى أن يشغلنا طول العمر بالحوار الفكرى والردود ..."},"ومازالت هذه هى خطته ، يرسل لنا فى كل جيل من يحاول أن يحوّل الدين إلى نقاش وجدل وفكر وحوار وآراء وردود ... مريداً بهذا أن يعطل العمل الروحى من جهة ، ويثير الإنقسام والخصومات من جهة أخرى ، ولو باسم الدين ، وباسم الدفاع عن العقيدة ، وتصبح الكنيسة مذاهب وشيعاً ، ويفرح الشيطان بهذا . من يسقطون فى الهرطقات مكسب له ، ومن يتعبون من الشكوك مكسب آخر . ومن ينشغلون عن العمل الروحى بهذه السلبيات وإضاعة جهودهم فى الردود ، كل ذلك مكسب أيضاً .",{"h":"ونشكر الله أن الآباء الذين ردوا على الهرطقات كانوا روحيين ."},"تقرأ مثلاً كتاب (تجسد الكلمة) للقديس أثناسيوس فتجده كتاب روح كما هو كتاب لاهوت وعقيدة ... ولكن كثير ين انشغلوا بالفكر ... ونحن نشكر الله أيضاً أن حركة الهرطقات والرد عليها فى القرنين الرابع والخامس ، سارت معها جنباً إلى جنب"],"82":["حركة الرهبنة وإرشادها الروحى . فأقامت توازناً مع الدوامات الفكرية .","كان الرد على الهراطقة لازماً جداً لحفظ الإيمان . ولكن كان الإنشغال بذلك تعطيلاً للكنيسة . ولكن الله حوّله إلى خير بتعميق الإيمان فى القلوب وبإزالة الشكوك .",{"h":"وحتى فى الروحيات البحتة ، يحاول الشيطان تحويلها إلى فلسفة ."},"يمكن أن يجعل حتى الصلاة مثلاً منهجاً فكرياً له قواعده العقلية . وكذلك يمكن أن يفعل ذلك بالرهبنة ويحولها إلى مدارس تتصارع فكرياً بين الوحدة والعمل ، والتأمل والخدمة . ويتحول الأمر إلى نقاش وإلى صراع ، يسر به الشيطان ويفرح !",{"h":"حتى صلاة « أبانا الذى » يحولها إلى صراع حول الترجمات ."},"وإذا بالناس وهم يصلون يقول أحدهم « خبزنا كفافنا » ويصيح آخر بصوت عال « الذى للغد » . وتتصارع الترجمات وتتبلبل الأفكار ، وبدلاً من التأمل فى الصلاة يدور الجدل والنقاش أية الترجمات أصح !!","ونفس الوضع قد يدور فى القداس الإلهى أيضاً : يريد الشيطان أن يقضى على التأمل والروحيات ، فيثير حرباً من الترجمات .",{"h":"وفى داخل الكنيسة ما أسهل أن يثير أفكاراً جديدة ..."},"يجعل البعض يشغف بالجديد ، فيقدم تفسيراً جديداً ، أو معتقداً مغايراً للمفاهيم العامة . ويقول صاحبه وناشره إن كل من سبقوه قد أخطأوا . وبدلاً من استخدام الفكر الدينى للحب ولنقاوة القلب ، يحوله الشيطان إلى صراع وإلى حرب بين المتدينين بسبب الفكر والفهم الخاص ، وادعاء كل فريق أنه يدافع عن العقيدة ! وأنه الوحيد الصادق فى إيمانه ...","أو على الأقل يعطل الروحيين عن عملهم بالإنشغال بالسلبيات والرد عليها . وإن لم يفعلوا ذلك ، يملأ الجو شكوكاً وبلبلةً .","حرب أخرى من حروب الشيطان وهى :",{"h":"١٩ فتـرة راحـة من الخطيــة"},"إنه لا يحارب باستمرار ، إن وجد للحرب الدائمة أضراراً ..."],"83":["فهو قد يبطل الحرب فترة ، ليس إشفاقاً منه على من يحاربه ، وإنما لكى يجره إلى التهاون وعدم الحرص ، ثم يعود إليه بأسلوب أكثر قساوة فيسقطه . وبهذا يشعره على الدوام بعدم ثقة فى القدرة على حياة البر ، ويقنعه بأنه مهما تاب ، لابد سيعود إلى الخطية مرة أخرى .",{"h":"أو قد يبعد الخطية عنه فترة ، ليشتاق إليها ."},"ربما كثرة ممارسة الخطية تولد الملل منها وكراهيتها . فتكون خطة الشيطان أن يبعدها فترة . ثم يعيدها بعد حين بأسلوب أكثر تشويقاً ، أو أكثر حدة ، أو بأسلوب غير متوقع ، لكى يسهل السقوط فيها .",{"h":"وهكذا يستخدم أسلوب المنح والمنع فى المحاربة بالخطية ."},"إنه بهذا يلعب بمشاعر النفس البشرية ... ويجعلها باستمرار فى حالة عدم استقرار ، ما بين علو وهبوط . وأولاد الله يدفعهم ذلك إلى مزيد من الحرص والتدقيق ، وإلى مزيد من الإتضاع . ولكن الشيطان يريد أن يجعلهم فى جو من الخوف وعدم الثقة ، والشعور بأن البر فوق مستواهم .","ثم يتدرج من الهجوم الفكرى إلى هجوم عام يقول فيه : إن المسيحية ديانة سمو وكمال . ولكنه سمو غير عملى ، ليس فى مستوى قدرة الإنسان أن يناله . ويخفى فى كل ذلك الأمثلة التى قدمتها لنا سير الأبرار فى كل زمان ...","حرب أخرى من حروب الشيطان هى :",{"h":"٢٠ الفضـائل الظـاهرة الجسـدية"},"يغرى الإنسان بالفضائل الظاهرة الجسدية ، بدلاً من الفضائل الروحية الخفية .","ونقصد بالظاهرة ، الظاهرة لصاحبها ، وليس فقط الظاهرة للآخرين . وهذه الفضائل الظاهرة يمكن أن يلقيه بها فى الإعجاب بالنفس والغرور ، أو يلقيه فى احتقار الآخرين الذين لم يصلوا إلى نفس المستوى .",{"h":"وهذه الحرب يحارب بها الرهبان كما يحارب بها العلمانيين أيضاً ."}],"84":["فإذا بدأ الراهب جهاده ، يجعله الشيطان يهتم بالصوم ، وبالمطانيات ، والسهر ، والصمت ، والإعتكاف . وكلها أمور ظاهرة ... وفى نفس الوقت لا يهتم بفضائل القلب من الداخل مثل الفرح والسلام والنقاوة والوداعة والهدوء ... الخ",{"h":"وفى الصوم يحارب بالأسلوب الجسدانى ويترك الروحى ."},"فيجعل كل اهتمام الصائم بفترة الإنقطاع وكم تكون ، وبنوع الأكل ووجوب الإمتناع عن بعض مشتهيات ، والإقلال من كمية الماء التى يشربها . وكل هذه أمور جسدية ، ولا يشغل نفسه أبداً بالفضائل الروحية التى فى الصوم مثل : انسحاق القلب ، وسمو الروح ، وضبط النفس فى كل الأمور .","والشيطان يعرف أن مثل هذا الصوم الجسدى قد لا يفيد الإنسان روحياً . ويستغل هذا الأمر فيا بعد ، لكى يبعده عن الصوم كلية .",{"h":"ونفس الوضع بالنسبة إلى المطانيات ."},"المهم هو عددها ، ونمو هذا العدد باستمرار . أما أن الإنسان فيا يسجد ، تلصق بالتراب نفسه (مز ١١٩) كما تلصق رأسه بالتراب ، فهذا ما لا يجعله يفكر فيه ! كذلك لا يجعله يهتم بالمشاعر الروحية التى تصحب المطانيات ، وما تصحبها أيضاً من صلوات ... وكل ما يقصده هو أن تتحول هذه المطانيات - على الرغم من كثرة عددها - إلى عمل جسدانى يمكن أن يرهقه دون أن يفيده ، كما يلقيه به فى المجد الباطل !",{"h":"والوحدة أيضاً يهتم بمظهرها وليس بروحياتها ."},"كإنسان يحيا الوحدة كطقس ، وليس كمنهج روحى يتميز بفضائل معينة ، فيها يكون الفكر منفرداً بالله فى حب ، ويكون القلب قد مات كلية عن العالم . ولكن كثيراً ما يجعل الشيطان هذا المتوحد يقنع بمجرد سكنى المغارة والبعد عن الدير ، ويملأ قلبه بالكبرياء والسخط على الدير ومن فيه ، دون الإهتمام بالعمل الروحى داخل المغارة . وكما قال ماراسحق « يوجد إنسان قد يسكن فى القلاية خمسين سنة وهو لا يعرف طريقة الجلوس فى القلاية » .",{"h":"وما ينطبق على الوحدة ، ينطبق على الصمت أيضاً ."},"فالمفروض أن هدف الصمت ، هو أن الإنسان يبعد عن أخطاء اللسان ، ويعطى نفسه فرصة للحديث مع الله . أما أن يقنع الإنسان بمجرد الصمت ، فهذا عمل جسدانى"],"85":["ظاهر . إذ أن كل الأخطاء التى يقع فيها بلسانه ، يمكن أن يقع فيها بفكره مثل الإدانة والغضب والشتيمة والحدة ... الخ . فإن كان قلبه خالياً فى نفس الوقت من الحديث مع الله . يكون صمته بعيداً عن العمل الروحى .",{"h":"وبنفس الطريقة قد يقنع الإنسان باختيار البتولية ."},"ويظن أن البتولية هى ذلك العمل الظاهر الذى هو عدم الزواج . وقد تكون نفسه غير بتولة ، وأفكاره دنسة . والعنصر الإيجابى فى البتولية الذى هو توجيه الحب كله نحو الله ، قد لا يكون موجوداً أيضاً . وهكذا يكون قد أخذ من البتولية ظاهرها ، دون روحها ودون فاعليتها داخل القلب ...",{"h":"المفروض فينا أن نهتم بالعمل الروحى الداخلى ، فهو الأهم ."},"والرب قد قال « يا إبنى أعطنى قلبك » (أم ٢٣ : ٢٦) . فيبدأ الإنسان بنقاوة القلب ، وبمحبة الله ، وبالفضائل الداخلية . ثم من القلب النقى تخرج الصلاة النقية ، والمطانيات الظاهرة ، والصوم الروحانى ، وكل فضيلة أخرى ...","والعجيب أن المهتم بالفضائل الظاهرة ، كثيراً ما يصطدم بأب اعترافه ، وربما يفكر فى تغييره ، بينما حياته هو من الداخل ليست نقية أمام الله !",{"h":"٢١ العنـــف"},{"h":"إنها حرب يوجهها الشيطان إلى الروحيين كما إلى الخطاة ."},"يدرب الإنسان على العنف تجاه كل خطأ . وبالتالى يجعله عنيفاً فى مقابلة كل من يخالفه فى الرأى . وقد تختفى وراء هذا العنف كبرياء وقساوة قلب .","وربما كثير من أهل العالم يتميزون بالوداعة والهدوء ، بينما نجد من المتدينين من يكونون عنفاء جداً ، باسم الدين ، ساخطين على كل شىء ، شاعرين أنهم هم وحدهم الذين يعرفون الله ويسيرون فى طرقه . وبهذا العنف يسقطهم الشيطان فى عديد من الأخطاء التى لم يقع فيها العلمانيون . وينسيهم فضائل الوداعة واللطف التى هى من ثمار الروح القدس (غل ٥ : ٢٢) .","من حروب الشيطان أيضاً :"],"86":[{"h":"٢٢ المعطـــلات"},{"h":"كل عمل روحى معرض لمعطلات عديدة من الشيطان ."},"فقد يعزم الإنسان من كل قلبه على عمل روحى . ويقف ضده الشيطان بكل قوة لكى يعطله عن تنفيذ ما يريد . وكما يقول الرسول « الإرادة حاضرة عندى . ولكن أن أفعل الحسنى لست أجد » (رو ٧ : ١٨) . وهذه المعطلات إما أن تكون ظروفاً خارجية ، أو من نسيان ، أو من عدم توافر الوقت ، أو من مقاومات من أعداء ، أو من أخوة كذبة ... ثم يأتى الشيطان ليقول :",{"h":"قطعاً هذا العمل ليس من الله . وإلا كان قد سهل سبله !"},"أو قد يقول للناس عن هذا الإنسان الخير : لو كان هذا الإنسان من الله ، لكان الله قد وفقه فى عمله . ويضرب عصفورين بحجر واحد .","من حيل الشيطان أيضاً لإيقاع الإنسان : الخجل .",{"h":"٢٣ الخجـــل"},"الخجل فضيلة إن أحسن الإنسان استخدامها . ولكن الشيطان كثيراً ما يستخدم الخجل بطريقة تساعد على السقوط ...","كإنسان كان جالساً وسط أناس يتكلمون كلاماً رديئاً من الناحية الخلقية ، أو يتحدثون بالسوء فى سيرة إنسان له مكانته ويشهرون به ، أو يسردون قصصاً غير لائقة ... وهذا الإنسان البار الجالس وسطهم ، الذى لم يكن يتوقع كل هذا ، يفكر أن يتركهم وينسحب ... ولكن يأتيه شيطان الخجل ، ويرغمه على البقاء ... فيستمر جالساً ويمتلىء عقله بأفكار ما كان يحب مطلقاً أن تجول بذهنه .",{"h":"وعن طريق الخجل قد يوقع على تزكية لا يوافق عليها ضميره ."},"أو يوقع على أى بيان أو قرار ، هو فى داخله غير راض عليه ، أو يشترك فى مديح إنسان لا يستحق ذلك ... وإن حاول أن يمتنع يقف أمامه الخجل !",{"h":"وقد يجعل الشيطان فتاة تخجل من ملابسها المحتشمة ."}],"87":["وذلك إن كان التيار العام غير ذلك ... أو يجعلها تخجل من تدينها بوجه عام . تخجل من الصلاة ومن الصوم ، أو من معرفة ذلك عنها ... بل قد تخجل من تعليق صليب على صدرها . أو تخجل من رفض دعوة إلى حفل معين لا تستريح له روحياتها .","وبالمثل قد يخجل شاب متدين من رفض سيجارة تقدم له من زميل أو من أستاذ ... وكم من خطايا يقع فيها البعض بسبب شيطان الخجل !",{"h":"والمفروض أن يرفض المتدين هذا الخجل ويبعد عن مجالاته ."},"أو يجد له سبباً يخرج به من الإحراج بلباقة . أو أن يكون قوى الشخصية يستطيع أن يدافع عن موقفه الروحى بإقناع الآخرين ... أو على الأقل يبعد عن الصحبة التى تحرجه وعن المناسبات التى يتعرض فيها لحرب الخجل .","عجيب أن المتدينين يخجلون من تدينهم ، بينما الخاطئون تكون لهم جرأة وجسارة فى أخطائهم وفى انتقادهم للأعمال الروحية .","حرب أخرى من حروب الشيطان هى :",{"h":"٢٤ الوقـت الضـائـع"},"كما أن المؤمن قد يحارب أحياناً من شيطان الخجل ، كذلك يحاربه فى أحيان أخرى شيطان الوقت الضائع .",{"h":"حياة الإنسان هى وقت ، يحاول الشيطان أن يضيعه ."},"والوقت الضائع هو الوقت الذى يمر بك بلا أدنى فائدة : لا فائدة روحية ، ولا فائدة عقلية أو صحية ، ولا فائدة للآخرين .","لا يهم الشيطان أن يجعلك فيه ترتكب خطية ... بل يكفيه أن هذا الوقت يضيع ، كجزء من حياتك بلا ثمر لك أو لغيرك .",{"h":"والأمثلة كثيرة لهذا الضياع ، وهى متنوعة أيضاً ."},"منها أحاديث قد تطول بالساعات فى موضوعات لا فائدة منها ، وتكون بلا نتيجة . ومجادلات ومناقشات لا جدوى منها سوى تعب الأعصاب وضياع الوقت . وزيارات وسهرات ، وترفيهات زائدة عن الحد . ومسليات تأخذ كل الوقت وتعطل إيجابيات هامة"],"88":["فى حياتك . ومثل جلوس البعض فى المقاهى للعب والكلام ، وقتل الوقت .","إن الذى يقبل ضياع وقته ، تكون حياته رخيصة فى عينيه !",{"h":"٢٥ الشيطان يستخدم أعوانـاً"},"إنه لا يعمل وحده . فله أعوان من جنده الشياطين ، وأعوان من البشر أيضاً . وربما يكون هؤلاء من أحبائك أو أقربائك أو معارفك ، أو من الغرباء عنك .","لقد تكلم الشيطان على أفواه بعض الناس عند الصليب قائلاً للرب « إن كنت إبن الله ، إنزل من على الصليب » (متى ٢٧ : ٤٠) .",{"h":"وقد يستخدم أقرباءك كما قيل « أعداء الإنسان أهل بيته »"},"(متى ١٠ : ٣٦) .","فيوحى إلى أحد الأحباء إليك جداً بنصيحة تتلف حياتك . أو يجعلهم يقفون ضد عملك الروحى ، أو ضد تكريسك ، أو ضد عبادتك أو يستخدمهم للتهكم عليك ... فكن محترساً . وكل ما تسمعه من النصائح إفحصه جيداً ، وتمسك بالحسن (١تس ٥ : ٢١) . ولكن إحذر من أن تقول لأحد أقربائك (أنت من أعوان الشياطين) .",{"h":"وقد يكون أعوان الشيطان بالنسبة إليك صحبة شريرة ."},"وكما يقول الكتاب « المعاشرات الرديئة تفسد الأخلاق الجيدة » (١كو ١٥ : ٣٣) . لذلك ضع أمامك باستمرار المزمور الأول . فلا تسلك فى مشورة المنافقين ، وفى طريق الخطاة لا تقف ، وفى مجلس المستهزئين لا تجلس (مز ١) . إن كل هذه هى مجالس الشيطان ، هو يقودها ويدبرها ...",{"h":"لا تظن أن الشيطان يتراءى لك بروُى العين لكى يحاربك ."},"فهذه درجة عالية جداً من الحروب لا يسمح بها الله إلا للقديسين الذين يحتملونها . فإن أراد مثلاً أن يشيرك ، يرسل اليك من يشيرك . ويكون هذا الذى أثارك من أعوان الشيطان ، على الأقل فى هذه النقطة بالذات . وهكذا كل من يعثرك : كل من يقودك إلى الخطية ، أو يساعدك عليها ، أو يوقعك فيها ...",{"h":"والأشرار عموماً هم من أعوان الشياطين ."}],"89":["كل أجهزة العبث وكل مسببات العثرات . وكل الفلاسفة الملحدين وكل دعاة الإلحاد . وكل ناشرى الشكوك ... وكل مسببى الشر ... وعن هذا كان داود النبى ورجاله يصرخون قائلين : إبطل يارب مشورة أخيتوفل (٢صم ١٥ : ٣١) . وكانت مشورة ضارة جداً بداود ورجاله ، قدمها أخيتوفل لأبشالوم فى ثورته على أبيه داود ...","إن الشيطان إذا أراد مثلاً أن يوقع العالم فى البدع والشكوك ، فلا يعنى هذا بالضرورة أن يفعل هذا بنفسه ، إنما يقدم هذه البدع إلى العالم عن طريق أعوانه من البشر ، ينشرونها ويشرحونها للناس ، ويدعونهم إلى اعتناقها ..",{"h":"فعلينا أن نصلى كل حين ، أن ينجينا الرب من أعوان الشياطين ."},"وليس فقط من الشيطان وحده . بل من الشيطان وكل ملائكته وكل جنوده ، وكل أنصاره وأعوانه ، وكل منفذى مشيئته على الأرض ... كل قوات العدو ...",{"h":"ملاحظــــة :"},"أ - من جهة حروب المناظر المخيفة ، وحروب الرؤى والأحلام والضلالات الشيطانية ، فقد تحدثنا عنها فى الفصل الثانى الخاص بصفات الشيطان وحروبه ، تحت صفة (قاس) وصفة (كذاب) .",{"h":"ب - وهذه النقاط التى ذكرناها ليست هى كل حيل الشيطان ."},"ولا كل ما نعرفه عنها . فإن جعبة الشيطان لا تفرغ . وحيله لا تنتهى : القديمة والحديثة ، وما يمكن أن يخترعه الآن وفيا بعد . ولا شك أنه مجدد فى حيله ، رحمنا الله منه ومنها .","من أجل هذا ، نحن نصلى كل يوم فى تحليل الغروب :",{"h":"« نجنا من حيل المضاد . وإبطل سائر فخاخه المنصوبة لنا » آمين ."}],"90":[{"h":"الفصل الرابع"},{"h":"كيفية الإنتصار على حروب الشياطين"}],"91":["كل ما ذكرناه قبلاً من صفات الشيطان وتنوع حيله ، إنما كتبناه لكم ، لا لكى تخافوا منه ، إنما لكى تحترسوا منه . وعلى الرغم من عنف الشيطان ومكره ، إلا أن الإنتصار عليه ممكن جداً ، بل إنه سهل أيضاً .",{"h":"١ الإنتصـار ممكـن"},"إذا وضعت أمامك أن الإنتصار فى حروب الشياطين أمر صعب أو مستحيل ، ستخور قواك وتضعف وتستسلم ، وبالتالى ستسقط . أما أنت فإن حاربك الشيطان ، تأكد تماماً أنه فى إمكانك أن تنتصر ، وإلا ما كان الله يسمح بحرب غير متكافئة ...",{"h":"تأمل باستمرار فى سير القديسين الذين انتصروا ."},"ضع أمامك قصة يوسف الصديق الذى انتصر على الرغم صعوبة التجربة التى تعرض لها . أما داود وشمشون فى سقوطها ، فخذ درساً من قصة كل واحد منها . إعرف ما هى أسباب سقوطه وتحاشاها . إن كل قصة سقوط أعطيت لنا ، إنما لفائدتنا ، لكى نحترس ونتعلم ...",{"h":"الكتاب والتاريخ قدما لنا العديد من قصص الإنتصار ."},"نعرف أن التوبة ممكنة جداً ، مهما كانت الحالة سيئة ، وذلك من قصة توبة مريم القبطية ، وبيلاجية ، وبائيسة ، وأوغسطينوس ، وموسى الأسود . وكذلك توبة سليمان الحكيم ، وشمشون . لذلك إن حاربنا الشيطان باليأس من سوء ما وصلنا إليه نتذكر كل هذا لنتعزى ونتشجع .","ونعرف من قصة القديس الأنبا أنطونيوس ، كيف يمكن الإنتصار على الرغم من شدة الحروب وتنوعها وكثرتها . وكذلك من سير باقى القديسين ."],"92":[{"h":"كذلك علينا أن نتذكر باستمرار كيف أن الله بارك طبيعتنا ."},"إنه لما تجسد وأخذ هذه الطبيعة ، باركها . ولذلك نقول له فى القداس الغريغورى « وباركت طبيعتى فيك » . وأصبحت هذه الطبيعة قادرة جداً على قهر الشيطان . يكفى أننا صرنا هياكل للروح القدس ، وروح الله يسكن فينا (١كو ٣ : ١٦) . كما صرنا أبناء لله ، بطبيعة مولودة من فوق ، من الماء والروح (يو ٣ : ٣ ، ٥) .",{"h":"وكما نتذكر القوة التى أعطيت لنا ، نتذكر القوى الروحية المحيطة بنا ."},"نتذكر أننا لسنا وحدنا فى حرب الشيطان . فروح الله القدوس يعيننا ، ويبكتنا على خطية (يو ١٦ : ٨) ، ويعلمنا كل شىء (١يو ٢ : ٢٧) ، ويرشدنا إلى كل الحق (يو ١٦ : ١٣) . فكيف يمكن أن ينتصر الشيطان علينا ، ونحن لنا شركة الروح القدس (٢كو ١٣ : ١٤) . وكذلك نعمة ربنا يسوع المسيح معنا (١كو ١٦ : ٢٣) . ولذلك نحيا ، لا نحن ، بل المسيح الذى يحيا فينا (غل ٢ : ٢٠) ... يضاف إلى هذا ملائكة كثيرون محيطون بنا ، أرسلوا لخدمتنا لنرث الخلاص (عب ١ : ١٤) . كما أن سحابة من الشهود الذين انتصروا (من القديسين) محيطة بنا أيضاً « لنطرح كل ثقل والخطية المحيطة بنا بسهولة » (عب ١٢ : ١) .",{"h":"ولنتذكر أيضاً وعود الله لنا ، لكى نتشجع ..."},"إنه يقول « ها أنا معكم كل الأيام وإلى انقضاء الدهر » (متى ٢٨ : ٢٠) . « وإن كان الله معنا فمن علينا » (رو ٨ : ٣١) . إنه يقول لكل منا « لا أهملك ولا أتركك ... تشدد وتشجع . لا ترهب ولا ترتعب ، لأن الرب إلهك معك حيثما تذهب » (يش ١ : ٥ ، ٩) ، « أنا معك ، ولا يقع بك أحد ليؤذيك » (أع ١٨ : ١٠) .",{"h":"ولنتذكر وعود الله للغالبين ، لكى تحمسنا فى جهادنا ."},"لذلك إقرأ وعود الله مثلاً لرعاة الكنائس السبع التى فى آسيا « من يغلب فسأعطيه أن يجلس معى فى عرشى ، كما غلبت أنا أيضاً وجلست مع أبى فى عرشه » ، « وسيلبس ثياباً بيضاً ... وسأعترف بإسمه أمام أبى وأمام ملائكته » (رؤ"],"93":["٣ : ٢١ ، ٥) ، « سأعطيه أن يأكل من المن المخفى » ، « وأعطيه كوكب الصبح » ، « وأعطيه إكليل الحياة » (رؤ ٢ : ١٧ ، ٢٨ ، ١٠) ... حقاً من له أذنان للسمع فليسمع هذه الوعود التى تملأ القلب حماساً وقوة ...",{"h":"كذلك فلنثق تماماً أن الله هو الذى يحارب عنا ."},"فمهما كان الشيطان قوياً ، من هو أمام قوة الله التى لا تحد ؟ وإن كان الشيطان كأسد يزأر ، فإن الله يرسل ملاكه ليسد أفواه الأسود (دا ٦ : ٢٢) . حقاً « إن الحرب للرب » (١صم ١٧ : ٤٧) . هو « يقاتل عنكم وأنتم تصمتون » (خر ١٤ : ١٤) . مادام الرب هو الذى يقاتل عنكم ، إذن لا تخافوا مطلقاً من الشيطان .",{"h":"٢ لا تخـــافـــوا"},"لا تخافوا مطلقاً من الشيطان . فهو على الرغم من كل مواهبه وقوته وحيله ، كائن ضعيف أمام أولاد الله . قال عنه الرب :",{"h":"« رأيت الشيطان ساقطاً مثل البرق من السماء » (لو ١٠ : ١٨) ."},"لقد داسه الرب على الصليب ، ولم يعد « رئيس هذا العالم » كما كان . بل قال عنه الرب قبيل الصليب « الآن دينونة هذا العالم . الآن يُطرح رئيس هذا العالم خارجاً » (يو ١٢ : ٣١) ، « رئيس هذا العالم قد دين » (يو ١٦ : ١١) . لذلك قال الرب :",{"h":"« ها أنا أعطيكم سلطاناً لتدوسوا الحيات والعقارب وكل قوة العدو »"},"(لو ١٠ : ١٩) . إن وعد الرب لنا أن ندوس كل قوة العدو ، هو وعد كله قوة وعزاء ، ينزع الخوف من أى قلب ... ومن محبة الكنيسة لهذا الوعد الإلهى ، وضعته لنا فى آخر صلاة الشكر ، نذكره فى صلواتنا كل يوم بل كل ساعة ، حتى لا نخاف من الشيطان ولا من كل قوة العدو .",{"h":"إذن ليس للشيطان سلطان علينا ، بل لنا سلطان عليه ."},"حتى الشياطين تخضع لنا باسم الرب (لو ١٠ : ١٧) . بل جعل الرب إخراج"],"94":["الشياطين فى مقدمة الآيات التى تتبع المؤمنين (مر ١٦ : ١٧) . وطبعاً موهبة إخراج الشياطين لابد أن يسبقها الإنتصار أولاً فى حروب الشياطين . فالذى ينتصر على الشيطان فى تجاربه وإغراءاته ، ويجده الشيطان صلباً ، يبدأ أن يخافه . ويصير لهذا الإنسان سلطان عليه .",{"h":"هناك محاضرة جميلة للقديس أنطونيوس عن ضعف الشياطين ..."},"سجلها القديس أثناسيوس الرسولى فى كتابه عن حياة القديس أنطونيوس ، يمكن أن تقرأوها ، لكى تتقوى قلوبكم فلا تخافوا الشياطين .","وكم من رهبان بسطاء ، لم ينالوا من العلم كثيراً ولا قليلاً ، إستطاعوا أن يحطموا الشيطان فى البرية . ومنهم القديس بولس البسيط .","كذلك فإن الشهداء والمعترفين استطاعوا أن يحطموا جميع إغراءاته وكل قوته وأسلحته .",{"h":"والشيطان لا يسيطر إلا على الذى يخضع نفسه له ..."},"وعلى رأى المثل « إن العبيد هم الذين يخلقون السادة » ، أى أن ما فى العبيد من ذل وخضوع ، هو الذى يساعد السادة على السيطرة والتعالى . كذلك الحال مع الخاضعين للشيطان . أما الذين حررهم الإبن ، فبالحقيقة هم أحرار (يو ٨ : ٣٦) .",{"h":"أكثر شىء يحبه الشيطان ، أن يجعلك تخاف منه ."},"لأنك فى خوفك تضعف أمامه وتضطرب ، وتظن أنك لا بد واقع فى يديه ، فتخور معنوياتك ، وتستسلم له ، عاجزاً عن المقاومة ... وهذا عين ما يريده منك ، لأن الخوف يعطيه ساطة عليك . ولكن السيد المسيح نصحنا ألا نخاف مطلقاً ، بقوله :",{"h":"أنا هو . لا تخافوا . لا تضطرب قلوبكم ولا تجزع (متى ١٤ : ٢٧ ، يو ١٤ : ٢٧) ."},"لا تخف إذن . لأن قوة الله العاملة فيك ، هى أعظم بما لا يقاس من قوة الشيطان الذى يحاربك من الخارج . وثق أن خوفك فى داخلك هو أكثر ضرراً عليك من حرب الشيطان الخارجية .","إن الذين خافوا من جليات الجبار ، ضعفوا أمامه ولم يستطيعوا أن يقاوموه . أما داود الذى لم يخف ، فقد تقدم إليه بجسارة قلب ، معتمداً على معونة الرب ، وانتصر"],"95":["عليه . وقصة داود وجليات تصلح رمزاً لحروب الشياطين . ولعلك تسأل داود عن السر فى عدم خوفه فيقول :",{"h":"« الرب نورى وخلاصى ممن أخاف ؟! الرب عاضد حياتى ممن أرتعب ؟!"},"(مز ٢٧ : ١) ، ويستطرد « إن يحاربنى جيش فلن يخاف قلبى . وإن قام علىّ قتال ، ففى هذا أنا مطمئن » . لذلك أدخل حروب الشياطين بقلب مطمئن ، وحارب حروب الرب وأنت واثق أنك ستنتصر بمعونته . ما أصعب وما أخطر ما قيل فى سفر الرؤيا عن الخوف : « وأما الخائفون وغير المؤمنين والرجسون والقاتلون والزناة والسحرة وعبدة الأوثان وجميع الكذبة ، فنصيبهم فى البحيرة المتقدة بنار وكبريت » (رؤ ٢١ : ٨) .",{"h":"وهكذا وضع الخائفين قبل غير المؤمنين وقبل القتلة والزناة !"},"ولعلك تسأل لماذا ؟ ربما لأن الذى يخاف من الشيطان ويستسلم له ، يقع فى كل هذه الخطايا . أو لأن الذى يخاف من الشيطان ويخضع له ، يكون خائفاً فى اليوم الأخير ، لأنه لم يجاهد ويغلب مثل المؤمنين المختارين .",{"h":"ليتك تقرأ سير القديسين الذين لم يخافوا الشياطين ."},"إقرأ عن القديس الأنبا أنطونيوس الذى كانت الشياطين تظهر له على هيئة أسود ونمور ووحوش مفترسة ، تصيح بأصواتها المرعبة لتخيفه فيترك البرية ، ولكنه لم يخف ، وكان يجيبها بهدوء . أو إقرأ عن القديس مقاريوس الكبير الذى نام فى مقبرة ، وقد وضع جمجمة تحت رأسه . فكلّم الشياطين صاحبة هذه الجمجمة بصوت مسموع لكى تقوم معهم . فلم يضطرب القديس ، بل رفع رأسه قليلاً عن الجمجمة ، وقال لها « إن أردتِ ، قومى واذهبى معهم إلى الجحيم » ...","أما أنتم فلا تخافوا . لن تحاربكم الشياطين بهذه المخاوف التى حاربت بها القديسين . وهوذا الرسول يطمئنكم قائلاً :",{"h":"الله أمين ... لا يدعكم تجربون فوق ما تستطيعون (١كو ١٠ : ١٣) ."},"إن الله لا يسمح للشيطان أن يجربكم بما هو فوق احتمالكم « بل سيجعل مع التجربة المنفذ لتستطيعوا أن تحتملوا » (١كو ١٠ : ١٣) . لهذا لا تخافوا مطلقاً من الشياطين وحروبهم ، سواء كانت بمخاوف أو بخطايا . إن الشيطان قد يثير ضجة ليخيف ، ولكنه لا يستطيع أن يعمل شيئاً للمؤمن الصامد ."],"96":[{"h":"إنى أشبّه ضجيج الشيطان بقصة الثعلب والطبلة ."},"كانت هناك طبلة معلقة على شجرة ، تعصف بها الريح فتحدث صوتاً مهولاً . ومرّ عليها ثعلب وراءه هذا الصوت الضخم فخاف أولاً . ثم تجرأ وهجم عليها ، فرآها فارغة من الداخل ، فضحك واحتقرها . يشبه ذلك أيضاً البالونة الكبيرة التى تبدو ضخمة ، ولكن شكّة دبوس صغير ، تجعلها كلا شىء ...","هكذا الشيطان فى حروبه : ضجيج بلا قوة . يحاول أن يخيف ، ولكنه لا يملك قوة . والشيطان ليس كائناً مطلق الحرية يفعل ما يشاء .",{"h":"هناك الله ضابط الكل ، يمنع الشيطان حسبما يشاء ."},"وفى قصة أيوب الصديق ، ما كان الشيطان يتصرف حسب هواه ، بل إنه لا يحارب إلا فى النطاق الذى يسمح به الله (أى ١ ، ٢) .","إنه ليس قوياً بالشكل الذى تخافه . بل مجرد علامة الصليب فى إيمان ، تجعله يهرب من أمامك .",{"h":"يريد الشيطان أن يوهمك بأنه قوى . ولكن لا تصدقه ."},"وتذكر باستمرار إنهزاماته المتكررة فى قصص القديسين . وتذكر أولئك الذين كانت لهم قوة أن يخرجوه ممن صرعهم . وكيف كان يصيح فى خوف أمام أولاد الله ويهرب .","إن عرفتم ضعف الشيطان ، قاوموه فى شجاعة .",{"h":"٣ قـــاومـوه"},"ما أجمل أن نتذكر قول القديس يعقوب الرسول :",{"h":"« قاوموا إبليس ، فيهرب منكم » (يع ٤ : ٧) ."},"وهنا عبارة « يهرب منكم » تدل على ضعف الشيطان . فالرسول لم يقل قاوموه فيتركككم ، إنما قال قاوموه فيهرب منكم ...","إن الشيطان يجس نبض الإنسان ، ليعرف ما هو ممدنه . فإن وجده من النوع الذى يخاف ، يبدأ أن يتسلى به ويجعله لعبته . أما إن وجده قوياً ويقاوم ، ولا يقبل الهزيمة ، حينئذ يخافه الشيطان ويهرب منه ... لذلك قاوموه ولا تغركم قوته . فالقديس بطرس الرسول لما قال « إبليس خصمكم كأسد زائر يجول ملتمساً من يبتلعه هو » قال بعدها مباشرة :"],"97":[{"h":"« فقاوموه راسخين فى الإيمان » (١بط ٥ : ٩) ."},"أى أن زئيره كأسد لا يخيفكم ، بل قاوموه . ليكن لكم قلب أسد أقوى منه . إن تذكرتم أن الشيطان يزأر كأسد ، تذكروا قول دانيال « إلهى أرسل ملاكه فسد أفواه الأسود » (دا ٦ : ٢٢) . قفوا أمام الشيطان إذن فى قوة وصمود ، بكل مقاومة ...",{"h":"لا تستسلم ، بل اصمد فى الحرب ، كجندى صالح للمسيح ."},"حارب بكل قوتك ، واطلب معونة الرب . وهنا يعجبنى ما قيل فى سفر النشيد « تخت سليمان حوله ستون جباراً ... كلهم قابضون سيوفاً ومتعلمون الحرب . كل رجل سيفه على فخذه من هول الليل » (نش ٣ : ٨) . كن إذن متعلماً الحرب فى كل ما يثيره عليك الشيطان . وليكن سيفك على فخذك . بل كما يقول المرتل فى المزمور « تقلد سيفك على فخذك أيها الجبار ... إستله وانجح واملك » (مز ٤٥ : ٣ ، ٤) .",{"h":"إن حاربك الشيطان بفكر أو شعور ، لا تستسلم بل قاوم ."},"لا تقبل كل ما يعرضه عليك . لا تفتح له قلبك ، ولا تفتح له عقلك ، ولا تسلّم له إرادتك ، ولا تتساهل معه ، بل قاومه بكل عنف . قاوم كل أفكاره وكل إغراءاته وكل شهواته وكل تجاربه . واحذر أن تتراخى ، لئلا تسمع تأنيب الرسول :",{"h":"« لم تقاوموا بعد حتى الدم ، مجاهدين ضد الخطية » (عب ١٢ : ٤) ."},"حتى الدم ... حتى لو أدى الأمر أن تستشهد فى حربك ضده . كما يقال عن الضابط فى الجيش إنه « يحارب إلى آخر طلقة وآخر رجل » . وثق أنك لو فتحت للشيطان ولو ثقب إبرة فى فكرك أو فى إرادتك ، سيظل يتمادى ويوسع نطاقه حتى يتعبك . لذلك قاومه واطرده عنك . ومهما أراد أن يتفاهم معك فى شرح الخطية ، فلا تقبل .",{"h":"لا تفاهم مع الشيطان فى الخطية . ولا نقاش ولا جدال ."},"وكما قال أحد القديسين « لا تأخذ وتعطِ مع إنسان يقاتلك به العدو » . إن الشيطان عندما يعرض عليك الخطية ، إنما يريد أن يتفاهم معك فيها ، أى يريد بقاءك فى مجال الخطية أطول مدة لتتأثر بها . وفى هذا أنت الخاسر .",{"h":"لذلك قاومه من أول خطوة ، حينما تكون إرادتك فى يدك ."},"لأنك إن تأخرت فى مقاومته ، سيزداد تأثيره عليك ، وستقل إرادتك شيئاً فشيئاً ."],"98":["وكلما طالت المدة معه تضعف مقاومتك ، مثلما حدث لشمشون مع دليلة ، لأنه لما كثر إلحاحها عليه ضاقت نفسه وأخبرها بسره (قض ١٣ : ١٥ - ١٧) .",{"h":"لا تقل أنتظر على هذا الفكر حتى أعرف نهايته !"},"صدقنى ، أنت تعرف تماماً ما هى نهايته . فلا تخدع نفسك . مجرد فتح أبواب فكرك للشيطان هى خيانة للرب . لذلك إبعد كل البعد عن الشيطان وكل طرقه وكل جنده ، ولا تتساهل مع حيله ، ولا تتأخر . بل ارفضه بحزم وقل له « إذهب يا شيطان » (متى ٤ : ١٠) . فيعرف الشيطان أنك جاد فى رفضك له .",{"h":"وبرفضك الحازم لكل أفكاره ، تصير لك هيبة عند الشيطان ."},"الشيطان يدرك تماماً بذكائه ما هى المقاومة الجادة ، وما هو التمريج بين الفرقتين (١مل ١٨ : ٢١) . يعرف من هو الذى يرفضه بقلب نقى ، ومن هو الذى يرفض من الخارج بينها قلبه متجاوب مع الشيطان . نعم إن الشيطان يمكنه أن يستنتج من الذى سيقاومه حتى الموت ومن الذى إذا ضغط عليه قليلاً يستسلم . فقاوم بجدية ، وبكل قوة ، ومن قلبك .",{"h":"لست أحب أن يقول عنك الشيطان أنك إنسان طيب ."},"لا أريد أن يقول عنك : إنه إنسان طيب ، يثور علىّ جداً فى أول الأمر . ومع ذلك فإن قلبه أبيض سرعان ما يتصافى . ومع أنه يعارض كثيراً ، إلا أن الأمر ينتهى أخيراً بالموافقة والرضى ، مثل كل مرة ... !",{"h":"والمقاومة هى رفض الخطية بكل صورها ، ورفض التنازل عن الكمال ."},"والإصرار القلبى على السير فى الطريق الروحى ، ورفض كل مقترحات الشيطان ، بل ومراقبة كل أفكاره من بعيد ، وعدم التفاوض مع شىء منها ، بل طردها من أول وهلة . وغلق كل أبواب النفس والفكر والقلب أمامها . وعدم التساهل فى شىء ، بحجة أن هذا الأمر بسيط ، أو أن هذه العثرة لا تؤثر فىّ !","المقاومة لازمة ولكن كيف ؟ يقول الرسول : قاوموه راسخين فى الإيمان ."],"99":[{"h":"٤ بالإيمــــــان"},{"h":"أنت تغلب الشيطان بالإيمان . ولكن أى إيمان ؟ إنه :"},"الإيمان بعمل الله معك . الإيمان بأن الله يستطيع أن يبطل قوة العدو وكل فخاخه المنصوبة لنا . الإيمان بأن الله « لا يترك عصا الخطاة تستقر على نصيب الصديقين » (مز ١٢٥ : ٣) . الإيمان بأن الله أقوى من كل حيل العدو . وهو الذى يحارب عنا .","الحرب للرب (١صم ١٧ : ٤٧) ، الرب يقاتل عنكم وأنتم تصمتون (خر ١٤ : ١٤) .","تؤمن أن الحرب للرب . فلست أنت الذى تحارب الشيطان ، بل الله هو الذى يحاربه فيك ومعك . هو الذى يعطيك القوة التى تحارب بها ، والسلاح الذى تستخدمه ، وهو الذى يعطيك الخبرة فى مقاتلة الشياطين ، كما قال داود النبى :","« مبارك الرب ... الذى يعلم يدىّ القتال وأصابعى الحرب » (مز ١٤٤ : ١) .","فهل أنت أدخلت الله معك فى حروبك وفى تجاربك ومشاكلك ؟ إن كنت مهزوماً ، فربما لأنك لم تدخل الله معك . والله قادر تماماً أن يغلب بك ويتمجد فيك ، مهما كانت قوتك ضئيلة ومقاومتك لا شىء . فالكتاب يقول :","« ليس للرب مانع أن يخلص بالكثير أو بالقليل » (١صم ١٤ : ٦) .","إن حزقيا الملك لما وصله خطاب تهديد من ملك سنحاريب بجيشه الجبار ، وضع الخطاب أمام الله فى بيت الرب . وسكب نفسه أمام الله لكى يتصرف . وتدخل الله وأرسل ملاكه فضرب جيش سنحاريب (٢مل ١٩ : ٣٥) .",{"h":"ونلاحظ كيف أن داود النبى كان ينتصر بالإيمان فى حروبه ."},"إنه يقول « لولا أن الرب كان معنا حين قام الناس علينا ، لابتلعونا ونحن أحياء ... نجت أنفسنا مثل العصفور من فخ الصيادين ... عوننا من عند الرب الذى صنع السماء والأرض » (مز ١٢٤) ، « عيوننا إليك يارب ... إحفظنى من الفخ الذى نصبوه لى ومن شكوك فاعلى الإثم » (مز ١٤١ : ٩) ، « ... ضاع المهرب منى ، وليس من يسأل عن نفسى . فصرخت إليك يارب . وقلت أنت هو رجائى وحظى فى أرض الأحياء » (مز ١٤٢ : ٤ ، ٥) ."],"100":[{"h":"بهذا الإيمان إنتصر داود فى حروبه كما انتصر على جليات ."},"مهما كان عدوك قوياً ، آمن أن الله سيخلصك منه . رتّل مع داود النبى وقل : صوت الرب يقطع لهيب النار . صوت الرب يزلزل القفر » (مز ٢٩ : ٧ ، ٨) . وفى إيمان قوى ، قاوم الشيطان مردداً قول بولس الرسول :",{"h":"« أستطيع كل شىء فى المسيح الذى يقوينى » (فى ٤ : ١٣) ."},"وكن راسخاً فى هذا الإيمان ، واثقاً تماماً أن الله سيقف إلى جوارك وينصرك فى كل حروب الشيطان ، وأنه لن يتخلى عنك . وكما كان مع آبائنا وقادهم فى موكب نصرته ، سيكون معك أيضاً ، ولن يسمح أن يقع بك أحد ليؤذيك (أع ١٨ : ١٠) .",{"h":"هذا الإيمان سيعطيك قوة قلب فى الداخل ، وقوة على الشيطان فى الخارج ."},"ولذلك نرى أن الرسول حينما يتكلم عن قتالنا مع الشياطين يقول « أخيراً يا إخوتى ، تقووا فى الرب وفى شدة قوته . البسوا سلاح الله الكامل لكى تقدروا أن تثبتوا ضد مكايد إبليس » (أف ٦ : ١٠ ، ١١) .","إذن الأمر لا تصلح له قوتنا الشخصية ، بل « تقووا فى الرب » . ولا تصلح له أسلحتنا البشرية ، بل علينا أن نلبس سلاح الله الكامل . ونشعر بقوة الله العاملة معنا .",{"h":"وبهذه القوة ، لا تكون لنا روح الفشل ولا روح الإستسلام ."},"ولا تكون لنا روح التخاذل ، ولا روح اليأس ، لأن الله الذى نعتمد عليه قادر أن يحمينا فى كل حروب الشياطين . بهذه القوة استطاع القديس بولس الرسول أن يقول « حاربت وحوشاً فى أفسس » (١كو ١٥ : ٣٢) . وبهذه القوة إستطاع أن يقول « إن الله لم يعطنا روح الفشل بل روح القوة » (٢تى ١ : ٧) . لذلك أولاد الله لا يضعفون أبداً فى حروبهم .",{"h":"إنهم جبابرة بأس ، لا يقوى عليهم الشيطان ولا الخطية ."},"ما أجمل التقرير الذى كتبه القديس يوحنا الرسول عن أولاد الله « كل من وُلد من الله لا يخطىء ، بل المولود من الله يحفظ نفسه ، والشرير لا يمسه » (١يو ٥ : ١٨) . كلهم لهم روح الغلبة ونيل المواعيد كما شرح الرب فى سفر الرؤيا (رؤ ٢ ، ٣) .","أنظروا إلى أيوب الصديق وشهادة الرب عنه « ليس مثله فى الأرض ، إنه رجل كامل ومستقيم ، يتقى الله ويحيد عن الشر . وإلى الآن هو متمسك بكماله » (أى ٢ :"],"101":["٣) . هل مثل هذا يقدر عليه الشيطان ؟! كلا ، بل إن الله تحدى به الشيطان .",{"h":"دائماً فى الحرب ضع أمامك الإنتصار وليس الفشل ."},"قل : أنا لا يمكن أن أفشل ، مادمت ألجأ إلى الله ، وهو يحارب عنى . أنا لا أخاف الشيطان ، بل أقول للرب « إن سرت فى وادى ظل الموت ، لا أخاف شراً ، لأنك أنت معى » (مز ٢٣) . إننى فى يمين الرب ، نقشنى على كفه (أش ٤٩ : ١٦) . وقال عن خرافه « أنا أعطيها حياة أبدية ، ولن تهلك إلى الأبد ، ولا يخطفها أحد من يدى ... ولا يقدر أحد أن يخطف من يد أبى » (يو ١٠ : ٢٨ ، ٢٩) .","بهذا الإيمان يمكن أن تنتصر . كذلك تنتصر بالإتضاع .",{"h":"٥ بالإتضــــــاع"},"كان القديس الأنبا أنطونيوس يغلب الشياطين بالإتضاع :","فحينما كانوا يتكاثرون عليه ، كان يقول لهم باتضاع « أيها الأقوياء ، ماذا تريدون منى أنا الضعيف ؟! » وكان يصلى قائلاً « إنقذنى يارب من هؤلاء الذين يظنون أننى شىء ، مع أنى أضعف من أن أقاتل أصغرهم » . ولما كان الشياطين يسمعونه وهو يصلى هذه الصلاة المملوءة اتضاعاً ، ما كانوا يحتملون ، بل كانوا ينقشعون كالدخان .",{"h":"والقديس مقاريوس الكبير كان يغلب الشيطان أيضاً بالإتضاع ."},"فى إحدى المرات ظهر الشيطان للقديس مقاريوس وقال له « ويلاه منك يا مقاره ! أى شىء أنت تعمله ونحن لا نعمله ؟! أنت تصوم ونحن لا نأكل . أنت تسهر ونحن لا ننام . أنت تسكن البرارى والقفار ونحن كذلك . ولكن بشىء واحد تغلبنا » فسأله القديس ما هو؟ فأجاب : باتضاعك تغلبنا .",{"h":"الإتضاع يغلب الشيطان لأسباب كثيرة منها :"},"أولاً : لأن الشيطان غير متضع . والإتضاع يذكره بكبريائه التى أسقطته .","ثانياً : لأن الإتضاع يذكره بصورة المسيح الذى أخلى ذاته وأخذ شكل العبد ، لكى يخلص البشرية . ومجرد هذه الذكرى تتعبه ، فيذهب ."],"102":["ثالثاً : لأن المتضع إذ هو معترف بضعفه يستعين بقوة الله لتعينه فى حروب الشيطان . وهذا أخوف ما يخافه الشيطان .","ولهذا كتبت مرة فى مذكرتى العبارة الآتية :",{"h":"قال الشيطان لله : أترك لى الأقوياء فإننى كفيل بهم . أما الضعفاء فإننى لا أقوى عليهم . فإذ يرون أنه ليست لهم قوة ، يحاربونى بقوتك ."},{"h":"إن قصة أنبا صرابامون أبى طرحه تثبت إخراج الشياطين بالإتضاع ."},"كانت زهرة إبنة الحاكم عليها شيطان ، فجاءوا إلى البابا ليصلى عليها ليخرج . فقال لهم البابا فى اتضاع « أنا ليست لى هذه الموهبة . إذهبوا إلى الأنبا صرابامون أبى طرحه » . فذهبوا إليه . فقال لهم فى اتضاع « صلاتى لأجلها لا تكفى » . وطلب صليب البابا ليرشمها به ، قائلاً إنه « ببركة هذا الصليب تشفى » . وكان يريد بهذا أن ينسب شفاءها إلى البابا وليس إلى نفسه . وهكذا شفيت ، لأن الشيطان لم يحتمل هذا الإتضاع .","تحدثنا عن أهمية الإتضاع فى حروب الشياطين ، مع بعض قصص من سير القديسين . وبقى أن نعرض لسؤال هام وهو :",{"h":"ما هو الأثر العملى للإتضاع للإنتصار فى حروب الشياطين ؟"},"١ - المتضع يعترف دائماً بضعفه ويطلب من الله المعونة فتأتيه بقوتها . وهكذا ينتصر لأنه لم يعتمد على ذراعه البشرى ، بل على معونة الله .","٢ - المتضع يحترس من أقل الخطايا ، ويخاف السقوط فيبعد عن جميع العثرات . وبالتالى لا يلقى نفسه فى تجربة ولا يتهاون ، وبهذا الحرص الناتج عن الإتضاع ينتصر على الشيطان .","٣ - المتضع يكشف حروبه وضعفاته . فيمكن علاجها . وبهذا ينتصر .","٤ - المتضع دائماً يصلى . بل إن أصغر خطية يجعلها موضوعاً لصلاته . وهكذا يُدخل الله معه فى حروبه . وبهذا ينتصر .","٥ - نفس الإتضاع : فضيلة لا يحتملها الشياطين فيهربون .","وكما ينتصر الإنسان على الشياطين بالإتضاع ، ينتصر أيضاً بالحكمة والإفراز ."],"103":[{"h":"٦ بالحكمة والإفـراز"},"إن أتاك فكر ، لا بد أن تفحصه جيداً : هل هو من حروب الشياطين ؟ وأين الحق فيه ، وأين الباطل ؟ وهكذا تفعل مع الرؤى والأحلام ، ومع نصائح الآخرين ... ومع كل ضلالات الشياطين ... ومن أجل هذه المعرفة أو التمييز أو الإفراز ، ينبهنا الرسول بقوله « لا تصدقوا كل روح . بل امتحنوا الأرواح هل هى من الله ؟ ... » (١يو ٤ : ١) .",{"h":"فما هى مصادر الحكمة هذه والمعرفة والإفراز ؟"},"هناك إنسان حكيم بطبيعته . خلقه الله هكذا ، ومنحه الذكاء والحكمة والمعرفة ، ويستطيع أن يكتشف حرب الشيطان ويميزها ، ويفرزها عن الفكر الروحى . وهناك من يقتنى الحكمة عن طريق القراءة فى الكتاب المقدس وفى الكتب الروحية وسير القديسين . ونوع ثالث يقتنى الحكمة بالخبرة . وفى كل سقوط يأخذ درساً ويعرف حيلة العدو ، فلا يسقط مرة أخرى . وفى ذلك قال أحد القديسين :",{"h":"لا أتذكر أن الشياطين أطفوني فى خطية واحدة مرتين ."},"وقد يقتنى الإنسان الحكمة عن طريق المشورة والإسترشاد والتعلم .","وإذ يميز حرب الشيطان ويكشفها ، يبعد عنها ، فلا يخدعه العدو .","نقول هذا عن الذى يريد أن ينتصر . لأن هناك إنساناً يعرف أن هذه حرب من حروب العدو ، ومع ذلك يستمر فيها لأسباب داخل نفسه ، أو لإنحراف ، أو لأنه غير قادر على المقاومة ...",{"h":"والحكمة كما تكشف حيل الشياطين ، تعطى أيضاً وسيلة للتصرف ."},"فالإنسان الحكيم يعرف كيف يفلت من حيل الشيطان : كيف يهرب من فخاخه ، وكيف يقوم إذا سقط . وكيف يبعد عن كل سبل الخطية .","وإذا لم يعرف ، تدعوه الحكمة أن يستشير ..."],"104":[{"h":"٧ بالمشـــورة والإعتـراف"},{"h":"الإرشاد الروحى يكشف حيل الشياطين ، ويشرح كيفية النجاة منها ."},"كما أن المرشد يصلى من أجل النفس التى تكشف أفكارها لتنجو . وفى هذا قال القديس بولس الرسول « أطيعوا مرشديكم واخضعوا . لأنهم يسهرون لأجل نفوسكم كأنهم سوف يعطون حساباً ... لكى يفعلوا ذلك بفرح ... » (عب ١٣ : ١٧) . ولهذا فإن الذى يسلك فى الطريق الروحى بهواه ، يمكن أن يسقط فى فخاخ الشياطين . وقد قيل :",{"h":"الذين بلا مرشد يسقطون مثل أوراق الشجر ."},"من أجل هذا كانت أهمية أب الإعتراف فى الكنيسة . تكشف له ما فى قلبك وتخجل وتنسحق نفسك أمام الله فى حضرته . ويرشدك إلى ما ينبغى أن تفعله . والإعتراف يكشف حروباً ربما المبتدئون لا ينتبهون لها .",{"h":"وكثير من الخطايا يخلص منها المعترف بسبب فضيلة الإعتراف ."},"شياطينها لا تحتمل إنسحاق المعترف فى مذلة فتهرب . كما أن الشياطين تحب أن تعمل فى الظلمة ، والإعتراف يكشفها . كذلك الإرشاد يكسر فخاخها . والتحليل يضيع تعبها . وهكذا نرى أن الإنسان المعترف بخطاياه والمطيع للإرشاد ، يسلك فى طريق التوبة ، وينجو من حروب الشياطين . وحتى إن لم تتركه الخطية تماماً ، فإن قوتها تضعف فى مهاجمته .",{"h":"لهذا يحاول الشيطان أن يمنع الإعتراف . ويشكك فى أب الإعتراف ."},"يدخل هنا شيطان الخجل ليمنع الإعتراف . ويدخل شيطان الشهوة ليقول « ما الفائدة إن كنت سأعود إليك ؟! » . ويدخل شيطان الفكر والجدل ليناقش موضوع الإعتراف جملة . ويدخل شيطان الشك ليشككك فى الإعتراف وأب الإعتراف .","أما أنت فكن ثابتاً . واعترف بكل هذا أيضاً . فلا يجد الشيطان حيلة فيك ، ويعتبرك خصماً متعباً ، فيتركك ..."],"105":[{"h":"٨ بالسـهــر والحـرص"},"لا يكفى أن تعترف وتكشف نفسك وتطلب الإرشاد ، إنما ينبغى أن تكون ساهراً على خلاص نفسك (*) . وهوذا الرسول يقول :",{"h":"إصحوا واسهروا ، لأن إبليس خصمكم مثل أسد زائر ... » (١بط ٥ : ٨) ."},"إسهروا لأن عدوكم متيقظ وقوى ، لئلا يأخذكم فى ساعة غفلة أو تهاون أو تراخ ، أو فى ساعة فتور ، أو فى حالة نسيان لواجباتكم الروحية وعدم اهتمام بخلاصكم .",{"h":"والكنيسة توجد لنا مناسبات عديدة تنادينا أن نتيقظ :"},"هناك أصوام تقول لنا إصحوا واستعدوا . وهناك قداسات تقول لنا تعالوا تناولوا باستحقاق . وعظات وقراءات واجتماعات كلها تنادينا أن نهتم بأبديتنا ، ونحارب حروب الرب بكل اهتمام . لذلك علينا أن نتيقظ لأن الكنيسة تدعونا أن نقول للرب فى بدء صلاة نصف الليل « إنزع من عقولنا نوم الغفلة ، وأعطنا يارب يقظة ... » .",{"h":"الشيطان يحب أن يكون (فريسته) متهاوناً ليسهل القضاء عليه ."},"إن المتهاون فى واجباته الروحية من السهل أن يسقط ، إذ لا يكون محصناً باستعداد روحى ، ولا بالمشاعر الروحية التى تغرسها وسائط النعمة فى القلب . لذلك فى بعض الأوقات إذا أراد الشيطان إسقاط إنسان ، يبدأ معه بسلاح التهاون ، فيكسل فى صلواته وقراءاته واجتماعاته الروحية واعترافه وتناوله . وإذ لا يكون منتبهاً لنفسه يضربه الشيطان فيسقط .","أما المهتم بواجباته الروحية ، فإن الله يكون دائماً أمام عينيه ، فيستحى من السقوط ، كما أن الله يعينه فى حروبه .",{"h":"هناك نوع لا يصحو لنفسه إلا بعد السقوط ."},"مثال ذلك الإبن الضال ، الذى لم يستيقظ إلا بعد الضياع والإستمرار فيه مدة . وكذلك داود النبى حينما سقط لم يكن صاحياً لنفسه . إنما صحا حينما قال له ناثان « أنت هو الرجل » ! وكذلك سليمان الحكيم لم يكن فى حكمته حينما سقط . ولم يشعر أن الكل باطل وقبض الريح ، إلا بعد أن أغوته النساء ... !","(*) إقرأ كتابنا [ السهر الروحى ] ليشرح لك هذا الموضوع بالتفصيل ."],"106":[{"h":"أما أنت فمادام عدوك يزأر ، إعلن حالة التعبئة العامة ."},"قل للشيطان قف عند الحدود لا تتعداها . وجهز أنت كل أسلحتك من صوم وصلاة ، وسهر ويقظة قلب ، وتوبة واحتراس ، وتمسك بالرب . وكن متنبهاً لكل حركة من العدو ، لكل رغبة ، لكل فكر ، لكل حركة من الحواس . وكما يقول الرسول « مستأسرين كل فكر لطاعة المسيح » (٢كو ١٠ : ٥) .","وفى سهرك الروحى ، إستمع إلى قول الرسول :",{"h":"« إلبسوا سلاح الله الكامل ، لكى تقدروا أن تثبتوا ضد مكايد إبليس »"},"(أف ٦ : ١١) . كن ساهراً « وسيفك على فخذك من هول الليل » (نش ٣ : ٨) . نقصد سيف الروح ، ودرع البر ، وترس الإيمان (أف ٦) ، وكل الوسائط الروحية .",{"h":"وهذا الإحتراس ، أو هذا الإستعداد ، يكون معك مدى الحياة ."},"إحترس حتى الموت . وكن صاحياً إلى آخر لحظة « لئلا يأتى بغتة فيجدك نائماً » (مر ١٣ : ٣٦) . السيد المسيح حورب حتى وهو على الصليب ، حين قيل له « إن كنت إبن الله إنزل من على الصليب » ... فكن إذن مستعداً باستمرار . ولا تقل قد كبرت ، أو قد خلصت !",{"h":"واحترس من الشيطان الذى يحارب باللاهوتيات ."},"لئلا تقول « إرحمنى يارب » ، فيأتيك الشيطان وينهرك قائلاً : لا تقل إرحمنى مطلقاً . فقد رحمك الرب منذ زمان حينما فداك على الصليب وخلصك . إذن ما معنى كلمة « إرحمنى » هذه ؟! إنها هرطقة ! قل له : لقد رحمنى الرب وخلص نفسى . ولكننى لا أرحم نفسى ، بل كل يوم أضيع خلاصها ، لذلك أصرخ وأقول : إرحمنى . إسهر إذن على خلاص نفسك .",{"h":"وفى سهرك أسلك بكل جدية وبكل تدقيق ."},"وكن أميناً جداً حتى فى القليل . فإن أمانتك وتدقيقك وجديتك ، تجعل الشيطان يهرب منك ، شاعراً أن حربه معك هى حرب خاسرة .","وهناك سلاح هام للإنتصار ، وهو أهم سلاح ، أعنى الصلاة ."],"107":[{"h":"٩ بالصـــلاة والصــوم"},"لما عجز التلاميذ عن إخراج شيطان ، قال لهم الرب :",{"h":"هذا الجنس لا يخرج بشىء ، إلا بالصلاة والصوم (مر ٩ : ٢٩) ."},"وهكذا نرى أهمية الصلاة والصوم فى الإنتصار على حروب الشياطين ، أو بمعنى آخر أهمية إدخال الله فى حياتنا وحروبنا ، صارخين إلى الله وقائلين « نجنا من حيل المضاد ، وإبطل سائر فخاخه المنصوبة لنا » .",{"h":"إننا نفشل فى حروبنا إن واجهنا الشيطان وحدنا ، بدون الله ."},"إنما نحن نقول لله : عدونا هذا القوى الذى يجول كأسد يزأر ، عدونا هذا الماكر الواسع الحيلة ، نحن يارب لا نقدر عليه بمهارتنا وذكائنا ، إنما النجاة هى من عندك أنت . نحن على قدر إمكاننا نميز الأرواح ، ونعرف الفكر الذى من عنده ونحترس منه . ولكن القوة تأتى من عندك .",{"h":"بقدر إمكاننا نجاهد . ولكن أنت الذى تقودنا فى موكب نصرتك ."},"فى كل خطية كبيرة أو صغيرة ، لا نريد أن نقف وحدنا تجاه الشيطان ، إنما لابد أن يقف الله معنا . ولذلك نقول له فى بدء صلاة باكر « نسألك أن تحفظنا فى هذا اليوم بغير خطية » ، ونقول له فى ختام هذه الصلاة « هب لنا فى هذا اليوم الحاضر أن نرضيك فيه ، واحرسنا من كل شىء ردىء ، من كل خطية ، ومن كل قوة مضادة » ، « أحطنا بملائكتك القديسين ، لكى نكون بمعسكرهم محفوظين ومرشدين » ...",{"h":"والمفروض أن نطلب معونة الله من أول الطريق ."},"كثيرون لا يلجأون إلى الله إلا بعد أن تضيق بهم السبل جداً ، كالذى لا يلجأ إلى الطبيب إلا بعد أن يشتد عليه المرض ويصل إلى حالة سيئة للغاية . أما نحن ، فإن الكنيسة تعلمنا أن نصلى من أجل النجاة قبل أن تأتى الحروب ...",{"h":"وهكذا تكون صلاة وقائية ، قبل اللجوء إلى الصلاة العلاجية ."},"إننا نطلب من الله أن يبطل كل فخاخ الشيطان المنصوبة لنا . ولا ننتظر حتى نقع فى تلك الفخاخ ، ثم نطلب من الله أن يخرجنا منها ! وهكذا فى صلاة الشكر نطلب من"],"108":["الله أن يبعد عنا « كل تجربة ، وكل فعل الشيطان ... وقيام الأعداء الخفيين والظاهرين » ... يبعدها عنا قبل أن تجىء ... « ولا يدخلنا فى تجربة » .",{"h":"نحن لا نضطرب أمام حروب العدو ، إنما نطلب معونة الله ."},"هذا الشيطان الذى له خبرة ٧٠٠٠ سنة فى محاربة البشر ، أنا لا أقدر عليه . أما أنت يارب فأزلى ، كائن قبل أن يكون هذا الشيطان . وهو صنعة يديك من قبل أن يسقط . وتعرف كل حيله . وتستطيع أن تربطه وتقيده وتضع له حدوداً ، بل وتطرده طرداً . لذلك نجنى منه .","هكذا إلجأ إلى الصلاة . لأنك بدونها لا تخلص .",{"h":"وإن فشلت فى محاربة العدو ، إعرف أنك فاشل فى صلواتك ."},"ولو كانت لك صلاة قوية ، لانتصرت حتماً . وتأكد أن الله إن سمع صراخ المساكين ، لابد أن يستجيب . إنه نفسه يقول « من أجل صراخ المساكين وتنهد البائسين ، الآن أقوم - يقول الرب - أصنع الخلاص علانية » (مز ١٢ : ٥) . لذلك قل له : « قم أيها الرب الإله ، وليتبدد جميع أعدائك ، وليهرب من قدام وجهك كل مبغضى إسمك القدوس » (عد ١٠ : ٣٥) . قم يارب « فإن البار قد فنى ، وقلت الأمانة من بنى البشر » (مز ١٢ : ١) . قم إصنع الخلاص علانية « إستل سيفك على فخذك أيها الجبار . إستله وانجح واملك » (مز ٤٥ : ٣ ، ٤) .",{"h":"إن الشياطين هم أعداؤك يارب ، قبل أن يكونوا أعدائى ."},"إنهم يحاربون ملكوتك فىّ وفى غيرى ، فحاربهم عنى وعن الجميع . ولا تتركنا وحدنا فى حروب الشياطين ، لأننا بدونك لا نستطيع أن نفعل شيئاً (يو ١٥ : ٥) .","إن داود الذى اختبر نصرة الرب فى حروبه قال فى المزمور :",{"h":"« يمين الرب صنعت قوة . يمين الرب رفعتنى » (مز ١١٨ : ٥ ، ٦) ."},"فهل جربت يمين الرب فى حياتك ؟ هل جربت خلاص الرب ، الذى قال عنه موسى النبى « قفوا وانظروا خلاص الرب ... الرب يقاتل عنكم وأنتم تصمتون » (خر ١٤ : ١٣ ، ١٤) . لو أنك اختبرت هذا ، لاستطعت أن تقول مع داود النبى « الرب لى معين وأنا أرى بأعدائى » (مز ١١٨) ، « يسقط عن يسارك ألوف ، وعن يمينك ربوات ، وإليك لا يقتربون » (مز ٩١ : ٧) ."],"109":["إنك جربت تفكيرك وذكاءك وعزيمتك وتدبيرك ، ومعونات الناس لك ، ولكن هل جربت خلاص الرب ؟ هل جربت مفعول الصلاة القوية الممسكة بقرون المذبح ؟ ليتك تفعل ... لا تكن كإنسان يقول للرب :",{"h":"أتركنى يارب أن أعمل . وإن وقعت ولم أقدر أن أقوم ، سأطلبك ."},"ولماذا تنتظر إلى أن تقع ولا تقدر أن تقوم . أطلبه من الآن ، تجد قوته إلى جوارك لكى لا تقع . طبعاً إن وقعت وطلبت الله سيقيمك ، لكنك ستقوم وأنت مجروح ومكسور ! إلجأ إلى اليد الحصينة التى تحميك ، واصرخ إلى الرب قائلاً « نجنا من حيل المضاد ، وإبطل سائر فخاخه المنصوبة لنا » ، وحينئذ يتدخل الله لإنقاذك . وحينئذ تغنى مع المرتل :",{"h":"« الفخ انكسر ونحن نجونا . عوننا من عند الرب الذى صنع السماء والأرض »"},"(مز ١٢٤ : ٧ ، ٨) . أطلب من الرب إذن أن ينصرك كما نصر المجاهدين قبلك ، وأن يعطيك قوة كما أعطاهم ، وأن يعطيك نعمته وفعل روحه القدوس ، لكى تكون محصناً بقوته الإلهية ... واطلب إليه أن ينتهر الشيطان كما انتهره من قبل ، ويقول له « إذهب يا شيطان » (متى ٤ : ١٠) .",{"h":"١٠ إذهـب يـا شيـطـان"},"عبارة (إذهب يا شيطان) التى بها إنتهر الرب الشيطان ، لم تكن للتجربة على الجبل فقط ، إنما أيضاً لكل حروب الشيطان مع البشر ...","فليتك تختبر قوة هذه العبارة فى حياتك ، حينما يتدخل الرب ويطرد الشيطان ، فلا يشتد فى حربه عليك ، أو على الأقل يفعل كما فعل فى التجربة على الجبل ويتركك إلى حين (لو ٤ : ١٣) .","فإن وجدت أن الحرب قد رفعت عنك ، ووجدت أن الأفكار والشهوات لا تتعبك كما كان يحدث قبلاً . وإن فارقك الفتور وأشرق عليك نور جديد ، فاعرف أن الرب قد انتهر الشيطان وطرده ... ليذهب بعيداً عنك .",{"h":"إن الله لا يسمح أن نكون محاربين باستمرار من الشيطان ."},"ولا يسمح أن يمسكنا الشيطان بقبضته . وإن كان الله يترك الشيطان أحياناً"],"110":["ليجربنا ، فذلك لكى ننال الفوائد الروحية التى فى هذه الحروب . وعندما يضغطنا الشيطان باليأس أو بالإضطراب ، ينتهره الله قائلاً : إذهب يا شيطان .",{"h":"قد تمر على الإنسان أوقات راحة من حروب الشياطين ."},"ويجد نفسه طليقاً فى مجال الله ، فرحاً بعشرته ، بل يتعجب كيف كان يخطىء قبلاً ويسقط . وفى وسط هذا الجو الروحى والجو المريح ، يشعر أن المسيح له المجد الذى جرب حروب الشياطين ، قد انتهر الشيطان من أجله ... وكأنه يقول للشيطان : أنا قد أعطيتك حرية التجربة والإختبار ، ولكن ليس إلى هذا الحد . فاذهب يا شيطان ...",{"h":"صدقونى يا إخوتى إن الخطايا التى نقع فيها هى شىء قليل من حروب الشياطين التى كان يمكن أن تضغط علينا بعنف . ولكن الله منعها عنا قبل أن تصل إلينا . ولم يسمح للشيطان أن يجربنا بها . أما الحروب التى سمح الله بها ، فهى التى تقدر أن تقاومها . ولو سمح بالأخرى ما كنت تحتمل ..."},"وقد تتعرض أحياناً لحرب قاسية ، وتكون على وشك السقوط ...",{"h":"ثم تجد أنك نجوت من هذه الحرب بدون أن تشعر ."},"وذلك لأن الله قد تدخل . وقال للشيطان إذهب ... إنك ضغطت على هذا الإنسان بعنف ... ويذكرنا هذا بأن الله كان يضع للشيطان حدوداً فى حربه مع أيوب الصديق : مرة لا يمد يده إليه (أى ١ : ١٢) ، ومرة لا يمد يده إلى نفسه (أى ٢ : ٦) .",{"h":"إن عبارة « إذهب يا شيطان » فيها عزاء كبير لنا ."},"تشعرنا أن حروب الشيطان محدودة ، وأنه ليست له حرية مطلقة حتى يفعل بنا ما يشاء . وأيضاً بأن الشيطان هو أيضاً تحت قبضة ضابط الكل ، القادر أن ينتهره حينما يشاء ، ويمنعه ويضع له حدوداً وسدوداً وقيوداً ... بل ويطرده . فلنطمئن إذن أن الحروب التى نتعرض لها هى فى حدود قوتنا وطاقتنا ومقاومتنا ، وأنه بإمكاننا أن ننتصر عليها ، إن أردنا .","إن الله أعطانا سلطاناً على الشيطان ، نقول له إذهب فيذهب .",{"h":"ولكننا فى أحيان كثيرة لا نشاء أن نقول له : إذهب ."},"أحياناً نتراخى فى حربه ، ونعطيه فرصة فينا ومجالاً . وأحياناً نرضخ ونتراخى"],"111":["ونؤجل طرده . وأحياناً نفاوضه ونهادنه ولا نكون حازمين معه . بل أحياناً نستسلم له ، أو نتعاون معه ... ولا نشاء مطلقاً أن نقول له : إذهب ...",{"h":"بل أخشى أن البعض يفتح له قلبه وحواسه ، ويرحب به !"},"كثيرون لا يستطيعون أن يطردوا الشيطان بكلمة إذهب يا شيطان . لأن بينهم وبين الشيطان صداقات ومحبة وعشرة . وهناك قيود تربطهم به وتخضعهم لإرادته . بل لو انتهره الرب وذهب عنهم ، قد يسعون هم إليه ، ويتوسلون إليه قائلين : إرجع إلينا وأعنا ... ! هم لا يريدون أن يبتعد الشيطان عنهم !","إن القلب النقى هو الذى يستطيع أن ينتهر الشيطان ويقول له : إذهب . ويفرح بانتهار الرب له . ولكن البعض له حاجة عند الشيطان يستبقيه من أجلها ، بل ويدافع عنه ! تماماً مثلما فعل أهل أفسس فى دفاعهم عن آلهتهم أرطاميس وتمثالها (أع ١٩ : ٢٨) . لذلك فإن الرب كان أحياناً - قبل أن يشفى إنساناً - يسأله أولاً : أتريد أن تبرأ (يو ٥ : ٦) .",{"h":"فإن شاء الرب أن يطرد الشيطان عنك ، إستجب له ..."},"فلتتحد إرادتك مع إرادة الله فى طرد الشيطان من حياتك ، مهما كان ذلك سيكلفك ، ومهما (أتعبك) ذهاب الشيطان بعيداً عنك . لأن الكتاب يقول « أمينة هى جراح المحب . وغاشة هى قبلات العدو » (أم ٢٧ : ٦) . فقد يقبّلك الشيطان متظاهراً بالحب ، موهماً إياك أنه يسعدك ويحقق شهواتك ورغباتك ، لكى لا تطرده من حياتك ، بينما هو يعدّ لك فخاخاً لهلاكك ! فلا تصدقه .","أدخل إلى أعماق قلبك وفكرك ، وقل : إذهب يا شيطان .","وحينما ينتهر الرب هذا الشيطان ، إنتهره معه بكل صدق وبكل حزم وحسم ، مع إلغاء كل ما سبق من علاقات بينك وبينه . ولا تحاول أن تجمع بين الله والشيطان فى حياتك . لأنه « لا شركة بين النور والظلمة » (٢كو ٦ : ١٤) .","لا تصادق عدواً لله ، ولا تشترك معه فى أى عمل . واطرد كل متعلقاته فى حياتك وفى بيتك وفى مكتبتك . كل صوره ، وكل كتبه ومجلاته ، وكل ملاهيه وأغانيه وقصصه ، وكل أجهزته ، وكل أعوانه . قل له : إذهب يا شيطان ، ومعك كل ما ينتمى إليك . واقفل أمامه جميع الأبواب حتى لا يعود إليك ."],"112":[{"h":"وليكن طرداً ، بكل جدية ، طرداً نهائياً ، بتصميم ..."},"لا طرداً متذبذباً ، متردداً ، قلقاً ... كما يقول المثل العامى « عين فى الجنة ، وعين فى النار » ! وتأكد تماماً أن بقاء الشيطان بكل حيله ، خسارة لك . واحترس من أن تقبل ربحاً عن طريقه - لأن هذا (الربح) يكون ثمناً لحياتك وأبديتك ...","ومن الوسائل التى تساعدك فى طرد الشيطان :",{"h":"١١ مقـابـلـة الخطيـة بالوصـيـة"},{"h":"إحفظ عدداً من الآيات فى مواجهة الخطايا التى تحاربك ."},"فمثلاً إن حاربك الشيطان بالغضب قل له « إن غضب الإنسان لا يصنع بر الله » (يع ١ : ٢٠) . أو قول أحد القديسين « ولو أقام الغضوب أمواتاً ، فما هو مقبول عند الله ، ولا يقبله أحد من الناس » .","وإن حاربك العدو بنظرة شريرة ، ضع أمامه قول الرب « من نظر إلى إمرأة واشتهاها ، فقد زنى بها فى قلبه » (متى ٥ : ٢٨) . وإن حاربك بالزنا ، تذكر قول الرسول « ألستم تعلمون أن جسدكم هو هيكل الروح القدس » (١كو ٦ : ١٩) ، « ألستم تعلمون أن أجسادكم هى أعضاء المسيح . أفآخذ أعضاء المسيح وأجعلها أعضاء زانية ؟! حاشا » (١كو ٦ : ١٥) .","وإن حاربك الشيطان بأخطاء اللسان ، ضع أمامك آيات الكتاب « كثرة الكلام لا تخلو من معصية » (أم ١٠ : ١٩) ، « ليكن كل إنسان مسرعاً إلى الإستماع ، مبطئاً فى التكلم » (يع ١ : ٢٠) ، وأيضاً قل « ضع يارب حافظاً لفمى ، وباباً حصيناً لشفتى » (مز ١٤١ : ٣) .","وإن حاربك الشيطان بمحبة العالم الحاضر ، وما فيه من مغريات ، ضع أمام ذلك قول الكتاب « محبة العالم عداوة لله » (يع ٤ : ٤) . وأيضاً « لا تحبوا العالم ولا الأشياء التى فى العالم . إن أحب أحد العالم ، فليست فيه محبة الآب » (١يو ٢ : ١٥) ، « العالم يمضى وشهوته معه » (١يو ٢ : ١٧) . وأيضاً تذكر كل ما ورد فى سفر الجامعة عن هذا الموضوع ، وبخاصة قول الكتاب « باطل الأباطيل . الكل باطل"],"113":["وقبض الريح . ولا منفعة تحت الشمس » (جا ١ : ٢ ، ١٤ ، ٢ : ١١) .","وإن حاربك الشيطان بالكبرياء ، تذكر قول الكتاب « قبل الكسر الكبرياء ، وقبل السقوط تشامخ الروح » (أم ١٦ : ١٨) . وأيضاً « يقاوم الله المستكبرين . أما المتواضعون فيعطيهم نعمة » (يع ٤ : ٦ ، ١بط ٥ : ٥) .",{"h":"إن أسلوب مواجهة الخطية بالوصية ، من نصائح القديس مار أوغريس ."},"وهو موجود بأسلوب واسع جداً فى ميامره عن (حرب الأفكار) ، تستطيع أن تقرأها فى مخطوطات الأديرة . ومع ذلك فأنت تستطيع أن تستخرج لنفسك من الكتاب مجموعة من الآيات تستخدمها فى حروبك ، وتحفظها جيداً فى ذاكرتك .",{"h":"إن كلمة الله حية وفعالة (عب ٤ : ١٢) ولها تأثيرها ."},"وثق أنك حينما تتذكرها لا بد سيكون لها عمل رادع داخل نفسك . وهكذا قال الرب « كلمتى التى تخرج من فمى لا ترجع إلىّ فارغة . بل تعمل ما سررت به ، وتنجح فى ما أرسلتها له » (أش ٥٥ : ١١) . جرّب إذن قوة كلمة الرب فى حروب الشياطين"],"114":[{"h":"الفصل الخامس"},{"h":"فوائد الحروب الروحية"}],"115":[{"h":"إن الله لا يمنع عنا حروب الشيطان . ولكنه يقف معنا فيها ، وأيضاً يجعلها لفائدتنا الروحية ."},"ومن أجل هذا ، فإن القديس الأنبا أنطونيوس ، بعد أن عاش معه القديس بولس البسيط فترة محتمياً تحت ظل صلواته ، طلب منه الأنبا أنطونيوس أن يسكن وحده ، لكى يستطيع فى الوحدة أن يجرب حروب الشياطين ويقتنى منها فائدة لنفسه .","فما هى الفوائد الروحية التى تقتنى من حروب الشياطين ؟ والتى مارسها المتوحدون فى البرارى والقفار حتى تفرغوا لمحبة الله ، وبالتالى لقتال العدو ؟",{"h":"١ - الفائدة الأولى هى الإتضاع :"},"كلما تشتد حروب الشياطين على إنسان فى قوة وعنف ، يشعر بضعفه أمامها ، فيزول عنه انتفاخه ، وينسحق قلبه من الداخل ، ويرى أنه معرض للسقوط ، وأن إرادته ليست معصومة من الخطأ . ويعرف أن الخطية « طرحت كثيرين جرحى ، وكل قتلاها أقوياء » (أم ٧ : ٢٦) .",{"h":"٢ - الصلاة والتمسك بالله وطلب معونته :"},"الإنسان وهو مستريح ، قد لا يطلب المعونة الإلهية ، وقد لا يشعر أنه فى مسيس الإحتياج إليها . ولكنه إذا اشتدت عليه الحرب ، يصرخ إلى الله لينصره على عدو قاس . وهكذا إذ يشعر بضعفه يتمسك بالرب فى صلاة عميقة ، وفى صلوات قوية ؛ هذا الذى قال « أدعنى فى وقت الضيق ، أنقذك فتمجدنى » (مز ٥٠ : ١٥) .",{"h":"٣ - الحروب الروحية تدعو إلى الإشفاق على المخطئين :"},"الذى لم تحاربه الشياطين ، قد يقسو على المخطئين ويدينهم فى سقوطهم . أما الذى حورب ، وقد جرّب عنف العدو ، فإنه يشفق على كل خاطىء ويصلى لأجله . وكما قال القديس بولس الرسول « أذكروا المقيدين كأنكم مقيدون معهم . واذكروا المذلين"],"116":["كأنكم أنتم أيضاً فى الجسد » (عب ١٣ : ٣) . وقال عن رب المجد « لأنه فيما هو قد تألم مجرباً ، يقدر أن يعين المجربين » (عب ٢ : ١٨) .",{"h":"٤ - والحروب الروحية تعطى الإنسان خبرة :"},"فيتمرس بالقتال ، ويتعلم الحرب ، ويعرف حيل العدو وفنونه ، ويأخذ خبرة سواء من قيامه أو سقوطه . والمعروف أن كل ارتقاء درجة يسبقه امتحان ، من يجتازه يرتفع هذه الدرجة كما يحدث لطلاب العلم . وبهذا نرى أن الذين قد دخلوا فى حروب العدو إكتسبوا خبرة .","والخبرات الروحية هذه هى مدرسة تخرّج مرشدين روحيين ، قادرين على معونة غيرهم وتشجيعهم وكشف حيل العدو لهم .",{"h":"٥ - والحروب بركة ننال بها أكاليل :"},"وكما قال أحد القديسين : لا يكلل إلا الذى انتصر . ولا ينتصر إلا الذى حارب . وفى احتمالنا لحرب العدو ، وصمودنا فيها ، ومجاهدتنا ومقاومتنا ، فى كل ذلك تظهر محبتنا للرب ، وننال على ذلك أكاليل . وكما قال أحد الآباء : ليس الجنود المنتصرون هم فقط الذين ينالون أكاليل فى الحرب ، وإنما أيضاً الذين جرحوا وأصيبوا ، مادامو لم يستسلموا للعدو وقاتلوه .",{"h":"٦ - والحروب تعطينا باستمرار روح الصحو والإستعداد :"},"وكما قال الرب « لتكن أحقاؤكم ممنطقة ، ومصابيحكم موقدة » (لو ١٢ : ٣٥) . شعور الإنسان بأنه فى حرب ، يجعله باستمرار مستعداً للقتال ، يستخدم كل الوسائط الروحية من صلاة وصوم واتضاع ومشورة روحية ، لكى ينتصر . بينما ربما لو خفت الحروب ، لقاده ذلك إلى الفتور الروحى . أما الحرب فتجعله فى حالة تأهب مستمر ، وفى حالة حرص وتدقيق . والخوف من السقوط يجعله يستعد بأكثر قوة حتى ينتصر .",{"h":"٧ - والحروب الروحية تجعلنا أقوياء لا نخاف :"},"إنما يخاف الحرب ، الشخص الذى لم يدخلها ولم يقاتل . أما الذى يجرب"],"117":["الحروب ، فإن ذلك يعطيه شجاعة وجسارة قلب . وما يأخذه من أكاليل يشجعه على دخول حروب أخرى ، ولا يخشى الفشل فى الحرب . هل يستطيع تلميذ أن يقول إننى من خوف السقوط لا أدخل الإمتحان ، بل ولا أدرس ولا أدخل مدارس ؟! كلا . بل هو يدخل الإمتحانات فى شجاعة قلب ، ويقول : سأنتصر على كل مصاعب العلم وامتحاناته .",{"h":"٨ - والحروب الروحية هى مدرسة للإيمان :"},"نرى فيها يد الله كيف تتدخل ، وكيف تعين وتنصر ، وكيف تنتهر العدو ، وكيف تعطى داود الصغير القوة لينتصر على جليات الجبار . وهكذا تعمّق إيماننا فى محبة الله ورعايته وعمله لأجلنا .",{"h":"٩ - والحروب الروحية هى مبدأ تكافؤ فرص للشيطان :"},"أخذ الفرصة التى يقاتل فيها ، وبكل قوته . لئلا يحتج الشيطان على أولاد الله ويقول : لماذا يكافئهم الرب ؟ إننى لو أخذت فرصة لأسقطتهم ، كما اشتكى أيام أيوب ، وأخذ فرصته ، وبقى أيوب محتفظاً بكماله (أى ٢) . فالله يسمح للشيطان بأن يحارب المؤمنين ، ويعطى المؤمنين قوة على الإنتصار ، ويخرج الشيطان فى خزى .",{"h":"١٠ - وأخيراً فالحروب الروحية تفتح أبواب الملكوت لنا ، وتحدد درجتنا فيه :"},"وكل إنسان ينال أجرته بحسب تعبه ، وبحسب جهاده . وبهذا نرى المؤمنين يبذلون كل جهدهم لكى يعبروا لله عن حبهم . لأنه كيف يظهر حبهم دون أن يُختبر بالحروب الروحية . وكيف تتحدد درجتهم فى الملكوت بدون هذا الإختبار الروحى .","فليكن الرب معنا فى كل حروبنا الروحية ، يقودنا فى موكب نصرته ."]}}};
})();
